ClinicalChunks.register("data/templates-091.js",[{"id":"templates-9ae69193042650704eaf","key":"v1-c9ccc21dfe2a3058|templates-9ae69193042650704eaf","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"胃痛(中医辨证)","category":"中医","raw":{"name":"胃痛(中医辨证)","category":"中医","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】上腹胃脘部疼痛、胀满不适、嗳气反酸、恶心呕吐、食欲不振。\n【待人工确认·本机素材无此段原文】","现病史":"胃痛，又称胃脘痛，是指以上腹胃脘部近心窝处疼痛为主症的病证。\n常见表现：上腹胃脘部疼痛、胀满不适、嗳气反酸、恶心呕吐、食欲不振。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：体温、脉搏、呼吸、血压\n望诊：神（得神/少神/失神/假神/神乱）、色（常色/病色：青/赤/黄/白/黑，光泽/晦暗）、形态（形体胖瘦/动静姿态/异常动作）、头面（头颅/囟门/头发/面肿/口眼歪斜）、五官（目/耳/鼻/口/齿/龈/咽喉）、躯体（颈项/胸胁/腹部/腰背/四肢/皮肤）、舌诊（舌质：颜色/形质/动态；舌苔：苔色/苔质/润燥/厚薄/腻腐/剥落；舌底络脉）、排泄物（痰涎/呕吐物/大便/小便/经血/带下）\n闻诊：声音（语声/呼吸/咳嗽/喘哮/呃逆/嗳气/太息/肠鸣）、气味（口气/汗气/痰涕气味/二便气味/经带气味/病室气味）\n问诊：一般情况（姓名/性别/年龄/职业/籍贯）、主诉、现病史（起病情况/主症特点/病因诱因/病情发展/诊治经过/伴随症状）、既往史、个人史、家族史、十问歌（一问寒热二问汗，三问头身四问便，五问饮食六胸腹，七聋八渴俱当辨，九问旧病十问因，再兼服药参机变，妇女尤必问经期，迟速闭崩皆可见，再添片语告儿科，天花麻疹全占验）\n切诊：脉诊（部位：寸关尺；脉象：浮沉迟数虚实滑涩洪细濡弱弦紧结代促等，注意平脉/病脉/真脏脉）、按诊（按肌肤/按手足/按胸腹/按腧穴/按腹部，温度/湿度/压痛/包块/波动感）\n辨证：八纲辨证（表里/寒热/虚实/阴阳）、脏腑辨证、气血津液辨证、六经辨证、卫气营血辨证、三焦辨证、经络辨证","辅助检查":"检查计划：患者以上腹胃脘部疼痛为主症，伴胀满不适、嗳气反酸、恶心呕吐、食欲不振，入院后完善胃镜检查明确有无胃炎、胃溃疡、十二指肠溃疡及肿瘤等器质性病变，必要时取活检送病理；完善幽门螺杆菌检测（尿素呼气试验或胃镜下快速尿素酶试验）明确有无感染，指导中药辨证与根除治疗方案的制定；完善血常规、大便常规+隐血检查了解有无贫血及消化道出血；完善肝肾功能、电解质检查评估药物代谢与内环境状态；患者疼痛位于近心窝处，需完善心电图、心肌酶检查排除心绞痛、心肌梗死等心源性疾病所致上腹痛；完善腹部超声检查肝胆胰脾，排除胆囊炎、胆石症、胰腺炎等引起的上腹部牵涉痛；辨证属湿热中阻者完善尿常规检查了解有无湿热下注表现，必要时完善上腹部CT检查进一步明确诊断，并定期复查胃镜观察病变变化。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 上腹近心窝处胃脘部发生疼痛为特征，其疼痛有胀痛、刺痛、隐痛、剧痛等不同的性质。\n2. 常伴食欲不振，恶心呕吐，嘈杂泛酸，嗳气吞腐等上消化道症状。\n3. 发病特点：以中青年居多，多有反复发作病史，发病前多有明显的诱因。\n1. 胃痛(中医辨证)（ICD-10：K30）","鉴别诊断":"1. 胃痛与真心痛鉴别：真心痛疼痛部位在左胸，疼痛剧烈，伴汗出、肢冷、心悸、喘促，病情危急","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！\n\n方案1（脾胃虚寒）：\n 用法：参麦注射液40ml+5%GS250ml静滴qd\n\n方案2（肝胃郁热）：\n 用法：清开灵注射液40ml+5%GS250ml静滴qd\n\n方案3（胃阴不足）：\n 用法：生脉注射液40ml+5%GS250ml静滴qd\n\n📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！\n\n药物1（寒邪客胃）：\n 用法：香苏散合良附丸加减（高良姜6g 香附9g 紫苏9g 陈皮6g 甘草3g）\n\n药物2（饮食伤胃）：\n 用法：保和丸加减（山楂9g 神曲9g 半夏9g 茯苓9g 陈皮6g 连翘9g 莱菔子9g 麦芽9g）\n\n药物3（肝气犯胃）：\n 用法：柴胡疏肝散加减（柴胡9g 芍药9g 川芎6g 香附6g 陈皮6g 枳壳9g 佛手9g 甘草3g）\n\n药物4（湿热中阻）：\n 用法：清中汤加减（黄连6g 栀子9g 半夏9g 茯苓9g 白豆蔻6g 陈皮6g 甘草3g）\n\n药物5（瘀血停胃）：\n 用法：失笑散合丹参饮加减（蒲黄9g 五灵脂9g 丹参9g 檀香3g 砂仁3g）\n\n药物6（胃阴亏耗）：\n 用法：一贯煎合芍药甘草汤加减（沙参9g 麦冬9g 生地9g 枸杞子9g 当归9g 川楝子6g 芍药9g 甘草6g）\n\n药物7（脾胃虚寒）：\n 用法：黄芪建中汤加减（黄芪15g 桂枝9g 芍药18g 生姜3片 大枣5枚 饴糖30g 炙甘草6g）\n\n📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。\n\n【治疗】\n针灸：取中脘、足三里、内关、公孙；寒证加胃俞、神阙，热证加内庭，气滞加太冲，虚证加脾俞、胃俞\n耳针：胃、肝、脾、神门、交感、十二指肠\n穴位注射：足三里、胃俞，黄芪注射液或当归注射液2ml\n推拿：按揉中脘、足三里、内关，摩腹，捏脊\n\n【处理要点】\n规律饮食，忌暴饮暴食\n忌生冷辛辣油腻，戒烟酒\n保持心情舒畅，避免忧思恼怒\n注意保暖，避免受寒\n\n【护理】\n情志护理：肝气犯胃者多因情志不遂诱发或加重，嘱其戒怒少思、避免忧思恼怒，可予耳穴压豆（肝、胃、神门）或听舒缓音乐以疏肝理气；胃阴亏耗者忌劳神，宜静养调息。\n起居调护：脾胃虚寒者注意胃脘部及腹部保暖，忌受凉，可用热水袋温熨中脘（出血期忌用）；规律作息，勿过劳，饭后不宜立即平卧或剧烈活动。\n病情观察：观察胃痛部位、性质、时间、与进食及情志的关系及伴随症（嗳气、泛酸、呕吐、便血）；若出现痛势剧烈、腹肌紧张、呕血便血、面色苍白、脉细数等，立即报告并禁食禁水，警惕出血、穿孔。\n煎药服药护理：虚寒证汤剂宜温热服，清热化湿之剂宜温服、忌过烫，理气药煎煮时间宜短（后下）；服药宜温服分次，疼痛发作时遵医嘱予解痉止痛并观察疗效，泛酸者饭后服药，恶心呕吐者宜少量频服。\n外治护理：脾胃虚寒者可行艾灸中脘、足三里、神阙，或穴位贴敷温胃散寒；瘀血停胃者疼痛拒按，忌用力按压或热敷，可用中药离子导入、刺络拔罐需严格消毒并在医师指导下进行。\n\n【饮食】\n寒邪客胃、脾胃虚寒者：忌生冷瓜果、冷饮及性寒之品（苦瓜、绿豆、螃蟹等），宜温热细软易消化，可饮生姜红糖水，食疗方如胡椒炖猪肚、山药羊肉汤以温中散寒。\n肝气犯胃者：忌恼怒后勉强进食，忌产气壅滞之品（红薯、豆类、糯米），宜食理气和胃之品如陈皮、佛手、萝卜，可代茶饮玫瑰花、陈皮疏肝解郁。\n湿热中阻者：忌肥甘厚味、辛辣煎炸、甜腻及酒类，宜清淡易消化，可食薏苡仁粥、冬瓜汤、绿豆汤清热化湿，少食多餐。\n胃阴亏耗者：忌辛辣燥热之品（辣椒、羊肉、韭菜）及煎炸食品，宜甘凉濡润，可食山药、百合、石斛麦冬粥、鲜藕汁、梨汁以养阴生津，忌过热过快进食。\n瘀血停胃及出血期：忌粗糙坚硬、过烫及刺激性食物，宜温软流质或半流质，少量多餐；出血期间禁食，缓解后可进藕粉、山药粥，酌加山楂、三七粉（遵医嘱）活血化瘀。\n\n【注意事项】\n胃痛与真心痛鉴别：真心痛疼痛部位在左胸，疼痛剧烈，伴汗出、肢冷、心悸、喘促，病情危急；胃痛部位在上腹胃脘部，伴消化道症状。\n\n【急诊/急救】\n胃痛伴呕血、黑便、剧烈腹痛、腹肌紧张，可能为消化道出血或穿孔，立即急诊。","资料来源":"疾病库 diseases.json；鉴别诊断库 ddx_local.json（条目「胃痛（中医辨证）」原文）","中医辨证参考":"首次病程记录\n\n拟诊讨论：\n\n【中医辨证参考】胃痛\n（本页列出该病常见证型，请根据患者实际四诊资料选择相应证型，切勿直接套用）\n\n一、肝胃不和\n    症状舌脉：胃脘胀痛，痛连两胁，嗳气频作，泛酸嘈杂，情志不遂则加重，苔薄白，脉弦\n    治法：疏肝理气、和胃止痛\n    方剂：柴胡疏肝散\n\n二、脾胃湿热\n    症状舌脉：胃脘灼热胀痛，口苦口黏，渴不欲饮，身重纳呆，小便黄，大便不爽，舌红苔黄厚腻，脉滑数\n    治法：清热化湿、和中醒脾\n    方剂：清中汤\n\n三、胃阴不足\n    症状舌脉：胃脘隐隐灼痛，饥不欲食，口干咽燥，干呕呃逆，大便干结，舌红少津、苔少或剥脱，脉细数\n    治法：养阴益胃、缓急止痛\n    方剂：益胃汤\n\n四、脾胃虚寒\n    症状舌脉：胃痛隐隐，喜温喜按，空腹痛甚，得食则减，泛吐清水，畏寒肢冷，大便溏薄，舌淡胖有齿痕、苔薄白，脉虚弱或沉迟\n    治法：温中健脾、和胃止痛\n    方剂：黄芪建中汤\n\n五、瘀血停滞\n    症状舌脉：胃脘刺痛，痛有定处而拒按，食后加重，或见呕血黑便，面色晦暗，舌紫暗有瘀斑、苔薄，脉涩\n    治法：活血化瘀、理气止痛\n    方剂：失笑散合丹参饮\n\n六、寒邪客胃\n    症状舌脉：胃痛暴作，恶寒喜暖，得温痛减，遇寒加重，口淡不渴，或喜热饮，舌淡苔薄白，脉弦紧\n    治法：温胃散寒、行气止痛\n    方剂：良附丸\n\n七、饮食伤胃\n    症状舌脉：胃脘疼痛，胀满拒按，嗳腐吞酸，或呕吐不消化食物，其味腐臭，吐后痛减，不思饮食，大便不爽，得矢气及便后稍舒，舌苔厚腻，脉滑\n    治法：消食导滞、和胃止痛\n    方剂：保和丸。来源：《中医内科学》（中国中医药出版社“十四五”规划教材）·脾胃系病证·胃痛\n\n【方剂参考】\n  柴胡疏肝散：组成 陈皮（醋炒）6g、柴胡6g、川芎4.5g、香附4.5g、枳壳（麸炒）4.5g、白芍4.5g、炙甘草1.5g；功效 疏肝解郁，行气止痛\n      用法：水煎温服，日一剂，分两次服；亦可研末为散，每服6~9g，开水送下。\n      注意：阴虚火旺、气郁化火及孕妇慎用；本方辛散，久服易耗气伤阴。来源：《方剂学》（中国中医药出版社“十四五”规划教材）·理气剂（行气）；原方出自《景岳全书·古方八阵》\n  清中汤：组成 黄连6g、栀子9g、陈皮9g、茯苓12g、半夏9g、草豆蔻6g（后下）、炙甘草3g、生姜3片；功效 清热化湿，理气和中\n      用法：水煎，草豆蔻后下，温服，日一剂，分二次服。\n      注意：脾胃虚寒者忌用；黄连、栀子苦寒，中病即止，不宜久服；胃痛持续或伴消瘦、黑便者须先做胃镜检查除外恶性病变。来源：《方剂学》（中国中医药出版社“十四五”规划教材）·清热剂（清脏腑热）；原方出自《医学统旨》（《中医内科学》胃痛·脾胃湿热证用方）\n  益胃汤：组成 沙参9g、麦冬15g、生地黄15g、玉竹4.5g、冰糖3g（烊化）；功效 养阴益胃，生津润燥\n      用法：水煎去滓，纳冰糖烊化，温服，日一剂，分二次服。\n      注意：脾胃虚寒、痰湿中阻者忌用；糖尿病者去冰糖；胃痛持续或伴消瘦、黑便者须先做胃镜检查。来源：《方剂学》（中国中医药出版社“十四五”规划教材）·补益剂（补阴）；原方出自《温病条辨·卷二·中焦篇》\n  黄芪建中汤：组成 黄芪9g、桂枝9g、白芍18g、生姜9g、大枣4枚、炙甘草6g、饴糖30g（烊化）；功效 温中补气，和里缓急\n      用法：水煎前六味，去滓，纳入饴糖（烊化）温服，日一剂，分二次服；服后宜食热粥以助药力。\n      注意：呕吐或中满者不宜用；阴虚火旺、湿热内蕴者忌用；糖尿病患者慎用饴糖，可在医师指导下加减。来源：《方剂学》（中国中医药出版社“十四五”规划教材）·温里剂（温中祛寒）；本方系小建中汤加黄芪，小建中汤原方出自《伤寒论·辨太阳病脉证并治》，黄芪建中汤出自《金匮要略·血痹虚劳病脉证并治》\n  失笑散：组成 五灵脂6g、蒲黄6g；功效 活血祛瘀，散结止痛\n      用法：上药研末为散，每次6g，先用酽醋（浓醋）调成糊，再以水一盏煎服；亦可布袋包煎作汤剂。\n      注意：孕妇忌用；血虚无瘀及月经量多者禁用；脾胃虚弱者慎用（五灵脂伤胃）；不宜与人参同用。\n  良附丸：组成 高良姜9g、香附9g；功效 行气疏肝，祛寒止痛\n      用法：水煎温服，日一剂，分二次服；原方为丸剂，每服6g，日二次，米饮汤送下。\n      注意：胃热疼痛、阴虚火旺者忌用；高良姜辛热，久服易伤阴；胃痛持续或伴消瘦、黑便者须先做胃镜检查。来源：《方剂学》（中国中医药出版社“十四五”规划教材）·理气剂（行气）；原方出自《良方集腋·卷上》\n  保和丸：组成 山楂18g、神曲6g、半夏9g、茯苓9g、陈皮6g、连翘6g、莱菔子6g；功效 消食和胃\n      用法：上药为末，炊饼为丸如梧桐子大，每次6-9g，麦芽汤或温开水送服，日二至三次；亦可作汤剂。\n      注意：脾虚无食积者不宜久服（消导伤正）；孕妇慎用山楂、莱菔子；忌与滋补药同服。\n\n【西医诊断】\n  慢性胃炎\n  （西医诊断依据与鉴别诊断请结合患者病史、体征、辅助检查补充）\n\n医师签名：＿＿＿＿"},"icd10_diagnosis":"K30","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2625,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"da0d903ad7c9b2d6823435e7b3a5fbc544caae81aaad9eb4434f876663580849","pinyin":"weitong(zhongyibianzheng)","initials":"wt(zybz)","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源","中医辨证参考"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源 中医辨证参考",30],["主要诊断编码","K30",30]]},{"id":"templates-89204a6162c96e5a9014","key":"v1-c9ccc21dfe2a3058|templates-89204a6162c96e5a9014","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"胃肠道间质瘤","category":"肿瘤科","raw":{"name":"胃肠道间质瘤","category":"肿瘤科","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】腹痛、腹部不适、消化道出血（黑便、呕血、便血）、腹部包块、贫血、乏力、吞咽困难（食管/贲门）或肠梗阻（小肠）、食欲减退、体重下降。\n【待人工确认·本机素材无此段原文】","现病史":"胃肠道最常见的间叶源性肿瘤，多发于胃（约60%），具有潜在恶性，可发生肝及腹膜转移\n常见表现：腹痛、腹部不适、消化道出血（黑便、呕血、便血）、腹部包块、贫血、乏力、吞咽困难（食管/贲门）或肠梗阻（小肠）、食欲减退、体重下降。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"腹部：有无压痛、包块（大小、质地、活动度）\n全身：贫血貌、消瘦、乏力（慢性失血）\n直肠指检：低位直肠GIST可触及\n生命体征：急性失血时可有心率增快、血压下降","辅助检查":"1. 血常规：慢性失血性贫血评估\n2. 便潜血：消化道出血筛查\n3. 腹部增强CT：初诊必做，评估原发灶及肝、腹膜转移\n4. 胃镜/肠镜+超声内镜（EUS）：黏膜下肿瘤定位及活检\n5. 病理+免疫组化（CD117、DOG1、Ki-67）：确诊金标准\n6. 基因检测（KIT/PDGFRA）：指导靶向治疗及预后判断","初步诊断":"1. 内镜或CT发现胃肠道壁内占位\n2. 病理+免疫组化CD117（KIT）、DOG1阳性确诊\n3. 基因检测（KIT/PDGFRA突变）指导靶向治疗\n4. NIH危险度分级（大小、核分裂象、部位）评估复发风险\n1. 胃肠道间质瘤（ICD-10：C49.0）","鉴别诊断":"1. 免疫组化CD117/DOG1阳性是确诊关键，与平滑肌瘤、神经鞘瘤鉴别\n2. 诊断要点：内镜或CT发现胃肠道壁内占位\n3. 诊断要点：病理+免疫组化CD117（KIT）、DOG1阳性确诊\n4. 诊断要点：基因检测（KIT/PDGFRA突变）指导靶向治疗\n5. 诊断要点：NIH危险度分级（大小、核分裂象、部位）评估复发风险\n6. 肿瘤大小、核分裂象、部位决定NIH危险度分级，中高危需辅助治疗\n7. 服药期间避免与CYP3A4强诱导剂（利福平、苯妥英钠）合用，慎用圣约翰草","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：GIST 对传统化疗不敏感，不推荐常规静脉化疗，治疗以手术及口服靶向药物为主，以下方案仅供参考，切勿随意使用！\n\n方案1（一线靶向，参考）：\n 用法：伊马替尼400mg qd po（餐中服用，口服给药，非输液）\n\n方案2（二线靶向，参考）：\n 用法：舒尼替尼37.5mg qd po（伊马替尼耐药或不耐受时，口服给药，非输液）\n\n📌 用药前请核对药品名称、剂量、用法，确认无药物过敏史和禁忌症；靶向治疗需长期规律服用，不可随意停药。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！\n\n药物1：\n 用法：伊马替尼400mg qd（一线标准剂量，餐中服用，长期服用）\n\n药物2：\n 用法：奥美拉唑肠溶片20mg qd（抑酸护胃）\n\n药物3：\n 用法：昂丹司琼8mg bid（恶心明显时止吐）\n\n📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。\n\n【治疗】\n可切除者首选手术完整切除（R0切除）\n术前新辅助伊马替尼（肿瘤大、邻近器官受累时）\n中高危者术后辅助伊马替尼400mg qd（疗程3年）\n晚期/转移者伊马替尼一线治疗，进展后换舒尼替尼/瑞戈非尼\n定期影像随访（CT）评估疗效\n\n【处理要点】\n规律服药，切勿自行停药或减量（中断可致肿瘤快速进展）\n定期复查腹部增强CT（术后2-3年内每3-6个月）\n监测血常规、肝肾功能\n育龄期患者治疗期间避孕（伊马替尼有致畸性）\n\n【护理】\n用药护理：伊马替尼餐中服用、规律服用，观察水肿、乏力、皮疹、肌肉痉挛等不良反应\n病情观察：监测腹痛、黑便、呕血，警惕肿瘤破裂出血\n饮食护理：少食多餐、细软易消化，避免粗糙食物防梗阻及出血\n心理护理：讲解靶向治疗获益，提高服药依从性\n健康宣教：定期复查，治疗期间避孕宣教\n\n【饮食】\n少食多餐、细软易消化：粥、烂面条、蛋羹\n忌粗糙、坚硬及过烫食物：坚果、油炸食品，防肿瘤部位出血\n高蛋白高热量：鱼、蛋、奶、瘦肉，改善营养状态\n伊马替尼餐中服用，用温水送服，减轻胃肠刺激\n忌辛辣刺激及烟酒\n\n【注意事项】\n免疫组化CD117/DOG1阳性是确诊关键，与平滑肌瘤、神经鞘瘤鉴别\n肿瘤大小、核分裂象、部位决定NIH危险度分级，中高危需辅助治疗\n服药期间避免与CYP3A4强诱导剂（利福平、苯妥英钠）合用，慎用圣约翰草\n\n【急诊/急救】\n肿瘤破裂或消化道大出血（突发剧烈腹痛、呕血、黑便、休克）：急诊手术或介入止血\n肠梗阻：禁食、胃肠减压，急诊处理\n伊马替尼严重不良反应（粒细胞缺乏、严重肝损伤、过敏）：停药并急诊就医","资料来源":"疾病库 diseases.json；鉴别诊断库 ddx_local.json（条目「胃肠道间质瘤」原文）"},"icd10_diagnosis":"C49.0","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2626,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"831559394d09386c801c74364777247b110d0993e7dc4e981643b649dda21dea","pinyin":"weichangdaojianzhiliu","initials":"wcdjzl","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","C49.0",30]]},{"id":"templates-7c515aa49219de907e01","key":"v1-c9ccc21dfe2a3058|templates-7c515aa49219de907e01","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"胃脘痛(中医辨证)","category":"中医","raw":{"name":"胃脘痛(中医辨证)","category":"中医","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】寒邪：胃痛暴作，恶寒喜暖，得温痛减、饮食：胃脘胀满，嗳腐吞酸，吐食后痛减、肝气：胃脘胀痛，连及两胁，嗳气频作，情绪波动加重、湿热：胃脘灼痛，口干口苦，舌红苔黄腻、瘀血：胃痛如刺，痛有定处，拒按，舌紫暗、虚寒：胃痛隐隐，喜温喜按，空腹痛甚，得食痛减，畏寒肢冷。\n【待人工确认·本机素材无此段原文】","现病史":"以上腹胃脘部近心窝处疼痛为主症，常伴痞满、嗳气、反酸等。分寒邪客胃、饮食伤胃、肝气犯胃、湿热中阻、瘀血停胃、胃阴亏耗、脾胃虚寒等证型。\n常见表现：寒邪：胃痛暴作，恶寒喜暖，得温痛减、饮食：胃脘胀满，嗳腐吞酸，吐食后痛减、肝气：胃脘胀痛，连及两胁，嗳气频作，情绪波动加重、湿热：胃脘灼痛，口干口苦，舌红苔黄腻、瘀血：胃痛如刺，痛有定处，拒按，舌紫暗、虚寒：胃痛隐隐，喜温喜按，空腹痛甚，得食痛减，畏寒肢冷。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：体温、脉搏、呼吸、血压\n望诊：神（得神/少神/失神/假神/神乱）、色（常色/病色：青/赤/黄/白/黑，光泽/晦暗）、形态（形体胖瘦/动静姿态/异常动作）、头面（头颅/囟门/头发/面肿/口眼歪斜）、五官（目/耳/鼻/口/齿/龈/咽喉）、躯体（颈项/胸胁/腹部/腰背/四肢/皮肤）、舌诊（舌质：颜色/形质/动态；舌苔：苔色/苔质/润燥/厚薄/腻腐/剥落；舌底络脉）、排泄物（痰涎/呕吐物/大便/小便/经血/带下）\n闻诊：声音（语声/呼吸/咳嗽/喘哮/呃逆/嗳气/太息/肠鸣）、气味（口气/汗气/痰涕气味/二便气味/经带气味/病室气味）\n问诊：一般情况（姓名/性别/年龄/职业/籍贯）、主诉、现病史（起病情况/主症特点/病因诱因/病情发展/诊治经过/伴随症状）、既往史、个人史、家族史、十问歌（一问寒热二问汗，三问头身四问便，五问饮食六胸腹，七聋八渴俱当辨，九问旧病十问因，再兼服药参机变，妇女尤必问经期，迟速闭崩皆可见，再添片语告儿科，天花麻疹全占验）\n切诊：脉诊（部位：寸关尺；脉象：浮沉迟数虚实滑涩洪细濡弱弦紧结代促等，注意平脉/病脉/真脏脉）、按诊（按肌肤/按手足/按胸腹/按腧穴/按腹部，温度/湿度/压痛/包块/波动感）\n辨证：八纲辨证（表里/寒热/虚实/阴阳）、脏腑辨证、气血津液辨证、六经辨证、卫气营血辨证、三焦辨证、经络辨证","辅助检查":"检查计划：患者以上腹胃脘部近心窝处疼痛为主症，伴痞满、嗳气、反酸，辨证分寒邪客胃、饮食伤胃、肝气犯胃、湿热中阻、瘀血停胃、脾胃虚寒等证型，入院后完善胃镜检查明确有无胃溃疡、糜烂性胃炎、胃部肿瘤等病变，必要时取活检明确病理；完善幽门螺杆菌检测明确有无感染，作为辨证与用药的依据；完善血常规、大便常规+隐血检查排除消化道出血及贫血，尤其针对瘀血停胃证型；完善肝功能、肾功能、电解质检查评估药物代谢与内环境状况；患者疼痛位于近心窝处，需完善心电图、心肌酶检查排除心绞痛、心肌梗死所致上腹痛；完善腹部超声检查肝胆胰脾，排除胆囊炎、胆石症、胰腺炎所致上腹部疼痛；完善胃功能（胃泌素、胃蛋白酶原）检查了解胃黏膜功能状态，指导中西医结合治疗方案，并定期复查胃镜与幽门螺杆菌观察疗效。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 上腹胃脘部疼痛\n2. 常伴嗳气、反酸、腹胀\n3. 胃镜、幽门螺杆菌检测\n1. 胃脘痛(中医辨证)（ICD-10：K30）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！\n\n方案1（急性发作）：\n 用法：NS250ml+奥美拉唑40mg ivgtt qd\n\n方案2（痉挛疼痛）：\n 用法：山莨菪碱10mg im\n\n方案3（虚寒）：\n 用法：NS250ml+参附注射液40ml ivgtt qd\n\n📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！\n\n药物1（寒邪）：\n 用法：良附丸3g tid\n\n药物2（饮食）：\n 用法：保和丸1袋 tid，或枳实导滞丸1袋 tid\n\n药物3（肝气）：\n 用法：柴胡疏肝散1袋 tid，或气滞胃痛颗粒1袋 tid\n\n药物4（湿热）：\n 用法：三九胃泰1袋 tid，或左金丸3g tid\n\n药物5（瘀血）：\n 用法：失笑散6g tid，或丹参滴丸10粒 tid\n\n药物6（虚寒）：\n 用法：黄芪建中丸1丸 tid，或附子理中丸1丸 tid\n\n药物7（阴虚）：\n 用法：一贯煎颗粒1袋 tid\n\n📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。\n\n【治疗】\n寒邪：温胃散寒，良附丸\n饮食：消食导滞，保和丸\n肝气：疏肝理气，柴胡疏肝散\n湿热：清热化湿，清中汤\n瘀血：活血化瘀，失笑散合丹参饮\n虚寒：温中健脾，黄芪建中汤\n阴虚：养阴益胃，一贯煎合芍药甘草汤\n\n【处理要点】\n规律饮食，忌暴饮暴食\n忌生冷、辛辣、油腻\n保持心情舒畅\n虚寒者注意腹部保暖\n\n【护理】\n情志护理：肝气犯胃者多因情志不遂诱发，护理时宜耐心疏导，避免言语刺激，嘱患者戒怒、调畅情志，可指导其听舒缓音乐或练习深呼吸以疏肝和胃；胃痛发作时多倾听诉说，缓解紧张焦虑情绪。\n起居调护：寒邪客胃、脾胃虚寒者注意胃脘部保暖避风寒，可用热水袋温熨胃脘部（防烫伤）；起居有常，劳逸适度，饭后半小时内避免剧烈活动，保证充足睡眠。\n病情观察：密切观察胃痛部位、性质、程度及发作时间，注意有无呕血、黑便等出血先兆；若痛势剧烈、拒按、大汗淋漓或伴呕血便血，应立即报告医师处理；同时观察服药后疼痛缓解情况及食欲、大便变化。\n煎药服药护理：胃痛药多宜温服；补益温中之剂宜饭前温服，理气消导之剂宜饭后服，服药期间忌与生冷同进；丸剂宜嚼碎或温水送服，服药后稍作休息，观察有无脘胀、恶心等不适。\n外治护理：可选用中脘、足三里、内关等穴行艾灸、穴位贴敷或按揉以温中止痛、和胃降逆；虚寒证可艾灸中脘、神阙各15-20分钟，注意观察皮肤防烫伤；瘀血胃痛可于胃脘部轻柔按揉以活血止痛，手法宜和缓。\n\n【饮食】\n辨证忌口：寒邪客胃、脾胃虚寒者忌食生冷瓜果、冰镇饮品及寒凉之品；湿热中阻者忌肥甘厚味、甜腻食物及酒类；胃阴不足者忌辛辣煎炸、浓茶咖啡；肝气犯胃者忌暴饮暴食及产气壅滞之品（如红薯、豆类、糯米）。\n适宜食物：脾胃虚寒者宜温热易消化之品，如小米粥、山药、南瓜；湿热者宜清淡利湿之品，如薏苡仁、冬瓜、赤小豆；胃阴不足者宜甘凉濡润之品，如百合、银耳、石斛；瘀血停胃者宜理气活血之品，如山楂、黑木耳。\n食养调摄：规律进餐、细嚼慢咽、少食多餐，每餐七分饱，忌饥饱无常；餐后散步片刻以助运化，避免睡前进食及饭后立即平卧。\n药膳食疗：寒凝胃痛可服生姜红糖水或高良姜粥温胃散寒；肝气犯胃可饮陈皮玫瑰花茶疏肝理气；脾胃虚弱可食山药芡实粥健脾养胃；胃阴不足可食沙参麦冬炖鸭肉或百合银耳羹滋养胃阴。\n饮食宜温热、熟软、清淡，忌过烫过冷刺激胃黏膜；进食时保持心情舒畅，避免边进食边恼怒忧思，以防气机郁滞加重胃痛。\n\n【注意事项】\n久痛需胃镜排查溃疡、肿瘤\n幽门螺杆菌阳性需规范根除\n忌长期服用非甾体抗炎药\n\n【急诊/急救】\n一般不需急救\n呕血黑便：禁食，质子泵抑制剂，及时就诊\n穿孔：禁食，胃肠减压，急诊手术","资料来源":"疾病库 diseases.json","中医辨证参考":"首次病程记录\n\n拟诊讨论：\n\n【中医辨证参考】胃脘痛\n（本页列出该病常见证型，请根据患者实际四诊资料选择相应证型，切勿直接套用）\n\n一、肝胃不和\n    症状舌脉：胃脘胀痛，痛连两胁，嗳气频作，泛酸嘈杂，情志不遂则加重，苔薄白，脉弦\n    治法：疏肝理气、和胃止痛\n    方剂：柴胡疏肝散\n\n二、脾胃湿热\n    症状舌脉：胃脘灼热胀痛，口苦口黏，渴不欲饮，身重纳呆，小便黄，大便不爽，舌红苔黄厚腻，脉滑数\n    治法：清热化湿、和中醒脾\n    方剂：清中汤\n\n三、胃阴不足\n    症状舌脉：胃脘隐隐灼痛，饥不欲食，口干咽燥，干呕呃逆，大便干结，舌红少津、苔少或剥脱，脉细数\n    治法：养阴益胃、缓急止痛\n    方剂：益胃汤\n\n四、脾胃虚寒\n    症状舌脉：胃痛隐隐，喜温喜按，空腹痛甚，得食则减，泛吐清水，畏寒肢冷，大便溏薄，舌淡胖有齿痕、苔薄白，脉虚弱或沉迟\n    治法：温中健脾、和胃止痛\n    方剂：黄芪建中汤\n\n五、瘀血停滞\n    症状舌脉：胃脘刺痛，痛有定处而拒按，食后加重，或见呕血黑便，面色晦暗，舌紫暗有瘀斑、苔薄，脉涩\n    治法：活血化瘀、理气止痛\n    方剂：失笑散合丹参饮\n\n六、寒邪客胃\n    症状舌脉：胃痛暴作，恶寒喜暖，得温痛减，遇寒加重，口淡不渴，或喜热饮，舌淡苔薄白，脉弦紧\n    治法：温胃散寒、行气止痛\n    方剂：良附丸\n\n七、饮食伤胃\n    症状舌脉：胃脘疼痛，胀满拒按，嗳腐吞酸，或呕吐不消化食物，其味腐臭，吐后痛减，不思饮食，大便不爽，得矢气及便后稍舒，舌苔厚腻，脉滑\n    治法：消食导滞、和胃止痛\n    方剂：保和丸。来源：《中医内科学》（中国中医药出版社“十四五”规划教材）·脾胃系病证·胃痛\n\n【方剂参考】\n  柴胡疏肝散：组成 陈皮（醋炒）6g、柴胡6g、川芎4.5g、香附4.5g、枳壳（麸炒）4.5g、白芍4.5g、炙甘草1.5g；功效 疏肝解郁，行气止痛\n      用法：水煎温服，日一剂，分两次服；亦可研末为散，每服6~9g，开水送下。\n      注意：阴虚火旺、气郁化火及孕妇慎用；本方辛散，久服易耗气伤阴。来源：《方剂学》（中国中医药出版社“十四五”规划教材）·理气剂（行气）；原方出自《景岳全书·古方八阵》\n  清中汤：组成 黄连6g、栀子9g、陈皮9g、茯苓12g、半夏9g、草豆蔻6g（后下）、炙甘草3g、生姜3片；功效 清热化湿，理气和中\n      用法：水煎，草豆蔻后下，温服，日一剂，分二次服。\n      注意：脾胃虚寒者忌用；黄连、栀子苦寒，中病即止，不宜久服；胃痛持续或伴消瘦、黑便者须先做胃镜检查除外恶性病变。来源：《方剂学》（中国中医药出版社“十四五”规划教材）·清热剂（清脏腑热）；原方出自《医学统旨》（《中医内科学》胃痛·脾胃湿热证用方）\n  益胃汤：组成 沙参9g、麦冬15g、生地黄15g、玉竹4.5g、冰糖3g（烊化）；功效 养阴益胃，生津润燥\n      用法：水煎去滓，纳冰糖烊化，温服，日一剂，分二次服。\n      注意：脾胃虚寒、痰湿中阻者忌用；糖尿病者去冰糖；胃痛持续或伴消瘦、黑便者须先做胃镜检查。来源：《方剂学》（中国中医药出版社“十四五”规划教材）·补益剂（补阴）；原方出自《温病条辨·卷二·中焦篇》\n  黄芪建中汤：组成 黄芪9g、桂枝9g、白芍18g、生姜9g、大枣4枚、炙甘草6g、饴糖30g（烊化）；功效 温中补气，和里缓急\n      用法：水煎前六味，去滓，纳入饴糖（烊化）温服，日一剂，分二次服；服后宜食热粥以助药力。\n      注意：呕吐或中满者不宜用；阴虚火旺、湿热内蕴者忌用；糖尿病患者慎用饴糖，可在医师指导下加减。来源：《方剂学》（中国中医药出版社“十四五”规划教材）·温里剂（温中祛寒）；本方系小建中汤加黄芪，小建中汤原方出自《伤寒论·辨太阳病脉证并治》，黄芪建中汤出自《金匮要略·血痹虚劳病脉证并治》\n  失笑散：组成 五灵脂6g、蒲黄6g；功效 活血祛瘀，散结止痛\n      用法：上药研末为散，每次6g，先用酽醋（浓醋）调成糊，再以水一盏煎服；亦可布袋包煎作汤剂。\n      注意：孕妇忌用；血虚无瘀及月经量多者禁用；脾胃虚弱者慎用（五灵脂伤胃）；不宜与人参同用。\n  良附丸：组成 高良姜9g、香附9g；功效 行气疏肝，祛寒止痛\n      用法：水煎温服，日一剂，分二次服；原方为丸剂，每服6g，日二次，米饮汤送下。\n      注意：胃热疼痛、阴虚火旺者忌用；高良姜辛热，久服易伤阴；胃痛持续或伴消瘦、黑便者须先做胃镜检查。来源：《方剂学》（中国中医药出版社“十四五”规划教材）·理气剂（行气）；原方出自《良方集腋·卷上》\n  保和丸：组成 山楂18g、神曲6g、半夏9g、茯苓9g、陈皮6g、连翘6g、莱菔子6g；功效 消食和胃\n      用法：上药为末，炊饼为丸如梧桐子大，每次6-9g，麦芽汤或温开水送服，日二至三次；亦可作汤剂。\n      注意：脾虚无食积者不宜久服（消导伤正）；孕妇慎用山楂、莱菔子；忌与滋补药同服。\n\n【西医诊断】\n  慢性胃炎\n  （西医诊断依据与鉴别诊断请结合患者病史、体征、辅助检查补充）\n\n医师签名：＿＿＿＿"},"icd10_diagnosis":"K30","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2627,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"0f036adae760b009bc1c45155d648e3c8502ac72c8f3ab9abb39d201dadcf1be","pinyin":"weiwantong(zhongyibianzheng)","initials":"wwt(zybz)","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源","中医辨证参考"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源 中医辨证参考",30],["主要诊断编码","K30",30]]},{"id":"templates-2c68e340986e711ae625","key":"v1-c9ccc21dfe2a3058|templates-2c68e340986e711ae625","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"胆囊癌","category":"外科常见","raw":{"name":"胆囊癌","category":"外科常见","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】右上腹持续性隐痛或胀痛，进行性加重、右上腹可触及包块、进行性黄疸（肿瘤侵犯或压迫胆管）、食欲减退、恶心、呕吐、消瘦、乏力、贫血、晚期发热、腹水。\n【待人工确认·本机素材无此段原文】","现病史":"胆囊上皮来源的恶性肿瘤，与胆囊结石长期慢性炎症刺激密切相关，早期症状隐匿，多数确诊时已属晚期\n常见表现：右上腹持续性隐痛或胀痛，进行性加重、右上腹可触及包块、进行性黄疸（肿瘤侵犯或压迫胆管）、食欲减退、恶心、呕吐、消瘦、乏力、贫血、晚期发热、腹水。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：合并感染时体温升高\n一般情况：晚期消瘦、贫血貌\n腹部：右上腹压痛，可触及质硬包块，肝大\n皮肤黏膜：肿瘤侵犯胆管时皮肤巩膜黄染\n淋巴结：锁骨上淋巴结可肿大（远处转移时）","辅助检查":"1. 腹部彩超：首选筛查，观察胆囊壁增厚、腔内占位及肝侵犯情况\n2. CT/MRI增强：评估肿瘤分期、侵犯范围及淋巴结转移\n3. 肿瘤标志物CA19-9、CEA：辅助诊断及随访监测\n4. 肝功能+胆红素：判断有无胆道梗阻\n5. 血常规、凝血功能：术前评估\n6. 病理活检：确诊依据","初步诊断":"1. 超声示胆囊壁不规则增厚、胆囊内实性占位或胆囊腔消失\n2. CT/MRI增强扫描明确肿瘤侵犯范围及有无淋巴结、肝转移\n3. 肿瘤标志物CA19-9、CEA升高\n4. 合并胆道梗阻时肝功能、胆红素升高\n5. 病理检查（手术标本或穿刺活检）确诊\n1. 胆囊癌（ICD-10：C23）","鉴别诊断":"1. 需与胆囊息肉、胆囊腺肌症、黄色肉芽肿性胆囊炎鉴别\n2. 诊断要点：超声示胆囊壁不规则增厚、胆囊内实性占位或胆囊腔消失\n3. 诊断要点：CT/MRI增强扫描明确肿瘤侵犯范围及有无淋巴结、肝转移\n4. 诊断要点：肿瘤标志物CA19-9、CEA升高\n5. 诊断要点：合并胆道梗阻时肝功能、胆红素升高\n6. 诊断要点：病理检查（手术标本或穿刺活检）确诊\n7. 胆囊结石>1cm、瓷化胆囊、胆囊息肉>1cm、胆囊腺肌症为高危因素，建议手术切除胆囊","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！\n\n方案1（围手术期预防感染或合并胆囊炎）：\n 用法：NS250ml+头孢曲松2.0g ivgtt qd（抗感染）\n\n方案2（合并厌氧菌感染）：\n 用法：NS100ml+甲硝唑0.5g ivgtt bid（抗厌氧菌）\n\n📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！\n\n药物1（护肝利胆）：\n 用法：熊去氧胆酸250mg tid（黄疸、胆汁淤积时辅助治疗）\n\n药物2（疼痛管理）：\n 用法：布洛芬缓释胶囊0.3g bid（轻中度疼痛；肝肾功能不全者慎用）\n\n📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症；癌痛管理建议按WHO三阶梯原则规范化止痛。\n\n【治疗】\n根治性手术切除：胆囊癌根治术（胆囊切除+肝楔形切除+区域淋巴结清扫），早期（T1a）可行单纯胆囊切除术\n姑息性化疗：吉西他滨+顺铂方案（晚期不可切除者）\n姑息性胆道引流：PTCD或ERCP支架解除梗阻性黄疸\n放疗：局部晚期或术后高危者辅助放疗\n靶向及免疫治疗：HER2、BRAF等突变者个体化治疗\n\n【处理要点】\n多学科诊疗（MDT）制定个体化治疗方案\n围手术期营养支持，改善全身状况\n癌痛规范化管理，晚期患者安宁疗护\n术后定期随访复查影像学及肿瘤标志物\n\n【护理】\n病情观察：观察腹痛、黄疸、发热及腹部包块变化\n疼痛护理：评估疼痛程度，遵医嘱规范止痛，观察镇痛效果及不良反应\n围手术期护理：术前改善营养，术后观察切口、引流、出血及胆漏情况\n胆道引流护理：PTCD/ERCP术后保持引流管通畅，观察引流液性状\n健康宣教：指导合理饮食、定期复查，晚期患者做好心理疏导及安宁疗护\n\n【饮食】\n高蛋白、高维生素、均衡营养饮食，增强体质\n低脂饮食：减少油腻食物，减轻消化道症状\n黄疸患者补充脂溶性维生素\n少量多餐，注意食物多样化以改善食欲\n戒酒，避免腌制、霉变食物及辛辣刺激食物\n\n【注意事项】\n胆囊结石>1cm、瓷化胆囊、胆囊息肉>1cm、胆囊腺肌症为高危因素，建议手术切除胆囊\n需与胆囊息肉、胆囊腺肌症、黄色肉芽肿性胆囊炎鉴别\n术中发现胆囊壁可疑增厚时常规送术中冰冻病理检查\n\n【急诊/急救】\n急性胆囊炎发作：右上腹剧痛、发热，急诊抗感染并评估手术时机\n肿瘤致胆道梗阻：黄疸进行性加重，需急诊减黄（PTCD/ERCP）","资料来源":"疾病库 diseases.json；鉴别诊断库 ddx_local.json（条目「胆囊癌」原文）"},"icd10_diagnosis":"C23","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2628,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"fb73a83ded29d96b9b44741ecd18b51ca6e4e64a032d22fe55529f476612fd77","pinyin":"dannangai","initials":"dna","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","C23",30]]},{"id":"templates-2538789a8cc9eec571e2","key":"v1-c9ccc21dfe2a3058|templates-2538789a8cc9eec571e2","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"胆囊结石合并急性胆囊炎","category":"普通外科临床路径（2019年版）","raw":{"name":"胆囊结石合并急性胆囊炎","category":"普通外科临床路径（2019年版）","case":{"case_name":"门诊病历","templates":{"主诉":"【待人工确认·本机素材无此段原文】","现病史":"【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"【临床路径·住院期间检查项目】\n必需的检查项目：\r（1）血常规、尿常规、大便常规；\r（2）肝肾功能、电解质、凝血功能、感染性疾病筛查（乙型肝炎、丙型肝炎、艾滋病、梅毒等）、血型； \r（3）腹部超声；\r（4）心电图、胸部X线平片。 \r2.根据患者病情可选择的检查：血气分析、肺功能测定、超声心动图、MRCP、腹部CT等。\r（七）使用抗菌等药物选择与使用时机\r1.抗菌药物：按照《抗菌药物临床患者指导原则》（卫医发〔2015〕43号）执行。建议使用第二代头孢菌素，有反复感染史者可选头孢曲松或头孢哌酮或头孢哌酮/舒巴坦；明确感染患者，可根据药敏试验结果调整抗菌药物。 \r2.在给予抗菌药物治疗之前应尽可能留取相关标本送培养，获病原菌后进行药敏试验，作为调整用药的依据。有手术指征者应进行外科处理，并于手术过程中采集病变部位标本做细菌培养及药敏试验。\r3.尽早开始抗菌药物的经验治疗。经验治疗需选用能覆盖肠道革兰阴性杆菌、肠球菌属等需氧菌和脆弱拟杆菌等厌氧菌的药物。一般宜用至体温正常、症状消退后72～96小时。\r（八）手术日为入院\n3天\r1.麻醉方式：气管插管全身麻醉或硬膜外麻醉。\r2.手术方式：开腹胆囊切除术。\r3.术中用药：麻醉常规用药。\r4.输血：根据术前血红蛋白状况及术中出血情况而定。\r5.病理学检查：切除标本解剖后作病理学检查，必要时行术中冰冻病理学检查。\r（九）术后住院恢复3～4天\r1.必须复查的检查项目：血常规、肝肾功能、电解质。\r2.术后用药：抗菌药物使用按照《抗菌药物临床患者指导原则》（卫医发〔2015〕43号）执行。如有继发感染征象，尽早开始抗菌药物的经验治疗。经验治疗需选用能覆盖肠道革兰阴性杆菌、肠球菌属等需氧菌和脆弱拟杆菌等厌氧菌的药物。\r3.严密观察有无胆漏、出血等并发症，并作相应处理。\r4.术后饮食指导。\r（十）","初步诊断":"【临床路径·诊断依据】\n诊断依据\r根据《临床诊疗指南\n普通外科分册》（人民卫生出版社，2006年，第1版），全国高等学校教材《外科学》（人民卫生出版社，2013年，第8版）。\r1.症状：胆绞痛或上腹部隐痛、发热、偶尔有黄疸。\r2.体征：巩膜可有黄染，可触及肿大的胆囊，胆囊区压痛，墨菲征（+）；\r3.辅助检查：超声、CT或MRCP怀疑或提示胆囊结石。\r4.实验室检查：血常规检查显示白细胞总数升高，中性粒细胞百分比升高，偶见血清总胆红素及结合胆红素增高，血清转氨酶和碱性磷酸酶升高。\r（三）\n1. 胆囊结石合并急性胆囊炎（ICD-10：K80.0）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【临床路径·治疗方案的选择】\n治疗方案的选择\r根据《临床诊疗指南\n普通外科分册》（人民卫生出版社，2006年，第1版），全国高等学校教材《外科学》（人民卫生出版社，2013年，第8版）。\r行开腹胆囊切除术。\r（四）","临床路径·进入路径标准":"进入路径标准\r1.第一诊断必须符合ICD-10：K80.0胆囊结石合并胆囊炎。\r2.当患者合并其他疾病，但住院期间不需要特殊处理也不影响第一诊断的临床路径流程实施时，可以进入路径。\r（六）明确诊断及入院常规检查\n2天\r1.","临床路径·标准住院日":"标准住院日为\n7天\r（五）","临床路径·出院标准":"出院标准 \r1.一般状况好，体温正常，无明显腹痛。\r2.恢复肛门排气排便，可进半流质饮食。\r2.实验室检查基本正常。\r3.切口愈合良好：引流管拔除，伤口无感染，无皮下积液（或门诊可处理的少量积液），可门诊拆线。\r（十一）","临床路径·变异及原因分析":"变异及原因分析\r1.术前合并其他基础疾病影响手术的患者，需要进行相关的诊断和治疗。\r2.不同意手术患者，退出本路径。\r3.术中发现肝胆管结石和（或）炎症、胆管癌、肝癌，则进入相应路径。\r4.有并发症（胆漏、出血等）的患者，则转入相应路径。\r\r\r\r\r\r\r\r\r\r二、胆囊结石合并急性胆囊炎","资料来源":"国家卫健委《224个病种临床路径（2019年版）》（国卫办医函〔2019〕933号）· 普通外科临床路径（2019年版） · 胆囊结石合并急性胆囊炎临床路径（2019年版）.doc"},"icd10_diagnosis":"K80.0","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2629,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"fd8254cfee04db63b647d5fc15598f75b438ce16d06e1739ff3993a253e03e71","pinyin":"dannangjieshihebingjixingdannangyan","initials":"dnjshbjxdny","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","临床路径·进入路径标准","临床路径·标准住院日","临床路径·出院标准","临床路径·变异及原因分析","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 临床路径·进入路径标准 临床路径·标准住院日 临床路径·出院标准 临床路径·变异及原因分析 资料来源",30],["主要诊断编码","K80.0",30]]},{"id":"templates-a2f987b6d571f19f4f93","key":"v1-c9ccc21dfe2a3058|templates-a2f987b6d571f19f4f93","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"胆总管结石","category":"肝胆外科","raw":{"name":"胆总管结石","category":"肝胆外科","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文·卫健委临床路径原文】右上腹或剑突下绞痛，阵发性加重，向右肩背部放射、寒战、发热（合并胆管炎时），黄疸（结石嵌顿梗阻时）、恶心、呕吐、食欲减退，尿色加深、大便颜色变浅、无症状者仅在体检超声/MRCP时发现胆管扩张或结石、合并急性胰腺炎时出现上腹持续剧痛、向腰背放射、腹胀。\n【待人工确认·本机素材无此段原文】","现病史":"胆总管结石分为继发性（胆囊结石排入胆总管）与原发性（胆管内形成，多与胆道感染、胆汁淤积、寄生虫有关）。可无症状，也可引起胆绞痛、梗阻性黄疸、急性胆管炎、急性胰腺炎，是外科常见急症。\n常见表现：右上腹或剑突下绞痛，阵发性加重，向右肩背部放射、寒战、发热（合并胆管炎时），黄疸（结石嵌顿梗阻时）、恶心、呕吐、食欲减退，尿色加深、大便颜色变浅、无症状者仅在体检超声/MRCP时发现胆管扩张或结石、合并急性胰腺炎时出现上腹持续剧痛、向腰背放射、腹胀。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：体温、脉搏、血压（评估感染与休克）\n皮肤黏膜：巩膜及皮肤黄染程度、抓痕（胆汁淤积性瘙痒）、脱水征\n腹部视诊：右上腹膨隆、呼吸运动受限、手术瘢痕\n腹部触诊：右上腹压痛、Murphy征、肝区叩击痛、有无腹膜刺激征\n腹部叩诊：肝浊音界、移动性浊音\n腹部听诊：肠鸣音（合并胰腺炎时减弱或消失）\n一般情况：营养状态、体重变化（长期胆道疾病）","辅助检查":"1. 肝功能+胆红素（总/直接）+ALP+GGT：判断梗阻部位与程度，治疗后观察胆红素下降\n2. 血常规+CRP+PCT：评估感染程度，合并胆管炎时显著升高\n3. 血培养+胆汁培养及药敏：发热或引流时留取，指导抗生素选择\n4. 淀粉酶+脂肪酶：排除/评估合并急性胰腺炎\n5. 凝血功能：梗阻性黄疸影响维生素K吸收，术前必查\n6. MRCP（或腹部超声+CT）：明确结石位置、数目、胆管扩张及解剖变异\n7. 尿常规+尿胆原/胆红素：辅助判断梗阻性黄疸\n\n【临床路径·住院期间检查项目】\n必需的检查项目\n（1）血常规，尿常规，大便常规＋隐血。\n（2）肝肾功能、电解质、血糖、血淀粉酶、血型、Rh因子、凝血功能、感染性疾病筛查（乙型肝炎、丙型肝炎、艾滋病、梅毒等）。\n（3）腹部超声、心电图、X线胸片。\n2.根据患者病情可选择的检查：超声心动、腹部CT、MRI/MRCP、超声内镜（EUS）等。\n（七）","初步诊断":"1. 肝功能+胆红素：直接胆红素、ALP、GGT升高提示胆道梗阻\n2. 血常规+CRP+PCT：合并感染时升高；血培养（发热者）\n3. 腹部超声：可见胆管扩张、结石回声（末端结石常显示不清）\n4. MRCP：无创首选，明确结石部位、数目、大小及胆管解剖\n5. CT：评估有无胰腺炎、胆管炎并发症及胆管壁情况\n6. ERCP：诊疗一体，可同时取石；疑结石嵌顿或需治疗时选用\n7. 淀粉酶/脂肪酶：疑合并急性胰腺炎时必查\n【临床路径·诊断依据】\n诊断依据\n根据《实用内科学》（复旦大学上海医学院《实用内科学》编委会编著，人民卫生出版社，2017年，第15版），《黄家驷外科学》（吴孟超、吴在德主编，人民卫生出版社，2008年，第7版），《内镜下逆行胰胆管造影术（ERCP）诊治指南（2010版）》[中华医学会消化内镜分会ERCP学组.中华消化内镜杂志,2010,27(3):113-118; 2010,27(4):169-172; 2010,27(5):225-228.]，《急性胆道系统感染的诊断和治疗指南（2011版）》[中华医学会外科学分会胆道外科学组.中华消化外科杂志,2011, 10(1):9-13.]，《中国急性胰腺炎诊治指南（2013版）》[中华医学会消化病分会胰腺疾病学组.中华消化杂志,2013,33（4）:217-222.]。\n1.胆绞痛、梗阻性黄疸、急性胆管炎[即查科三联征（Charcot triad）：腹痛、黄疸、发热]或胆源性急性胰腺炎。\n2.实验室检查：在急性发作期，血常规检查可见白细胞和中性粒细胞升高，肝功能检查可见胆红素、碱性磷酸酶（ALP）、-谷氨酰转肽酶（GGT）及血清转氨酶（ALT、AST）不同程度升高，合并胆源性急性胰腺炎可见淀粉酶（AMY）和脂肪酶（LIP）升高。\n3.辅助检查：腹部超声、CT、MRI/MRCP或超声内镜（EUS）怀疑或提示胆总管结石。\n（三）\n1. 胆总管结石（ICD-10：K80.5）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：请根据病情选择，切勿全部同时使用！\n\n方案1（抗感染，合并胆管炎时）：\n 用法：头孢曲松 2g 静滴 qd + 甲硝唑 0.5g 静滴 q8h；重症用哌拉西林他唑巴坦 4.5g q8h\n\n方案2（解痉止痛，诊断明确后）：\n 用法：间苯三酚 40～80mg 静滴/静推 必要时（可重复）；或山莨菪碱 10mg 肌注\n\n方案3（补液支持）：\n 用法：平衡盐溶液 500～1000ml 静滴；呕吐明显者补钾（见尿补钾）\n\n📌 禁用吗啡（引起Oddi括约肌痉挛加重梗阻）；使用抗菌药物前留取血培养。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：同类药物选一种，切勿重复用药！\n\n药物1（利胆溶石，仅适用于部分胆固醇结石）：\n 用法：熊去氧胆酸 250mg tid（疗程6～24个月，需定期复查）\n\n药物2（抗感染序贯）：\n 用法：头孢克肟 0.1g bid 或 左氧氟沙星 0.5g qd + 甲硝唑 0.4g tid\n\n药物3（对症）：\n 用法：铝碳酸镁 1.0g tid（胃部不适）；消旋山莨菪碱 10mg 必要时\n\n📌 有症状的胆总管结石以取石/手术为主，药物不能替代解除梗阻。\n\n【治疗】\nERCP+EST取石：首选（尤其单发、直径<1.5cm、无解剖禁忌），可同时放置ENBD或支架\n腹腔镜/开腹胆总管切开取石+T管引流：结石大、多发、嵌顿或ERCP失败者\n腹腔镜胆囊切除+胆总管探查：合并胆囊结石者一并处理\n合并急性胆管炎：先紧急胆道减压引流（ENBD/PTCD），病情稳定后再取石\n合并急性胰腺炎：按胰腺炎规范治疗（禁食、抑酸抑酶、补液），择期处理结石\n对症治疗：解痉止痛、补液、纠正电解质紊乱、抗感染\n\n【处理要点】\n观察腹痛、体温、黄疸变化，记录大便颜色及尿色\nT管护理：妥善固定、防脱出，记录胆汁量（正常300～700ml/日）与性状，术后2周经T管造影后决定拔管\n饮食：低脂饮食，避免暴饮暴食及油腻餐\n术后观察有无胆漏（腹痛、发热、引流液胆汁样）、出血及胰腺炎表现\n定期复查超声/MRCP，监测结石残留或复发\n合并糖尿病、高脂血症者控制基础疾病\n\n【护理】\n腹痛观察：注意疼痛部位、性质、持续时间及有无腹膜刺激征，禁用吗啡类镇痛药\nT管/ENBD护理：妥善固定防脱出，记录引流量与颜色，避免牵拉及逆行感染\n黄疸护理：皮肤瘙痒者温水擦洗、勿抓破，剪短指甲，必要时遵医嘱用药\n饮食护理：低脂饮食，少量多餐，避免油腻及暴饮暴食，术前禁食禁水\n术后观察：腹痛、发热、引流液性状、切口渗液，警惕胆漏、出血与胰腺炎\n\n【饮食】\n急性发作期禁食禁水，静脉补充营养与液体\n缓解期低脂流质/半流质，逐步过渡到低脂普食\n长期低脂饮食：少食动物内脏、蛋黄、油炸食品，多用蒸煮炖\n规律早餐、少量多餐，避免长时间空腹（利于胆汁排空）\n多饮水，多食新鲜蔬菜水果，控制体重与血脂\n\n【注意事项】\n胆总管结石一旦引起梗阻性黄疸或胆管炎，须尽早解除梗阻，不宜长期观察\nERCP术后需观察有无胰腺炎（术后淀粉酶升高+腹痛）、出血、穿孔\nT管拔管前必须确认胆道通畅（造影无残留结石、无梗阻）\n原发性胆总管结石复发率高，术后需定期随访\n\n【急诊/急救】\n寒战高热+黄疸+腹痛（Charcot三联征）或伴休克、神志改变 → 紧急胆道引流\n上腹持续剧痛向腰背放射伴呕吐（合并急性胰腺炎）→ 急诊处理并禁食\n腹痛突然加剧伴腹膜刺激征（胆道穿孔/胆汁性腹膜炎）→ 急诊手术\n\n【临床路径·治疗方案的选择】\n治疗方案的选择\n根据《实用内科学》（复旦大学上海医学院《实用内科学》编委会编著，人民卫生出版社，2017年，第15版），《黄家驷外科学》（吴孟超、吴在德主编，人民卫生出版社，2008年，第7版），《内镜下逆行胰胆管造影术（ERCP）诊治指南（2010版）》[中华医学会消化内镜分会ERCP学组.中华消化内镜杂志,2010,27(3):113-118; 2010,27(4):169-172; 2010,27(5):225-228.]，《急性胆道系统感染的诊断和治疗指南（2011版）》[中华医学会外科学分会胆道外科学组.中华消化外科杂志,2011, 10(1):9-13.]，《中国急性胰腺炎诊治指南（2013版）》[中华医学会消化病分会胰腺疾病学组.中华消化杂志,2013,33（4）:217-222.]。\n1.对症治疗。\n2.抗感染治疗。\n3.根据患者病情行急诊或择期内镜下胆总管取石术。 \n（四）\n\n【临床路径·选择用药】\n选择用药\n1.抗菌药物：按照《抗菌药物临床患者指导原则（2015版）》（国卫办医发〔2015〕43号）执行，并结合患者的病情决定抗菌药物的选择与使用时间。\n2.对比剂选择：碘过敏试验阴性者，选用泛影葡胺；碘过敏试验阳性者，选用有机碘对比剂。 \n（八）内镜治疗（ERCP）日为入院第1～4天\n1.操作前患者静脉镇静药、解痉药及口咽部局部麻醉剂。\n2.行无痛内镜时，术中需监测生命体征，术后要在内镜室观察至清醒，并经麻醉医师同意后返回病房。\n3.术中根据病情可能使用胆管支架或鼻胆引流管。\n4.ERCP术中明确胆管结石，先行EST或球囊扩张，然后网篮和（或）球囊取石。\n（九）治疗后住院恢复1～4天\n1.必须复查的检查项目：血常规、肝肾功能、电解质、血淀粉酶。\n2.术后用药：患者抗菌谱覆盖革兰阴性杆菌和厌氧菌，并主要从胆汁排泄的广谱抗菌药物。\n3.严密观察有否胰腺炎、胆道感染、穿孔、出血等并发症，并作相应处理。\n（十）","临床路径·进入路径标准":"进入路径标准\n1.第一诊断必须符合ICD-10：K80.3/K80.4/K80.5胆总管结石疾病编码。\n2.当患者同时具有其他疾病诊断，但在住院期间不需要特殊处理也不影响第一诊断的临床路径流程实施时，可以进入路径。\n（六）入院第1～2天\n1.","临床路径·标准住院日":"标准住院日为7～10天\n（五）","临床路径·出院标准":"出院标准\n1.一般状况好，体温正常，无明显腹痛，腹部体征阴性。\n2.实验室检查基本正常。\n3.无需要住院治疗的并发症。\n（十一）","临床路径·变异及原因分析":"变异及原因分析\n1.出现并发症（ERCP相关性胰腺炎、胆道感染、出血、穿孔及麻醉意外等）转入相应临床路径。\n2.合并胆管狭窄、占位者转入相应临床路径。\n3.巨大结石需要内镜下机械或激光碎石，或需要多次内镜下取石等转入相应临床路径。\n4.合并胆囊结石、肝内胆管结石者，已完成ERCP取石可列为路径完成，相应疾病转入相应临床路径。\n5.合并妊娠、心脏起搏器植入后等不宜接触X线或电外科设备（ESU）者，进入其他相应路径。\n6. 消化道重建术后患者行ERCP有较大的难度及风险，建议由经验丰富的内镜医师操作或转入其他路径，其中Roux-en-Y 术后ERCP多需要小肠镜辅助，转入其他路径。","资料来源":"疾病库 diseases.json；国家卫健委《224个病种临床路径（2019年版）》（国卫办医函〔2019〕933号）· 消化病临床路径（2019年版） · 胆总管结石临床路径（2019年版）.docx"},"icd10_diagnosis":"K80.5","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2630,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"f14236942204645a4c81a7350f30f0a2eeba88faed3cb152e6815ad35dcb228a","pinyin":"danzongguanjieshi","initials":"dzgjs","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","临床路径·进入路径标准","临床路径·标准住院日","临床路径·出院标准","临床路径·变异及原因分析","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 临床路径·进入路径标准 临床路径·标准住院日 临床路径·出院标准 临床路径·变异及原因分析 资料来源",30],["主要诊断编码","K80.5",30]]},{"id":"templates-2976c04aab12e8ef25e7","key":"v1-c9ccc21dfe2a3058|templates-2976c04aab12e8ef25e7","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"胆管癌","category":"外科常见","raw":{"name":"胆管癌","category":"外科常见","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】进行性无痛性梗阻性黄疸、皮肤瘙痒、尿色加深、陶土样大便、右上腹或上腹部隐痛、不适、食欲减退、消瘦、乏力、合并胆管炎时发热、寒战、恶心、呕吐，晚期可及腹部包块。\n【待人工确认·本机素材无此段原文】","现病史":"起源于胆管上皮的恶性肿瘤，分为肝内、肝门部及肝外胆管癌，典型表现为进行性梗阻性黄疸\n常见表现：进行性无痛性梗阻性黄疸、皮肤瘙痒、尿色加深、陶土样大便、右上腹或上腹部隐痛、不适、食欲减退、消瘦、乏力、合并胆管炎时发热、寒战、恶心、呕吐，晚期可及腹部包块。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：合并胆管炎时体温升高、心率增快、血压下降\n一般情况：消瘦、乏力、营养不良貌\n皮肤黏膜：皮肤巩膜明显黄染，可见抓痕\n腹部：右上腹压痛，肝大，Courvoisier征阳性（胆总管梗阻致胆囊增大）\n淋巴结：锁骨上、腹股沟等浅表淋巴结可触及肿大","辅助检查":"1. 肝功能+胆红素：梗阻性黄疸特征，ALP、GGT明显升高\n2. 肿瘤标志物CA19-9、CEA：辅助诊断及疗效监测\n3. 凝血功能：梗阻性黄疸时常延长（维生素K吸收障碍）\n4. 腹部超声：首选筛查，示肝内外胆管扩张、胆管壁增厚或占位\n5. CT/MRCP：明确肿瘤部位、范围及与血管关系，MRCP为无创胆道成像金标准\n6. ERCP/PTC活检病理：确诊的金标准","初步诊断":"1. 肝功能示梗阻性黄疸：总胆红素、直接胆红素、ALP、GGT升高\n2. 肿瘤标志物CA19-9、CEA升高（需排除胆管炎等良性因素）\n3. 超声、CT、MRCP示胆管扩张及胆管壁增厚或占位\n4. ERCP/PTC胆管造影及刷检、活检病理确诊\n5. PET-CT评估远处转移（拟手术者）\n1. 胆管癌（ICD-10：C24.0）","鉴别诊断":"1. 肿瘤标志物CA19-9、CEA升高（需排除胆管炎等良性因素）\n2. 进行性无痛性黄疸为主要表现，需与胰头癌、壶腹癌、肝细胞癌鉴别\n3. CA19-9升高需排除急性胆管炎等良性梗阻因素","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！\n\n方案1（合并胆道感染）：\n 用法：NS250ml+头孢曲松2.0g ivgtt qd（抗感染）\n\n方案2（黄疸重、进食差者支持治疗）：\n 用法：5%GS250ml+注射用还原型谷胱甘肽1.2g ivgtt qd（护肝）\n\n📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史；梗阻性黄疸患者注意监测凝血功能，必要时补充维生素K1。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！\n\n药物1（利胆退黄）：\n 用法：熊去氧胆酸250mg tid（梗阻性黄疸辅助利胆）\n\n药物2（护肝）：\n 用法：水飞蓟宾胶囊140mg tid（保肝降酶）\n\n📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症；黄疸伴凝血功能障碍者补充维生素K1。\n\n【治疗】\n根治性手术切除：肝内胆管癌行肝切除，肝门部胆管癌行围肝门切除等\n姑息性胆道引流：PTCD或ERCP支架置入解除梗阻\n全身化疗：吉西他滨+顺铂方案（晚期不可切除者）\n局部治疗：放疗、射频消融、TACE等\n靶向及免疫治疗：FGFR2融合、IDH1/2突变者行靶向治疗，联合免疫治疗\n\n【处理要点】\n多学科诊疗（MDT）制定个体化方案\n梗阻性黄疸者充分引流、加强营养支持\n疼痛评估与管理，晚期患者安宁疗护\n定期随访复查肿瘤标志物及影像学\n\n【护理】\n病情观察：观察黄疸程度、尿便颜色变化及有无发热、腹痛，监测生命体征\n皮肤护理：瘙痒明显者温水擦浴、剪短指甲，避免搔抓致皮肤破损\n胆道引流护理：PTCD/ERCP支架术后观察引流液量、性状，保持引流管通畅、妥善固定\n围手术期护理：术前改善营养、补充维生素K1，术后观察出血、胆漏、感染等并发症\n健康宣教：指导高蛋白高维生素饮食，加强营养，定期复查，不适及时就医\n\n【饮食】\n高蛋白、高维生素、易消化饮食，保证足够热量摄入\n低脂饮食：减少油腻食物，减轻胆汁淤积及腹泻\n黄疸患者补充脂溶性维生素（维生素K、A、D、E）\n少量多餐，改善食欲，必要时营养支持（肠内营养）\n戒酒，避免辛辣刺激及粗糙食物\n\n【注意事项】\n进行性无痛性黄疸为主要表现，需与胰头癌、壶腹癌、肝细胞癌鉴别\nCA19-9升高需排除急性胆管炎等良性梗阻因素\n梗阻性黄疸患者警惕凝血功能障碍及术后肝衰竭风险\n\n【急诊/急救】\n急性胆管炎（Charcot三联征：腹痛、寒战高热、黄疸）：急诊抗感染并尽快胆道引流\n胆道梗阻未缓解者黄疸进行性加重，需及时行PTCD/ERCP减黄","资料来源":"疾病库 diseases.json；鉴别诊断库 ddx_local.json（条目「胆管癌」原文）"},"icd10_diagnosis":"C24.0","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2631,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"969f141d6715674aadcf4b8271f403cef815d897377e355f47c8a2247f14519e","pinyin":"danguanai","initials":"dga","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","C24.0",30]]},{"id":"templates-285db66ebd1013bb0355","key":"v1-c9ccc21dfe2a3058|templates-285db66ebd1013bb0355","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"胆管结石(无胆管炎或胆囊炎)","category":"普通外科临床路径（2019年版）","raw":{"name":"胆管结石(无胆管炎或胆囊炎)","category":"普通外科临床路径（2019年版）","case":{"case_name":"门诊病历","templates":{"主诉":"【待人工确认·本机素材无此段原文】","现病史":"【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"检查计划：患者平时无症状或仅有上腹不适，当结石造成胆管梗阻时可出现腹痛或黄疸，入院后完善血常规+血型、尿常规、大便常规+隐血检查，了解有无贫血、感染及消化道出血并备血；完善肝肾功能、电解质、凝血功能检查评估胆道梗阻程度、肝细胞损伤及手术耐受性，完善感染性疾病筛查（乙肝、丙肝、梅毒、HIV）作为手术前必查项目；完善腹部超声检查作为胆道结石首选筛查手段，明确结石部位、胆管扩张及有无胆囊病变；完善心电图、胸部X线平片评估心肺功能，排除心肺基础疾病对手术的影响，老年或合并心脏基础疾病者加做超声心动图检查了解心功能与瓣膜情况；根据患者病情选择肿瘤标志物检查（含CA19-9、CEA）鉴别胆道恶性肿瘤；存在心肺基础疾病或老年体弱患者完善超声心动图、肺功能检测和血气分析，评估麻醉与手术风险；完善上腹部CT或MRCP/MRA检查明确结石位置、数目及胆管解剖，必要时行ERCP检查同时完成诊断与治疗。\n\n（检查清单）\n【临床路径·住院期间检查项目】\n必需的检查项目：\r（1）血常规+血型、尿常规、大便常规+隐血；\r（2）肝肾功能、电解质、凝血功能、感染性疾病筛查；\r（3）腹部超声；\r（4）心电图、胸部X线平片。 \r2.根据患者病情可选择的检查：\r（1）肿瘤标志物检查（含CA19-9、CEA）；\r（2）超声心动图、肺功能检测和血气分析（存在心肺基础疾病或者老年体弱患者）；\r（3）ERCP，上腹部CT或MRCP/MRA。\r（七）","初步诊断":"【临床路径·诊断依据】\n诊断依据\r根据《临床诊疗指南\n普通外科分册》（中华医学会编著，人民卫生出版社，2006年，第1版）、全国高等学校教材《外科学》（人民卫生出版社，2013年，第8版）。\r1.症状：平时无症状或仅有上腹不适，当结石造成胆管梗阻时可出现腹痛或黄疸。\r2.体征：无发作时可无阳性体征，或仅有剑突下和右上腹深压痛。\r3.辅助检查：超声、CT、MR或MRCP怀疑或提示胆总管结石。\r4.实验室检查：血常规检查显示白细胞总数正常或轻微升高，血清总胆红素及结合胆红素正常或轻微升高，血清转氨酶和碱性磷酸酶正常或升高。\r（三）\n1. 胆管结石(无胆管炎或胆囊炎)（ICD-10：K80.5）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【临床路径·治疗方案的选择】\n治疗方案的选择\r根据《临床诊疗指南\n普通外科分册》（人民卫生出版社，2006年，第1版）、全国高等学校教材《外科学》（人民卫生出版社，2013年，第8版）。\r1.根据术前检查所获得的资料，初步判断肝内外胆管结石是否产生急性梗阻、胆管和（或）胆囊有无炎症。\r2.手术治疗：\r（1）诊断明确，无手术禁忌证，择期手术者；\r（2）胆囊切除+胆总管切开取石（包括胆道镜检查并碎石、取石）+胆总管T管引流术（为基本术式），适用于：\r\n 1 \n GB3 \n肝内外胆管多发结石不伴有明显的肝实质纤维化和萎缩； \r\n 2 \n GB3 \n伴有胆汁性肝硬化和门静脉高压症但肝功能处于代偿期；\r（3）胆囊切除+胆管切开取石（包括胆道镜检查并碎石、取石）+肝门部胆管狭窄修复重建术（如胆管狭窄成形+空肠Roux-Y吻合、胆管狭窄成形+游离空肠段吻合、胆管狭窄成形+组织补片修复等术式），适用于结石沿肝内胆管树局限分布于1个或2个肝段内或双侧肝叶胆管内，仅伴有区域性肝实质纤维化和萎缩，以及受累肝脏区段主肝管的狭窄，或合并左右肝管或汇合部以下胆管的严重狭窄；\r（4）胆囊切除+胆管切开取石（包括胆道镜检查并碎石、取石）+肝部分切除术（以肝段、肝叶为单位作规则性切除方式），适用于萎缩的肝叶或肝段，难以取净的多发性结石，并有难以纠正的肝管狭窄或囊性扩张和（或）肝叶段的肝内胆管癌。\r（四）\n\n【临床路径·选择用药】\n选择用药\r1.抗菌药物：按照《抗菌药物临床患者指导原则》（卫医发〔2015〕43号）执行。建议使用第二代头孢菌素，有反复感染史者可选头孢曲松或头孢哌酮或头孢哌酮/舒巴坦；明确感染患者，可根据药敏试验结果调整抗菌药物。\r2.如有继发感染征象，尽早开始抗菌药物的经验治疗。\r3.预防性用抗菌药物，时间为术前0.5小时，手术超过3小时加用1次抗菌药物；总预防性用药时间一般不超过24小时，个别情况可延长至48小时。\r4.在给予抗菌药物治疗之前应尽可能留取相关标本送培养，获病原菌后进行药敏试验，作为调整用药的依据。有手术指征者应进行外科处理，并于手术过程中采集病变部位标本做细菌培养及药敏试验。\r5.对比剂选择：碘过敏试验阴性者，选用泛影葡胺；碘过敏试验阳性者，选用有机碘对比剂。\r（八）手术日为入院第2～3天\r1.麻醉方式：气管内插管局部麻醉或硬膜外麻醉。\r2.手术方式（包括开腹手术或腹腔镜手术）：基本术式为胆囊切除+胆管切开取石（包括胆道镜检查并碎石、取石）加胆总管T管引流术，或加肝门部胆管狭窄修复重建术（如胆管狭窄成形+空肠Roux-Y吻合、胆管狭窄成形+游离空肠段吻合、胆管狭窄成形+组织补片修复等），或加肝部分切除术（以肝段、肝叶为单位作规则性切除方式）。\r3.手术内固定物：无。\r4.术中用药：麻醉常规用药，补充血容量药物（晶体、胶体）、血管活性药物。\r5.输血：根据术前血红蛋白状况及术中出血情况而定。\r（九）术后住院恢复7～8天\r1.必须复查的检查项目：血常规、电解质、肝肾功能。\r2.根据患者病情选择：经T管胆管造影、腹部超声；\r3.术后用药：抗菌药物、制酸剂、肠外营养（视情况）。\r4.各种管道处理：视具体情况尽早拔除胃管、尿管、引流管。\r5.T管处理（一般原则）：拔管时间患者术后2周以上，拔管前试夹T管24～48小时无异常，T管造影显示胆管下段通畅，无狭窄，无胆管内残余结石；T管窦道造影提示窦道形成完整（必要时）。\r6.康复情况检测：监测生命体征、有无并发症发生、胃肠道功能恢复情况、指导患者术后饮食。\r7.伤口护理。\r（十）","临床路径·进入路径标准":"进入路径标准\r1.第一诊断必须符合胆管结石ICD-10：K80.5疾病编码。\r2.患者本人有手术治疗意愿，并符合以下条件：\r（1）结石沿肝内胆管树局限分布于1个或2个肝段内，常合并病变区段肝管的狭窄及受累肝段的萎缩；\r（2）结石遍布双侧肝叶胆管内（包括：不伴有明显的肝实质纤维化和萎缩；或伴有区域性肝实质纤维化和萎缩，合并萎缩肝脏区段主肝管的狭窄；或伴有胆汁性肝硬化和门静脉高压症，合并左右肝管或汇合部以下胆管的严重狭窄，但肝功能处于代偿期）；\r（3）合并肝外胆管结石。\r3.当患者合并其他疾病，但住院期间不需要特殊处理也不影响第一诊断的临床路径流程实施时，可以进入路径。\r（六）术前准备1～2天（工作日）\r1.","临床路径·标准住院日":"标准住院日为9～11天\r（五）","临床路径·出院标准":"出院标准\r1.伤口无感染、引流管拔除。\r2.无发热、血白细胞正常、生命体征平稳。\r3.饮食恢复，无需静脉补液。\r4.不需要住院处理的其他并发症和（或）合并症如胆漏、胰腺炎等。\r（十一）","临床路径·变异及原因分析":"变异及原因分析\r1.患者存在合并症及并发症，如全身重要器官功能不全等，手术风险增高，需要进行相关的诊断和治疗。\r2.术前或术中发现胆管癌、肝癌、胰头癌，或伴有胆汁性肝硬化和门静脉高压症且肝功能失代偿期，则进入相应路径。\r3.围术期由于营养不良，糖代谢异常以及合并症，需延期外科手术，住院时间延长，费用增加。\r4.围术期的并发症和（或）合并症（如术后残留结石），需要进行相关的诊断和治疗，导致住院时间延长、费用增加。\r\r\r\r二、胆管结石（无胆管炎或胆囊炎）","资料来源":"国家卫健委《224个病种临床路径（2019年版）》（国卫办医函〔2019〕933号）· 普通外科临床路径（2019年版） · 胆管结石（无胆管炎或胆囊炎）临床路径（2019年版）.doc"},"icd10_diagnosis":"K80.5","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2632,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"c870bbaa065c76cb78eb6de260a5390d9c99ae05268bc8c9e268f88742f7e63f","pinyin":"danguanjieshi(wudanguanyanhuodannangyan)","initials":"dgjs(wdgyhdny)","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","临床路径·进入路径标准","临床路径·标准住院日","临床路径·出院标准","临床路径·变异及原因分析","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 临床路径·进入路径标准 临床路径·标准住院日 临床路径·出院标准 临床路径·变异及原因分析 资料来源",30],["主要诊断编码","K80.5",30]]},{"id":"templates-53d7820b664d652771f6","key":"v1-c9ccc21dfe2a3058|templates-53d7820b664d652771f6","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"胆管结石合并胆管炎","category":"普通外科临床路径（2019年版）","raw":{"name":"胆管结石合并胆管炎","category":"普通外科临床路径（2019年版）","case":{"case_name":"门诊病历","templates":{"主诉":"【待人工确认·本机素材无此段原文】","现病史":"【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"检查计划：患者出现腹痛、寒战高热、黄疸（Charcot三联征），巩膜可有黄染，剑突下及右上腹深压痛，提示急性胆管炎，入院即刻完善血常规+CRP、降钙素原检查评估感染严重程度，同时完善血培养及尿培养在抗生素使用前留取标本，明确致病菌并指导抗感染治疗；完善肝肾功能检查明确胆红素升高程度及胆道梗阻性质，完善电解质检查评估有无脱水、急性肾损伤及电解质紊乱，完善凝血功能检查判断肝功能储备与手术出血风险，完善感染性疾病筛查（乙肝、丙肝、梅毒、HIV）；完善尿常规、大便常规+隐血检查了解有无胆道出血及泌尿系统感染；完善腹部超声检查明确胆管结石部位、胆管扩张及有无肝脓肿，完善心电图、胸部X线平片评估心肺功能，必要时加做超声心动图检查了解心脏结构与功能；根据病情选择肿瘤标志物（CA19-9、CEA）鉴别胆道肿瘤；老年体弱或合并心肺基础疾病者完善超声心动图、肺功能检测和血气分析；完善上腹部CT或MRCP/MRA明确结石与胆管解剖，必要时行ERCP/ENBD行胆道减压引流，为手术方案提供依据。\n\n（检查清单）\n【临床路径·住院期间检查项目】\n必需的检查项目：\r（1）血常规+血型、尿常规、大便常规+隐血；\r（2）肝肾功能、电解质、凝血功能、感染性疾病筛查；\r（3）腹部超声；\r（4）心电图、胸部X线平片。 \r2.根据患者病情可选择的检查项目：\r（1）肿瘤标志物检查（含CA19-9、CEA）；\r（2）超声心动图、肺功能检测和血气分析（存在心肺基础疾病或者老年体弱患者）；\r（3）上腹部CT或MRCP/MRA。\r（七）","初步诊断":"【临床路径·诊断依据】\n诊断依据\r根据《临床诊疗指南\n普通外科分册》（人民卫生出版社，2006年，第1版），全国高等学校教材《外科学》（人民卫生出版社，2013年，第8版）。\r1.症状：腹痛、寒战高热、黄疸。\r2.体征：巩膜可有黄染，有剑突下和右上腹深压痛及局部腹膜炎征象，肝区有叩击痛。\r3.辅助检查：超声、CT、MR或MRCP怀疑或提示胆总管结石。\r4.实验室检查：血常规检查显示白细胞总数升高，中性粒细胞百分比升高，血清总胆红素及结合胆红素增高，血清转氨酶和碱性磷酸酶升高。\r（三）\n1. 胆管结石合并胆管炎（ICD-10：K80.3）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【临床路径·治疗方案的选择】\n治疗方案的选择\r根据《临床诊疗指南\n普通外科分册》（人民卫生出版社，2006年，第1版），全国高等学校教材《外科学》（人民卫生出版社，2013年，第8版）。\r1.胆囊切除+胆管切开取石（包括胆道镜检查并碎石、取石）+胆总管T管引流术（为基本术式），适用于：\r（1）急症和重症病例；\r（2）肝内胆管结石不伴有明显的肝实质纤维化和萎缩；\r（3）伴有胆汁性肝硬化和门静脉高压症但肝功能处于代偿期。\r2.胆囊切除+胆管切开探查、取石（包括胆道镜检查并碎石、取石）+肝门部胆管狭窄修复重建术（如胆管狭窄成形+空肠Roux-Y吻合、胆管狭窄成形+游离空肠段吻合、胆管狭窄成形+组织补片修复等术式），适用于结石沿肝内胆管树局限分布于1个或2个肝段内或双侧肝叶胆管内，仅伴有区域性肝实质纤维化和萎缩，以及受累肝脏区段主肝管的狭窄，或合并左右肝管或汇合部以下胆管的严重狭窄。\r3.胆囊切除+胆管切开取石（包括胆道镜检查并碎石、取石）+肝部分切除术（以肝段、肝叶为单位作规则性切除方式），适用于萎缩的肝叶或肝段，难以取净的多发性结石，并有难以纠正的肝管狭窄或囊性扩张和（或）慢性肝脓肿和（或）肝叶段的肝内胆管癌。\r（四）\n\n【临床路径·选择用药】\n选择用药\r1.抗菌药物：按照《抗菌药物临床患者指导原则》（卫医发〔2015〕43号）执行。建议使用第二代头孢菌素，有反复感染史者可选头孢曲松或头孢哌酮或头孢哌酮/舒巴坦；明确感染患者，可根据药敏试验结果调整抗菌药物。\r2.在给予抗菌药物治疗之前应尽可能留取相关标本送培养，获病原菌后进行药敏试验，作为调整用药的依据。有手术指征者应进行外科处理，并于手术过程中采集胆汁做细菌培养及药敏试验。\r3.尽早开始抗菌药物的经验治疗。经验治疗需选用能覆盖肠道革兰阴性杆菌、肠球菌属等需氧菌和脆弱拟杆菌等厌氧菌的药物。一般宜用至体温正常、症状消退后72～96小时。\r4.对比剂选择：碘过敏试验阴性者，选用泛影葡胺；碘过敏试验阳性者，选用有机碘对比剂。\r（八）手术日为入院第3～4天\r1.麻醉方式：气管内插管全身麻醉或硬膜外麻醉。\r2.手术方式（包括开腹手术或腹腔镜手术）：基本术式为胆管切开取石（包括胆道镜检查并碎石、取石），或加胆总管T管引流术，或加肝门部胆管狭窄修复重建术（如胆管狭窄成形+空肠Roux-Y吻合、胆管狭窄成形+游离空肠段吻合、胆管狭窄成形+组织补片修复等），或加肝部分切除术（以肝段、肝叶为单位作规则性切除方式）。应严格掌握胆管空肠Roux-en-Y吻合术和胆管-游离空肠段吻合术的适应症（合并Oddi括约肌松弛或狭窄者），原则上不行胆管十二指肠吻合术。\r3.术中用药：麻醉常规用药，补充血容量药物（晶体、胶体）、血管活性药物。\r4.输血：根据术前血红蛋白状况及术中出血情况而定。\r（九）术后住院恢复7～9天\r1.必须复查的检查项目：血常规、血电解质、肝肾功能。\r2.根据患者病情选择：经T管胆管造影、腹部超声等。\r3.术后用药：抗菌药物、制酸剂、静脉营养（视情况）。\r4.各种管道处理：视具体情况尽早拔除胃管、尿管、引流管。\r5.T管处理（一般原则）：拔管时间患者术后2周以上，拔管前试夹T管24～48小时无异常，T管造影显示胆管下段通畅，无狭窄，无胆管内残余结石；T管窦道造影提示窦道形成完整（必要时）。\r6.康复情况检测：监测生命体征、有无并发症发生、胃肠道功能恢复情况、指导患者术后饮食。\r7.伤口护理。\r（十）","临床路径·进入路径标准":"进入路径标准\r1.第一诊断必须符合ICD-10：K80.3胆管结石合并胆管炎疾病编码。\r2.患者本人有手术治疗意愿，并符合以下条件：\r（1）结石沿肝内胆管树局限分布于1个或2个肝段内，常合并病变区段肝管的狭窄及受累肝段的萎缩；\r（2）肝内胆管多发结石（包括：不伴有明显的肝实质纤维化和萎缩；或伴有区域性肝实质纤维化和萎缩，合并萎缩肝脏区段主肝管的狭窄；或伴有胆汁性肝硬化和门静脉高压症，合并左右肝管或汇合部以下胆管的严重狭窄，但肝功能处于代偿期）；\r（3）合并肝外胆管结石。\r3.当患者合并其他疾病，但住院期间不需要特殊处理也不影响第一诊断的临床路径流程实施时，可以进入路径。\r（六）术前准备1～3天（指工作日）\r1.","临床路径·标准住院日":"标准住院日为10～13天\r（五）","临床路径·出院标准":"出院标准\r1.伤口无感染、引流管拔除。\r2.无发热、血白细胞正常、生命体征平稳。\r3.饮食恢复，无需静脉补液。\r4.不需要住院处理的其他并发症和（或）合并症如胆漏、胰腺炎等。\r（十一）","临床路径·变异及原因分析":"变异及原因分析\r1.患者存在合并症及并发症，如全身重要器官功能不全等，手术风险增高，需要进行相关的诊断和治疗。\r2.术前或术中发现胆管癌、肝癌、胰头癌、肝脓肿，或伴有胆汁性肝硬化和门静脉高压症且肝功能失代偿期，则进入相应路径。\r3.围术期由于营养不良、脓毒血症、糖代谢异常以及合并症，需延期外科手术，住院时间延长，费用增加。\r4.围术期的并发症和（或）合并症（如术后残留结石），需要进行相关的诊断和治疗，导致住院时间延长、费用增加。\r\r\r\r\r\r\r二、胆管结石合并胆管炎","资料来源":"国家卫健委《224个病种临床路径（2019年版）》（国卫办医函〔2019〕933号）· 普通外科临床路径（2019年版） · 胆管结石合并胆管炎临床路径（2019年版）.doc"},"icd10_diagnosis":"K80.3","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2633,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"47f9b8df5886a41afd41b49716a86b70f110db44930533ce093a1707d21027ab","pinyin":"danguanjieshihebingdanguanyan","initials":"dgjshbdgy","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","临床路径·进入路径标准","临床路径·标准住院日","临床路径·出院标准","临床路径·变异及原因分析","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 临床路径·进入路径标准 临床路径·标准住院日 临床路径·出院标准 临床路径·变异及原因分析 资料来源",30],["主要诊断编码","K80.3",30]]},{"id":"templates-6348979e53c0d126b322","key":"v1-c9ccc21dfe2a3058|templates-6348979e53c0d126b322","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"胆道术后胆漏","category":"肝胆外科","raw":{"name":"胆道术后胆漏","category":"肝胆外科","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】术后腹痛（右上腹或全腹）、腹胀，可伴腹膜刺激征（胆汁性腹膜炎）、发热（多为低热至中度热），白细胞升高、腹腔引流管引出胆汁样液体（金黄色、黄绿色），量可多可少、无引流管者出现腹腔积液、腹胀与肠麻痹、严重者出现黄疸（胆道梗阻或损伤）、胆汁性腹膜炎致脓毒症。\n【待人工确认·本机素材无此段原文】","现病史":"胆漏是胆道手术（胆囊切除、胆总管探查、肝切除、胆肠吻合）后胆汁从胆道系统漏出至腹腔或引流管，发生率约0.5%～2%，多因胆囊管残端处理不当、迷走胆管损伤、胆总管损伤或吻合口漏所致。表现为腹痛、发热、引流液呈胆汁样，需充分引流+抗感染，必要时内镜或手术处理。\n常见表现：术后腹痛（右上腹或全腹）、腹胀，可伴腹膜刺激征（胆汁性腹膜炎）、发热（多为低热至中度热），白细胞升高、腹腔引流管引出胆汁样液体（金黄色、黄绿色），量可多可少、无引流管者出现腹腔积液、腹胀与肠麻痹、严重者出现黄疸（胆道梗阻或损伤）、胆汁性腹膜炎致脓毒症。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：体温、脉搏、血压（感染与休克评估）\n一般情况：精神、营养状态、有无黄疸与脱水\n腹部视诊：切口愈合情况（有无渗液、红肿）、腹胀、手术瘢痕\n腹部触诊：压痛部位与范围、反跳痛、肌紧张（胆汁性腹膜炎）、肝区叩击痛\n腹部叩诊：移动性浊音（腹腔积液）、肝浊音界\n引流管：位置、引流量与性状（胆汁样）、周围皮肤情况\n腹部听诊：肠鸣音（肠麻痹时减弱或消失）","辅助检查":"1. 引流液胆红素+淀粉酶：与血清对比（胆红素>血清3倍提示胆漏；淀粉酶高提示胰漏）\n2. 肝功能+胆红素+ALP/GGT：评估胆道梗阻与损伤程度，动态观察\n3. 血常规+CRP+PCT：感染程度评估，每2～3天复查\n4. 血培养+引流液培养及药敏：发热或感染加重时留取\n5. 腹部超声/CT：评估腹腔积液部位与量（可引导穿刺引流）\n6. MRCP/ERCP：明确胆漏部位与胆道损伤程度，同时可行治疗\n7. 电解质+白蛋白+肾功能：评估营养状态与液体丢失","初步诊断":"1. 引流液检查：胆红素浓度显著高于血清（>血清3倍）可确诊胆漏；测淀粉酶排除胰漏\n2. 腹部超声/CT：评估腹腔积液部位与量（可引导穿刺引流）\n3. MRCP/肝胆核素扫描（HIDA）：明确胆漏部位与胆道是否通畅\n4. ERCP/胆道造影（经T管或ENBD）：诊断胆漏部位及胆管损伤程度，同时可行治疗（支架/鼻胆管引流）\n5. 血常规+CRP+PCT+肝功能（胆红素）：评估感染与胆道梗阻\n6. T管造影（术后2周）：评估胆道通畅性与有无残余结石、胆漏\n1. 胆道术后胆漏（ICD-10：K83.8）","鉴别诊断":"1. 测淀粉酶排除胰漏\n2. 同时注意与胰漏、淋巴漏鉴别\n3. 诊断要点：引流液检查：胆红素浓度显著高于血清（>血清3倍）可确诊胆漏；测淀粉酶排除胰漏\n4. 诊断要点：腹部超声/CT：评估腹腔积液部位与量（可引导穿刺引流）\n5. 诊断要点：MRCP/肝胆核素扫描（HIDA）：明确胆漏部位与胆道是否通畅\n6. 诊断要点：ERCP/胆道造影（经T管或ENBD）：诊断胆漏部位及胆管损伤程度，同时可行治疗（支架/鼻胆管引流）\n7. 诊断要点：血常规+CRP+PCT+肝功能（胆红素）：评估感染与胆道梗阻\n8. 诊断要点：T管造影（术后2周）：评估胆道通畅性与有无残余结石、胆漏","处理方案":"【药物治疗·输液】\n⚠️ 按病情选择方案，切勿全部同时使用！\n\n方案1（抗感染，覆盖肠道菌群）：\n 用法：头孢曲松 2g 静滴 qd + 甲硝唑 0.5g 静滴 q8h；或哌拉西林他唑巴坦 4.5g 静滴 q8h（重症）\n\n方案2（抑酸抑酶，减少胆胰分泌）：\n 用法：艾司奥美拉唑 40mg 静推 q12h；生长抑素 3mg/12h 泵入 或 奥曲肽 25～50μg/h（必要时）\n\n方案3（保肝与营养支持）：\n 用法：还原型谷胱甘肽 1.2g 静滴 qd + 腺苷蛋氨酸 1g 静滴 qd；全肠外营养（禁食者）；白蛋白 10g 静滴（低蛋白）\n\n方案4（补液与电解质）：\n 用法：平衡盐溶液/0.9%氯化钠 静滴（按引流量与尿量补足）；纠正低钾低钠\n\n📌 胆漏治疗核心是『充分引流+保持胆道通畅』；抗生素不能替代引流。\n\n【药物治疗·口服】\n⚠️ 恢复期遵医嘱，同类只选一种：\n\n药物1（利胆）：\n 用法：熊去氧胆酸 250mg tid 或 腺苷蛋氨酸肠溶片 500mg bid\n\n药物2（保肝）：\n 用法：多烯磷脂酰胆碱 456mg tid\n\n药物3（抗感染序贯）：\n 用法：头孢克肟 0.1g bid + 甲硝唑 0.4g tid 或 阿莫西林克拉维酸 0.625g tid\n\n📌 引流期间避免剧烈活动与用力（防引流管脱出）；T管需妥善固定并按医嘱拔管。\n\n【治疗】\n充分引流：经皮穿刺置管/原引流管保持通畅，多数小胆漏经充分引流可自愈（1～2周）\n内镜治疗（首选干预手段）：ERCP+EST+鼻胆管（ENBD）或胆道支架置入，降低胆道压力促进漏口愈合\n抗生素：覆盖肠道菌群，按培养调整，合并胆汁性腹膜炎时加强\n营养支持：禁食、全肠外营养；肠功能允许时经鼻空肠管肠内营养；补充白蛋白\n手术指征：腹腔引流不畅、胆汁性腹膜炎、胆管横断或损伤、内镜治疗失败——行胆管修补、T管引流或胆肠吻合\n胆道通畅维护：T管/ENBD妥善固定，避免牵拉、受压与脱出\n随访：引流减少、症状缓解后逐步退管；复查MRCP/超声评估胆道情况\n\n【处理要点】\n引流观察与记录：每日记录引流量、颜色（金黄色/黄绿/浑浊）与性状，突然增多或减少均需报告\n引流管护理：妥善固定（标记刻度）、防止牵拉脱出、保持通畅，必要时低压冲洗\n腹痛与腹部体征监测：观察腹膜刺激征范围变化（胆汁性腹膜炎加重需紧急处理）\n体温与感染指标：每4小时测体温，动态复查血常规、CRP、PCT与肝功能\n营养与出入量：记录24小时出入量，按引流量补充液体与电解质，监测白蛋白\n皮肤护理：引流口周围胆汁刺激易致皮肤糜烂，及时清洁并涂氧化锌软膏保护\n拔管管理：引流量<20～50ml/日、症状缓解、复查影像无积液后逐步拔管（由主管医师决定）\n\n【护理】\n引流护理：妥善固定并标记刻度，记录引流量与性状，保持通畅，防止牵拉脱出与逆行感染\n皮肤护理：胆汁刺激可致引流口周围皮肤糜烂，及时清洁并涂氧化锌软膏或造口护肤粉\n腹痛与体温观察：每4小时测体温，观察腹痛与腹膜刺激征变化，异常立即报告\n出入量与营养：记录24小时出入量，按引流量补液，遵医嘱给予肠外/肠内营养并观察耐受\n体位与活动：半卧位利于引流，避免剧烈活动与用力（防引流管脱出）\n拔管宣教：告知拔管需循序渐进（先退管后拔除），避免自行拔管\n\n【饮食】\n急性期禁食禁水，行胃肠减压与肠外营养\n引流减少、肠功能恢复后：低脂流质→低脂半流质→低脂软食逐步过渡\n低脂饮食（每日脂肪<40g），减少胆汁分泌与胆道负担\n高蛋白、高维生素饮食促进组织修复（鱼、瘦肉、蛋清、新鲜蔬果）\n禁酒、忌辛辣刺激与油炸食物；少量多餐，避免暴饮暴食\n\n【注意事项】\n胆漏诊断关键：引流液胆红素>血清3倍；同时注意与胰漏、淋巴漏鉴别\n多数小胆漏经充分引流+保持胆道通畅可自愈，避免过早再次手术（局部水肿粘连，手术困难）\n胆囊切除术后迷走胆管（Luschka管）漏较常见，多可自愈；胆总管损伤漏需积极处理\nERCP+ENBD/支架是胆漏的非手术治疗首选，可避免再次手术\n胆汁性腹膜炎可致严重脓毒症，引流不畅者必须及时手术\n\n【急诊/急救】\n腹痛加剧伴全腹腹膜刺激征、血压下降（胆汁性腹膜炎/脓毒症）→ 急诊手术探查\n引流管引出大量鲜血（胆道出血/血管损伤）→ 急诊介入或手术止血\n高热寒战伴黄疸加重（胆道梗阻合并感染）→ 紧急胆道引流","资料来源":"疾病库 diseases.json；鉴别诊断库 ddx_local.json（条目「胆道术后胆漏」原文）"},"icd10_diagnosis":"K83.8","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2634,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"8d148964d7275ee7fd04b5f6eedb391ccac2b2ab4a8ed8759591921a49894664","pinyin":"dandaoshuhoudanlou","initials":"ddshdl","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","K83.8",30]]},{"id":"templates-c06289ef01f2382012eb","key":"v1-c9ccc21dfe2a3058|templates-c06289ef01f2382012eb","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"胎动不安(中医辨证)","category":"中医","raw":{"name":"胎动不安(中医辨证)","category":"中医","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】肾虚：妊娠期腰酸腹痛，胎动下坠，或阴道少量流血，色淡暗，头晕耳鸣，小便频数，或曾屡孕屡堕，舌淡苔白，脉沉滑尺弱、气血虚弱：妊娠期小腹坠痛，胎动下坠，阴道少量流血，色淡质稀，头晕眼花，心悸气短，面色晄白，舌淡苔薄白，脉细滑无力、血热：妊娠期阴道少量流血，色鲜红，质稠，或腰腹坠胀疼痛，心烦不安，手足心热，口干咽燥，舌红苔黄，脉滑数、血瘀：妊娠期阴道少量流血，色紫暗，或有血块，小腹疼痛拒按，舌暗或有瘀点，脉沉涩。\n【待人工确认·本机素材无此段原文】","现病史":"妊娠期出现腰酸腹痛、胎动下坠，或阴道少量流血者，称胎动不安。分肾虚、气血虚弱、血热、血瘀等证型。可见于先兆流产。\n常见表现：肾虚：妊娠期腰酸腹痛，胎动下坠，或阴道少量流血，色淡暗，头晕耳鸣，小便频数，或曾屡孕屡堕，舌淡苔白，脉沉滑尺弱、气血虚弱：妊娠期小腹坠痛，胎动下坠，阴道少量流血，色淡质稀，头晕眼花，心悸气短，面色晄白，舌淡苔薄白，脉细滑无力、血热：妊娠期阴道少量流血，色鲜红，质稠，或腰腹坠胀疼痛，心烦不安，手足心热，口干咽燥，舌红苔黄，脉滑数、血瘀：妊娠期阴道少量流血，色紫暗，或有血块，小腹疼痛拒按，舌暗或有瘀点，脉沉涩。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：体温、脉搏、呼吸、血压\n望诊：面色、神、舌诊（舌质/舌苔）、月经（量色质）、带下（量色质气味）\n闻诊：声音、经带气味\n问诊：月经史（初潮/周期/经期/经量/色质）、带下史、婚育史、既往史、十问歌\n切诊：脉诊、腹诊（小腹压痛/包块）\n辨证：脏腑辨证（肝肾脾）、气血辨证、冲任督带辨证","辅助检查":"检查计划：患者妊娠期出现腰酸腹痛、胎动下坠、阴道少量流血，属胎动不安，辨证有肾虚、气血虚弱、血热、血瘀之分，须先排除异位妊娠、葡萄胎等，入院即刻完善妇科B超检查明确宫内妊娠、孕囊位置、胚胎存活与孕周情况；完善血HCG、孕酮检查了解胚胎滋养细胞活性、评估黄体功能，指导安胎方案；完善血常规检查排除感染、贫血所致胎元不固，并鉴定血型为阴道流血及输血做准备；完善凝血功能及D-二聚体检查评估凝血状态，排除凝血功能障碍所致出血；因安胎用药需经肝肾代谢，完善肝肾功能、电解质检查排除肝肾功能不全及电解质紊乱；患者腰酸、小便频数、屡孕屡堕者，完善甲状腺功能检查排除甲状腺功能减退所致胚胎发育不良，完善TORCH及支原体、衣原体等感染筛查排除宫内感染所致的胎动不安；查尿常规排除泌尿系感染，查尿妊娠试验辅助判断胚胎情况；对阴道流血量多、腰腹坠痛明显者，完善宫颈长度测量及宫颈分泌物检查明确有无宫颈机能不全，必要时完善腹部超声与阑尾炎、卵巢囊肿蒂扭转等急腹症相鉴别。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 妊娠期（早中期多见）腰酸腹痛、胎动下坠、阴道少量流血\n2. B超（孕囊/胎心）、血HCG、孕酮\n3. 排除异位妊娠、葡萄胎等\n1. 胎动不安(中医辨证)（ICD-10：O20.0）","鉴别诊断":"1. 排除异位妊娠、葡萄胎等","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！\n\n方案1：\n 用法：一般不需输液，口服中药调理为主\n\n方案2（出血量多/贫血明显）：\n 用法：5%GS250ml+酚磺乙胺1.0g ivgtt qd；NS500ml+维生素C2.0g ivgtt qd\n\n方案3（合并感染）：\n 用法：NS250ml+头孢呋辛3.0g ivgtt bid（皮试后）；甲硝唑0.5g ivgtt bid\n\n📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！\n\n📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。妊娠期、哺乳期用药务必谨慎！\n\n药物1（肾虚）：滋肾育胎丸6g tid，或寿胎丸1丸 tid\n药物2（气血虚弱）：八珍颗粒6g tid，或胎宝胶囊3粒 tid\n药物3（血热）：保胎无忧片4片 tid\n药物4（配合）：黄体酮10mg im qd（孕酮低时，遵医嘱）\n\n【治疗】\n肾虚：固肾安胎，寿胎丸加减\n气血虚弱：益气养血安胎，胎元饮加减\n血热：清热凉血安胎，保阴煎加减\n血瘀：益气和血安胎，当归芍药散加减\n\n【处理要点】\n卧床休息，禁止性生活\n保持情志舒畅，避免紧张焦虑\n清淡易消化饮食，保持大便通畅\n\n【护理】\n病情观察：密切观察阴道流血量、色、质及小腹坠痛、腰酸程度，若流血量增多、腹痛加剧或见肉样组织排出，立即报告医师并保留排出物备查；每日记录体温及卧床期间二便情况。\n起居调护：嘱绝对卧床休息，减少活动与屏气用力，避免弯腰、提重物及下蹲动作；肾虚者尤须静卧少动、节房事，忌劳累熬夜，卧处避风寒。\n情志护理：向孕妇讲明安胎注意事项以缓解紧张恐惧，嘱家属多陪伴安抚，保持情绪安定，避免忧思恼怒、惊骇伤肾扰动胎气。\n煎药服药护理：安胎药以文火煎煮、温服为宜，少量多次缓缓服下以防呕吐拒药，服后静卧片刻；遵医嘱慎用艾灸等外治，灸肾俞、命门等温肾穴位时注意温度，避免烫伤及过度刺激腹部。\n二便护理：保持大便通畅，便秘者勿用力努挣，可晨起饮温蜂蜜水润肠；血热者忌用热水袋热敷下腹，血瘀者注意腹部保暖、避免寒凉刺激。\n\n【饮食】\n肾虚者：宜补肾安胎，可食山药、芡实、核桃仁、黑豆、黑芝麻，药膳如桑寄生鸡蛋汤、菟丝子粥；忌寒凉生冷之品。\n气血虚弱者：宜益气养血安胎，可用黄芪、党参炖母鸡汤，食大枣、桂圆肉、阿胶（烊化）适量；忌耗气破气之品。\n血热者：宜清热凉血安胎，可食鲜藕、荸荠、丝瓜、冬瓜、绿豆，药膳如苎麻根粥；忌辛辣燥热及羊肉、狗肉、荔枝、桂圆等助热动血之品。\n血瘀者：宜行气化瘀安胎，可饮玫瑰花茶、陈皮粥，少食多餐；忌生冷寒凉及肥甘厚味凝滞之品。\n饮食总以清淡易消化、富营养为原则，少食多餐，忌烟酒、浓茶、咖啡；各类药膳均需在医师辨证指导下选用，不可自行滥补。\n\n【注意事项】\n阴道流血量多、腹痛加剧者立即转妇科急诊\nB超确认胚胎存活后保胎治疗\n反复流产（≥3次）需系统查因（染色体、免疫等）\n\n【急诊/急救】\n一般不需急救\n大出血伴休克：立即急诊抢救\n宫外孕破裂/急性腹痛：立即转妇科急诊","资料来源":"疾病库 diseases.json；鉴别诊断库 ddx_local.json（条目「胎动不安（中医辨证）」原文）","中医辨证参考":"首次病程记录\n\n拟诊讨论：\n\n【中医辨证参考】胎动不安\n（本页列出该病常见证型，请根据患者实际四诊资料选择相应证型，切勿直接套用）\n\n一、肾虚\n    症状舌脉：妊娠期阴道少量出血，色淡暗，腰酸腹坠痛，或伴头晕耳鸣，小便频数，夜尿多，既往有堕胎小产史，舌淡、苔白，脉沉滑尺弱\n    治法：固肾安胎、佐以益气\n    方剂：寿胎丸\n\n二、气虚\n    症状舌脉：妊娠期腰酸腹痛，小腹空坠，阴道少量流血，色淡红，质稀薄，神疲肢倦，气短懒言，面色㿠白，舌淡、苔薄白，脉细滑\n    治法：补气固冲、养血安胎\n    方剂：举元煎\n\n三、血虚\n    症状舌脉：妊娠期腰酸腹痛，胎动下坠，阴道少量流血，色淡红，质稀薄，面色萎黄，头晕心悸，失眠多梦，舌淡、苔薄白，脉细滑\n    治法：补血固冲、养血安胎\n    方剂：苎根汤\n\n四、血热\n    症状舌脉：妊娠期阴道下血，色鲜红或深红，质稠，腰酸腹痛，心烦不安，口干咽燥，小便短黄，大便秘结，舌红、苔黄而干，脉滑数\n    治法：清热凉血、养血安胎\n    方剂：保阴煎\n\n五、跌仆伤胎\n    症状舌脉：妊娠期因跌仆闪挫或劳累后腰酸腹痛，胎动下坠，阴道少量流血，舌暗红、苔薄白，脉滑无力\n    治法：益气养血、固冲安胎\n    方剂：圣愈汤合寿胎丸。来源：《中医妇科学》（中国中医药出版社“十四五”规划教材）·妊娠病·胎动不安\n\n【方剂参考】\n  寿胎丸：组成 菟丝子12g、桑寄生12g、续断12g、阿胶12g（烊化）；功效 补肾安胎\n      用法：水煎，阿胶烊化，温服，日一剂，分二次服；原方为蜜丸，每服6g。\n      注意：须先经产科检查排除异位妊娠、葡萄胎等；阴道出血量多或腹痛剧烈者须立即就医；血热、外伤所致胎动不安非本方所宜。来源：《方剂学》（中国中医药出版社“十四五”规划教材）·补益剂；原方出自《医学衷中参西录·治女科方》\n  举元煎：组成 黄芪15g、人参6g（另煎兑服，或党参15g代）、白术9g、炙甘草6g、升麻6g；功效 益气升阳，举陷摄血\n      用法：水煎温服，日一剂，分二次服。\n      注意：血热妄行、阴虚火旺之出血禁用；实热证忌用；升麻升散，阴虚阳亢者慎用。来源：《方剂学》（中国中医药出版社“十四五”规划教材）·补益剂（补气）；原方出自《景岳全书·新方八阵·补阵》\n  苎根汤：组成 苎麻根30g、干地黄15g、当归9g、白芍12g、阿胶12g（烊化）、甘草6g；功效 养血止血，清热安胎\n      用法：水煎，阿胶烊化，温服，日一剂，分二次服。\n      注意：须先经产科检查排除异位妊娠、葡萄胎、宫颈病变等；出血量多或腹痛剧者须立即就医；脾胃虚寒者慎用。来源：《方剂学》（中国中医药出版社“十四五”规划教材）·理血剂；原方出自《外台秘要》引《小品方》（《金匮要略·妇人妊娠病脉证并治第二十》附方）\n  保阴煎：组成 生地黄12g、熟地黄12g、黄芩9g、黄柏9g、白芍12g、山药12g、续断12g、甘草6g；功效 滋阴清热，凉血止血\n      用法：水煎温服，日一剂，分二次服。\n      注意：脾胃虚寒、阳虚出血者忌用；黄芩、黄柏苦寒，久服易伤脾胃；服药期间忌辛辣燥热之品。来源：《方剂学》（中国中医药出版社“十四五”规划教材）·补益剂（补阴）；原方出自《景岳全书·新方八阵·寒阵》\n  圣愈汤：组成 熟地黄15g、白芍12g、当归9g、川芎6g、人参6g（另煎兑服，或党参15g代）、黄芪15g；功效 益气，补血，摄血\n      用法：水煎温服，日一剂，分二次服；人参宜另煎兑服。\n      注意：血热妄行之月经先期、量多色深者忌用；瘀血阻滞者不宜；服人参期间忌萝卜、浓茶。来源：《方剂学》（中国中医药出版社“十四五”规划教材）·补益剂（补气）；原方出自《医宗金鉴·删补名医方论》（《兰室秘藏》方）\n\n【西医诊断】\n  先兆流产\n  （西医诊断依据与鉴别诊断请结合患者病史、体征、辅助检查补充）\n\n医师签名：＿＿＿＿"},"icd10_diagnosis":"O20.0","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2635,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"e3e22e9b5db3c1274f12183e31cea89fec26bd55715c92e26d9dcb9f5165fad9","pinyin":"taidongbuan(zhongyibianzheng)","initials":"tdba(zybz)","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源","中医辨证参考"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源 中医辨证参考",30],["主要诊断编码","O20.0",30]]},{"id":"templates-167aa99d19efa1e1d94e","key":"v1-c9ccc21dfe2a3058|templates-167aa99d19efa1e1d94e","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"胎膜早破","category":"妇产科","raw":{"name":"胎膜早破","category":"妇产科","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】阴道突然流出液体，量可多可少，时断时续、流液为清亮或淡黄色，可混有胎脂、腹压增加（咳嗽、用力）时流液增多、可伴有宫缩或胎动异常。\n【待人工确认·本机素材无此段原文】","现病史":"临产前胎膜自然破裂，羊水自阴道流出，可增加母儿感染及脐带脱垂风险\n常见表现：阴道突然流出液体，量可多可少，时断时续、流液为清亮或淡黄色，可混有胎脂、腹压增加（咳嗽、用力）时流液增多、可伴有宫缩或胎动异常。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：体温、心率、血压，重点监测有无发热（感染征象）\n腹部检查：宫高、腹围、有无宫缩及压痛\n产科检查：胎心、胎位、先露衔接情况\n窥阴器检查：观察羊水自宫颈口流出情况及性状、颜色","辅助检查":"1. 阴道液pH试纸检测：羊水呈碱性（pH>6.5）\n2. 阴道液涂片：干燥后镜下见羊齿状结晶\n3. 血常规、CRP：评估有无感染\n4. 超声检查：羊水指数评估羊水量及胎儿情况\n5. 必要时羊水细菌培养及药敏试验","初步诊断":"1. 窥阴器检查见液体自宫颈口流出或后穹窿有羊水池\n2. 阴道液pH试纸检测呈碱性（pH>6.5）\n3. 阴道液涂片干燥后见羊齿状结晶\n4. 超声检查羊水量减少\n5. 必要时羊水生化指标（IGFBP-1）检测协助诊断\n1. 胎膜早破（ICD-10：O42.9）","鉴别诊断":"1.与尿失禁、阴道分泌物增多鉴别，确诊靠窥阴器及pH试纸\n2. 诊断要点：窥阴器检查见液体自宫颈口流出或后穹窿有羊水池\n3. 诊断要点：阴道液pH试纸检测呈碱性（pH>6.5）\n4. 诊断要点：阴道液涂片干燥后见羊齿状结晶\n5. 诊断要点：超声检查羊水量减少\n6. 诊断要点：必要时羊水生化指标（IGFBP-1）检测协助诊断\n7. 臀先露、多胎妊娠、宫颈机能不全等为高危因素","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！\n\n方案1（预防感染）：\n 用法：0.9%NS 250ml + 头孢呋辛1.5g，ivgtt bid（破膜>12小时或未足月胎膜早破，无过敏史）\n\n方案2（促胎肺成熟）：\n 用法：地塞米松6mg im q12h，共4次（孕34周前未足月胎膜早破）\n\n📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！\n\n药物1（阿莫西林）：\n 用法：阿莫西林0.5g tid po（对青霉素不过敏者，遵医嘱）\n\n药物2（红霉素）：\n 用法：红霉素250mg qid po（青霉素过敏者未足月胎膜早破预防感染，遵医嘱）\n\n📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。\n\n【治疗】\n确诊后评估孕周、胎儿情况及有无感染征象\n足月胎膜早破：期待24-48小时未临产者引产\n未足月胎膜早破：卧床休息、促胎肺成熟，监测感染\n破膜超过12小时预防性抗感染治疗\n出现绒毛膜羊膜炎或胎儿窘迫时及时终止妊娠\n\n【处理要点】\n监测体温、宫缩、羊水性状及气味，警惕感染\n监测胎心、胎动，定期胎心监护\n查血常规、CRP评估有无宫内感染\n\n【护理】\n绝对卧床休息，抬高臀部或取侧卧位，减少羊水流出及脐带脱垂风险\n密切监测体温、羊水性状、颜色、气味及胎心胎动变化\n会阴护理：保持外阴清洁，使用无菌会阴垫，勤更换，预防逆行感染\n心理护理：解释病情及注意事项，缓解紧张焦虑，配合保胎或引产治疗\n\n【饮食】\n高蛋白饮食：鱼、蛋、瘦肉、奶类，增强抵抗力\n富含维生素C食物：新鲜蔬菜水果，增强组织修复能力\n适量多饮水，保持尿路通畅，预防泌尿系感染\n少食多餐，易消化饮食，避免辛辣刺激性食物\n\n【注意事项】与尿失禁、阴道分泌物增多鉴别，确诊靠窥阴器及pH试纸\n臀先露、多胎妊娠、宫颈机能不全等为高危因素\n破膜时间越长，绒毛膜羊膜炎及脐带脱垂风险越高，需及时处理\n\n【急诊/急救】\n大量流液伴胎心减慢：警惕脐带脱垂，立即抬高臀部、膝胸卧位，急诊处理\n发热、羊水异味、宫体压痛：警惕绒毛膜羊膜炎，立即抗感染并终止妊娠","资料来源":"疾病库 diseases.json；鉴别诊断库 ddx_local.json（条目「胎膜早破」原文）"},"icd10_diagnosis":"O42.9","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2636,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"d92ed05c7189ec767d3e7753d30d2209a209ca9219c8a708ba3a7f0309fce3e0","pinyin":"taimozaopo","initials":"tmzp","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","O42.9",30]]},{"id":"templates-465c7ee09a797de8b37c","key":"v1-c9ccc21dfe2a3058|templates-465c7ee09a797de8b37c","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"胫腓骨干骨折","category":"骨科临床路径（2019年版）","raw":{"name":"胫腓骨干骨折","category":"骨科临床路径（2019年版）","case":{"case_name":"门诊病历","templates":{"主诉":"【待人工确认·本机素材无此段原文】","现病史":"【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"【临床路径·住院期间检查项目】\n必需的检查项目：\r（1）血常规、血型、尿常规+镜检；\r（2）电解质检查、肝功能测定、肾功能测定、凝血功能检查、感染性疾病筛查（乙型肝炎，丙型肝炎，梅毒，艾滋病）；\r（3）胸部X线平片、心电图；\r（4）骨科X线检查。\r2.根据患者病情可选择的检查项目：CT检查、下肢血管超声、血气分析、肺功能检查、超声心动图等。\r（七）预防性抗菌药物选择与使用时机\r1.按照《抗菌药物临床患者指导原则》（卫医发〔2015〕43号）执行，并根据患者的病情决定抗菌药物的选择与使用时间。建议使用第一、二代头孢菌素。\r2.预防性用药时间为术前30分钟；手术超时3小时加用1次；术中出血量大于1500ml时加用1次。\r（八）手术日为入院第1～7天\r1.麻醉方式：椎管内麻醉和（或）全身麻醉。\r2.手术方式：胫腓骨干骨折内固定术。\r3.手术内固定物：钢板螺钉或带锁髓内钉。 \r4.术中用药：麻醉用药、抗菌药。\r5.输血：根据出血情况。\r（九）术后住院恢复6～9天\r1.必须复查的项目：血常规、X线检查。\r2.可选择的检查项目：电解质、肝肾功能、CT。\r3.术后用药：\r（1）抗菌药物使用：抗菌药物使用按照《抗菌药物临床患者指导原则》（卫医发〔2015〕43号）执行，并根据患者的病情决定抗菌药物的选择与使用时间。建议使用第一、二代头孢菌素；\r（2）术后镇痛：参照《骨科常见疼痛的处理专家建议》（《中华骨科杂志》.2008年1月.28卷.1期）；\r（3）预防静脉血栓栓塞症：参照《中国骨科大手术后静脉血栓栓塞症预防指南》（《中华骨科杂志》，2016，36（2）：65-71）；\r（4）其他药物：消肿、促骨折愈合等。\r4.保护下功能锻炼。\r（十）","初步诊断":"【临床路径·诊断依据】\n诊断依据\r根据《外科学（下册）》（8年制和7年制临床医学专用教材，赵玉沛、陈孝平主编，人民卫生出版社，2015年）。\r1.病史：外伤史。\r2.体格检查：患肢肿胀、疼痛、活动受限、畸形、反常活动。\r3.辅助检查：X线检查发现胫腓骨干骨折。\r（三）\n1. 胫腓骨干骨折（ICD-10：S82.201）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【临床路径·治疗方案的选择】\n选择治疗方案的依据\r根据《外科学（下册）》（8年制和7年制临床医学专用教材，赵玉沛、陈孝平主编，人民卫生出版社，2015年）。\r1.年龄在16岁以上。\r2.伤前生活质量及活动水平。 \r3.全身状况允许手术。\r4.首选钢板螺钉内固定，也可根据具体情况选择其他治疗方式。\r（四）","临床路径·进入路径标准":"进入路径标准\r1.第一诊断必须符合ICD-10：S82.201闭合性胫腓骨干骨折疾病编码。\r2.外伤引起的单纯性、新鲜胫腓骨干骨折。\r3.除外病理性骨折。\r4.除外合并其他部位的骨折和损伤。\r5.当患者合并其他疾病，但住院期间不需要特殊处理也不影响第一诊断的临床路径流程实施时，可以进入路径。\r（六）术前准备（术前评估）1～7天\r1.","临床路径·标准住院日":"标准住院日为\n16天\r（五）","临床路径·出院标准":"出院标准\r1.体温正常，常规实验室检查无明显异常。\r2.伤口愈合好：引流管拔除，伤口无感染征象（或可在门诊处理的伤口情况）。\r3.术后X线片证实复位固定满意。\r4.无需要住院处理的并发症和（或）合并症。\r（十一）","临床路径·变异及原因分析":"变异及原因分析\r1.并发症：本病可伴有其他损伤，应当严格掌握入选标准。部分患者因骨折本身的合并症而延期治疗，如大量出血需术前输血、血栓形成、血肿引起体温增高，骨折本身对骨的血循环破坏较重，术后易出现骨折延迟愈合、不愈合等。\r2.合并症：老年患者易有合并症，如骨质疏松、糖尿病、心脑血管疾病等，骨折后合并症可能加重，需同时治疗，而需延期治疗。\r3.内固定物选择：根据骨折类型选择适当的内固定物。\r4.开放性骨折不进入本路径。\r\r\f二、胫腓骨干骨折","资料来源":"国家卫健委《224个病种临床路径（2019年版）》（国卫办医函〔2019〕933号）· 骨科临床路径（2019年版） · 胫腓骨干骨折临床路径（2019年版）.doc"},"icd10_diagnosis":"S82.201","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2637,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"d3da2bc01dd2461bb2201d19e7bdab45f09c1b2cfa4082cc840b4e96875419f5","pinyin":"jingfeiguganguzhe","initials":"jfgggz","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","临床路径·进入路径标准","临床路径·标准住院日","临床路径·出院标准","临床路径·变异及原因分析","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 临床路径·进入路径标准 临床路径·标准住院日 临床路径·出院标准 临床路径·变异及原因分析 资料来源",30],["主要诊断编码","S82.201",30]]},{"id":"templates-43b6df8614c270319f3a","key":"v1-c9ccc21dfe2a3058|templates-43b6df8614c270319f3a","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"胰腺假性囊肿","category":"肝胆外科","raw":{"name":"胰腺假性囊肿","category":"肝胆外科","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文·卫健委临床路径原文】上腹或左上腹包块，可活动度差，伴上腹胀满、隐痛或钝痛、进食后腹胀加重、食欲减退、消瘦、压迫症状：压迫胃十二指肠致恶心呕吐（胃排空障碍）、压迫胆管致黄疸、压迫门静脉致脾大或腹水、继发感染：发热、腹痛加剧、包块压痛（囊内感染/脓肿）、并发症：囊肿破裂（急腹症）、囊内出血（腹痛加重、血红蛋白下降）、胰源性腹水。\n【待人工确认·本机素材无此段原文】","现病史":"胰腺假性囊肿是急性胰腺炎或胰腺外伤后，胰液外渗被纤维组织包裹形成的囊性积液，囊壁无上皮细胞（故称假性）。多在急性胰腺炎后4周以上形成，表现为上腹包块、腹胀、腹痛；直径>6cm、持续6周以上不消退或出现并发症（感染、出血、破裂、压迫）者需干预（内镜/经皮引流或手术）。\n常见表现：上腹或左上腹包块，可活动度差，伴上腹胀满、隐痛或钝痛、进食后腹胀加重、食欲减退、消瘦、压迫症状：压迫胃十二指肠致恶心呕吐（胃排空障碍）、压迫胆管致黄疸、压迫门静脉致脾大或腹水、继发感染：发热、腹痛加剧、包块压痛（囊内感染/脓肿）、并发症：囊肿破裂（急腹症）、囊内出血（腹痛加重、血红蛋白下降）、胰源性腹水。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：体温（感染）、脉搏、血压、体重变化\n一般情况：营养状态、消瘦、有无黄疸\n腹部视诊：上腹膨隆（包块）、手术瘢痕、腹壁静脉曲张\n腹部触诊：上腹/左上腹包块（大小、质地、活动度、有无压痛与波动感）、肝脾大小\n腹部叩诊：包块叩诊浊音、移动性浊音（胰源性腹水）\n腹部听诊：肠鸣音（胃排空障碍时减弱）\n皮肤：黄疸、皮下瘀斑（Grey-Turner征）","辅助检查":"1. 血淀粉酶+脂肪酶：评估胰腺炎活动性与囊肿性质（囊液淀粉酶极高提示与胰管相通）\n2. 血常规+CRP+PCT：感染评估（囊内感染时升高）\n3. 肝功能+胆红素：评估胆道是否受压（梗阻性黄疸）\n4. 白蛋白+前白蛋白+体重：营养状态评估（指导营养支持）\n5. 腹部增强CT+MRCP：明确囊肿大小、部位、与胰管关系（决定治疗方案）\n6. 内镜超声（EUS）±细针穿刺：评估囊壁成熟度与囊液分析（鉴别囊性肿瘤）\n7. 血糖+糖化血红蛋白：胰腺内分泌功能评估（胰腺炎后糖尿病常见）\n\n【临床路径·住院期间检查项目】\n必需的检查项目：\r（1）血常规+血型、尿常规、大便常规+隐血；\r（2）肝功能、肾功能、电解质、凝血功能、肿瘤标志物检查（含CA19-9、CA125及CEA等）、感染性疾病筛查（乙型肝炎、丙型肝炎、HIV、梅毒）；\r（3）心电图、X线胸片正侧位。\r2.根据患者病情选择的检查项目：\r（1）血气分析、超声心动图、肺功能检测（老年人或既往有相关病史者）；\r（2）肝胆胰腺超声、ERCP、EUS、上腹部CT或MRCP。\r（七）","初步诊断":"1. 腹部超声：首选筛查，显示上腹囊性无回声区、囊壁厚度、与胰腺关系\n2. 腹部增强CT：明确囊肿大小、部位、数目、与胰管和周围脏器关系（决定治疗方式）\n3. MRCP/磁共振：评估囊肿与胰管是否相通（是否适合内镜引流的关键）\n4. 血淀粉酶/脂肪酶+肝功能：评估胰腺炎活动与胆道受压\n5. 血常规+CRP+PCT：疑感染时（囊内感染需引流）\n6. 内镜超声（EUS）：评估囊壁成熟度（是否适合内镜引流）、可行细针穿刺送检（鉴别囊性肿瘤）\n7. 囊肿穿刺液分析（必要时）：淀粉酶（极高提示与胰管相通）、CEA/细胞学（排除囊性肿瘤）\n【临床路径·诊断依据】\n诊断依据\r根据《临床诊疗指南\n普通外科分册》（中华医学会编著，人民卫生出版社，2006年，第1版），《黄家驷外科学》（吴孟超，吴在德主编，人民卫生出版社，2013年，第7版）及全国高等学校教材《外科学》（陈孝平，汪建平主编，人民卫生出版社，2014年，第8版）。\r1.主要症状：胰腺外伤或急性胰腺炎后出现上腹疼痛、食欲不振、腹胀、消化不良等，合并感染时可有发热。\r2.体征：上腹部囊性感肿物，光滑，不移动，合并感染时可有触痛。\r3.影像学检查：超声、胰腺CT或MRI可见胰腺囊肿。\r4.实验室检查：多无特异性表现，合并感染时可有白细胞增高；囊肿穿刺液可有淀粉酶增高；肿瘤标志物阴性。\r（三）\n1. 胰腺假性囊肿（ICD-10：K86.3）","鉴别诊断":"1. 内镜超声（EUS）：评估囊壁成熟度（是否适合内镜引流）、可行细针穿刺送检（鉴别囊性肿瘤）\n2. 囊肿穿刺液分析（必要时）：淀粉酶（极高提示与胰管相通）、CEA/细胞学（排除囊性肿瘤）\n3. 胰腺假性囊肿需与胰腺囊性肿瘤（黏液性/浆液性囊腺瘤、IPMN）鉴别，囊液CEA与细胞学有助鉴别\n4. （4）与胰腺囊性肿瘤难以鉴别者","处理方案":"【药物治疗·输液】\n⚠️ 按病情选择方案，切勿全部同时使用！\n\n方案1（抑制胰液分泌）：\n 用法：生长抑素 3mg/12h 持续泵入 或 奥曲肽 25～50μg/h 泵入（疗程1～2周）；艾司奥美拉唑 40mg 静推 q12h\n\n方案2（抗感染，囊内感染时）：\n 用法：哌拉西林他唑巴坦 4.5g 静滴 q8h 或 美罗培南 1g 静滴 q8h + 甲硝唑 0.5g 静滴 q8h\n\n方案3（营养支持）：\n 用法：全肠外营养（葡萄糖+氨基酸+脂肪乳+电解质）；或鼻空肠管肠内营养（避免刺激胰腺分泌）\n\n方案4（支持/镇痛）：\n 用法：0.9%氯化钠 静滴；布桂嗪 100mg 肌注 必要时；白蛋白 10g 静滴（低蛋白）\n\n📌 囊肿未感染时不需要抗生素；肠内营养须经鼻空肠管（避免经胃喂养刺激胰腺）。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：同类药物选一种，切勿重复用药！\n\n药物1（胰酶补充，胰腺外分泌功能不全）：\n 用法：胰酶肠溶胶囊 1～2粒 随餐 tid\n\n药物2（抑酸）：\n 用法：艾司奥美拉唑 20mg qd（餐前）\n\n药物3（镇痛）：\n 用法：对乙酰氨基酚 0.5g 必要时 或 塞来昔布 200mg qd（餐后）\n\n📌 恢复期严格低脂饮食、禁酒；囊肿消退前避免剧烈运动与腹部外伤（防破裂）。\n\n【治疗】\n随访观察：囊肿<6cm、无症状、无并发症者可先观察（每2～3个月复查超声/CT），部分可自行吸收（多见于<4cm者）\n内镜引流（首选）：囊肿与胃/十二指肠壁紧贴且囊壁成熟（>4～6周）者行EUS引导下囊肿胃/十二指肠吻合或支架置入\n经皮穿刺置管引流：适用于囊肿较大、与胰管相通或不适合内镜者（注意胰瘘风险），可反复冲洗\n外科手术：内镜/经皮引流失败、囊肿多发或合并胰管狭窄/断裂者行囊肿空肠Roux-en-Y吻合或胰部分切除\n感染性囊肿：引流+抗感染，必要时手术清除坏死组织\n并发症处理：破裂（急诊手术）、出血（介入栓塞或手术）、压迫致梗阻（引流解除）\n病因处理：胆源性胰腺炎处理结石；高脂血症性控制血脂；戒酒\n\n【处理要点】\n观察囊肿大小与症状：定期复查超声/CT，记录包块大小、腹胀与疼痛变化\n饮食管理：低脂饮食，少量多餐；急性期禁食、肠外营养\n引流管护理：妥善固定、保持通畅、记录引流液量与淀粉酶（高淀粉酶提示胰瘘），观察引流口周围皮肤\n感染监测：体温、腹痛、白细胞与PCT；囊内感染时需及时引流\n营养评估：每月测体重与白蛋白，营养不良者加强肠内/肠外营养\n随访计划：内镜/经皮引流后每1～3个月复查，确认囊肿消退与有无复发\n宣教：避免饮酒、暴饮暴食与腹部外伤；出现腹痛加剧、发热及时就诊\n\n【护理】\n病情观察：观察腹痛、腹胀、包块大小与体温变化，警惕囊肿感染、破裂与出血\n饮食护理：低脂饮食、少量多餐；引流期间遵医嘱禁食或肠内营养（鼻空肠管）\n引流管护理：妥善固定、防止脱出，记录引流液量与性状，观察引流口周围皮肤有无糜烂（胰液腐蚀），必要时涂氧化锌软膏\n营养与体重监测：每周测体重，记录进食量，配合营养师制定方案\n活动指导：避免剧烈运动、腹部撞击与用力排便（防囊肿破裂）\n宣教随访：禁酒、低脂饮食、按时复查，出现剧烈腹痛或发热立即就诊\n\n【饮食】\n严格低脂饮食：禁油炸、肥肉、动物内脏、浓肉汤，脂肪摄入控制在每日30～50g以内\n少量多餐（每日5～6餐），减轻胰腺与胃肠负担\n适量优质蛋白（鱼、瘦肉、蛋清、豆制品）与充足碳水提供热量\n禁酒（酒精是胰腺炎复发与囊肿形成的重要诱因）\n恢复期补充胰酶制剂（随餐服用），必要时补充脂溶性维生素\n\n【注意事项】\n胰腺假性囊肿需与胰腺囊性肿瘤（黏液性/浆液性囊腺瘤、IPMN）鉴别，囊液CEA与细胞学有助鉴别\n囊肿壁成熟一般需4～6周，过早引流易致胰瘘与复发\n囊肿与胰管相通是选择内镜引流的重要依据（MRCP/EUS评估）\n感染性假性囊肿病死率较高，需及时引流并抗感染\n合并胰管断裂者常需手术（内镜引流效果差）\n\n【急诊/急救】\n突发剧烈腹痛伴腹膜刺激征（囊肿破裂）→ 急诊手术\n腹痛加剧伴血红蛋白下降（囊内出血）→ 急诊评估，介入栓塞或手术\n高热寒战伴上腹剧痛、感染指标升高（囊肿感染/脓肿）→ 急诊引流+抗感染\n\n【临床路径·治疗方案的选择】\n选择治疗方案的依据\r根据《临床诊疗指南\n普通外科分册》（中华医学会编著，人民卫生出版社，2006年，第1版），《黄家驷外科学》（吴孟超，吴在德主编，人民卫生出版社，2013年，第7版）及全国高等学校教材《外科学》（陈孝平，汪建平主编，人民卫生出版社，2014年，第8版）。\r1.囊肿内引流手术适用于：\r（1）6周以上成熟囊肿，直径＞6cm；\r（2）合并胰管狭窄和部分扩张；\r（3）合并压迫症状（胆道或胃、十二指肠梗阻）；\r（4）其他方法治疗后复发者(如外引流或置管引流者)；\r（5）外引流术后窦道形成，经久不愈者。\r2.囊肿切除术（胰体尾切除或胰十二指肠切除）适用于：\r（1）慢性胰腺炎后囊肿伴疼痛；\r（2）多发性囊肿；\r（3）假性动脉瘤致消化道大出血；\r（4）与胰腺囊性肿瘤难以鉴别者。\r3.囊肿外引流术仅用于：\r（1）感染性囊肿经皮穿刺置管引流失败；\r（2）囊肿破裂；\r（3）准备行囊肿内引流术的病例术中证实囊壁未成熟。\r（四）临床路径\n\n【临床路径·选择用药】\n选择用药\r1.抗菌药物：按照《抗菌药物临床患者指导原则》（卫医发〔2015〕43号）执行。建议使用第二代头孢菌素，有反复感染史者可选头孢曲松或头孢哌酮或头孢哌酮/舒巴坦；明确感染患者，可根据药敏试验结果调整抗菌药物。\r2.如有继发感染征象，尽早开始抗菌药物的经验治疗。经验治疗需选用能覆盖肠道革兰阴性杆菌、肠球菌属等需氧菌和脆弱拟杆菌等厌氧菌的药物。\r3.在给予抗菌药物治疗之前应尽可能留取相关标本送培养，获病原菌后进行药敏试验，作为调整用药的依据。有手术指征者应进行外科处理，并于手术过程中采集病变部位标本做细菌培养及药敏试验。\r4.预防性用抗菌药物，时间为术前0.5小时，手术超过3小时加用1次抗菌药物；总预防性用药时间一般不超过24小时，个别情况可延长至48小时。\r（八）手术日为入院第3～4天\r1.麻醉方式：气管内插管全身麻醉或硬膜外麻醉。\r2.手术方式：胰腺假性囊肿切除术；内引流手术（胰腺假性囊肿-空肠Roux-en-Y吻合术、胰腺假性囊肿-胃吻合术、胰腺假性囊肿-十二指肠吻合术）；胰腺假性囊肿外引流术。\r3.手术内置物：无。\r4.术中用药：麻醉常规用药，补充血容量药物（晶体、胶体）、血管活性药物。\r5.输血：根据术中出血量决定。\r（九）术后住院恢复7～9天\r1.必须复查的检查项目：血常规、血电解质、血淀粉酶、尿淀粉酶。\r2.根据患者病情，可以考虑行腹部超声、CT检查。\r3.术后用药：抗菌药物；根据患者病情使用抑酸剂、静脉营养、生长抑素。\r4.各种管道处理：尽早拔除胃管、尿管、引流管、深静脉穿刺管。\r5.康复情况：监测生命体征，观察有无并发症发生、胃肠道功能恢复情况，指导患者术后饮食。\r6.伤口护理。\r（十）","临床路径·进入路径标准":"进入路径标准\r1.第一诊断必须符合ICD-10：K86.3胰腺假性囊肿疾病编码。\r2.当患者合并其他疾病，但住院期间不需要特殊处理也不影响第一诊断的临床路径流程实施时，可以进入路径。\r（六）术前准备1～3天\r1.","临床路径·标准住院日":"标准住院日为9～11天\r（五）","临床路径·出院标准":"出院标准\r1.饮食恢复，无需静脉补液。\r2.不需要住院处理的并发症和（或）合并症如肠漏、胰瘘等。\r（十一）","临床路径·变异及原因分析":"变异及原因分析\r1.胰腺假性囊肿发生不足6个月、囊壁薄、有缩小趋势，尚未符合手术治疗指征者。\r2.可行经皮穿刺置管引流者，进入相应临床路径。\r3.可行经乳头内镜引流、经胃肠壁内镜引流术者，进入相应临床路径。\r4.合并全身其他重要器官功能不全，手术风险增高，需要进行相关的诊断和治疗。\r5.患者方面其他因素。\r6.围手术期的合并症和（或）并发症，需要进行相关的诊断和治疗，导致住院时间延长、费用增加。\r\r\r二、胰腺假性囊肿","资料来源":"疾病库 diseases.json；鉴别诊断库 ddx_local.json（条目「胰腺假性囊肿」原文）；国家卫健委《224个病种临床路径（2019年版）》（国卫办医函〔2019〕933号）· 普通外科临床路径（2019年版） · 胰腺假性囊肿临床路径（2019年版）.doc"},"icd10_diagnosis":"K86.3","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2638,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"3d1158d1084a17374358c8de912d284ef94c7c5eb70f90fb3d2f51eddeacb55a","pinyin":"yixianjiaxingnangzhong","initials":"yxjxnz","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","临床路径·进入路径标准","临床路径·标准住院日","临床路径·出院标准","临床路径·变异及原因分析","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 临床路径·进入路径标准 临床路径·标准住院日 临床路径·出院标准 临床路径·变异及原因分析 资料来源",30],["主要诊断编码","K86.3",30]]},{"id":"templates-31373a879215343e1a1d","key":"v1-c9ccc21dfe2a3058|templates-31373a879215343e1a1d","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"胸主动脉瘤","category":"血管外科","raw":{"name":"胸主动脉瘤","category":"血管外科","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】多无明显症状（体检发现）、胸背部钝痛或撕裂样疼痛、声音嘶哑、吞咽困难（压迫症状）、突发剧烈胸痛伴休克（破裂/夹层）。\n【待人工确认·本机素材无此段原文】","现病史":"胸主动脉局限性扩张（直径≥5cm），有破裂及主动脉夹层风险\n常见表现：多无明显症状（体检发现）、胸背部钝痛或撕裂样疼痛、声音嘶哑、吞咽困难（压迫症状）、突发剧烈胸痛伴休克（破裂/夹层）。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：双上肢血压对比（夹层时差异>20mmHg）\n心脏：主动脉瓣听诊区舒张期杂音（主动脉瓣关闭不全）\n胸部：纵隔增宽体征、颈部搏动性肿块\n外周：股动脉搏动减弱提示累及降主动脉","辅助检查":"1. 主动脉CTA：首选确诊及测量（全程评估累及范围）\n2. 心脏超声：评估主动脉瓣、心包积液及心功能\n3. 心电图+肌钙蛋白：排除急性心梗（胸痛鉴别）\n4. 血常规+凝血功能+肾功能：术前评估及破裂出血监测\n5. 基因检测：年轻患者筛查马凡综合征等遗传病","初步诊断":"1. 胸片示纵隔增宽\n2. 主动脉CTA/MRA确诊并测量\n3. 直径≥5.5cm或快速增长考虑手术\n4. 马凡综合征等遗传病相关筛查\n1. 胸主动脉瘤（ICD-10：I71.2）","鉴别诊断":"1. 突发撕裂样胸痛需与急性主动脉夹层鉴别（均需急诊CTA）\n2. 诊断要点：胸片示纵隔增宽\n3. 诊断要点：主动脉CTA/MRA确诊并测量\n4. 诊断要点：直径≥5.5cm或快速增长考虑手术\n5. 诊断要点：马凡综合征等遗传病相关筛查\n6. 马凡综合征患者妊娠期破裂风险极高需专科评估\n7. 声音嘶哑提示压迫左喉返神经，瘤体较大","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！\n\n方案1（急诊降压）：\n 用法：NS50ml+艾司洛尔0.5mg/kg iv（1min内）负荷，继以50-200μg/kg/min泵入滴定（目标心率60次/分、收缩压100-120mmHg）；β阻滞达标前勿用血管扩张剂\n\n方案2（持续降压）：\n 用法：硝普钠0.3-5μg/kg/min泵入（与β受体阻滞剂联用，防反射性心动过速）\n\n📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！\n\n药物1：\n 用法：美托洛尔12.5-25mg bid（控制心率血压，减慢主动脉壁张力）\n\n药物2：\n 用法：阿托伐他汀20mg qn（降脂稳定斑块）\n\n📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。\n\n【治疗】\n直径<5.5cm且稳定者定期CTA随访（每6-12个月）\n直径≥5.5cm或快速增大行腔内修复（TEVAR）或开放手术\n控制血压心率、戒烟\n\n【处理要点】\n严格控制血压心率（β受体阻滞剂基础用药）\n戒烟、控制血脂血糖\n定期CTA随访，避免剧烈运动\n\n【护理】\n病情观察：密切监测血压心率，警惕突发胸痛、咯血等破裂先兆\n术后护理（TEVAR/开放）：观察切口渗血、肢端血运、尿量，监测内漏及脊髓缺血（下肢感觉运动）\n血压管理：遵医嘱降压，避免血压剧烈波动及用力排便\n健康宣教：戒烟、低脂饮食、定期CTA复查，教会识别危险信号\n\n【饮食】\n低盐低脂饮食：每日食盐<5g，控制血脂血压\n戒烟限酒：吸烟加速动脉瘤进展\n高纤维饮食：保持大便通畅，避免用力排便诱发破裂\n适量优质蛋白：瘦肉、鱼、蛋，术后促进恢复\n\n【注意事项】\n突发撕裂样胸痛需与急性主动脉夹层鉴别（均需急诊CTA）\n马凡综合征患者妊娠期破裂风险极高需专科评估\n声音嘶哑提示压迫左喉返神经，瘤体较大\n\n【急诊/急救】\n破裂/夹层：立即呼救、控制血压心率，急诊手术\n剧烈胸痛伴血压下降、休克：快速评估并转运","资料来源":"疾病库 diseases.json；鉴别诊断库 ddx_local.json（条目「胸主动脉瘤」原文）"},"icd10_diagnosis":"I71.2","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2639,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"a97e73d9ec84e567de22696569b393c7e03be7d4717924ea9b669b080236925e","pinyin":"xiongzhudongmailiu","initials":"xzdml","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","I71.2",30]]},{"id":"templates-84ed3b9b54c171a7df76","key":"v1-c9ccc21dfe2a3058|templates-84ed3b9b54c171a7df76","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"胸椎管狭窄症","category":"骨科临床路径（2019年版）","raw":{"name":"胸椎管狭窄症","category":"骨科临床路径（2019年版）","case":{"case_name":"门诊病历","templates":{"主诉":"【待人工确认·本机素材无此段原文】","现病史":"【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"【临床路径·住院期间检查项目】\n必需的检查项目：\r（1）血常规、血型、尿常规；\r（2）凝血功能、肝功能、肾功能、电解质、血糖、感染性疾病筛查；\r（3）X线胸片、心电图；\r（4）胸椎正侧位平片或全脊柱正侧位拼接；\r（5）全脊柱MRI和病变部位CT，若患者条件不允许行MRI检查，可行胸椎CTM代替。\r2.根据患者病情可选择的检查项目：心肌酶、肺功能、超声心动、动态心电图、动态血压监测和骨密度（老年人或既往有相关病史者）。\r（七）预防性抗菌药物选择与使用时机\r1.按照《抗菌药物临床患者指导原则》（2015年版，人民卫生出版社）执行，并根据患者的病情决定抗菌药物的选择与使用时间。建议使用第一、二代头孢菌素，头孢曲松。MRSA感染高发医疗机构的高危患者可用（去甲）万古霉素。\r2.静脉输注患者皮肤切开前0.5～1小时内或麻醉开始时给药，在输注完毕后开始手术；万古霉素由于需输注较长时间，患者手术前1～2小时开始给药；手术时间较短（＜2小时）时术前给药1次即可。如手术时间超过3小时或超过所用药物半衰期的2倍以上，或成人出血量超过1500ml，术中应追加1次。\r（八）手术日为入院\n6天\r1.麻醉方式：气管内插管全身麻醉。\r2.手术方式：后路椎管后壁切除术或后路椎管后壁切除内固定植骨融合术或后路环形减压内固定植骨融合术。\r3.手术内植物：椎弓根螺钉、固定钩、固定棒等。\r4.术中用药：麻醉常规用药、预防性抗菌药物、激素，术后镇痛泵的患者。\r5.根据术中情况决定是否使用自体血回输。\r6.根据情况决定是否使用术中脊髓功能监测。\r7.输血：视术中具体情况而定。\r（九）术后住院恢复\n16天\r1.必须复查的检查项目：血常规、胸椎平片。\r2.必要时复查的项目：肝肾功能、电解质、胸椎CT、胸椎MRI等。\r3.术后用药：\r抗菌药物使用：按照《抗菌药物临床患者指导原则》（2015年版，人民卫生出版社）执行，并根据患者的病情决定抗菌药物的选择与使用时间。建议使用第一、二代头孢菌素，头孢曲松。MRSA感染高发医疗机构的高危患者可用（去甲）万古霉素。\r（十）","初步诊断":"【临床路径·诊断依据】\n诊断依据\r根据《临床诊疗指南\n骨科分册》（中华医学会编著，人民卫生出版社，2009年），《骨科学高级教程》（中华医学会组织，邱贵兴主编，中华医学电子音像出版社，2016年），《实用骨科学》（田伟主编，人民卫生出版社，2016年）。\r1.由于发育、退变、代谢或韧带骨化等因素造成胸椎管狭窄，出现相应的神经受压的影像学表现。\r2.上述病理改变压迫和刺激相应水平的脊髓或神经根并出现相应的临床表现。\r（三）\n1. 胸椎管狭窄症（ICD-10：M48.003）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【临床路径·治疗方案的选择】\n选择治疗方案的依据\r根据《临床诊疗指南\n骨科分册》（中华医学会编著，人民卫生出版社，2009年），《骨科学高级教程》（中华医学会组织，邱贵兴主编，中华医学电子音像出版社，2016年），《实用骨科学》（田伟主编，人民卫生出版社，2016年）。\r1.保守治疗：少数脊髓压迫较轻，症状轻且无进展者可以试行保守治疗。\r2.手术治疗：多数有神经症状者，需要手术治疗。\r（四）","临床路径·进入路径标准":"进入路径标准\r1.第一诊断必须符合ICD-10:M48.02胸椎管狭窄症疾病编码。\r2.当患者合并其他疾病，但住院期间不需要特殊处理也不影响第一诊断的临床路径流程实施时，可以进入路径。\r（六）术前准备（术前评估）\n5天（工作日）\r1.","临床路径·标准住院日":"标准住院日为\n17天\r（五）","临床路径·出院标准":"出院标准。\r1.切口：愈合好，无感染征象，或可在门诊处理的未完全愈合切口。\r2.无需要住院处理的并发症和合并症。\r（十一）","临床路径·变异及原因分析":"变异及原因分析\r1.有影响手术的合并症，需要进行相关的诊断和治疗。\r2.需要根据患者的病情以及影像学特点制定手术方案，包括单纯后路减压、后路环形减压、减压＋内固定融合、前路减压固定融合、前后路联合手术。\r3.对于部分诊断不明确患者，术前可能需要肌电图、诱发电位、脊柱其他部位影像检查等以确诊。\r4.术后若出现并发症，需进行相应处理。\r\r二、胸椎管狭窄症","资料来源":"国家卫健委《224个病种临床路径（2019年版）》（国卫办医函〔2019〕933号）· 骨科临床路径（2019年版） · 胸椎管狭窄症临床路径（2019年版）.doc"},"icd10_diagnosis":"M48.003","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2640,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"c55f28302bb9fd09d49f4716b17b918e69ff9cda294e45923f30cad9329661d7","pinyin":"xiongzhuiguanxiazhaizheng","initials":"xzgxzz","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","临床路径·进入路径标准","临床路径·标准住院日","临床路径·出院标准","临床路径·变异及原因分析","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 临床路径·进入路径标准 临床路径·标准住院日 临床路径·出院标准 临床路径·变异及原因分析 资料来源",30],["主要诊断编码","M48.003",30]]},{"id":"templates-40c6f86d30e7be33ae17","key":"v1-c9ccc21dfe2a3058|templates-40c6f86d30e7be33ae17","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"胸痹(中医辨证)","category":"中医","raw":{"name":"胸痹(中医辨证)","category":"中医","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】胸部闷痛、胸痛彻背、喘息不得卧、心悸气短、倦怠乏力。\n【待人工确认·本机素材无此段原文】","现病史":"胸痹是指以胸部闷痛，甚则胸痛彻背，喘息不得卧为主症的一种疾病。\n常见表现：胸部闷痛、胸痛彻背、喘息不得卧、心悸气短、倦怠乏力。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：体温、脉搏、呼吸、血压\n望诊：神（得神/少神/失神/假神/神乱）、色（常色/病色：青/赤/黄/白/黑，光泽/晦暗）、形态（形体胖瘦/动静姿态/异常动作）、头面（头颅/囟门/头发/面肿/口眼歪斜）、五官（目/耳/鼻/口/齿/龈/咽喉）、躯体（颈项/胸胁/腹部/腰背/四肢/皮肤）、舌诊（舌质：颜色/形质/动态；舌苔：苔色/苔质/润燥/厚薄/腻腐/剥落；舌底络脉）、排泄物（痰涎/呕吐物/大便/小便/经血/带下）\n闻诊：声音（语声/呼吸/咳嗽/喘哮/呃逆/嗳气/太息/肠鸣）、气味（口气/汗气/痰涕气味/二便气味/经带气味/病室气味）\n问诊：一般情况（姓名/性别/年龄/职业/籍贯）、主诉、现病史（起病情况/主症特点/病因诱因/病情发展/诊治经过/伴随症状）、既往史、个人史、家族史、十问歌（一问寒热二问汗，三问头身四问便，五问饮食六胸腹，七聋八渴俱当辨，九问旧病十问因，再兼服药参机变，妇女尤必问经期，迟速闭崩皆可见，再添片语告儿科，天花麻疹全占验）\n切诊：脉诊（部位：寸关尺；脉象：浮沉迟数虚实滑涩洪细濡弱弦紧结代促等，注意平脉/病脉/真脏脉）、按诊（按肌肤/按手足/按胸腹/按腧穴/按腹部，温度/湿度/压痛/包块/波动感）\n辨证：八纲辨证（表里/寒热/虚实/阴阳）、脏腑辨证、气血津液辨证、六经辨证、卫气营血辨证、三焦辨证、经络辨证","辅助检查":"检查计划：患者以胸部闷痛，甚则胸痛彻背、喘息不得卧为主症，多见于中年以上，常因操劳过度、抑郁恼怒或多饮暴食、感受寒冷而诱发，入院即刻完善18导联心电图检查明确有无ST-T改变及心肌缺血定位；完善心肌酶谱检查（肌钙蛋白I、CK-MB）排除急性心肌梗死等急性心肌损伤；完善血常规检查排除感染、贫血所致心肌缺血；完善电解质检查排除低钾、低镁等电解质紊乱所致心律失常；因治疗用药需经肝肾代谢，完善肝肾功能检查排除肝肾功能不全，查血脂四项了解血脂水平，指导调脂方案；完善NT-ProBNP及心脏彩超+左心功能测定明确有无心功能衰竭，了解室壁运动、射血分数及瓣膜情况；完善凝血功能检查评估出血风险，为抗血小板、抗凝治疗提供依据；完善动态心电图检查明确有无阵发性心律失常，完善胸部X线检查排除肺部疾病及主动脉夹层等；为明确冠脉病变，待病情稳定后完善冠脉CTA检查明确冠脉狭窄部位与程度，必要时完善冠状动脉造影检查作为金标准进一步明确并指导血运重建。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 膻中或心前区憋闷疼痛，甚则痛彻左肩背、咽喉、胃脘部、左上臂内侧等部位，呈反复发作性。\n2. 常伴有心悸、气短、自汗，甚则喘息不得卧。\n3. 多见于中年以上，常因操劳过度、抑郁恼怒或多饮暴食、感受寒冷而诱发。\n1. 胸痹(中医辨证)（ICD-10：I20.9）","鉴别诊断":"1. 胸痹与胃脘痛鉴别：胸痹疼痛部位在膻中或心前区，可放射至左肩背","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！\n\n方案1（心血瘀阻）：\n 用法：丹参注射液20ml+5%GS250ml静滴qd\n\n方案2（气滞心胸）：\n 用法：舒血宁注射液20ml+5%GS250ml静滴qd\n\n方案3（气阴两虚）：\n 用法：参麦注射液40ml+5%GS250ml静滴qd\n\n方案4（心肾阳虚）：\n 用法：参附注射液20ml+5%GS250ml静滴qd\n\n📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！\n\n药物1（心血瘀阻）：\n 用法：血府逐瘀汤加减（桃仁9g 红花6g 当归9g 生地9g 川芎6g 赤芍9g 牛膝9g 桔梗6g 柴胡6g 枳壳9g 甘草3g）\n\n药物2（气滞心胸）：\n 用法：柴胡疏肝散加减（柴胡9g 枳壳9g 白芍9g 香附6g 川芎6g 陈皮6g 甘草3g）\n\n药物3（痰浊闭阻）：\n 用法：瓜蒌薤白半夏汤合涤痰汤加减（瓜蒌15g 薤白9g 半夏9g 胆南星6g 竹茹9g 人参6g 茯苓9g 甘草3g 石菖蒲9g 陈皮6g 枳实9g）\n\n药物4（寒凝心脉）：\n 用法：枳实薤白桂枝汤合当归四逆汤加减（枳实9g 薤白9g 桂枝9g 瓜蒌15g 厚朴9g 当归9g 芍药9g 细辛3g 通草6g 大枣5枚 炙甘草6g）\n\n药物5（气阴两虚）：\n 用法：生脉散合人参养荣汤加减（人参6g 麦冬9g 五味子6g 黄芪15g 当归9g 白芍9g 白术9g 茯苓9g 熟地9g 陈皮6g 桂心3g 远志6g 甘草3g）\n\n药物6（心肾阴虚）：\n 用法：天王补心丹合炙甘草汤加减（生地15g 玄参9g 丹参9g 当归9g 人参6g 茯苓9g 五味子6g 远志6g 酸枣仁9g 柏子仁9g 天冬9g 麦冬9g 炙甘草6g 桂枝6g 阿胶9g 生姜3片 大枣5枚）\n\n药物7（心肾阳虚）：\n 用法：参附汤合右归饮加减（人参6g 附子6g 肉桂3g 熟地9g 山萸肉9g 山药9g 枸杞子9g 杜仲9g 甘草3g）\n\n📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。\n\n【治疗】\n针灸：取膻中、内关、心俞、厥阴俞、巨阙；瘀血加血海，痰浊加丰隆，寒证加关元、气海\n耳针：心、交感、神门、皮质下、小肠、内分泌\n穴位注射：内关、心俞、厥阴俞，丹参注射液2ml\n推拿：按揉膻中、内关、心俞、厥阴俞，擦前胸后背\n\n【处理要点】\n调情志，避免情绪激动\n慎起居，注意保暖\n节饮食，忌肥甘厚味，戒烟酒\n适当运动，避免劳累\n\n【护理】\n情志护理：胸痹多因情志不遂、气机郁滞诱发，嘱患者避免大喜大悲、恼怒忧思，以防气滞血瘀加重心痛；可用移情易性法（听舒缓音乐、交谈转移）安神定志。\n起居调护：注意保暖防寒，胸背尤须护暖，避免骤冷骤热诱发寒凝心脉；起居有常，劳逸结合，避免剧烈活动及过劳，心痛发作时应立即静卧休息、减少搬动。\n病情观察：密切观察胸痛部位、性质、程度、持续时间及诱发因素，注意有无胸闷气短、汗出肢冷、面色苍白、脉象细涩或结代等变证先兆；疼痛持续不缓解或含服药物无效时立即报告并配合急救处理。\n煎药服药护理：中药宜温服，分次频饮，忌一次顿服；含服芳香开窍类中成药（如速效救心丸、麝香保心丸）时嘱舌下含服、切勿吞服，并观察用药后心绞痛缓解情况及有无头晕、血压下降等反应；服温阳散寒药期间忌再受寒。\n外治护理：可予耳穴压豆（心、神门、交感）或穴位按摩内关、膻中、心俞以理气活血、通络止痛，力度以酸胀为度；寒凝心脉者可用艾灸心俞、厥阴俞温通心阳，灸后避风寒；外治期间观察局部皮肤及症状变化。\n\n【饮食】\n忌口要点：忌肥甘厚味、辛辣炙煿及高脂高盐之品（如动物内脏、油炸食品、腌制品），以免助湿生痰、壅滞心脉；气阴两虚者忌辛辣温燥伤阴耗气，阳虚寒凝者忌生冷瓜果、冷饮。\n适宜饮食：饮食宜清淡、易消化、低盐低脂，多食新鲜蔬菜及富含纤维之品，少食多餐，勿过饱，以免饱餐后气机壅滞诱发心痛。\n辨证食疗：气滞血瘀者宜山楂、桃仁、黑木耳等活血化瘀之品，可饮山楂丹参茶；痰浊闭阻者宜薏苡仁、陈皮、萝卜、海带以健脾化痰、理气宽胸。\n虚证调补：气阴两虚者宜山药、莲子、百合、枸杞、麦冬炖粥或煮汤以益气养阴；心肾阳虚者宜桂圆、红枣、核桃、羊肉等温补之品，但宜少量缓补、不可过燥。\n药膳食疗：可常服薤白粥（薤白、粳米）通阳散结，或黄芪丹参炖瘦肉益气活血；食疗宜在医生指导下结合辨证选用，勿以食代药。\n\n【注意事项】\n胸痹与胃脘痛鉴别：胸痹疼痛部位在膻中或心前区，可放射至左肩背；胃脘痛部位在胃脘部，伴嗳气、反酸、腹胀等消化道症状。\n\n【急诊/急救】\n真心痛：胸痛剧烈，持续不解，伴汗出、肢冷、面白、唇紫、手足青至节，脉微欲绝，急用参附注射液、硝酸甘油，急诊PCI。","资料来源":"疾病库 diseases.json；鉴别诊断库 ddx_local.json（条目「胸痹（中医辨证）」原文）","中医辨证参考":"首次病程记录\n\n拟诊讨论：\n\n【中医辨证参考】胸痹\n（本页列出该病常见证型，请根据患者实际四诊资料选择相应证型，切勿直接套用）\n\n一、心血瘀阻\n    症状舌脉：心胸疼痛剧烈，如刺如绞，痛有定处，入夜为甚，甚则心痛彻背、背痛彻心，或痛引肩背，伴有胸闷，日久不愈，可因暴怒、劳累而加重，舌质紫暗有瘀斑、苔薄，脉弦涩\n    治法：活血化瘀、通脉止痛\n    方剂：血府逐瘀汤\n\n二、气滞心胸\n    症状舌脉：心胸满闷，隐痛阵发，痛无定处，时欲太息，遇情志不遂时容易诱发或加重，或兼有脘腹胀闷、得嗳气或矢气则舒，苔薄或薄腻，脉细弦\n    治法：疏肝理气、活血通络\n    方剂：柴胡疏肝散\n\n三、痰浊闭阻\n    症状舌脉：胸闷重而心痛微，痰多气短，肢体沉重，形体肥胖，遇阴雨天而易发作或加重，伴有倦怠乏力、纳呆便溏、咯吐痰涎，舌体胖大且边有齿痕、苔浊腻或白滑，脉滑\n    治法：通阳泄浊、豁痰宣痹\n    方剂：栝蒌薤白半夏汤合涤痰汤\n\n四、寒凝心脉\n    症状舌脉：猝然心痛如绞，心痛彻背，喘不得卧，多因气候骤冷或骤感风寒而发病或加重，伴形寒、甚则手足不温、冷汗自出、胸闷气短、心悸，苔薄白，脉沉紧或沉细\n    治法：辛温散寒、宣通心阳\n    方剂：枳实薤白桂枝汤合当归四逆汤\n\n五、气阴两虚\n    症状舌脉：心胸隐痛，时作时休，心悸气短，动则益甚，伴倦怠乏力、声息低微、面色㿠白、易汗出，舌质淡红、舌体胖且边有齿痕、苔薄白，脉虚细缓或结代\n    治法：益气养阴、活血通脉\n    方剂：生脉散合人参养荣汤\n\n六、心肾阴虚\n    症状舌脉：心痛憋闷，心悸盗汗，虚烦不寐，腰酸膝软，头晕耳鸣，口干便秘，舌红少津、苔薄或剥，脉细数或促代\n    治法：滋阴清火、养心和络\n    方剂：天王补心丹合炙甘草汤\n\n七、心肾阳虚\n    症状舌脉：心悸而痛，胸闷气短，动则更甚，自汗，面色㿠白，神倦怯寒，四肢欠温或肿胀，舌质淡胖、边有齿痕、苔白或腻，脉沉细迟\n    治法：温补阳气、振奋心阳\n    方剂：参附汤合右归饮。来源：《中医内科学》（中国中医药出版社“十四五”规划教材）·心系病证·胸痹。提示：胸痛剧烈持续不缓解、伴汗出肢冷者须警惕急性心肌梗死，立即呼叫急救\n\n【方剂参考】\n  血府逐瘀汤：组成 桃仁12g、红花9g、当归9g、生地黄9g、川芎4.5g、赤芍6g、牛膝9g、桔梗4.5g、柴胡3g、枳壳6g、甘草6g；功效 活血化瘀，行气止痛\n      用法：水煎温服，日二次；亦可制为丸剂或口服液，每次10ml，日三次。\n      注意：孕妇忌用；有出血倾向（血小板减少、活动性溃疡、月经量多）者慎用；体虚无瘀者不可用。\n  柴胡疏肝散：组成 陈皮（醋炒）6g、柴胡6g、川芎4.5g、香附4.5g、枳壳（麸炒）4.5g、白芍4.5g、炙甘草1.5g；功效 疏肝解郁，行气止痛\n      用法：水煎温服，日一剂，分两次服；亦可研末为散，每服6~9g，开水送下。\n      注意：阴虚火旺、气郁化火及孕妇慎用；本方辛散，久服易耗气伤阴。来源：《方剂学》（中国中医药出版社“十四五”规划教材）·理气剂（行气）；原方出自《景岳全书·古方八阵》\n  桂枝汤：组成 桂枝9g、芍药9g、生姜9g、大枣3枚、炙甘草6g；功效 解肌发表，调和营卫\n      用法：水煎温服，服后啜热稀粥一碗以助药力，覆被取微汗；一服汗出病瘥即停，不汗更服，不必尽剂。\n      注意：表实无汗、外感风热、温热病及酒客湿热内蕴者忌用；服药期间忌生冷、油腻、酒酪、臭恶之物。\n  生脉散：组成 人参9g、麦冬9g、五味子6g；功效 益气生津，敛阴止汗\n      用法：水煎温服，日二至三次；气阴欲脱时可频服或代茶饮，亦可服生脉口服液、注射液（急症）。\n      注意：外感表证未解、湿热内盛及实热证者忌用；五味子酸收，痰多者慎用；人参反藜芦，不宜同用。\n  天王补心丹：组成 生地黄12g、人参9g、丹参9g、玄参9g、茯苓9g、五味子6g、远志6g、桔梗6g、当归9g、天冬9g、麦冬9g、柏子仁9g、酸枣仁9g、朱砂0.3g；功效 滋阴养血，补心安神\n      用法：上药为末，炼蜜为丸如梧桐子大，朱砂为衣，每次6-9g，空腹或睡前以竹叶煎汤送服，日二次；亦可作汤剂，朱砂冲服且量宜小。\n      注意：脾胃虚弱、纳差便溏及痰湿内盛者不宜；朱砂含汞，不可过量久服，肝肾功能不全者禁用；忌与碘、溴化物同服。\n  参附汤：组成 人参9g、制附子9g（先煎）；功效 益气回阳固脱\n      用法：水煎，附子先煎30~60分钟，人参另煎兑服，日一剂，分两次温服；急救时宜浓煎顿服。\n      注意：本方为急救之剂，不可久服；热厥及阴虚阳亢者忌用；阳气回复后须辨证续治，不可专恃温补。来源：《方剂学》（中国中医药出版社“十四五”规划教材）·温里剂（回阳救逆）；原方出自《正体类要·卷下》\n\n【西医诊断】\n  冠心病 稳定型心绞痛\n  （西医诊断依据与鉴别诊断请结合患者病史、体征、辅助检查补充）\n\n医师签名：＿＿＿＿"},"icd10_diagnosis":"I20.9","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2641,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"539c597c6b507f5996904b4506157404cf07a92c377e15a04998c2d0300542f3","pinyin":"xiongbi(zhongyibianzheng)","initials":"xb(zybz)","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源","中医辨证参考"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源 中医辨证参考",30],["主要诊断编码","I20.9",30]]},{"id":"templates-9de611b7e47173915321","key":"v1-c9ccc21dfe2a3058|templates-9de611b7e47173915321","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"胸痹(冠心病中医辨证)","category":"中医","raw":{"name":"胸痹(冠心病中医辨证)","category":"中医","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】心血瘀阻：胸痛如刺，痛有定处，入夜尤甚，舌紫暗、气滞心胸：心胸满闷，隐痛阵发，痛无定处，情志不遂诱发、痰浊闭阻：胸闷重而心痛微，痰多气短，肢体沉重，苔浊腻、寒凝心脉：猝然心痛如绞，心痛彻背，多因气候骤冷或骤感风寒发病、气阴两虚：心胸隐痛，时作时休，心悸气短，动则益甚，倦怠乏力、心肾阳虚：心悸而痛，胸闷气短，动则更甚，自汗，面色㿠白，畏寒肢冷。\n【待人工确认·本机素材无此段原文】","现病史":"以胸部闷痛，甚则胸痛彻背、喘息不得卧为主症，即冠心病心绞痛。分心血瘀阻、气滞心胸、痰浊闭阻、寒凝心脉、气阴两虚、心肾阳虚等证型。\n常见表现：心血瘀阻：胸痛如刺，痛有定处，入夜尤甚，舌紫暗、气滞心胸：心胸满闷，隐痛阵发，痛无定处，情志不遂诱发、痰浊闭阻：胸闷重而心痛微，痰多气短，肢体沉重，苔浊腻、寒凝心脉：猝然心痛如绞，心痛彻背，多因气候骤冷或骤感风寒发病、气阴两虚：心胸隐痛，时作时休，心悸气短，动则益甚，倦怠乏力、心肾阳虚：心悸而痛，胸闷气短，动则更甚，自汗，面色㿠白，畏寒肢冷。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：体温、脉搏、呼吸、血压\n望诊：神（得神/少神/失神/假神/神乱）、色（常色/病色：青/赤/黄/白/黑，光泽/晦暗）、形态（形体胖瘦/动静姿态/异常动作）、头面（头颅/囟门/头发/面肿/口眼歪斜）、五官（目/耳/鼻/口/齿/龈/咽喉）、躯体（颈项/胸胁/腹部/腰背/四肢/皮肤）、舌诊（舌质：颜色/形质/动态；舌苔：苔色/苔质/润燥/厚薄/腻腐/剥落；舌底络脉）、排泄物（痰涎/呕吐物/大便/小便/经血/带下）\n闻诊：声音（语声/呼吸/咳嗽/喘哮/呃逆/嗳气/太息/肠鸣）、气味（口气/汗气/痰涕气味/二便气味/经带气味/病室气味）\n问诊：一般情况（姓名/性别/年龄/职业/籍贯）、主诉、现病史（起病情况/主症特点/病因诱因/病情发展/诊治经过/伴随症状）、既往史、个人史、家族史、十问歌（一问寒热二问汗，三问头身四问便，五问饮食六胸腹，七聋八渴俱当辨，九问旧病十问因，再兼服药参机变，妇女尤必问经期，迟速闭崩皆可见，再添片语告儿科，天花麻疹全占验）\n切诊：脉诊（部位：寸关尺；脉象：浮沉迟数虚实滑涩洪细濡弱弦紧结代促等，注意平脉/病脉/真脏脉）、按诊（按肌肤/按手足/按胸腹/按腧穴/按腹部，温度/湿度/压痛/包块/波动感）\n辨证：八纲辨证（表里/寒热/虚实/阴阳）、脏腑辨证、气血津液辨证、六经辨证、卫气营血辨证、三焦辨证、经络辨证","辅助检查":"检查计划：患者以胸部闷痛、甚则胸痛彻背、心悸气短为主症，辨证分心血瘀阻、气滞心胸、痰浊闭阻、寒凝心脉、气阴两虚、心肾阳虚，即冠心病心绞痛，入院即刻完善心电图检查明确ST-T改变及缺血导联；完善心肌酶检查排除急性心肌损伤；完善血常规检查排除感染、贫血所致心肌缺血；完善电解质检查排除电解质紊乱所致心律失常；因长期用药需经肝肾代谢，完善肝肾功能检查排除肝肾功能不全，查血脂四项、血糖检查了解血脂血糖水平，指导降脂与控糖方案；完善NT-ProBNP及心脏彩超+左心功能测定明确有无心功能衰竭，了解室壁运动、射血分数及瓣膜情况；完善凝血功能检查评估出血风险，为抗血小板、抗凝治疗提供依据；查甲状腺功能排除甲状腺功能亢进所致心悸胸闷；完善动态心电图检查明确有无阵发性心肌缺血与心律失常；患者胸痛如刺、痛有定处者，完善冠脉CTA检查明确冠脉狭窄程度，必要时完善冠状动脉造影检查进一步明确病变并指导介入治疗；定期复查心电图观察有无动态演变。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 胸闷痛，心悸气短\n2. 心电图ST-T改变，心肌酶\n3. 冠脉CTA或造影明确\n1. 胸痹(冠心病中医辨证)（ICD-10：I25.1）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！\n\n方案1（急性发作）：\n 用法：NS250ml+丹参川芎嗪10ml ivgtt qd，或NS250ml+红花黄色素100mg ivgtt qd\n\n方案2（气虚）：\n 用法：NS250ml+参麦注射液40ml ivgtt qd\n\n方案3（阳虚）：\n 用法：NS250ml+参附注射液40ml ivgtt qd\n\n📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！\n\n药物1（心血瘀阻）：\n 用法：血府逐瘀胶囊6粒 tid，或丹参滴丸10粒 tid\n\n药物2（气滞心胸）：\n 用法：柴胡疏肝散1袋 tid，或速效救心丸4-6粒 tid\n\n药物3（痰浊闭阻）：\n 用法：瓜蒌薤白半夏汤1袋 tid，或丹蒌片5片 tid\n\n药物4（寒凝心脉）：\n 用法：苏合香丸1丸含服，或冠心苏合丸1丸 tid\n\n药物5（气阴两虚）：\n 用法：生脉饮1支 tid，或参松养心胶囊4粒 tid\n\n药物6（心肾阳虚）：\n 用法：金匮肾气丸1丸 tid，或右归丸1丸 tid\n\n📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。\n\n【治疗】\n心血瘀阻：活血化瘀，通脉止痛，血府逐瘀汤\n气滞心胸：疏肝理气，活血通络，柴胡疏肝散\n痰浊闭阻：通阳泄浊，豁痰宣痹，瓜蒌薤白半夏汤\n寒凝心脉：辛温散寒，宣通心阳，枳实薤白桂枝汤合当归四逆汤\n气阴两虚：益气养阴，活血通脉，生脉散合人参养荣汤\n心肾阳虚：温补阳气，振奋心阳，参附汤合右归饮\n\n【处理要点】\n低盐低脂饮食\n戒烟限酒\n避免劳累和情绪激动\n保持大便通畅\n\n【护理】\n病情观察：密切观察胸痛部位、性质、程度、持续时间及诱发因素，注意心电图、血压、心率变化；若心痛持续不缓解、汗出肢冷、面白唇紫、脉微欲绝，为心阳欲脱之危候，立即报告医师并配合抢救（吸氧、静卧、含服速效救心丸等）；心肾阳虚兼水肿者每日记录24小时出入量及体重，监测下肢水肿消长。\n情志护理：胸痹多因情志失调诱发或加重，尤以气滞心胸证为甚，应避免大喜大悲、暴怒忧思；引导患者倾诉、听舒缓音乐、练习八段锦或呼吸吐纳以调畅气机、宁心安神，家属亦宜营造平和氛围。\n起居调护：寒凝心脉证者注意保暖防寒，尤其背部与心胸部位，天冷时减少晨起外出；避免用力排便、剧烈活动、饱餐后劳作等耗气加重心痛之诱因；保证充足睡眠，起居有常，勿过劳。\n煎药服药护理：活血化瘀、理气之剂宜温服，饭后服用以护胃气；寒凝心脉证汤药宜热服，服后加盖衣被、忌吹风；观察服药后胸痛缓解情况及有无胃肠不适、出血倾向（如牙龈出血、便血）等，及时报告。\n外治护理：遵医嘱予耳穴贴压（取心、神门、交感、胸等穴）或穴位按摩（内关、膻中、心俞、足三里），手法轻柔，每次5～10分钟；中药足浴水温以38～40℃为宜，心肾阳虚肢冷者防烫伤，心功能不全水肿明显者慎用热敷及足浴。\n\n【饮食】\n总则：宜清淡、低盐、低脂、低胆固醇饮食，戒烟酒，忌浓茶、咖啡等兴奋饮品；少食多餐，忌暴饮暴食及饱餐（饱餐易诱发心痛），晚餐尤宜七分饱。\n心血瘀阻证：忌肥甘厚味、动物内脏、油炸食品等助湿生瘀之品；宜食活血化瘀之品，如山楂、黑木耳、桃仁、丹参，可服山楂红糖饮（消食活血，血糖偏高者改用山楂煮水），日常佐以黑木耳炒芹菜。\n痰浊闭阻证：忌甜腻生痰之品（糕点、糯米、肥肉）及过量饮酒；宜清淡利湿化痰，多食薏苡仁、冬瓜、萝卜、海带、陈皮，药膳可用薏苡仁冬瓜汤、陈皮茯苓粥（健脾化痰、宽胸理气）。\n气阴两虚证：忌辛辣燥热、煎炸之品以免耗气伤阴；宜益气养阴，食山药、百合、莲子、大枣、太子参，药膳可用太子参麦冬茶或山药百合莲子粥；阴虚盗汗者忌过食温补燥烈之品。\n心肾阳虚证：忌生冷瓜果、冰镇饮品以免损阳；宜温补心肾，食桂圆、核桃、羊肉、生姜、韭菜；兼水肿者低盐饮食（每日食盐<3g），限制饮水量，可用附子生姜炖羊肉或桂圆红枣粥温阳散寒。\n\n【注意事项】\n急性胸痛持续>15分钟需警惕心梗\n随身携带硝酸甘油或速效救心丸\n规范二级预防用药\n\n【急诊/急救】\n心绞痛发作：休息，硝酸甘油0.5mg舌下含服，或速效救心丸10粒含服\n急性心梗：立即拨打120，阿司匹林300mg嚼服，氯吡格雷300mg口服\n心跳骤停：心肺复苏","资料来源":"疾病库 diseases.json","中医辨证参考":"首次病程记录\n\n拟诊讨论：\n\n【中医辨证参考】胸痹\n（本页列出该病常见证型，请根据患者实际四诊资料选择相应证型，切勿直接套用）\n\n一、心血瘀阻\n    症状舌脉：心胸疼痛剧烈，如刺如绞，痛有定处，入夜为甚，甚则心痛彻背、背痛彻心，或痛引肩背，伴有胸闷，日久不愈，可因暴怒、劳累而加重，舌质紫暗有瘀斑、苔薄，脉弦涩\n    治法：活血化瘀、通脉止痛\n    方剂：血府逐瘀汤\n\n二、气滞心胸\n    症状舌脉：心胸满闷，隐痛阵发，痛无定处，时欲太息，遇情志不遂时容易诱发或加重，或兼有脘腹胀闷、得嗳气或矢气则舒，苔薄或薄腻，脉细弦\n    治法：疏肝理气、活血通络\n    方剂：柴胡疏肝散\n\n三、痰浊闭阻\n    症状舌脉：胸闷重而心痛微，痰多气短，肢体沉重，形体肥胖，遇阴雨天而易发作或加重，伴有倦怠乏力、纳呆便溏、咯吐痰涎，舌体胖大且边有齿痕、苔浊腻或白滑，脉滑\n    治法：通阳泄浊、豁痰宣痹\n    方剂：栝蒌薤白半夏汤合涤痰汤\n\n四、寒凝心脉\n    症状舌脉：猝然心痛如绞，心痛彻背，喘不得卧，多因气候骤冷或骤感风寒而发病或加重，伴形寒、甚则手足不温、冷汗自出、胸闷气短、心悸，苔薄白，脉沉紧或沉细\n    治法：辛温散寒、宣通心阳\n    方剂：枳实薤白桂枝汤合当归四逆汤\n\n五、气阴两虚\n    症状舌脉：心胸隐痛，时作时休，心悸气短，动则益甚，伴倦怠乏力、声息低微、面色㿠白、易汗出，舌质淡红、舌体胖且边有齿痕、苔薄白，脉虚细缓或结代\n    治法：益气养阴、活血通脉\n    方剂：生脉散合人参养荣汤\n\n六、心肾阴虚\n    症状舌脉：心痛憋闷，心悸盗汗，虚烦不寐，腰酸膝软，头晕耳鸣，口干便秘，舌红少津、苔薄或剥，脉细数或促代\n    治法：滋阴清火、养心和络\n    方剂：天王补心丹合炙甘草汤\n\n七、心肾阳虚\n    症状舌脉：心悸而痛，胸闷气短，动则更甚，自汗，面色㿠白，神倦怯寒，四肢欠温或肿胀，舌质淡胖、边有齿痕、苔白或腻，脉沉细迟\n    治法：温补阳气、振奋心阳\n    方剂：参附汤合右归饮。来源：《中医内科学》（中国中医药出版社“十四五”规划教材）·心系病证·胸痹。提示：胸痛剧烈持续不缓解、伴汗出肢冷者须警惕急性心肌梗死，立即呼叫急救\n\n【方剂参考】\n  血府逐瘀汤：组成 桃仁12g、红花9g、当归9g、生地黄9g、川芎4.5g、赤芍6g、牛膝9g、桔梗4.5g、柴胡3g、枳壳6g、甘草6g；功效 活血化瘀，行气止痛\n      用法：水煎温服，日二次；亦可制为丸剂或口服液，每次10ml，日三次。\n      注意：孕妇忌用；有出血倾向（血小板减少、活动性溃疡、月经量多）者慎用；体虚无瘀者不可用。\n  柴胡疏肝散：组成 陈皮（醋炒）6g、柴胡6g、川芎4.5g、香附4.5g、枳壳（麸炒）4.5g、白芍4.5g、炙甘草1.5g；功效 疏肝解郁，行气止痛\n      用法：水煎温服，日一剂，分两次服；亦可研末为散，每服6~9g，开水送下。\n      注意：阴虚火旺、气郁化火及孕妇慎用；本方辛散，久服易耗气伤阴。来源：《方剂学》（中国中医药出版社“十四五”规划教材）·理气剂（行气）；原方出自《景岳全书·古方八阵》\n  桂枝汤：组成 桂枝9g、芍药9g、生姜9g、大枣3枚、炙甘草6g；功效 解肌发表，调和营卫\n      用法：水煎温服，服后啜热稀粥一碗以助药力，覆被取微汗；一服汗出病瘥即停，不汗更服，不必尽剂。\n      注意：表实无汗、外感风热、温热病及酒客湿热内蕴者忌用；服药期间忌生冷、油腻、酒酪、臭恶之物。\n  生脉散：组成 人参9g、麦冬9g、五味子6g；功效 益气生津，敛阴止汗\n      用法：水煎温服，日二至三次；气阴欲脱时可频服或代茶饮，亦可服生脉口服液、注射液（急症）。\n      注意：外感表证未解、湿热内盛及实热证者忌用；五味子酸收，痰多者慎用；人参反藜芦，不宜同用。\n  天王补心丹：组成 生地黄12g、人参9g、丹参9g、玄参9g、茯苓9g、五味子6g、远志6g、桔梗6g、当归9g、天冬9g、麦冬9g、柏子仁9g、酸枣仁9g、朱砂0.3g；功效 滋阴养血，补心安神\n      用法：上药为末，炼蜜为丸如梧桐子大，朱砂为衣，每次6-9g，空腹或睡前以竹叶煎汤送服，日二次；亦可作汤剂，朱砂冲服且量宜小。\n      注意：脾胃虚弱、纳差便溏及痰湿内盛者不宜；朱砂含汞，不可过量久服，肝肾功能不全者禁用；忌与碘、溴化物同服。\n  参附汤：组成 人参9g、制附子9g（先煎）；功效 益气回阳固脱\n      用法：水煎，附子先煎30~60分钟，人参另煎兑服，日一剂，分两次温服；急救时宜浓煎顿服。\n      注意：本方为急救之剂，不可久服；热厥及阴虚阳亢者忌用；阳气回复后须辨证续治，不可专恃温补。来源：《方剂学》（中国中医药出版社“十四五”规划教材）·温里剂（回阳救逆）；原方出自《正体类要·卷下》\n\n【西医诊断】\n  冠心病 稳定型心绞痛\n  （西医诊断依据与鉴别诊断请结合患者病史、体征、辅助检查补充）\n\n医师签名：＿＿＿＿"},"icd10_diagnosis":"I25.1","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2642,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"271faa3a569f5616194dc819171278059e4f7e6a7b9fa2d2e4fb68d553339968","pinyin":"xiongbi(guanxinbingzhongyibianzheng)","initials":"xb(gxbzybz)","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源","中医辨证参考"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源 中医辨证参考",30],["主要诊断编码","I25.1",30]]},{"id":"templates-4197b54c2017bfd76479","key":"v1-c9ccc21dfe2a3058|templates-4197b54c2017bfd76479","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"胸部创伤(急诊评估与处理)","category":"胸外科","raw":{"name":"胸部创伤(急诊评估与处理)","category":"胸外科","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】胸痛、呼吸困难、呼吸急促、发绀、咯血、皮下气肿（握雪感）、气管偏移、血压下降、心率增快、颈静脉怒张（心脏压塞/张力性气胸）、胸部伤口（开放伤可见吸吮性伤口）、胸廓畸形与反常呼吸（连枷胸）、合并伤表现：腹部压痛（肝脾破裂）、意识改变（颅脑损伤）、骨盆与四肢骨折。\n【待人工确认·本机素材无此段原文】","现病史":"胸部创伤是创伤致死的常见原因，可分为危及生命的即刻损伤（气道梗阻、张力性气胸、开放性气胸、连枷胸、心脏压塞、大出血）与潜在致命损伤（食管破裂、膈肌破裂、肺挫伤、心肌挫伤）。处理遵循ATLS原则：气道→呼吸→循环，多数胸部创伤可通过胸腔闭式引流等简单措施处理，仅少数需急诊开胸。\n常见表现：胸痛、呼吸困难、呼吸急促、发绀、咯血、皮下气肿（握雪感）、气管偏移、血压下降、心率增快、颈静脉怒张（心脏压塞/张力性气胸）、胸部伤口（开放伤可见吸吮性伤口）、胸廓畸形与反常呼吸（连枷胸）、合并伤表现：腹部压痛（肝脾破裂）、意识改变（颅脑损伤）、骨盆与四肢骨折。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：呼吸频率与形态、血氧、心率、血压、意识（ATLS评估）\n气道：口腔与气道内有无异物、血液、分泌物与骨折（气道梗阻）\n颈部：气管位置（向健侧移位提示张力性气胸/大量血胸）、颈静脉充盈（怒张提示心脏压塞/张力性气胸）、皮下气肿\n胸部视诊：胸廓畸形、呼吸动度（双侧对比）、反常呼吸（连枷胸）、开放性伤口与吸吮声\n胸部触诊：肋骨压痛与骨擦感、皮下气肿（握雪感）、语颤（减弱提示气胸/血胸）\n胸部叩诊与听诊：鼓音（气胸）/浊音（血胸）、呼吸音减弱或消失、心音遥远\n合并伤：腹部压痛（肝脾破裂）、骨盆与四肢骨折、脊柱与颅脑损伤","辅助检查":"1. 血常规+血型+交叉配血+凝血功能：急查并动态监测血红蛋白，备血（胸部创伤常需输血）\n2. 血气分析+乳酸：低氧血症、通气障碍与组织灌注评估\n3. 心肌酶（CK-MB、肌钙蛋白）+心电图：心肌挫伤与心律失常评估\n4. 床旁超声（FAST+eFAST）：心包积液、胸腔积液与气胸的快速评估（创伤首选）\n5. 胸部X线+胸部增强CT：气胸血胸量、肋骨骨折、肺挫伤、纵隔血肿与膈肌破裂\n6. 淀粉酶+肝功能：合并腹部损伤评估\n7. 尿常规+尿量：组织灌注与泌尿系损伤筛查","初步诊断":"1. 初级评估（ABCDE，ATLS）：气道通畅性、呼吸音与呼吸动度、循环（脉搏、血压、颈静脉）、意识与瞳孔\n2. 床旁超声（FAST+eFAST）：快速判断心包积液（心脏压塞）、胸腔积液（血胸）与气胸（肺滑动征消失）\n3. 胸部X线：气胸、血胸、肋骨骨折、纵隔增宽（主动脉损伤）、膈肌破裂\n4. 胸部增强CT：稳定患者首选，评估肺挫伤、气胸血胸量、肋骨骨折、纵隔与血管损伤\n5. 心电图+心肌酶：心肌挫伤与心律失常评估\n6. 血气分析+乳酸：低氧血症与组织灌注评估\n7. 胸腔闭式引流结果：引流血性液体量（>1500ml或>200ml/h持续3小时提示需开胸探查）\n1. 胸部创伤(急诊评估与处理)（ICD-10：S29.9）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【药物治疗·输液】\n⚠️ 抢救用药，患者监护下按病情选择！\n\n方案1（抗休克液体复苏，控制性复苏）：\n 用法：平衡盐溶液/0.9%氯化钠 快速补液（晶体为主）；红细胞悬液、新鲜冰冻血浆按1:1:1输注；目标Hb 70～90g/L、收缩压80～90mmHg（活动性出血未控制时避免过度升压）\n\n方案2（止血辅助）：\n 用法：氨甲环酸 1g 静滴（伤后3小时内）；维生素K1 10mg 静滴\n\n方案3（镇痛与呼吸支持）：\n 用法：曲马多 100mg 静滴 或 氟比洛芬酯 50mg 静滴 q12h（充分镇痛以利于咳嗽排痰）；必要时无创通气\n\n方案4（抗感染）：\n 用法：头孢呋辛 1.5g 静滴 q8h + 甲硝唑 0.5g 静滴 q8h（开放性损伤/胸腔引流后）\n\n📌 张力性气胸与心脏压塞需立即穿刺减压，不能等待影像学检查；限制晶体液避免加重肺挫伤。\n\n【药物治疗·口服】\n⚠️ 稳定后遵医嘱，同类只选一种：\n\n药物1（镇痛）：\n 用法：对乙酰氨基酚 0.5g 必要时 或 塞来昔布 200mg qd；必要时曲马多 50mg\n\n药物2（化痰排痰）：\n 用法：氨溴索 30mg tid 或 乙酰半胱氨酸 0.6g tid\n\n药物3（抗感染序贯）：\n 用法：头孢呋辛酯 0.25g bid 或 阿莫西林克拉维酸 0.625g tid\n\n药物4（通便镇咳）：\n 用法：乳果糖 15ml bid；复方甲氧那明 2粒 tid（干咳明显者）\n\n📌 充分镇痛是有效排痰与预防肺部感染的关键；肋骨骨折患者应避免抑制呼吸的强效镇静药。\n\n【治疗】\n立即处理危及生命的损伤：气道梗阻（清理气道/气管插管）、张力性气胸（锁骨中线第2肋间粗针穿刺减压）、开放性气胸（凡士林敷料封闭+闭式引流）、连枷胸（镇痛+固定+必要时机械通气）\n心脏压塞：床旁超声确诊后立即心包穿刺或急诊开胸（剑突下心包开窗）\n大量血胸/进行性血胸：胸腔闭式引流+抗休克；引流>1500ml或>200ml/h持续3小时行开胸探查\n肺挫伤：限制液体、充分镇痛排痰、必要时机械通气（小潮气量保护性通气）\n食管/膈肌破裂：急诊手术修补（胸腔镜或开胸）\n肋骨骨折：多根多处骨折（连枷胸）行胸壁固定或手术内固定\n抗感染与破伤风预防（开放性损伤）\n并发症处理：脓胸（引流+抗感染）、肺不张与肺炎（排痰+抗感染）、ARDS（保护性通气）\n\n【处理要点】\n按ABC顺序评估与处理，边处理边评估（创伤救治的'黄金十分钟'）\n呼吸管理：吸氧、监测血氧与呼吸音，鼓励深呼吸与有效咳嗽，必要时吸痰与无创通气\n胸腔闭式引流护理：保持密闭与通畅，观察水封瓶气泡（漏气）与水柱波动，记录引流量与性状（血性、乳糜样）\n液体管理：限制晶体液（避免肺挫伤加重肺水肿），监测出入量与尿量\n镇痛管理：多模式镇痛（硬膜外/椎旁阻滞+静脉），评估疼痛评分并保证有效咳嗽\n合并伤评估：腹部（FAST/CT）、颅脑、脊柱与四肢（避免漏诊）\n观察病情变化：呼吸与循环状态、皮下气肿范围、疼痛与腹部体征（迟发性血气胸、膈肌破裂）\n\n【护理】\n急救护理：配合气道管理与穿刺减压，快速建立静脉通路，遵医嘱补液输血，监测生命体征每5～15分钟\n呼吸护理：吸氧、保持气道通畅、鼓励深呼吸与有效咳嗽、协助体位排痰（充分镇痛前提下）\n闭式引流护理：保持密闭与通畅、低于胸腔60～100cm，观察气泡与引流量、记录性状，搬动时夹闭\n疼痛护理：评估疼痛评分，遵医嘱多模式镇痛（保证有效咳嗽与活动）\n并发症观察：呼吸与血氧变化、皮下气肿范围、腹痛（迟发性膈肌破裂/腹腔出血）、发热与引流液浑浊（脓胸）\n功能锻炼与宣教：早期活动、呼吸功能锻炼、戒烟、避免剧烈活动与感染，按时复查\n\n【饮食】\n急性期禁食禁水（可能急诊手术或需观察），必要时静脉营养\n病情稳定后：高蛋白、高热量、高维生素饮食促进创伤修复\n多饮水（心功能与液体管理允许下），稀释痰液利于咳出\n避免产气食物与辛辣刺激食物；戒烟\n贫血者增加含铁与优质蛋白食物（瘦肉、动物肝脏、蛋奶）\n\n【注意事项】\n胸部创伤处理遵循ATLS的ABCDE原则：气道与呼吸问题优先，多数通过穿刺减压、闭式引流等简单措施即可稳定\n张力性气胸与心脏压塞是'立即致命'损伤，必须临床诊断并立即处理，不能等待影像学\n限制晶体液是肺挫伤处理的重要原则（过量补液加重肺水肿与呼吸衰竭）\n肺挫伤常在伤后24～48小时进展，需动态观察血氧与影像\n迟发性血气胸可发生于伤后数小时至数天，需随访胸片\n\n【急诊/急救】\n极度呼吸困难、气管偏移、患侧呼吸音消失伴血压下降（张力性气胸）→ 立即穿刺减压+闭式引流\n颈静脉怒张、心音遥远、血压下降（心脏压塞）→ 立即心包穿刺或急诊开胸\n胸腔引流>1500ml或>200ml/h持续3小时、血压不稳（进行性血胸）→ 急诊开胸探查\n开放性胸壁伤口有吸吮声（开放性气胸）→ 立即封闭伤口并置管引流\n呼吸困难加重伴血氧下降（肺挫伤致ARDS）→ 立即机械通气支持","资料来源":"疾病库 diseases.json"},"icd10_diagnosis":"S29.9","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2643,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"e6292cb39be6988c0a81ced0f0c792df2a912b0e02ed0547d35abce8e2fb70eb","pinyin":"xiongbuchuangshang(jizhenpingguyuchuli)","initials":"xbcs(jzpgycl)","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","S29.9",30]]},{"id":"templates-bd70ff1cbcdc6cc938f4","key":"v1-c9ccc21dfe2a3058|templates-bd70ff1cbcdc6cc938f4","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"脂溢性角化病","category":"烧伤整形科","raw":{"name":"脂溢性角化病","category":"烧伤整形科","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】淡褐色至黑色斑片或丘疹、表面粗糙，呈油腻性鳞屑、好发于颜面、手背、胸背等部位、通常多发，随年龄增长而增多、一般无自觉症状，偶有瘙痒。\n【待人工确认·本机素材无此段原文】","现病史":"脂溢性角化病是一种常见的良性表皮肿瘤，多见于中老年人，以颜面、手背、胸背等处出现淡褐色至黑色斑片或丘疹为特征。\n常见表现：淡褐色至黑色斑片或丘疹、表面粗糙，呈油腻性鳞屑、好发于颜面、手背、胸背等部位、通常多发，随年龄增长而增多、一般无自觉症状，偶有瘙痒。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"检查计划：患者中老年起病，颜面、手背、胸背等处多发淡褐色至黑色斑片或丘疹，表面粗糙呈油腻性鳞屑且随年龄增长而增多，需与色素痣、基底细胞癌、黑色素瘤等相鉴别；查皮肤镜检查明确皮损的色素分布与血管结构，协助鉴别良恶性并判断是否需手术切除；完善皮肤组织病理检查明确表皮角化过度、棘层肥厚及乳头瘤样增生等改变，作为确诊依据并排除恶变；完善血常规、凝血功能、肝肾功能、血糖及传染病筛查（乙肝、丙肝、梅毒、HIV）等术前常规检查，评估手术耐受性，为激光或手术切除治疗提供安全保障；完善心电图检查排除心脏疾病，评估麻醉及手术风险；对颜面多发病损者完善胸部X线检查评估心肺情况；对色深、边界不清、近期增大或破溃者，完善局部超声检查了解病变深度及与周围组织关系，必要时完善区域淋巴结超声检查排除转移；术后定期复查及皮肤镜检查随访有无复发与新发病损。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 中老年人多见\n2. 淡褐色至黑色斑片或丘疹，表面粗糙呈油腻性\n3. 好发于颜面、手背等暴露部位\n4. 组织病理：表皮角化过度，棘层肥厚，乳头瘤样增生\n1. 脂溢性角化病（ICD-10：L82）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【药物治疗·输液】\n一般无需静脉用药\n\n【药物治疗·口服】\n一般无需口服药物\n\n【治疗】\n一般无需治疗\n影响美观者可采用冷冻治疗、激光治疗、电灼治疗\n外用维A酸软膏\n可疑恶变者手术切除并做病理检查\n\n【处理要点】\n避免搔抓、摩擦\n注意防晒\n不要自行抠挖，以免感染或恶变\n短期内迅速增大、颜色不均、破溃出血者需及时就医\n\n【注意事项】\n本病为良性肿瘤，极少恶变\n多见于中成年人，随年龄增长而增多\n避免自行处理，以免感染或遗留瘢痕\n\n【急诊/急救】\n皮损迅速增大、破溃出血、怀疑恶变时需手术切除并做病理检查","资料来源":"疾病库 diseases.json"},"icd10_diagnosis":"L82","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2644,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"b40caa0c5a91c912c6aadc06cabdf2175f5a602f0d33fcf5423a96490dc466d8","pinyin":"zhiyixingjiaohuabing","initials":"zyxjhb","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","L82",30]]},{"id":"templates-65e0863cfe7ed5d82bfa","key":"v1-c9ccc21dfe2a3058|templates-65e0863cfe7ed5d82bfa","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"脊柱脊髓损伤","category":"院前急救","raw":{"name":"脊柱脊髓损伤","category":"院前急救","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】外伤后颈/胸/腰背部疼痛、损伤平面以下感觉减退/消失、肢体无力/瘫痪、大小便失禁/潴留、腹胀（胸腰段损伤）、呼吸困难（颈髓损伤，C4以上可致呼吸骤停）、脊髓休克：弛缓性瘫痪、反射消失、阴茎异常勃起（颈髓损伤）。\n【待人工确认·本机素材无此段原文】","现病史":"外伤导致脊柱骨折/脱位，压迫或损伤脊髓，可致损伤平面以下瘫痪。现场正确搬运是防止二次损伤的关键。\n常见表现：外伤后颈/胸/腰背部疼痛、损伤平面以下感觉减退/消失、肢体无力/瘫痪、大小便失禁/潴留、腹胀（胸腰段损伤）、呼吸困难（颈髓损伤，C4以上可致呼吸骤停）、脊髓休克：弛缓性瘫痪、反射消失、阴茎异常勃起（颈髓损伤）。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征（快速评估ABC）：意识（清醒/呼之能应/无反应）、气道（通畅/梗阻）、呼吸（存在/停止/频率/节律）、脉搏（桡动脉/颈动脉/股动脉，存在/停止）、血压（可测/不可测）、血氧\n一般情况：神志、面色（苍白/发绀/潮红）、体位、有无大汗\n皮肤黏膜：温度/湿度/颜色、出血点/瘀斑、伤口/出血（部位/量/活动性）、烧伤（面积/深度）、发绀\n头颈部：瞳孔（大小/对光反射）、耳鼻出血/脑脊液漏、颈椎损伤（固定）、颈静脉怒张\n胸部：胸廓对称/畸形（连枷胸）、呼吸动度、心尖搏动、心率心律、心音、双肺呼吸音（单侧消失提示气胸/血胸）、皮下气肿\n腹部：膨隆/凹陷、压痛（观察反应）、肌紧张、移动性浊音、外出血\n骨盆：挤压分离试验（骨盆骨折）\n四肢：畸形/肿胀/压痛/反常活动（骨折）、脉搏（桡/足背）、毛细血管充盈、感觉运动（脊髓损伤评估）\n脊柱：轴线对位、压痛（脊髓损伤风险）\n其他：GCS评分、创伤评分、现场环境安全","辅助检查":"1. 脊柱CT（损伤节段三维重建，必要时全脊柱扫描）：急诊首选快速筛查骨折脱位，入院即完成\n2. 全脊柱MRI（T1/T2/压脂像）：明确脊髓水肿、出血、受压程度及韧带损伤，生命体征稳定后尽早完成\n3. 血气分析+电解质：评估呼吸肌受累（C4以上损伤警惕低通气/高碳酸血症）、酸碱失衡及电解质紊乱\n4. 血常规、凝血功能、肝肾功能+交叉配血：完成术前评估，为急诊减压内固定手术备血准备\n5. 脊柱正侧位X线：作为CT补充，用于观察序列及动态稳定性（辅助筛查隐匿性不稳）\n6. 神经电生理（SEP/MEP，可选）：客观评估脊髓传导功能受损程度，记录基线便于预后判断","初步诊断":"1. 高处坠落/车祸/重物砸伤史\n2. 脊柱局部压痛、畸形\n3. 损伤平面以下感觉运动障碍\n4. 肛门指检（肛门括约肌张力）\n5. 脊柱X线/CT：骨折脱位\n6. MRI：脊髓损伤、椎间盘、韧带\n7. 神经平面评估（ASIA分级）\n1. 脊柱脊髓损伤（ICD-10：T09.3）","鉴别诊断":"1. 诊断要点：高处坠落/车祸/重物砸伤史\n2. 诊断要点：脊柱局部压痛、畸形\n3. 诊断要点：损伤平面以下感觉运动障碍\n4. 诊断要点：肛门指检（肛门括约肌张力）\n5. 诊断要点：脊柱X线/CT：骨折脱位\n6. 诊断要点：MRI：脊髓损伤、椎间盘、韧带\n7. 诊断要点：神经平面评估（ASIA分级）\n8. 错误搬运是导致二次损伤的最常见原因\n9. 脊髓损伤后8h内是治疗黄金期\n10. 甲泼尼龙冲击疗法有争议（增加感染风险），需个体化\n11. 颈髓损伤可出现神经源性休克（低血压+心动过缓）\n12. 阴茎异常勃起提示颈髓损伤","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！\n方案1：\n 用法：0.9%氯化钠 静滴（维持血压，保证脊髓灌注）\n方案2：\n 用法：甲泼尼龙 30mg/kg 静推（15min内，伤后3h内），后5.4mg/kg/h维持23h（争议，需评估利弊）\n方案3：\n 用法：甘露醇（减轻脊髓水肿，剂量按说明书/医嘱，注意监测肾功能与电解质）\n方案4：\n 用法：奥美拉唑 40mg 静推\n📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！\n\n药物1：\n 用法：禁食（拟手术/腹胀者）\n\n📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。\n\n【治疗】\n现场脊柱制动（最重要）\nABC：颈髓损伤注意呼吸（C4以上需通气支持）\n维持血压（MAP≥85mmHg，保证脊髓灌注）\n大剂量甲泼尼龙（伤后8h内，有争议）\n急诊影像学检查\n手术：减压、内固定（骨折脱位/压迫）\n防治并发症：压疮、泌尿系感染、肺部感染、深静脉血栓\n康复治疗\n\n【处理要点】\n现场即开始脊柱制动：颈托固定颈部\n搬运：至少4人，轴线翻身/滚动，保持脊柱中立位，使用硬板担架\n禁止抱头、抬脚、一人背送等错误搬运\n评估ABC：颈髓损伤者监测呼吸，C4以上膈肌麻痹需机械通气\n建立静脉通路，维持MAP≥85mmHg（脊髓灌注）\n不要反复尝试让患者行走\n留置尿管（尿潴留）\n甲泼尼龙（伤后3h内可考虑，30mg/kg冲击后维持）\n脊柱X线/CT/MRI\n通知骨科/神经外科\n激素、脱水（脊髓水肿）\n防治并发症：早期翻身防压疮、呼吸训练、抗凝预防DVT\n\n【护理】\n严格轴线翻身、颈托固定、脊柱板搬运，任何搬动保持头颈躯干一体，严禁屈曲旋转，转运及检查全程执行\n持续心电、血氧、血压监测：C4以上损伤立即准备气管插管/呼吸机；警惕神经源性休克（低血压+心动过缓），遵医嘱升压维持MAP≥85-90mmHg保证脊髓灌注\n留置导尿并记录尿量（神经源性膀胱），观察腹胀及自主神经反射异常（头痛、大汗、血压骤升）\n定时评估并记录感觉运动平面及括约肌功能（ASIA评分），密切观察损伤平面是否上升\n预防并发症：卧气垫床、每2小时翻身，双下肢气压泵，动态评估DVT风险后酌情抗凝；高热者物理降温\n\n【饮食】\n入院初期暂禁食水（6-8小时），为急诊手术及麻醉做准备，遵医嘱以晶体液静脉补液\n低血压或合并失血者按医嘱快速补液复苏，维持血压以保障脊髓灌注，禁忌口服补液\n术后或病情稳定后由流质、半流质逐步过渡至软食，少量多餐，观察有无呛咳及误吸\n腹胀、肠麻痹者继续禁食，必要时胃肠减压，待肠鸣音恢复、排气后再恢复进食\n恢复期高蛋白、高维生素、富含膳食纤维饮食（蛋、奶、鱼、瘦肉、蔬果），每日饮水约2000ml（心肾功能正常者），预防便秘\n\n【注意事项】\n错误搬运是导致二次损伤的最常见原因\n脊髓损伤后8h内是治疗黄金期\n甲泼尼龙冲击疗法有争议（增加感染风险），需个体化\n颈髓损伤可出现神经源性休克（低血压+心动过缓）\n阴茎异常勃起提示颈髓损伤\n不要在现场判断'没事'就让患者走动\n\n【急诊/急救】\n现场立即颈托固定，禁止任何脊柱屈曲/扭转\n4人轴线搬运：1人扶头颈部牵引，其余3人同步平托至硬板担架\n整体滚动翻身，保持头颈躯干一条直线\n禁止抱持、拖拽、让患者坐起或行走\n评估呼吸：C4以上损伤膈肌麻痹→立即气管插管机械通气\n建立静脉通路，维持MAP≥85mmHg（保证脊髓灌注压）\n神经源性休克（低血压+心动过缓）：补液+多巴胺/去甲肾上腺素\n留置尿管\n伤后3h内可考虑甲泼尼龙30mg/kg静推后5.4mg/kg/h维持\n脊柱CT+MRI，通知骨科/神经外科急诊手术减压","资料来源":"疾病库 diseases.json；鉴别诊断库 ddx_local.json（条目「脊柱脊髓损伤」原文）"},"icd10_diagnosis":"T09.3","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2645,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"ff0b81bef62706899c52d5548c25add16cca4df7a4476ca4b91c8893c24f7e04","pinyin":"jizhujisuisunshang","initials":"jzjsss","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","T09.3",30]]},{"id":"templates-022f7702fd16c0b9c72e","key":"v1-c9ccc21dfe2a3058|templates-022f7702fd16c0b9c72e","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"脐疝与白线疝(成人)","category":"疝与腹壁外科","raw":{"name":"脐疝与白线疝(成人)","category":"疝与腹壁外科","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】脐部或上腹中线处可复性包块，站立、用力与咳嗽时增大，平卧可回纳、局部胀痛或坠胀感，包块增大时明显；白线疝疼痛常位于上腹正中、嵌顿：包块不能回纳、变硬、疼痛加剧，伴恶心呕吐与腹胀（肠梗阻）、合并腹水者：脐疝可迅速增大、皮肤变薄发亮，破裂风险高（可致腹水外漏）、部分白线疝仅表现为上腹疼痛而无明显包块（易误诊为胃病）。\n【待人工确认·本机素材无此段原文】","现病史":"成人脐疝多因腹壁薄弱（肥胖、多次妊娠、腹水、慢性咳嗽）致腹腔内容物经脐环突出，白线疝（腹上疝）则经腹白线纤维间隙突出。两者均可逐渐增大并发生嵌顿，成人脐疝嵌顿率较高（尤其合并腹水者），确诊后一般建议手术修补（补片无张力修补为主）。\n常见表现：脐部或上腹中线处可复性包块，站立、用力与咳嗽时增大，平卧可回纳、局部胀痛或坠胀感，包块增大时明显；白线疝疼痛常位于上腹正中、嵌顿：包块不能回纳、变硬、疼痛加剧，伴恶心呕吐与腹胀（肠梗阻）、合并腹水者：脐疝可迅速增大、皮肤变薄发亮，破裂风险高（可致腹水外漏）、部分白线疝仅表现为上腹疼痛而无明显包块（易误诊为胃病）。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：体温、脉搏、血压、体重与腹围（腹水评估）\n一般情况：BMI、营养状态、有无慢性咳嗽和便秘、有无肝硬化体征\n腹部视诊：脐部/上腹中线包块（大小、形态）、腹壁静脉曲张、腹围、皮肤张力\n腹部触诊：包块能否回纳、疝环大小（可容指数）、压痛、腹壁缺损范围；肝脾大小\n腹部叩诊：移动性浊音（腹水）、包块叩诊\n腹部听诊：肠鸣音（嵌顿时亢进或减弱）\n合并症评估：下肢水肿、黄疸、蜘蛛痣（肝硬化）","辅助检查":"1. 血常规+CRP：术前基线，嵌顿时白细胞升高\n2. 肝功能+白蛋白+胆红素+凝血功能：腹水患者肝储备评估（决定手术时机）\n3. 电解质+肾功能：利尿治疗与腹水管理监测\n4. 腹部超声/CT（含Valsalva）：明确疝环大小、腹壁缺损范围与疝内容物（术前规划）\n5. 乳酸+腹部立位平片：嵌顿/绞窄与肠梗阻评估\n6. 血糖+糖化血红蛋白+心电图：术前常规评估（肥胖与老年患者）\n7. 腹水检查（必要时）：细胞数、蛋白、SAAG（鉴别门静脉高压性腹水与其他原因）","初步诊断":"1. 体格检查：脐部/腹白线处包块、能否回纳、疝环大小与压痛（站立位与卧位对比）\n2. 腹部超声：明确疝内容物（肠管、网膜）与疝环，鉴别脐部脂肪瘤与脐尿管囊肿\n3. 腹部CT（含Valsalva）：肥胖、复发性或多发疝者，明确疝环大小与腹壁缺损范围（术前规划）\n4. 腹部立位平片：嵌顿伴肠梗阻时可见气液平面\n5. 血常规+CRP+乳酸：嵌顿/绞窄时白细胞与乳酸升高\n6. 合并腹水者：肝功能、腹部超声/CT评估腹水与门静脉高压（需先控制腹水再手术）\n1. 脐疝与白线疝(成人)（ICD-10：K42.9）","鉴别诊断":"1. 腹部超声：明确疝内容物（肠管、网膜）与疝环，鉴别脐部脂肪瘤与脐尿管囊肿\n2. 部分白线疝仅表现为上腹疼痛而无明显包块（易误诊为胃病）\n3. 诊断要点：体格检查：脐部/腹白线处包块、能否回纳、疝环大小与压痛（站立位与卧位对比）\n4. 诊断要点：腹部超声：明确疝内容物（肠管、网膜）与疝环，鉴别脐部脂肪瘤与脐尿管囊肿\n5. 诊断要点：腹部CT（含Valsalva）：肥胖、复发性或多发疝者，明确疝环大小与腹壁缺损范围（术前规划）\n6. 诊断要点：腹部立位平片：嵌顿伴肠梗阻时可见气液平面\n7. 诊断要点：血常规+CRP+乳酸：嵌顿/绞窄时白细胞与乳酸升高\n8. 诊断要点：合并腹水者：肝功能、腹部超声/CT评估腹水与门静脉高压（需先控制腹水再手术）","处理方案":"【药物治疗·输液】\n⚠️ 围手术期按医嘱选择方案，切勿全部同时使用！\n\n方案1（术前预防性抗感染，切皮前0.5～1小时）：\n 用法：头孢呋辛 1.5g 静滴（单次）或 头孢唑林 1g 静滴\n\n方案2（嵌顿/绞窄术前）：\n 用法：头孢呋辛 1.5g 静滴 q8h + 甲硝唑 0.5g 静滴 q8h；补液（平衡盐溶液 500～1000ml）\n\n方案3（肝硬化腹水患者围手术期）：\n 用法：白蛋白 10g 静滴（低蛋白/腹水者）；呋塞米 20～40mg 静推 + 螺内酯（利尿，按医嘱）；必要时补充凝血因子\n\n方案4（术后支持）：\n 用法：0.9%氯化钠/葡萄糖 静滴；镇痛与营养支持\n\n📌 合并大量腹水者应先控制腹水（利尿、限盐、必要时放腹水+白蛋白）再手术，否则修补失败率高。\n\n【药物治疗·口服】\n⚠️ 术后与合并症用药，按医嘱选择：\n\n药物1（镇痛）：\n 用法：塞来昔布 200mg qd 或 洛索洛芬钠 60mg tid（餐后）\n\n药物2（通便）：\n 用法：乳果糖 15ml bid 或 聚乙二醇4000散 1袋 qd\n\n药物3（利尿，腹水者）：\n 用法：螺内酯 40mg qd + 呋塞米 20mg qd（按尿量、体重与电解质调整）\n\n药物4（降门脉压，肝硬化者）：\n 用法：普萘洛尔 10mg bid 起（按心率调整，遵医嘱）\n\n📌 腹水患者术后应继续控制腹水与腹内压，避免腹压骤增致修补失败。\n\n【治疗】\n手术治疗：疝环较小、缺损<3cm可行单纯缝合修补；缺损>3cm或复发者行补片无张力修补（开放或腹腔镜IPOM）\n术前优化：减重、控制慢性咳嗽与便秘、控制腹水（肝硬化患者）、戒烟、控制血糖\n嵌顿/绞窄：急诊手术，切除坏死肠管并修补（感染时不用补片）\n肝硬化腹水患者：术前控制腹水与改善肝功能，术后加强利尿与白蛋白支持，警惕修补失败与腹水漏\n术后管理：腹带加压3个月、避免腹压增高、控制体重\n白线疝：小的可缝合修补，多发缺损（Swiss cheese型）需补片修补\n并发症处理：血清肿（多自行吸收）、切口感染（换药引流，必要时取出补片）、复发（再次修补）\n\n【处理要点】\n术前准备：控制腹水（肝硬化者）、减重、控制咳嗽与便秘、备皮、术前排空膀胱\n术后体位与活动：平卧位、腹带加压，麻醉清醒后6小时可下床轻度活动\n切口与腹部观察：观察渗血渗液、局部肿胀与腹围变化（腹水患者警惕腹水漏）\n腹压管理：避免剧烈咳嗽、用力排便与提重物，必要时镇咳通便；腹带使用3个月\n腹水管理（肝硬化者）：每日测体重与腹围、记录尿量，遵医嘱利尿与补充白蛋白，监测电解质\n出院指导：控制体重、戒烟、治疗慢性咳嗽与便秘、按时复查、复发及时就诊\n\n【护理】\n术前护理：腹水患者限制钠盐与液体、监测体重腹围与尿量；控制咳嗽与便秘；备皮与术前准备\n术后观察：切口渗血渗液、局部肿胀（血清肿）、腹围与体重变化（警惕腹水漏）\n腹带使用：术后腹带加压固定3个月，指导正确佩戴与皮肤保护\n腹压管理宣教：避免剧烈咳嗽、用力排便与提重物，必要时镇咳通便药\n腹水护理（肝硬化者）：每日测体重与腹围、记录尿量，遵医嘱利尿并监测电解质与肾功能\n出院宣教：控制体重、戒烟、治疗慢性咳嗽与便秘、按时复查、出现复发或疼痛及时就诊\n\n【饮食】\n术前禁食禁水6～8小时\n术后6小时进流质，逐步过渡到半流质、软食、普食\n腹水患者：严格限制钠盐（每日<2g）、适量限制液体，高蛋白饮食（肝性脑病风险者遵医嘱调整）\n多饮水（无腹水者）、多食蔬菜水果与粗纤维，保持大便通畅\n控制体重（肥胖是脐疝重要诱因）；忌烟酒与辛辣刺激食物\n\n【注意事项】\n成人脐疝不会自愈，且嵌顿风险随缺损增大而增加（尤其合并腹水者），建议择期手术\n合并大量腹水的脐疝修补失败率高，术前应先控制腹水；破裂风险高者需紧急处理\n白线疝可仅表现为上腹疼痛而无明显包块，反复上腹痛患者应仔细触诊腹白线\n缺损>3cm者应使用补片修补（单纯缝合复发率高）\n术后控制腹内压增高因素（咳嗽、便秘、肥胖、腹水）是防复发关键\n\n【急诊/急救】\n脐部包块不能回纳伴剧烈腹痛与呕吐（嵌顿）→ 急诊手术\n脐疝皮肤变薄发亮伴渗液（腹水外漏/破裂）→ 立即急诊处理并补充白蛋白与抗感染\n发热、腹膜刺激征、乳酸升高（绞窄坏死）→ 立即急诊手术\n肝硬化腹水患者脐疝快速增大伴疼痛 → 急诊评估（破裂风险）","资料来源":"疾病库 diseases.json；鉴别诊断库 ddx_local.json（条目「脐疝与白线疝（成人）」原文）"},"icd10_diagnosis":"K42.9","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2646,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"2a98b795001a7bf530337a183ba004d2f158a240534060bdddf7d0239696cd5c","pinyin":"qishanyubaixianshan(chengren)","initials":"qsybxs(cr)","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","K42.9",30]]},{"id":"templates-1b84baf312677d333ae8","key":"v1-c9ccc21dfe2a3058|templates-1b84baf312677d333ae8","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"脑动脉瘤破裂","category":"鉴别诊断速查","raw":{"name":"脑动脉瘤破裂","category":"鉴别诊断速查","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】未破裂动脉瘤：多无症状，大者可有占位效应（视力下降、动眼神经麻痹）、破裂出血：突发剧烈头痛（'一生中最剧烈的头痛'）、恶心呕吐、意识障碍、脑膜刺激征、动眼神经麻痹：后交通动脉瘤压迫动眼神经→眼睑下垂、瞳孔散大、眼球外斜、脑血管痉挛：出血后3-14天，表现为意识恶化、局灶神经功能缺损、脑积水：出血后急性或慢性，表现为头痛、呕吐、意识障碍、步态不稳、癫痫发作。\n【待人工确认·本机素材无此段原文】","现病史":"临床表现为恶心、呕吐、神志不清、肢体活动障碍，可见病理征阳性，头部影像学检查可见出血病灶。\n常见表现：未破裂动脉瘤：多无症状，大者可有占位效应（视力下降、动眼神经麻痹）、破裂出血：突发剧烈头痛（'一生中最剧烈的头痛'）、恶心呕吐、意识障碍、脑膜刺激征、动眼神经麻痹：后交通动脉瘤压迫动眼神经→眼睑下垂、瞳孔散大、眼球外斜、脑血管痉挛：出血后3-14天，表现为意识恶化、局灶神经功能缺损、脑积水：出血后急性或慢性，表现为头痛、呕吐、意识障碍、步态不稳、癫痫发作。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：体温、脉搏（徐缓提示颅内压增高）、呼吸（节律改变：潮式呼吸/叹息样）、血压（Cushing三联征：血压升高/脉搏徐缓/呼吸深慢）、血氧\n一般情况：神志（GCS评分：睁眼/语言/运动，满分15分）、精神状态、体位\n头颈部：头皮血肿/裂伤/手术瘢痕、颅骨凹陷、耳鼻出血/脑脊液漏（Battle征/熊猫眼）、颈强直、颈抵抗\n颅神经：瞳孔（大小/形状/对光反射，双侧对比，一侧散大固定提示小脑幕切迹疝）、眼球运动、面肌、听力、吞咽\n运动系统：肌力（0-5级，双侧对比）、肌张力（增高/降低/去脑强直/去皮质强直）、肌萎缩、不自主运动\n感觉系统：痛觉/触觉/位置觉（清醒患者）\n反射：深反射（亢进/减弱/消失）、病理征（Babinski/Chaddock/Oppenheim/Gordon）\n脑膜刺激征：颈强直、Kernig征、Brudzinski征\n其他：呼吸道通畅情况、有无呕吐（喷射性）、视乳头水肿（眼底检查）","辅助检查":"检查计划：患者突发剧烈头痛，伴恶心呕吐、意识障碍及脑膜刺激征，高度怀疑动脉瘤破裂所致蛛网膜下腔出血，急诊即刻完善头颅CT平扫检查明确脑沟、脑池、脑室有无高密度出血影并判断出血范围；对发病24小时内头颅CT平扫阴性而临床仍高度怀疑者，完善腰椎穿刺检查明确脑脊液是否呈均匀血性；为明确动脉瘤位置、大小与形态，完善头颅CTA检查，其无创快速并可同时显示载瘤动脉情况；病情允许时完善全脑血管造影DSA检查，作为诊断金标准明确动脉瘤详情并指导介入栓塞或开颅夹闭方案；对未破裂动脉瘤或CTA显示不清者，完善头颅MRI检查及MRA了解动脉瘤与周围脑组织、颅神经的关系；完善血常规检查了解有无感染、贫血及血小板水平，为手术及介入治疗提供依据；同时完善凝血功能、肝肾功能、电解质及血糖检查评估全身状况与手术耐受性；完善心电图、心肌酶及胸部X线检查排除心肺部合并症，完善血型鉴定与交叉配血以备术中输血；动态复查头颅CT及经颅多普勒超声评估有无再出血、脑血管痉挛与脑积水。\n\n（检查清单）\n1. 头颅CTA检查\n2. 全脑血管造影DSA\n3. 头颅CT平扫\n4. 头颅MRI检查\n5. 血常规检查","初步诊断":"1. 突发剧烈头痛+脑膜刺激征→高度怀疑\n2. 头颅CT：蛛网膜下腔高密度影（脑沟、脑池、脑室），发病24h内阳性率>95%\n3. CTA：无创，可显示动脉瘤位置、大小、形态\n4. DSA（数字减影血管造影）：金标准，可明确动脉瘤详情并指导治疗\n5. MRI/MRA：未破裂动脉瘤筛查\n6. 腰椎穿刺：CT阴性但高度怀疑时，脑脊液呈均匀血性\n7. Hunt-Hess分级和WFNS分级评估病情严重程度\n1. 脑动脉瘤破裂（ICD-10：I60.9）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！\n\n方案1：\n 用法：尼莫地平微量泵入5-10ml/h（防治脑血管痉挛，持续21天）\n\n方案2（3H疗法）：\n 用法：高血压、高血容量、血液稀释（脑血管痉挛时）\n\n方案3：\n 用法：20%甘露醇125-250ml静滴（颅高压时）\n\n方案4：\n 用法：氨甲环酸0.5g静滴 bid（短期止血，<72h）\n\n方案5：\n 用法：奥美拉唑40mg静推 q12h\n\n方案6（镇静镇痛）：\n 用法：咪达唑仑、芬太尼\n\n方案7（抗癫痫）：\n 用法：丙戊酸钠持续泵入\n\n📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！\n\n药物1：\n 用法：尼莫地平60mg q4h（口服，防治脑血管痉挛）\n\n药物2：\n 用法：丙戊酸钠0.5g bid\n\n药物3：\n 用法：左乙拉西坦0.5g bid\n\n药物4：\n 用法：降压药（控制血压<140/90mmHg）\n\n📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。\n\n【治疗】\n急诊处理：绝对卧床、镇静、镇痛、控制血压、降颅压、抗癫痫、防治脑血管痉挛\n病因治疗（防止再出血）：开颅动脉瘤夹闭术、血管内介入栓塞术（弹簧圈）、血流导向装置\n手术时机：破裂动脉瘤患者72小时内尽早处理（超早期）\n迟发性脑缺血（DCI）防治：尼莫地平（静滴0.5-1mg/h或口服60mg q4h共21天）+维持正常血容量与灌注压+必要时脑脊液引流；不推荐预防性3H疗法，仅动脉瘤已处理后的难治性症状性血管痉挛可在严密监护下谨慎诱导高血压；严重者血管内治疗（球囊血管成形或动脉内钙拮抗剂灌注）\n脑积水：脑室外引流（急性）或脑室-腹腔分流术（慢性）\n\n【处理要点】\n术前：绝对卧床、避免声光刺激、控制血压、保持大便通畅、避免用力\n监测：意识、瞳孔、生命体征、神经功能评分\n脑血管痉挛监测：TCD（经颅多普勒）每日检查，关注MCA血流速度\n脑脊液引流：腰大池引流或脑室外引流，引流血性脑脊液\n并发症防治：再出血、脑血管痉挛、脑积水、癫痫、低钠血症、心肺并发症\n术后：ICU监护、控制血压、继续尼莫地平、康复训练\n随访：术后3、6、12个月复查DSA或CTA，了解动脉瘤复发和载瘤动脉通畅\n未破裂动脉瘤：根据大小、位置、形态、患者年龄和合并症决定干预或观察\n\n【护理】\n绝对卧床休息\n情绪护理\n血压控制护理\n预防再出血护理\n术前准备护理\n\n【饮食】\n清淡饮食\n低盐饮食\n高纤维饮食\n避免刺激性饮食\n\n【注意事项】\n【鉴别要点】临床表现为恶心、呕吐、神志不清、肢体活动障碍，可见病理征阳性，头部影像学检查可见出血病灶。\n颅内动脉瘤破裂是蛛网膜下腔出血最常见原因（约85%）\n再出血死亡率极高（首次30-40%，再次60-70%），应尽早处理\n脑血管痉挛是SAH致死致残的主要原因，出血后3-14天为高峰期\n尼莫地平是唯一被证实可改善SAH预后的药物\n介入栓塞创伤小、恢复快，已成为多数动脉瘤的首选治疗\n未破裂动脉瘤年破裂率约0.5-1%，但>7mm、后循环、形态不规则者风险高\n【来源】字段对齐库内同名基础条目，未新增医学内容（核查报告_B B-H1/B-H2/B-M12 修复）\n\n【急诊/急救】\n突发剧烈头痛→急诊CT，确诊后绝对卧床、控制血压、尼莫地平\n意识恶化→警惕再出血或脑血管痉挛，立即CT/CTA\n急性脑积水→急诊脑室外引流\n癫痫→地西泮静推","资料来源":"疾病库 diseases.json"},"icd10_diagnosis":"I60.9","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2647,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"8dd00d1a6abfdb8efbf1bda2857d172a703e19661fef7c457e381592c1b7a78c","pinyin":"naodongmailiupolie","initials":"ndmlpl","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","I60.9",30]]},{"id":"templates-0905d8be63c82eb1b1ba","key":"v1-c9ccc21dfe2a3058|templates-0905d8be63c82eb1b1ba","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"脑卒中","category":"鉴别诊断速查","raw":{"name":"脑卒中","category":"鉴别诊断速查","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】突发一侧肢体无力/麻木、突发言语不清/理解困难、突发口角歪斜、突发视物模糊/失明、突发剧烈头痛、头晕、行走不稳、意识障碍。\n【待人工确认·本机素材无此段原文】","现病史":"患者可有基础疾病史如高血压病、糖尿病，患者可突发口齿不清，肢体偏瘫，可伴不同程度意识障碍，头颅MRI可明确诊断；\n常见表现：突发一侧肢体无力/麻木、突发言语不清/理解困难、突发口角歪斜、突发视物模糊/失明、突发剧烈头痛、头晕、行走不稳、意识障碍。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征（快速评估ABC）：意识（清醒/呼之能应/无反应）、气道（通畅/梗阻）、呼吸（存在/停止/频率/节律）、脉搏（桡动脉/颈动脉/股动脉，存在/停止）、血压（可测/不可测）、血氧\n一般情况：神志、面色（苍白/发绀/潮红）、体位、有无大汗\n皮肤黏膜：温度/湿度/颜色、出血点/瘀斑、伤口/出血（部位/量/活动性）、烧伤（面积/深度）、发绀\n头颈部：瞳孔（大小/对光反射）、耳鼻出血/脑脊液漏、颈椎损伤（固定）、颈静脉怒张\n胸部：胸廓对称/畸形（连枷胸）、呼吸动度、心尖搏动、心率心律、心音、双肺呼吸音（单侧消失提示气胸/血胸）、皮下气肿\n腹部：膨隆/凹陷、压痛（观察反应）、肌紧张、移动性浊音、外出血\n骨盆：挤压分离试验（骨盆骨折）\n四肢：畸形/肿胀/压痛/反常活动（骨折）、脉搏（桡/足背）、毛细血管充盈、感觉运动（脊髓损伤评估）\n脊柱：轴线对位、压痛（脊髓损伤风险）\n其他：GCS评分、创伤评分、现场环境安全","辅助检查":"1. 头颅CT平扫（急诊首选，发病即刻完成，快速排除脑出血，决定能否静脉溶栓）\n2. 床旁快速血糖（急诊第一时间测定，排除低血糖性昏迷所致假性卒中，并作为溶栓前基线）\n3. 血常规+凝血功能+电解质+肝肾功能（急诊抽血、溶栓前必查，评估出血风险与溶栓禁忌）\n4. 心电图（急诊常规，排查房颤等心源性栓塞病因，并除外急性心肌梗死合并卒中）\n5. 头颅MRI（DWI）及头颈部血管成像（CTA/MRA）：CT阴性而高度疑诊缺血性卒中、或疑大血管闭塞拟行机械取栓时尽快完善；有条件可加做CT灌注评估缺血半暗带\n6. 血气分析（意识障碍、呼吸异常或疑缺氧、酸碱失衡时检查）","初步诊断":"1. FAST识别：Face面瘫、Arm肢体无力、Speech言语、Time时间\n2. 突发神经功能缺损\n3. 头颅CT鉴别出血/梗死\n4. 发病时间是关键\n1. 脑卒中（ICD-10：I63.9）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！\n\n方案1：\n 用法：建立静脉通路，NS维持\n\n方案2（避免低血糖）：\n 用法：50%GS40ml iv（血糖<3.3mmol/L）\n\n方案3：\n 用法：避免大量补液\n\n方案4（脑出血）：\n 用法：甘露醇125ml ivgtt（颅内压高时）\n\n方案5（脑梗死）：\n 用法：发病4.5小时内可溶栓（rt-PA 0.9mg/kg）\n\n📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！\n\n药物1：\n 用法：院前以静脉用药为主\n\n药物2：\n 用法：不要随意给降压药\n\n📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。\n\n【治疗】\n快速识别FAST，记录发病时间\n保持气道通畅，吸氧\n建立静脉通路，监测血糖\n侧卧防误吸（意识障碍者）\n避免过度降压（除非SBP>200或DBP>110）\n避免低血糖，低血糖补糖\n脑出血：降颅压（甘露醇），控制血压\n脑梗死：时间窗内转有溶栓/取栓能力医院\n抽搐：地西泮10mg iv\n120转院，提前通知医院\n\n【处理要点】\n平卧或侧卧，避免搬动\n保持气道通畅，防误吸\n监测生命体征及血糖\n记录发病时间及症状变化\n避免喂食喂水（防误吸）\n注意保暖\n\n【护理】\n立即平卧、头偏向一侧，保持气道通畅，及时清除口鼻分泌物；SpO2＜94%时予吸氧；每15分钟监测意识（GCS评分）、瞳孔及生命体征并记录\n溶栓/取栓抢救配合：快速建立两条静脉通路（一条专用给溶栓药），备好阿替普酶（rt-PA），遵医嘱按时给药，全程观察皮肤黏膜、牙龈、消化道及颅内出血征象，如有头痛加剧、呕吐、意识恶化立即报告\n血压管理：遵医嘱控制血压，溶栓前血压控制在185/110mmHg以下，避免快速过度降压导致低灌注；监测双侧肢体血压差异\n液体管理：控制输液速度，避免快速大量补液加重脑水肿；记录出入量，按医嘱患者脱水降颅压药物（甘露醇等）时观察尿量\n防误吸与并发症：吞咽评估前严格禁食禁水，防误吸；定时翻身拍背防压疮，早期踝泵运动或气压泵预防深静脉血栓\n\n【饮食】\n急性期24小时内、吞咽功能评估（洼田饮水试验）通过前：禁食禁水，防止误吸，必要时遵医嘱静脉补液\n吞咽评估通过后先试温开水，无呛咳再进食\n进食取坐位或抬高床头30°~45°、头稍前倾，少量多餐，以软食、半流质为主，温度适宜\n低盐、低脂、低糖饮食，忌烟酒；合并高血压者限制钠盐，合并糖尿病者控制主食与糖分摄入\n恢复期均衡饮食，增加蔬菜水果与优质蛋白，保证充足饮水，防止便秘（避免用力排便诱发血压波动）\n\n【注意事项】\n【鉴别要点】患者可有基础疾病史如高血压病、糖尿病，患者可突发口齿不清，肢体偏瘫，可伴不同程度意识障碍，头颅MRI可明确诊断；\n时间就是大脑，越早越好\n发病时间是溶栓/取栓的关键\n不要随意用降压药、止血药、活血药\n先CT鉴别出血/梗死再针对性治疗\n转有卒中中心的医院\n【2023中国急性缺血性卒中指南更新】前循环大血管闭塞取栓（EVT）时间窗：发病6小时内直接取栓，经多模影像（CTP/MRI）筛选可延长至6-16小时，严格筛选者至24小时；院前应尽快转运至具备静脉溶栓+血管内取栓能力的卒中中心，避免因转运延误错失时间窗（静脉溶栓4.5h内，rt-PA 0.9mg/kg，已收录）。\n【来源】字段对齐库内同名基础条目，未新增医学内容（核查报告_B B-H1/B-H2/B-M12 修复）\n\n【急诊/急救】\nFAST识别：面瘫、肢体无力、言语不清\n记录发病时间（最后正常时间）\n侧卧防误吸，保持气道通畅\n吸氧，监测血糖\n建立静脉通路（NS维持）\n低血糖：50%GS40ml iv\n抽搐：地西泮10mg iv\n120转有溶栓/取栓能力的卒中中心\n不要随意用降压/止血/活血药","资料来源":"疾病库 diseases.json"},"icd10_diagnosis":"I63.9","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2648,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"8307c6364ff82a4ad9dfd7afa24bb3317bb9669a09d2e47d7c5ff3351a998f3d","pinyin":"naozuzhong","initials":"nzz","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","I63.9",30]]},{"id":"templates-2cfbbdbc9accb0f147c2","key":"v1-c9ccc21dfe2a3058|templates-2cfbbdbc9accb0f147c2","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"脑梗塞","category":"鉴别诊断速查","raw":{"name":"脑梗塞","category":"鉴别诊断速查","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】突发偏瘫/偏身感觉障碍、口角歪斜、言语不清/失语、头晕、行走不稳、视物模糊/视野缺损、意识障碍（大面积梗死）、多在安静/睡眠中起病。\n【待人工确认·本机素材无此段原文】","现病史":"患者可有基础疾病史，如：高血压、糖尿病，患者可肢体偏瘫口齿不清，重者可有不同程度意识障碍，偏侧体征，头颅磁共振可确证。\n常见表现：突发偏瘫/偏身感觉障碍、口角歪斜、言语不清/失语、头晕、行走不稳、视物模糊/视野缺损、意识障碍（大面积梗死）、多在安静/睡眠中起病。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：体温（多正常，合并感染/吸收热可升高）、脉搏（可正常/增快/不齐，房颤时绝对不齐）、呼吸（可正常，脑干梗死可有节律改变）、血压（多升高，急性期应激反应）、血氧（可下降）\n一般情况：神志清或嗜睡/昏睡/昏迷（大面积梗死/脑干梗死），精神状态可改变，言语可障碍\n皮肤黏膜：无特殊，可有房颤体征\n头颈部：颈动脉搏动可减弱/不对称（颈动脉狭窄），可闻及颈动脉血管杂音，颈软无抵抗\n颅神经：中枢性面瘫（对侧鼻唇沟变浅/口角歪斜/额纹存在）、构音障碍、吞咽困难（球麻痹）、视野缺损（同向偏盲）、瞳孔（脑干梗死可异常）\n运动系统：对侧肢体肌力下降（0-5级，取决于梗死部位和大小）、肌张力增高（急性期可降低，随后增高）、腱反射亢进（急性期可减弱）、病理征阳性（Babinski征等）、共济失调（小脑梗死）\n感觉系统：对侧偏身感觉减退/消失\n反射：深反射不对称（患侧亢进），病理征阳性\n脑膜刺激征：阴性（除非出血转化）\n其他：失语（运动性/感觉性/混合性，优势半球梗死）、失用/失认、GCS评分（意识障碍时）","辅助检查":"1. 头颅CT平扫：急诊首选，发病后即刻完成，用于排除脑出血（溶栓/取栓前必查）\n2. 头颅MRI+DWI：发病6小时内即可超早期显影梗死灶，明确梗死部位、大小及分期，入院后尽早完成；联合MRA评估颅内血管狭窄或闭塞\n3. 颈动脉超声+经颅多普勒（TCD）：评估颅内外血管狭窄程度、侧支循环及不稳定斑块，24小时内完成\n4. 血常规、凝血功能、血糖、血脂、肝肾功能、同型半胱氨酸：寻找病因及危险因素，入院即刻采血（溶栓前必查血糖、凝血）\n5. 心电图+24小时动态心电图：筛查心源性栓塞（心房颤动等），入院即行心电监护至少24小时\n6. 神经功能量表：NIHSS评分、mRS评分，入院时、溶栓后2小时及24小时动态评估","初步诊断":"1. 突发局灶神经功能缺损\n2. 头颅CT（早期可正常，排除出血）\n3. 头颅MRI/DWI（早期确诊）\n4. CTA/MRA评估血管\n5. NIHSS评分\n6. 危险因素：高血压、糖尿病、房颤、高血脂\n1. 脑梗塞（ICD-10：I63.9）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！\n\n方案1：\n 用法：阿替普酶 rt-PA 0.9mg/kg（最大90mg）：先取总量10%静推（1min内），余90%加入NS持续静滴1h（4.5h时间窗内；溶栓前血压须<185/110mmHg且CT排除出血）\n\n方案2：\n 用法：尿激酶（6h内）\n\n方案3：\n 用法：丁基苯酞 25mg bid 静滴\n\n方案4：\n 用法：依达拉奉 30mg bid 静滴\n\n方案5：\n 用法：0.9%氯化钠 静滴\n\n方案6：\n 用法：甘露醇（脑水肿）\n\n📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！\n\n药物1：\n 用法：阿司匹林 100-300mg qd（溶栓24h后）\n\n药物2：\n 用法：氯吡格雷 75mg qd\n\n药物3：\n 用法：阿托伐他汀 40-80mg qn（强化降脂）\n\n药物4：\n 用法：丁基苯酞 0.2g tid\n\n药物5：\n 用法：二级预防用药\n\n📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。\n\n【治疗】\n超早期溶栓/取栓（时间窗内）\n抗血小板（阿司匹林+氯吡格雷21天）\n强化他汀\n改善循环/脑保护\n控制血压血糖\n康复训练（早期开始）\n二级预防\n\n【处理要点】\n识别中风FAST：Face口角歪斜、Arm肢体无力、Speech言语不清、Time立即拨打120\n溶栓时间窗4.5h，越早越好\n发病24-48h内不要急于降压（除非>220/120或溶栓）\n吞咽功能评估（防误吸）\n早期康复介入\n房颤患者抗凝治疗\n\n【护理】\n病情观察：急性期每1-2小时监测生命体征并记录NIHSS评分，重点观察意识、语言、肢体肌力变化，血压控制在医嘱范围、避免剧烈波动\n意识与瞳孔评估：每4小时评估GCS评分及瞳孔大小、对光反射；出现意识障碍加深、瞳孔不等大、剧烈头痛立即报告医生（警惕脑疝、梗死后出血转化）\n体位与气道管理：急性期平卧或床头抬高15-30°，昏迷或吞咽障碍者头偏向一侧，及时清除口鼻分泌物，防止误吸；必要时吸氧、吸痰\n防跌倒防误吸：偏瘫侧加床栏、穿防滑鞋，下床及如厕须有人陪同；吞咽障碍者暂禁食水，留置胃管\n康复护理与并发症预防：生命体征平稳后48小时尽早予良肢位摆放及被动关节活动，每2小时翻身拍背预防压疮，气压泵/弹力袜预防下肢深静脉血栓\n\n【饮食】\n吞咽评估先行：进食前做床旁洼田饮水试验，吞咽障碍者暂禁食，留置胃管行肠内营养，预防误吸性肺炎\n急性期48小时内给予清淡流质/半流质（米汤、藕粉、去油鱼汤），病情平稳后逐步过渡至软食\n低盐低脂饮食：每日食盐＜5g，少食动物内脏、肥肉、油炸食品，控制总热量\n推荐富含膳食纤维及优质蛋白食物：新鲜蔬菜、水果、全谷物、鱼类（富含Omega-3）、豆制品、瘦肉\n合并高血压/糖尿病者严格限盐、定时定量进餐、监测血糖；戒烟限酒，避免过饱及进餐过快\n\n【注意事项】\n【鉴别要点】患者可有基础疾病史，如：高血压、糖尿病，患者可肢体偏瘫口齿不清，重者可有不同程度意识障碍，偏侧体征，头颅磁共振可确证。\n时间就是大脑，溶栓每延迟1分钟损失190万个神经元\n不要自行服用阿司匹林（需先排除脑出血）\nCT排除出血前不能溶栓/抗血小板\n溶栓后24h复查CT无出血才开始抗血小板\n【2023中国急性缺血性卒中诊治指南更新】静脉溶栓：阿替普酶（rt-PA 0.9mg/kg）4.5小时时间窗内；替奈普酶（TNK-tPA 0.25mg/kg）单次静推（5-10秒）可作为4.5小时内的替代方案（证据等级提升）。\n【2023指南更新】血管内取栓（EVT）：前循环大血管闭塞（颈内动脉/大脑中动脉M1段）发病6小时内直接取栓；经多模影像（CTP/MRI-DWI）筛选，时间窗可延长至6-16小时，部分经严格筛选者可达24小时（DAWN/DEFUSE-3标准），不再局限于6小时。\n【2023指南更新】轻型卒中（NIHSS≤3分）非心源性栓塞：阿司匹林+氯吡格雷双抗21天后改为单药（CHANCE-2/POINT方案，已收录）；发病24-48小时内不急于降压（除非>220/120mmHg或拟溶栓/取栓）。\n【来源】字段对齐库内同名基础条目，未新增医学内容（核查报告_B B-H1/B-H2/B-M12 修复）\n\n【急诊/急救】\n突发偏瘫、失语、意识障碍→立即拨打120，记住发病时间（决定能否溶栓）","资料来源":"疾病库 diseases.json"},"icd10_diagnosis":"I63.9","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2649,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"c3cee190287d47076e2f42040bd7138bebf8f66b70fcf4d8c624356cbaa081c2","pinyin":"naogengse","initials":"ngs","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","I63.9",30]]},{"id":"templates-dcbe597aba9286d16121","key":"v1-c9ccc21dfe2a3058|templates-dcbe597aba9286d16121","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"脑疝(颅内压增高危象)","category":"神经内科","raw":{"name":"脑疝(颅内压增高危象)","category":"神经内科","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】剧烈头痛、喷射性呕吐与视乳头水肿（颅压增高三联征）、意识迅速恶化（嗜睡→昏迷）与烦躁不安、患侧瞳孔先缩小后散大、对光反射迟钝或消失（小脑幕切迹疝）、血压升高伴心率减慢与呼吸节律异常（Cushing反应，脑干受压）、去大脑强直（四肢伸直与角弓反张）与呼吸骤停（枕骨大孔疝终末期）。\n【待人工确认·本机素材无此段原文】","现病史":"脑疝是颅内压急剧增高致脑组织从高压区向低压区移位、压迫脑干与颅神经的危象，常见类型为小脑幕切迹疝（钩回疝）与枕骨大孔疝（小脑扁桃体疝）。表现为意识恶化、瞳孔不等大、血压升高伴心率减慢（Cushing反应）与呼吸异常，属神经科最危急情况，需立即降颅压并病因处理。\n常见表现：剧烈头痛、喷射性呕吐与视乳头水肿（颅压增高三联征）、意识迅速恶化（嗜睡→昏迷）与烦躁不安、患侧瞳孔先缩小后散大、对光反射迟钝或消失（小脑幕切迹疝）、血压升高伴心率减慢与呼吸节律异常（Cushing反应，脑干受压）、去大脑强直（四肢伸直与角弓反张）与呼吸骤停（枕骨大孔疝终末期）。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"意识与瞳孔：GCS（每15～30分钟）、瞳孔大小与对光反射（不等大为脑疝核心体征）\n生命体征：血压（升高）、心率（减慢）与呼吸（节律异常，Cushing反应）\n脑干反射：角膜反射、头眼反射与眼前庭反射（脑干功能评估）\n肢体姿势：去大脑强直（四肢伸直）或去皮质强直（上肢屈曲）\n眼底：视乳头水肿（颅压增高证据）\n神经系统定位：偏瘫与病理反射（病因定位）\n其他：头皮外伤、手术瘢痕与脑室外引流管位置","辅助检查":"1. 头颅CT（紧急，首选）：占位、出血、水肿、中线移位与脑室受压\n2. 电解质（钠、钾）+血浆渗透压+肾功能：高渗治疗监测（甘露醇与高渗盐水）\n3. 血气分析：通气与氧合状态（机械通气调整）\n4. 血糖（立即）：低血糖可模拟脑疝样意识障碍\n5. 头颅MRI/CTA（稳定后）：病因评估（肿瘤、血管病变与静脉窦血栓）\n6. 颅内压监测（有条件）：ICP与脑灌注压（CPP）\n7. 凝血功能+血常规（术前）：手术前评估与准备","初步诊断":"1. 神经系统查体（关键）：GCS、瞳孔大小与对光反射、脑干反射与肢体姿势（动态评估每15～30分钟）\n2. 生命体征：血压升高、心率减慢与呼吸异常（Cushing反应）\n3. 头颅CT（紧急）：颅内占位、出血、脑水肿、中线移位与脑室受压/脑疝征象\n4. 眼底检查：视乳头水肿（颅压增高证据）\n5. 病因评估：脑出血、大面积脑梗死、颅内肿瘤、颅脑外伤、颅内感染与脑积水\n6. 电解质+血气分析+血糖：代谢因素与通气状态\n7. 鉴别诊断：中毒与代谢性脑病（瞳孔改变与意识障碍）、癫痫发作后状态与低血糖昏迷\n1. 脑疝(颅内压增高危象)（ICD-10：G93.5）","鉴别诊断":"1. 鉴别诊断：中毒与代谢性脑病（瞳孔改变与意识障碍）、癫痫发作后状态与低血糖昏迷\n2. 诊断要点：神经系统查体（关键）：GCS、瞳孔大小与对光反射、脑干反射与肢体姿势（动态评估每15～30分钟）\n3. 诊断要点：生命体征：血压升高、心率减慢与呼吸异常（Cushing反应）\n4. 诊断要点：头颅CT（紧急）：颅内占位、出血、脑水肿、中线移位与脑室受压/脑疝征象\n5. 诊断要点：眼底检查：视乳头水肿（颅压增高证据）\n6. 诊断要点：病因评估：脑出血、大面积脑梗死、颅内肿瘤、颅脑外伤、颅内感染与脑积水\n7. 诊断要点：电解质+血气分析+血糖：代谢因素与通气状态","处理方案":"【药物治疗·输液】\n⚠️ 抢救用药：立即降颅压，争取病因治疗时间！\n\n方案1（快速降颅压，首选高渗治疗）：\n 用法：20%甘露醇 250ml 静滴（15～30分钟内快速滴完，必要时q4～6h）；或 3%氯化钠 150～250ml 静滴（15～30分钟，血钠目标145～155mmol/L）；呋塞米 20～40mg 静推（辅助）；监测尿量、电解质与肾功能\n\n方案2（激素，仅用于肿瘤/血管源性水肿）：\n 用法：地塞米松 10mg 静推 q6h（脑肿瘤与转移瘤周围水肿；创伤与缺血性卒中不推荐常规使用）\n\n方案3（气道与通气管理）：\n 用法：气管插管与机械通气（GCS≤8或呼吸异常）；短期过度通气（PaCO₂ 30～35mmHg，仅作临时措施）；头高位30°、避免颈部受压与躁动\n\n方案4（病因与支持）：\n 用法：脑出血/肿瘤——急诊手术或血肿清除；脑积水——脑室外引流；颅内感染——抗生素；癫痫——地西泮 10mg 缓慢静推；维持血压与灌注（避免低血压）\n\n📌 脑疝抢救核心是『立即降颅压+病因处理』；甘露醇与高渗盐快速输注（15～30分钟内）；避免低血压与低氧（加重脑损伤）；禁用镇静剂（除插管后）。\n\n【药物治疗·口服】\n⚠️ 急性期不能口服；稳定后用药：\n\n药物1（口服降颅压与激素减量）：\n 用法：甘油果糖口服液 25ml tid（轻症或过渡期）；泼尼松（肿瘤水肿，按医嘱逐渐减量）；乙酰唑胺 250mg bid（脑积水，遵医嘱）\n\n药物2（抗癫痫维持）：\n 用法：左乙拉西坦 500mg bid（有癫痫或术后预防，疗程依病因，不可骤停）\n\n药物3（通便与对症）：\n 用法：乳果糖 15～30ml bid（防便秘与用力致颅压升高）；对乙酰氨基酚 0.5g 必要时（头痛与发热）\n\n药物4（康复与支持）：\n 用法：甲钴胺 0.5mg tid（神经修复）；碳酸钙D3（长期激素者）；营养支持（管饲或口服补充剂）\n\n📌 颅压增高者禁用：大量补液、血管扩张药（硝酸酯类）、镇静药（未插管者）与用力排便；随访需复查头颅CT/MRI与神经功能。\n\n【治疗】\n立即降颅压：甘露醇或高渗盐水快速输注（15～30分钟），呋塞米辅助，头高位30°与限制液体\n气道与呼吸支持：气管插管与机械通气（GCS≤8或呼吸异常），短期过度通气（临时）\n病因治疗（关键）：脑出血/肿瘤/外伤行急诊手术（血肿清除或去骨瓣减压）；脑积水行脑室外引流；颅内感染抗感染；癫痫控制发作\n监测与评估：每小时神经查体（GCS、瞳孔与脑干反射）、有创动脉压、颅内压监测（有条件）与血气\n血压与灌注管理：维持MAP与脑灌注压（CPP 60～70mmHg），避免低血压与高血压（依病因调整）\n电解质与液体管理：高渗治疗期间监测血钠（145～155mmol/L）、血钾与肾功能；避免低渗液体\n并发症处理：癫痫、肺部感染、应激性溃疡与深静脉血栓（预防）\n随访与康复：术后/稳定后神经功能评估与康复（认知、运动与吞咽）；抗癫痫药与病因随访\n\n【处理要点】\n神经功能监测（核心）：每15～30分钟评估GCS、瞳孔与脑干反射（直至稳定），异常立即报告并复查CT\n颅压管理护理：头高位30°、头颈中立（避免颈静脉受压）、避免躁动与用力、遵医嘱快速脱水\n气道护理：保持通畅、吸氧与按需吸痰、插管者口腔护理与呼吸机管理（床头抬高30～45°）\n液体与电解质监测：严格记录出入量与每小时尿量、监测血钠与肾功能（高渗治疗期间）\n安全与舒适护理：加床档、必要时镇静（插管者）、避免约束致用力、减少声光刺激\n基础护理：每2小时翻身（轴线）防压疮、口腔护理、眼部护理（眼睑闭合不全者用眼膏）\n宣教与家属沟通：解释病情危重性与抢救措施、术后康复计划与随访要求\n\n【护理】\n神经功能观察：每15～30分钟评估GCS、瞳孔与脑干反射并记录，异常立即报告\n颅压管理护理：头高位30°、头颈中立、避免躁动与用力、遵医嘱快速脱水并观察疗效\n气道护理：保持通畅、吸氧与吸痰、插管者呼吸机管理与口腔护理，床头抬高30～45°\n出入量与电解质：严格记录（每小时尿量）、监测血钠与肾功能，异常报告\n安全护理：加床档、避免约束致用力、减少声光刺激、必要时镇静（插管者）\n基础护理：每2小时轴线翻身、口腔与眼部护理（眼睑闭合不全）、肢体良肢位\n宣教与沟通：向家属解释危重性与抢救、术后康复与随访计划\n\n【饮食】\n急性期：禁食（需急诊手术或意识障碍），静脉营养支持\n稳定后：意识清醒且吞咽安全者从流质开始；不能进食者鼻饲（床头抬高30～45°）\n颅压增高者：限制液体入量（按医嘱）与钠盐\n高蛋白、高热量与高维生素饮食（神经修复与康复需求）\n便秘者：高纤维饮食与缓泻剂（避免用力排便致颅压骤升）\n\n【注意事项】\n脑疝是神经科最危急情况——意识恶化+瞳孔不等大+Cushing反应需立即降颅压与病因处理\n首次降颅压用甘露醇 250ml 快速输注（15～30分钟）；高渗盐水在低血容量与低钠患者更适用\n激素仅用于肿瘤/血管源性水肿，创伤与缺血性卒中不推荐常规使用\n颅压增高者禁用大量补液、低渗液体、血管扩张药与未插管时的镇静剂\n腰穿在颅压明显增高或脑疝征象时绝对禁忌（可诱发脑疝）\n\n【急诊/急救】\n瞳孔不等大伴意识恶化（小脑幕切迹疝）→ 立即甘露醇快速输注+激素，气管插管准备与急诊CT/手术\n呼吸骤停（枕骨大孔疝）→ 立即气管插管与机械通气+快速降颅压（高渗盐水），急诊手术减压\n抽搐伴颅压增高 → 地西泮缓慢静推+降颅压，避免镇静过量掩盖病情\n血压骤降（脑干功能衰竭终末期）→ 立即升压药与心肺复苏准备\n脑室外引流管堵塞或移位伴意识恶化 → 立即检查管路并报告（引流不畅可致颅内压骤升）","资料来源":"疾病库 diseases.json；鉴别诊断库 ddx_local.json（条目「脑疝（颅内压增高危象）」原文）"},"icd10_diagnosis":"G93.5","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2650,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"4fd11b4121c1af994b96a3392e1c2a19dc9c4ac8acd7a0e8e4ef95982d55e20d","pinyin":"naoshan(luneiyazenggaoweixiang)","initials":"ns(lnyzgwx)","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","G93.5",30]]},{"id":"templates-1552acea2efc08e6064a","key":"v1-c9ccc21dfe2a3058|templates-1552acea2efc08e6064a","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"脑脓肿","category":"神经外科","raw":{"name":"脑脓肿","category":"神经外科","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】颅内压增高：头痛（持续性、晨起加重）、喷射性呕吐、视乳头水肿、意识障碍、感染中毒症状：发热（可低热或高热）、寒战、乏力、食欲减退（慢性者可不明显）、局灶性神经缺损：偏瘫、失语、视野缺损、癫痫发作（依脓肿部位）、脑膜刺激征：颈项强直、Kernig征（合并脑膜炎时）、病情进展可出现脑疝（瞳孔不等大、呼吸不规则、意识迅速恶化）。\n【待人工确认·本机素材无此段原文】","现病史":"脑脓肿是化脓性细菌侵入脑组织形成的局限性化脓性炎症与脓腔，多继发于中耳炎/乳突炎、鼻窦炎、牙源性感染、颅脑外伤或血行播散（肺脓肿、感染性心内膜炎）。表现为颅内压增高（头痛、呕吐、视乳头水肿）、局灶性神经功能缺损与感染中毒症状，治疗包括抗感染、穿刺引流或手术切除。\n常见表现：颅内压增高：头痛（持续性、晨起加重）、喷射性呕吐、视乳头水肿、意识障碍、感染中毒症状：发热（可低热或高热）、寒战、乏力、食欲减退（慢性者可不明显）、局灶性神经缺损：偏瘫、失语、视野缺损、癫痫发作（依脓肿部位）、脑膜刺激征：颈项强直、Kernig征（合并脑膜炎时）、病情进展可出现脑疝（瞳孔不等大、呼吸不规则、意识迅速恶化）。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"意识与瞳孔：GCS评分、瞳孔大小与对光反射（脑疝筛查）\n生命体征：体温（感染）、血压与心率（Cushing反应：血压升高、心率减慢提示颅内压增高）、呼吸\n神经系统：肢体肌力、感觉、病理反射、脑膜刺激征（颈项强直、Kernig征、Brudzinski征）\n局灶体征：失语、视野缺损、共济失调、颅神经麻痹（依脓肿部位）\n眼底：视乳头水肿（颅内压增高）\n耳鼻喉与口腔：中耳炎/乳突炎体征、鼻窦压痛、牙源性感染灶（原发灶寻找）\n心肺与皮肤：肺部感染体征（肺脓肿）、心脏杂音（心内膜炎）、皮肤感染灶（血行播散来源）","辅助检查":"1. 头颅增强MRI（DWI+增强，首选）+增强CT：脓肿部位、大小、数目、环形强化与周围水肿\n2. 血常规+CRP+PCT+血沉：感染程度与治疗反应监测（每2～3天）\n3. 血培养×2套+脓液培养及药敏（穿刺或手术时）：病原学诊断（抗生素前留取）\n4. 脑脊液检查（无颅内压增高者可谨慎腰穿）：细胞数、蛋白、糖、氯化物、涂片与培养\n5. 电解质+肾功能+尿量：甘露醇脱水监测（每1～2天）\n6. 抗癫痫药物血药浓度（丙戊酸钠、左乙拉西坦）+肝功能：用药监测\n7. 胸部CT+心脏超声+耳鼻喉/口腔检查：寻找原发感染灶","初步诊断":"1. 头颅增强CT：低密度灶伴环形强化、周围水肿带（首选快速筛查）\n2. 头颅MRI（增强+DWI）：更敏感，DWI高信号（脓液）与环形强化，可鉴别肿瘤与脓肿（首选）\n3. 腰椎穿刺（慎重）：颅内压明显增高者禁做（脑疝风险）；脑脊液细胞数升高、蛋白升高、糖降低；涂片与培养（阳性率低）\n4. 血培养+感染灶培养：寻找病原菌与感染来源（耳、鼻窦、牙、肺）\n5. 耳鼻喉科与口腔科检查：寻找原发感染灶（中耳炎、鼻窦炎、牙源性）\n6. 胸片/胸部CT+心脏超声：排除肺脓肿与感染性心内膜炎（血行播散来源）\n7. 血常规+CRP+PCT+血沉：感染程度评估\n1. 脑脓肿（ICD-10：G06.0）","鉴别诊断":"1. 头颅MRI（增强+DWI）：更敏感，DWI高信号（脓液）与环形强化，可鉴别肿瘤与脓肿（首选）\n2. 胸片/胸部CT+心脏超声：排除肺脓肿与感染性心内膜炎（血行播散来源）\n3. 脑脓肿的诊断首选增强MRI（DWI可鉴别脓肿与肿瘤）","处理方案":"【药物治疗·输液】\n⚠️ 抗感染是基础，须足量足疗程并穿透血脑屏障！\n\n方案1（经验性抗感染，覆盖链球菌、葡萄球菌、厌氧菌与肠杆菌科）：\n 用法：头孢曲松 2g 静滴 q12h（或头孢噻肟 2g q6h）+ 甲硝唑 0.5g 静滴 q8h + 万古霉素 1g 静滴 q12h（疑MRSA，监测血药浓度）；重症/术后：美罗培南 2g 静滴 q8h\n\n方案2（降颅压）：\n 用法：20%甘露醇 125～250ml 静滴 q6～8h（快速静滴，监测尿量、肾功能与电解质）；或 3%氯化钠 100～150ml 静滴；地塞米松 10mg 静推（水肿明显者，短期，注意免疫抑制）\n\n方案3（抗癫痫）：\n 用法：左乙拉西坦 500mg 静滴 q12h 或 丙戊酸钠 400mg 静滴 q12h（有癫痫发作或颞叶脓肿者），监测血药浓度\n\n方案4（支持治疗）：\n 用法：0.9%氯化钠/葡萄糖 静滴；白蛋白（低蛋白/水肿者）；营养支持；维持水电解质平衡\n\n📌 抗菌疗程长（4～8周或更长，依影像与临床），须静脉给药后序贯口服；脑疝征象出现时立即降颅压并急诊处理。\n\n【药物治疗·口服】\n⚠️ 恢复期序贯用药（须按药敏与专科指导）：\n\n药物1（抗感染序贯）：\n 用法：阿莫西林克拉维酸 0.625g tid + 甲硝唑 0.4g tid；或 利奈唑胺 0.6g bid（MRSA/耐药球菌，注意血常规）\n\n药物2（抗癫痫维持）：\n 用法：左乙拉西坦 500mg bid 或 丙戊酸钠缓释片 500mg bid（疗程依病因：脓肿治愈后一般继续3～6个月，遵医嘱）\n\n药物3（脱水与激素减量）：\n 用法：泼尼松（按医嘱逐渐减量，不可骤停）；必要时甘油果糖口服\n\n药物4（营养神经与支持）：\n 用法：甲钴胺 0.5mg tid + 维生素B1 10mg tid；碳酸钙D3 600mg qd（长期激素者）\n\n📌 抗感染与抗癫痫药物均不可自行停药（脓肿复发与癫痫发作风险）；定期复查影像与血药浓度。\n\n【治疗】\n抗感染治疗：经验性广谱（穿透血脑屏障）+ 病原学指导，疗程4～8周或更长（影像显示脓肿缩小/消失），静脉为主后序贯口服\n穿刺抽脓/置管引流（首选手术方式）：脓肿直径>2.5cm、占位效应明显或抗感染效果不佳者，CT/MRI引导下穿刺抽脓+置管引流（创伤小、可反复抽吸）\n开颅脓肿切除：多房性、厚壁脓肿、异物或外伤性脓肿、穿刺失败或颅压危象者\n原发灶处理：中耳炎/乳突炎（耳科手术）、鼻窦炎（鼻窦引流）、牙源性感染（口腔处理）、肺脓肿（呼吸科）\n降颅压与抗癫痫：甘露醇/高渗盐水、短期激素、抗癫痫药物\n支持治疗：营养支持、纠正水电解质紊乱、控制血糖（糖尿病者）\n康复治疗：神经功能缺损（偏瘫、失语）行康复训练；癫痫长期随访\n随访：治疗期间每2～4周复查增强CT/MRI，直至脓肿消失；之后每3～6个月随访（复发监测）\n\n【处理要点】\n意识与瞳孔监测：每1～2小时（急性期）评估GCS与瞳孔，意识恶化或瞳孔不等大立即报告（脑疝预警）\n颅内压管理：床头抬高15～30°、保持头颈中立、避免用力与躁动、遵医嘱脱水治疗，记录尿量与电解质\n引流管护理（穿刺置管者）：妥善固定、保持通畅、记录引流液量与性状（脓性、血性），严格无菌操作\n体温与感染监测：每4小时测体温，观察感染中毒症状与血象变化，及时发现感染灶（耳、鼻窦、牙、肺）\n抗癫痫护理：观察癫痫发作类型与频率，遵医嘱按时给药、监测血药浓度；发作时保护气道与安全（防坠床与舌咬伤）\n营养与基础护理：高蛋白高热量饮食（能进食者）/鼻饲或静脉营养；口腔护理与压疮预防；高热护理\n宣教与随访：强调足疗程抗感染与按时复查影像的重要性；癫痫患者长期服药与随访；控制原发感染灶（耳鼻喉与口腔卫生）\n\n【护理】\n意识与瞳孔观察：每1～2小时评估GCS与瞳孔并记录，意识恶化或瞳孔异常立即报告（脑疝预警）\n颅内压护理：床头抬高15～30°、头颈中立、避免用力排便与躁动（必要时镇静）、遵医嘱脱水并监测电解质\n引流管护理：穿刺置管者妥善固定、保持通畅、记录引流液量与性状，严格无菌操作（换药、接头消毒）\n体温与感染护理：每4小时测体温，高热时物理降温与补液；观察感染灶（耳道流脓、鼻窦压痛、牙痛）\n癫痫护理：观察发作类型与频率，按时给予抗癫痫药；发作时保护气道、防坠床与舌咬伤，记录发作时间与表现\n营养与康复护理：能进食者高蛋白高热量饮食，吞咽障碍者鼻饲（床头抬高30～45°防误吸）；指导肢体功能康复训练\n\n【饮食】\n能进食者：高蛋白、高热量、高维生素易消化饮食（鱼、瘦肉、蛋、奶、蔬果），少量多餐\n意识障碍或吞咽困难者：鼻饲营养液（床头抬高30～45°防误吸）或静脉营养支持\n限制水分者按医嘱（颅内压增高与脱水治疗期间需控制入量）\n多食蔬菜水果与粗纤维，保持大便通畅（避免用力排便致颅压升高），必要时用缓泻剂\n控制血糖（糖尿病患者）、戒烟酒；癫痫患者避免咖啡因与酒精\n\n【注意事项】\n脑脓肿的诊断首选增强MRI（DWI可鉴别脓肿与肿瘤）；腰椎穿刺在颅内压明显增高时禁做（脑疝风险）\n抗感染必须穿透血脑屏障且疗程足够（4～8周或更长），过早停药可致复发\n脓肿>2.5cm或有明显占位效应者应穿刺引流（创伤小，优于开颅切除）\n必须寻找并处理原发感染灶（中耳炎、鼻窦炎、牙源性、肺脓肿），否则易复发\n脑脓肿可致癫痫（尤其颞叶脓肿），需长期抗癫痫治疗与随访\n\n【急诊/急救】\n意识迅速恶化、瞳孔不等大、血压升高伴心率减慢（脑疝）→ 立即降颅压（甘露醇/高渗盐水）并急诊CT/手术\n癫痫持续状态（发作>5分钟或反复发作）→ 立即静推地西泮/咪达唑仑+抗癫痫药负荷量，保护气道\n脓肿破入脑室（高热、意识障碍、脑膜刺激征加重）→ 急诊脑室外引流+抗感染\n引流管引出大量新鲜血液（脓肿内出血）→ 立即复查CT并报告医师处理","资料来源":"疾病库 diseases.json；鉴别诊断库 ddx_local.json（条目「脑脓肿」原文）"},"icd10_diagnosis":"G06.0","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2651,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"9317c640b427fed84a1672ee74e38b38e6d487d7a3558084f57b0e491d86d8e0","pinyin":"naonongzhong","initials":"nnz","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","G06.0",30]]},{"id":"templates-f6d27b724429f644fac6","key":"v1-c9ccc21dfe2a3058|templates-f6d27b724429f644fac6","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"脑血管痉挛","category":"鉴别诊断速查","raw":{"name":"脑血管痉挛","category":"鉴别诊断速查","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】患者多数出现一过性单侧肢体障碍，数小时可自行恢复，行脑血管检查可进一步明确。。\n【待人工确认·本机素材无此段原文】","现病史":"患者多数出现一过性单侧肢体障碍，数小时可自行恢复，行脑血管检查可进一步明确。\n常见表现：患者多数出现一过性单侧肢体障碍，数小时可自行恢复，行脑血管检查可进一步明确。。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：体温、脉搏、呼吸、血压、血氧\n一般情况：神志、精神状态、面容、体位\n皮肤黏膜：颜色/温度/湿度/皮疹/出血点/黄染/水肿\n头颈部：瞳孔/巩膜/咽部/扁桃体/颈静脉/淋巴结/甲状腺\n胸部：心率心律/心音/杂音/双肺呼吸音/啰音/哮鸣音\n腹部：压痛/反跳痛/肌紧张/肝脾肿大/移动性浊音/肠鸣音\n神经系统：意识/瞳孔/肌力/病理征/脑膜刺激征\n四肢：脉搏/水肿/活动度","辅助检查":"检查计划：患者出现一过性单侧肢体障碍、数小时可自行恢复，需明确有无脑血管痉挛及短暂性脑缺血发作，入院即刻完善头颅CT平扫检查排除脑出血、脑梗死及颅内占位；完善头颅MRI+DWI检查明确有无急性缺血灶，评估脑组织损伤范围；完善颈动脉+椎动脉超声及经颅多普勒超声检查了解颅内外血管血流速度，评估有无血管痉挛、狭窄或斑块；完善头颈部CTA或MRA检查明确颅内大血管有无狭窄、闭塞、动脉瘤或血管畸形；必要时完善全脑血管造影DSA检查作为金标准进一步明确血管病变；完善血常规、凝血功能及D-二聚体检查了解有无感染、贫血及高凝状态；完善血脂、血糖及糖化血红蛋白检查明确脑血管病危险因素；完善肝肾功能、电解质检查排除电解质紊乱及肝肾功能不全；完善心电图、心脏彩超检查排除心房颤动及心源性栓塞；完善同型半胱氨酸、抗心磷脂抗体等检查排除高凝状态及免疫相关病因，定期复查经颅多普勒超声观察血管痉挛的动态变化。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 患者多数出现一过性单侧肢体障碍，数小时可自行恢复，行脑血管检查可进一步明确。\n1. 脑血管痉挛（ICD-10：I67.8）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！\n\n方案1：\n 用法：【待补·缺依据】本病为鉴别诊断速查条目，库内无对应静脉用药素材\n\n【药物治疗·口服】\n⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！\n\n药物1：\n 用法：【待补·缺依据】本病为鉴别诊断速查条目，库内无对患者药素材\n\n【治疗】\n【待补·缺依据】本病为「鉴别诊断速查」条目，库内无对应基础条目，未生成处理原则\n\n【处理要点】\n完善相关检查明确诊断\n对症支持治疗\n\n【注意事项】\n【鉴别要点】患者多数出现一过性单侧肢体障碍，数小时可自行恢复，行脑血管检查可进一步明确。\n【待补·缺依据】缺处理原则素材，未生成（禁止占位式表述）\n\n【急诊/急救】\n患者多数出现一过性单侧肢体障碍，数小时可自行恢复，行脑血管检查可进一步明确。","资料来源":"疾病库 diseases.json"},"icd10_diagnosis":"I67.8","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2652,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"9d806ef5e6d4015c603a3b678b8151a977569b6991f061828d80ac16cbdc35dc","pinyin":"naoxueguanjingluan","initials":"nxgjl","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","I67.8",30]]},{"id":"templates-63aa6f8831590a4ac04f","key":"v1-c9ccc21dfe2a3058|templates-63aa6f8831590a4ac04f","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"脾功能亢进与脾切除术","category":"肝胆外科","raw":{"name":"脾功能亢进与脾切除术","category":"肝胆外科","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】贫血（乏力、面色苍白、活动后心悸气短）、感染易感性增加（白细胞减少）、出血倾向（血小板减少）、左上腹胀痛或坠胀感、餐后饱胀（脾大压迫胃）、肝硬化门静脉高压者伴腹水、食管胃底静脉曲张（可致呕血黑便）、黄疸、血液病者伴原发病表现（如淋巴瘤发热、遗传性球形红细胞增多症黄疸）、脾梗死或脾周围炎时左上腹剧痛并向左肩放射。\n【待人工确认·本机素材无此段原文】","现病史":"脾功能亢进（脾亢）是各种原因（肝硬化门静脉高压、血液病、感染、免疫性疾病）致脾大伴外周血细胞一系或多系减少，脾切除后血象可改善。脾切除指征包括脾亢致严重血细胞减少、门静脉高压致食管胃底静脉破裂出血（断流术）、脾外伤、脾肿瘤与某些血液病。\n常见表现：贫血（乏力、面色苍白、活动后心悸气短）、感染易感性增加（白细胞减少）、出血倾向（血小板减少）、左上腹胀痛或坠胀感、餐后饱胀（脾大压迫胃）、肝硬化门静脉高压者伴腹水、食管胃底静脉曲张（可致呕血黑便）、黄疸、血液病者伴原发病表现（如淋巴瘤发热、遗传性球形红细胞增多症黄疸）、脾梗死或脾周围炎时左上腹剧痛并向左肩放射。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：体温、脉搏、血压（感染与出血评估）\n一般情况：贫血貌、皮肤黏膜出血点、营养状态\n皮肤黏膜：黄疸、蜘蛛痣、肝掌、瘀斑（肝功能与凝血状态）\n腹部视诊：左上腹膨隆（脾大）、腹壁静脉曲张、腹围\n腹部触诊：脾下缘位置与质地（大小分级）、肝大小与质地、有无压痛\n腹部叩诊：脾区叩击痛、移动性浊音（腹水）\n腹部听诊：脾区摩擦音（脾梗死/脾周围炎）、肠鸣音","辅助检查":"1. 血常规（三系）+网织红细胞：评估脾亢程度，术后每日复查直至稳定（重点血小板）\n2. 肝功能+白蛋白+胆红素+凝血酶原时间：评估肝储备（Child-Pugh）与术前风险\n3. 骨髓穿刺+活检：鉴别骨髓造血功能与外周破坏（血液病者必查）\n4. 腹部超声/增强CT：脾大小、门静脉内径与血栓、腹水、副脾\n5. 胃镜：门静脉高压者评估食管胃底静脉曲张程度与出血风险\n6. 病因检查：肝炎病毒标志物+HBV-DNA、自身抗体、Coombs试验、红细胞脆性试验\n7. 血型+交叉配血+电解质+肾功能：术前准备与评估","初步诊断":"1. 血常规+网织红细胞：三系减少（白细胞<4×10⁹/L、血小板<100×10⁹/L、血红蛋白降低）\n2. 腹部超声/CT：脾大小（脾长径>12cm或厚径>4cm为脾大）、门静脉内径、有无血栓、腹水\n3. 骨髓穿刺+活检：评估骨髓造血功能（鉴别骨髓衰竭与外周破坏）\n4. 肝功能+白蛋白+胆红素+凝血：评估肝储备（Child-Pugh分级）\n5. 胃镜：门静脉高压者评估食管胃底静脉曲张\n6. 病因学检查：肝炎病毒标志物、自身免疫抗体、Coombs试验、红细胞脆性试验、HBV-DNA等\n7. 血细胞破坏部位评估（放射性核素）：脾脏是否为破坏主要部位（必要时）\n1. 脾功能亢进与脾切除术（ICD-10：D73.1）","鉴别诊断":"1. 骨髓穿刺+活检：评估骨髓造血功能（鉴别骨髓衰竭与外周破坏）\n2. 诊断要点：血常规+网织红细胞：三系减少（白细胞<4×10⁹/L、血小板<100×10⁹/L、血红蛋白降低）\n3. 诊断要点：腹部超声/CT：脾大小（脾长径>12cm或厚径>4cm为脾大）、门静脉内径、有无血栓、腹水\n4. 诊断要点：骨髓穿刺+活检：评估骨髓造血功能（鉴别骨髓衰竭与外周破坏）\n5. 诊断要点：肝功能+白蛋白+胆红素+凝血：评估肝储备（Child-Pugh分级）\n6. 诊断要点：胃镜：门静脉高压者评估食管胃底静脉曲张\n7. 诊断要点：病因学检查：肝炎病毒标志物、自身免疫抗体、Coombs试验、红细胞脆性试验、HBV-DNA等","处理方案":"【药物治疗·输液】\n⚠️ 围手术期按医嘱选择方案，切勿全部同时使用！\n\n方案1（术前预防性抗感染，切皮前0.5～1小时）：\n 用法：头孢呋辛 1.5g 静滴（单次）或 头孢唑林 1g 静滴\n\n方案2（术前/术后补充凝血）：\n 用法：维生素K1 10mg 静滴 qd（肝功能差者）；血小板<30×10⁹/L 或有出血时输注血小板；新鲜冰冻血浆按需\n\n方案3（保肝/支持，肝硬化患者）：\n 用法：还原型谷胱甘肽 1.2g 静滴 qd + 腺苷蛋氨酸 1g 静滴 qd；白蛋白 10g 静滴（低蛋白）；必要时补充凝血酶原复合物\n\n方案4（降门脉压，门静脉高压者）：\n 用法：生长抑素 3mg/12h 泵入 或 奥曲肽 25～50μg/h 泵入（按医嘱，用于出血期）\n\n📌 脾切除术后血小板可显著升高（术后1～2周达高峰），需监测并必要时抗血小板治疗（防血栓）。\n\n【药物治疗·口服】\n⚠️ 术后与长期用药，按医嘱选择：\n\n药物1（抗血小板，血小板显著升高时）：\n 用法：阿司匹林肠溶片 100mg qd 或 氯吡格雷 75mg qd（血小板>500～1000×10⁹/L时，遵医嘱）\n\n药物2（预防感染，脾切除后）：\n 用法：青霉素V钾 0.5g bid（长期预防，尤其术后前2年，遵医嘱）\n\n药物3（保肝）：\n 用法：多烯磷脂酰胆碱 456mg tid 或 水飞蓟宾 70mg tid\n\n药物4（降门脉压，预防再出血）：\n 用法：普萘洛尔 10mg bid 起（调整至静息心率下降25%或55～60次/分）\n\n📌 脾切除后需接种肺炎链球菌、脑膜炎奈瑟菌与流感嗜血杆菌疫苗（术前2周或术后恢复期）。\n\n【治疗】\n脾切除术指征：脾亢致严重血细胞减少（尤其血小板<30×10⁹/L或有出血）、门静脉高压致反复食管胃底静脉破裂出血（贲门周围血管离断+脾切除）、脾外伤、脾脓肿/肿瘤、遗传性球形红细胞增多症等血液病\n术式选择：开腹脾切除（巨脾、门静脉高压）或腹腔镜脾切除（中等大小脾、血液病）\n术前准备：评估肝功能与凝血、补充维生素K与血小板、备血、疫苗接种\n术中注意：处理脾蒂血管、防止脾破裂（避免脾组织种植致副脾残留、复发）\n术后处理：监测血小板与血象变化、抗凝/抗血小板（血小板过高时）、预防感染\n门静脉高压者：术后继续降门脉压治疗与胃镜随访，预防再出血\n血液病者：术后评估疗效与原发病治疗（如需要化疗、免疫抑制）\n\n【处理要点】\n术后监测：血压、心率、引流液（腹腔引流>200ml/h鲜红提示活动性出血需处理）、血小板与血象\n血小板管理：术后每日查血常规，血小板>500×10⁹/L时遵医嘱抗血小板治疗（警惕门静脉/脾静脉血栓）\n感染预防：术后早期监测体温与切口，脾切除后远期有爆发性感染（OPSI）风险，需疫苗接种与预防性抗生素\n疼痛与体位：观察左上腹疼痛与腹胀，协助半卧位与早期活动\n引流管护理：保持通畅、记录引流量与性状（胰尾损伤可致胰漏，引流液淀粉酶高）\n营养支持：术后遵医嘱从流质过渡，肝硬化者控制蛋白与钠盐\n随访：术后1、3、6个月复查血常规、肝功能与超声；血液病者随访原发病\n\n【护理】\n术前护理：评估出血倾向（牙龈、皮肤瘀斑）、遵医嘱补充维生素K与血小板，做好疫苗接种宣教\n术后观察：密切监测血压、心率、引流液性状与量（腹腔出血是主要早期并发症）\n血小板监测：术后每日查血常规，血小板>500×10⁹/L时按医嘱抗血小板并观察血栓征象（下肢肿痛、腹痛）\n感染预防：监测体温、切口情况；宣教脾切除后感染风险（发热需及时就医）与疫苗接种重要性\n体位与活动：麻醉清醒后取半卧位，鼓励早期床上活动与深呼吸，预防肺部感染与血栓\n引流与营养：保持腹腔引流管通畅，术后按医嘱从流质过渡到高蛋白饮食（肝硬化者限钠限蛋白）\n\n【饮食】\n脾亢伴肝硬化者：限制钠盐（<2g/日）、适量优质蛋白，避免肝性脑病时过量蛋白\n非肝硬化者：高蛋白、高维生素、易消化饮食，促进术后恢复\n贫血者增加含铁食物（动物肝脏、瘦肉、菠菜）与维生素C促进铁吸收\n血小板低者避免粗糙、坚硬、带刺食物（防口腔与消化道出血）\n戒酒、忌辛辣刺激；少量多餐，避免饱胀（巨脾压迫胃）\n\n【注意事项】\n脾切除术后血小板升高是常见现象（多在1～2周达高峰），显著升高需抗血小板治疗并警惕血栓\n脾切除后终生有爆发性感染（OPSI）风险（尤其儿童与免疫抑制者），必须接种疫苗并告知发热需及时就诊\n门静脉高压患者脾切除+断流术可降低出血风险，但仍需胃镜随访与药物预防\n血小板过低者术前输注血小板，术中精细止血（避免术后腹腔出血）\n术后左上腹持续剧痛伴发热需警惕脾窝积液/膈下脓肿与胰尾损伤\n\n【急诊/急救】\n术后引流大量鲜红血液、血压下降（腹腔活动性出血）→ 急诊探查止血\n术后高热伴左上腹剧痛、感染指标升高（脾窝脓肿/膈下脓肿）→ 引流+抗感染\n脾切除后突发高热寒战、休克（OPSI）→ 立即抗感染与抢救\n脾切除后腹痛腹胀迅速加重伴血小板显著升高（门静脉血栓）→ 急诊影像评估并抗凝","资料来源":"疾病库 diseases.json；鉴别诊断库 ddx_local.json（条目「脾功能亢进与脾切除术」原文）"},"icd10_diagnosis":"D73.1","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2653,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"7b7bb5c992498ec2a9315ddb80aa06ac2e07f8142c5c134e194b9e72853e2a18","pinyin":"pigongnengkangjinyupiqiechushu","initials":"pgnkjypqcs","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","D73.1",30]]},{"id":"templates-03b9121fe151b225ee37","key":"v1-c9ccc21dfe2a3058|templates-03b9121fe151b225ee37","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"腮腺多形性腺瘤","category":"口腔医学临床路径（2019年版）","raw":{"name":"腮腺多形性腺瘤","category":"口腔医学临床路径（2019年版）","case":{"case_name":"门诊病历","templates":{"主诉":"【待人工确认·本机素材无此段原文】","现病史":"【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"检查计划：患者腮腺区无痛性肿块、生长缓慢、质地中等、呈球状或分叶状、周界清楚且无面神经功能障碍，需与腮腺沃辛瘤、腺样囊性癌、黏液表皮样癌及腮腺淋巴结炎等相鉴别；完善腮腺区超声检查明确肿块的部位、大小、边界、内部回声及血流情况，判断是否为界限清楚的占位病变；完善腮腺区增强CT或MRI检查明确肿瘤与面神经、腮腺导管及周围组织的关系，评估有无骨质破坏及深叶受累，为手术方式选择提供依据；必要时完善细针穿刺细胞学检查明确细胞学性质，协助鉴别良恶性；完善胸部X线或胸部CT检查排除肺部转移；完善血常规、凝血功能、肝肾功能、血糖及传染病筛查（乙肝、丙肝、梅毒、HIV）等术前常规检查，评估手术耐受性；完善心电图检查排除心脏疾病，评估麻醉风险；完善血型鉴定与交叉配血以备术中输血；对疑有面神经受累者完善面神经肌电图检查评估神经功能，术后定期复查超声随访有无复发。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"【临床路径·诊断依据】\n诊断依据\r根据《临床诊疗指南\n口腔医学分册（2016修订版）》（中华口腔医学会编著，人民卫生出版社,2016）。\r1.腮腺区无痛性肿块，生长缓慢，无明显自觉症状。\r2.肿块质地中等，呈球状或分叶状，周界清楚，与周围组织无粘连，无面神经功能障碍。\r3.超声或CT显示腮腺内有界限清楚的占位病变。\r（三）\n1. 腮腺多形性腺瘤（ICD-10：D11.0）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【临床路径·治疗方案的选择】\n治疗方案的选择\r根据《临床诊疗指南\n口腔医学分册（2016修订版）》（中华口腔医学会编著，人民卫生出版社,2016）。\r选择腮腺肿物及浅叶切除＋面神经解剖术或包括腮腺肿瘤及瘤周正常腮腺切除的部分腮腺切除术，其适应证为：\r1.腮腺浅叶多形性腺瘤。\r2.患者全身状况可耐受手术。\r3.患者无明显手术禁忌证。\r（四）","临床路径·进入路径标准":"进入路径标准\r1.第一诊断符合ICD-10：D11.0，M8940/0腮腺多形性腺瘤疾病编码。\r2.患者同时具有其他疾病诊断，如在住院期间不需要特殊处理，也不影响第一诊断的临床路径流程实施时，可以进入路径。\r（六）术前准备（术前评估）2天\r1.必须检查的项目\r（1）血常规、尿常规、便常规、血型。\r（2）凝血功能。\r（3）血生化。\r（4）感染性疾病筛查（乙型肝炎、丙型肝炎、艾滋病、梅毒等）。\r（5）胸片。\r（6）心电图。\r（7）腮腺超声。 \r2.选择性检查的项目\r（1）超声心动图。\r（2）肺功能/动脉血气分析。\r（3）腮腺CT（建议首选增强CT）/MRI检查。\r（七）预防性抗菌药物选择与使用时机\r1.抗菌药物：按照《抗菌药物临床患者指导原则》（卫医发〔2015〕43号）执行。\r2.必要时可预防性使用抗菌药物。抗菌药物选用青霉素类或其他类抗菌药物，用药时间为术前30分钟。\r（八）手术日为入院第3天\r1.麻醉方式：全身麻醉或局部麻醉。 \r2.手术植入物：必要时可植入口腔生物膜，以预防涎瘘和味觉出汗综合征。 \r3.术中用药：除麻醉用药外无特殊用药。\r（九）术后住院恢复2～4天\r术后用药：术后出现面神经损伤症状者，酌情选用神经营养药物。\r（十）","临床路径·标准住院日":"标准住院日为5～7天\r（五）","临床路径·出院标准":"出院标准\r1.生命体征平稳。\r2.手术切口无红、肿、热、痛等炎症表现，无新鲜渗血。\r3.伤口无明显唾液渗漏等需要住院治疗的并发症。\r（十一）","临床路径·变异及原因分析":"变异及原因分析\r1.位于腮腺深叶的肿瘤不进入该路径。\r2.如肿瘤生长时间长，特别巨大（直径＞8cm），有生长迅速、疼痛或出现面瘫症状等恶变倾向时不进入该临床路径。\r3.复发性腮腺多形性腺瘤的手术方式根据具体情况酌定。\r\f二、腮腺多形性腺瘤","资料来源":"国家卫健委《224个病种临床路径（2019年版）》（国卫办医函〔2019〕933号）· 口腔医学临床路径（2019年版） · 腮腺多形性腺瘤临床路径（2019年版）.doc"},"icd10_diagnosis":"D11.0","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2654,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"9d37f8b42d291fbed8c0397810316805b0a88e67f9e0cc66dff5e33dd8ed726f","pinyin":"saixianduoxingxingxianliu","initials":"sxdxxxl","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","临床路径·进入路径标准","临床路径·标准住院日","临床路径·出院标准","临床路径·变异及原因分析","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 临床路径·进入路径标准 临床路径·标准住院日 临床路径·出院标准 临床路径·变异及原因分析 资料来源",30],["主要诊断编码","D11.0",30]]},{"id":"templates-746ef948498a08a6a18a","key":"v1-c9ccc21dfe2a3058|templates-746ef948498a08a6a18a","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"腰痛(中医辨证)","category":"中医","raw":{"name":"腰痛(中医辨证)","category":"中医","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】寒湿：腰部冷痛重着，转侧不利，静卧不减，阴雨天加重、湿热：腰部疼痛，重着而热，暑湿阴雨天加重，活动后减轻，小便短赤、瘀血：腰痛如刺，痛有定处，痛处拒按，日轻夜重，不能转侧、肾阴虚：腰部隐隐作痛，酸软无力，缠绵不愈，心烦少寐，口燥咽干，面色潮红、肾阳虚：腰部隐隐作痛，酸软无力，缠绵不愈，局部发凉，喜温喜按，遇劳更甚，常反复发作。\n【待人工确认·本机素材无此段原文】","现病史":"以腰部一侧或两侧疼痛为主要症状。分寒湿腰痛、湿热腰痛、瘀血腰痛、肾虚腰痛（肾阴虚、肾阳虚）。\n常见表现：寒湿：腰部冷痛重着，转侧不利，静卧不减，阴雨天加重、湿热：腰部疼痛，重着而热，暑湿阴雨天加重，活动后减轻，小便短赤、瘀血：腰痛如刺，痛有定处，痛处拒按，日轻夜重，不能转侧、肾阴虚：腰部隐隐作痛，酸软无力，缠绵不愈，心烦少寐，口燥咽干，面色潮红、肾阳虚：腰部隐隐作痛，酸软无力，缠绵不愈，局部发凉，喜温喜按，遇劳更甚，常反复发作。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：体温、脉搏、呼吸、血压\n望诊：神（得神/少神/失神/假神/神乱）、色（常色/病色：青/赤/黄/白/黑，光泽/晦暗）、形态（形体胖瘦/动静姿态/异常动作）、头面（头颅/囟门/头发/面肿/口眼歪斜）、五官（目/耳/鼻/口/齿/龈/咽喉）、躯体（颈项/胸胁/腹部/腰背/四肢/皮肤）、舌诊（舌质：颜色/形质/动态；舌苔：苔色/苔质/润燥/厚薄/腻腐/剥落；舌底络脉）、排泄物（痰涎/呕吐物/大便/小便/经血/带下）\n闻诊：声音（语声/呼吸/咳嗽/喘哮/呃逆/嗳气/太息/肠鸣）、气味（口气/汗气/痰涕气味/二便气味/经带气味/病室气味）\n问诊：一般情况（姓名/性别/年龄/职业/籍贯）、主诉、现病史（起病情况/主症特点/病因诱因/病情发展/诊治经过/伴随症状）、既往史、个人史、家族史、十问歌（一问寒热二问汗，三问头身四问便，五问饮食六胸腹，七聋八渴俱当辨，九问旧病十问因，再兼服药参机变，妇女尤必问经期，迟速闭崩皆可见，再添片语告儿科，天花麻疹全占验）\n切诊：脉诊（部位：寸关尺；脉象：浮沉迟数虚实滑涩洪细濡弱弦紧结代促等，注意平脉/病脉/真脏脉）、按诊（按肌肤/按手足/按胸腹/按腧穴/按腹部，温度/湿度/压痛/包块/波动感）\n辨证：八纲辨证（表里/寒热/虚实/阴阳）、脏腑辨证、气血津液辨证、六经辨证、卫气营血辨证、三焦辨证、经络辨证","辅助检查":"检查计划：患者以腰部一侧或两侧疼痛为主症，辨证分寒湿、湿热、瘀血、肾阴虚、肾阳虚，须先排除腰椎器质性病变并与肾结石、妇科疾病相鉴别；入院完善腰椎正侧位X线检查了解腰椎生理曲度、椎间隙及骨质增生情况；完善腰椎CT检查明确有无椎间盘突出、椎管狭窄、骨折及骨质破坏；对伴下肢放射痛、麻木者完善腰椎MRI检查明确神经根受压节段及脊髓情况；完善泌尿系超声及尿常规检查排除肾结石、肾盂肾炎等泌尿系统疾病；女性患者完善妇科超声检查排除盆腔炎、子宫肌瘤及附件病变所致腰痛；完善血常规、CRP及血沉检查排除感染、贫血及风湿免疫性疾病；完善类风湿因子、HLA-B27及骶髂关节影像学检查排除强直性脊柱炎；完善肝肾功能、电解质、血糖及肿瘤标志物检查排除代谢性骨病及肿瘤骨转移；完善骨密度检查评估有无骨质疏松；对腰痛缠绵、酸软无力者完善腹部超声检查排除腹膜后病变，必要时完善肌电图检查评估神经受损情况，定期复查观察病情变化。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 腰部疼痛\n2. 腰椎X线/CT/MRI排除器质性病变\n3.与肾结石、妇科疾病鉴别\n1. 腰痛(中医辨证)（ICD-10：M54.5）","鉴别诊断":"1. 腰椎X线/CT/MRI排除器质性病变\n2.与肾结石、妇科疾病鉴别","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！\n\n方案1（急性发作）：\n 用法：NS250ml+丹参注射液20ml ivgtt qd\n\n方案2（肾虚）：\n 用法：NS250ml+参麦注射液40ml ivgtt qd\n\n📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！\n\n药物1（寒湿）：\n 用法：甘姜苓术汤1袋 tid，或独活寄生丸1丸 tid\n\n药物2（湿热）：\n 用法：四妙丸1袋 tid，或二妙丸1袋 tid\n\n药物3（瘀血）：\n 用法：身痛逐瘀汤1袋 tid，或腰痛宁胶囊4粒 qn\n\n药物4（肾阴虚）：\n 用法：左归丸1丸 tid，或六味地黄丸1丸 tid\n\n药物5（肾阳虚）：\n 用法：右归丸1丸 tid，或金匮肾气丸1丸 tid\n\n药物6（各型均可）：\n 用法：壮腰健肾丸1丸 tid\n\n📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。\n\n【治疗】\n寒湿：散寒行湿，温经通络，甘姜苓术汤\n湿热：清热利湿，舒筋止痛，四妙丸\n瘀血：活血化瘀，通络止痛，身痛逐瘀汤\n肾阴虚：滋补肾阴，濡养筋脉，左归丸\n肾阳虚：补肾壮阳，温煦经脉，右归丸\n\n【处理要点】\n避免久坐久站\n注意腰部保暖\n加强腰背肌锻炼\n睡硬板床\n\n【护理】\n寒湿腰痛：居处避风寒潮湿，腰骶部注意保暖，可予艾灸、热敷以温经散寒，忌发汗太过，以防汗出当风、耗伤阳气而加重病情。\n湿热腰痛：观察小便色量及下肢有无浮肿，记录出入量；保持腰背皮肤清洁干燥，外治多选清热利湿之法（如中药湿热敷），忌久坐湿地、贪凉露卧。\n瘀血腰痛：观察疼痛部位、性质及活动受限程度，痛处固定刺痛者警惕跌仆闪挫后病情反复；外治贴敷活血化瘀药时注意皮肤有无破损、过敏，急性期宜卧床休息，减少腰部负重。\n肾虚腰痛：忌劳神熬夜、房劳过度，起居有节，指导腰背肌功能锻炼（如五点支撑、小燕飞）；若疼痛加重或伴下肢放射痛、二便失禁，及时报告医师。\n煎药服药：中药宜温服，肾虚之补益药宜饭前服，寒湿、湿热、瘀血之祛邪药宜饭后服；服药期间观察疼痛缓解程度及有无胃脘不适、汗出异常。\n\n【饮食】\n寒湿腰痛忌生冷瓜果、冰镇饮品及肥腻之品，以免寒湿内滞；宜食温散之品，如生姜、葱白、羊肉、胡椒、韭菜等。\n湿热腰痛忌肥甘厚味、辛辣炙煿及酒类，以免助湿生热；宜食薏苡仁、冬瓜、赤小豆、绿豆、丝瓜等清热利湿之品。\n瘀血腰痛忌酸涩收敛之品（如乌梅、石榴），以免滞血碍行；宜食行气活血之品，如山楂、桃仁、黑木耳、红糖，可佐以三七炖鸡。\n肾虚腰痛忌辛辣动火之品，阳虚者忌生冷，阴虚者忌辛辣燥热；宜食核桃、黑芝麻、枸杞、山药、桑葚、羊肉等补肾之品，药膳可予杜仲猪腰汤、枸杞羊肾粥。\n饮食宜规律、少食多餐，避免暴饮暴食加重腰部负担；药膳食疗须按辨证分型选用，不可盲目进补。\n\n【注意事项】\n腰痛伴下肢麻木需排查腰椎间盘突出\n急性腰扭伤需休息\n反复腰痛需影像学检查\n\n【急诊/急救】\n一般不需急救\n马尾综合征：急诊手术","资料来源":"疾病库 diseases.json；鉴别诊断库 ddx_local.json（条目「腰痛（中医辨证）」原文）","中医辨证参考":"首次病程记录\n\n拟诊讨论：\n\n【中医辨证参考】腰痛\n（本页列出该病常见证型，请根据患者实际四诊资料选择相应证型，切勿直接套用）\n\n一、寒湿腰痛\n    症状舌脉：腰部冷痛重着，转侧不利，逐渐加重，静卧病痛不减，寒冷和阴雨天则加重，舌质淡、苔白腻，脉沉而迟缓\n    治法：散寒行湿、温经通络\n    方剂：甘姜苓术汤\n\n二、湿热腰痛\n    症状舌脉：腰部疼痛，重着而热，暑湿阴雨天气症状加重，活动后或可减轻，身体困重，小便短赤，苔黄腻，脉濡数或弦数\n    治法：清热利湿、舒筋止痛\n    方剂：四妙丸\n\n三、瘀血腰痛\n    症状舌脉：腰痛如刺，痛有定处，痛处拒按，日轻夜重，轻者俯仰不便，重则不能转侧，舌质暗紫、或有瘀斑，脉涩，部分病人有跌仆闪挫病史\n    治法：活血化瘀、通络止痛\n    方剂：身痛逐瘀汤\n\n四、肾虚腰痛\n    症状舌脉：腰部隐隐作痛，酸软无力，缠绵不愈。偏阴虚者心烦少寐，口燥咽干，面色潮红，手足心热，舌红少苔，脉弦细数，治以滋补肾阴、濡养筋脉，方用左归丸；偏阳虚者局部发凉，喜温喜按，遇劳更甚，卧则减轻，常反复发作，少腹拘急，面色㿠白，肢冷畏寒，舌质淡、脉沉细无力，治以补肾壮阳、温煦经脉，方用右归丸。来源：《中医内科学》（中国中医药出版社“十四五”规划教材）·肢体经络病证·腰痛。提示：腰痛伴下肢放射痛、大小便障碍或鞍区麻木者须警惕马尾综合征，立即急诊\n\n【方剂参考】\n  四妙丸：组成 苍术9g、黄柏9g、薏苡仁15g、川牛膝12g；功效 清热利湿，通筋利痹\n      用法：水煎温服，日一剂，分二次服；原方为水丸，每服6-9g，日二次。\n      注意：寒湿痹证、肝肾亏虚之痿证忌用；脾胃虚寒者慎用；孕妇慎用。「四妙散」为「四妙丸」之通称（原方为散，名四妙散）；本方即二妙散（苍术、黄柏）加薏苡仁、牛膝。来源：《方剂学》（中国中医药出版社“十四五”规划教材）·祛湿剂（清热祛湿）；原方出自《成方便读·卷三》\n  身痛逐瘀汤：组成 秦艽3g、川芎6g、桃仁9g、红花9g、甘草6g、羌活3g、没药6g、当归9g、五灵脂6g（炒）、香附3g、牛膝9g、地龙6g；功效 活血祛瘀，通经止痛，祛风除湿\n      用法：水煎温服，日一剂，分二次服；原书亦可以黄酒少许兑服。\n      注意：孕妇忌用；有出血倾向、月经量多者及体虚无瘀者慎用；本方法瘀力较强，中病即止，不宜久服。来源：《方剂学》（中国中医药出版社“十四五”规划教材）·理血剂（活血祛瘀）；原方出自《医林改错·卷下》\n\n【西医诊断】\n  腰椎间盘突出症 / 腰肌劳损\n  （西医诊断依据与鉴别诊断请结合患者病史、体征、辅助检查补充）\n\n医师签名：＿＿＿＿"},"icd10_diagnosis":"M54.5","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2655,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"286bd78d1124539fbf7a00c08ad49ee2249a91f6d32be29b276ceeb127ef4404","pinyin":"yaotong(zhongyibianzheng)","initials":"yt(zybz)","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源","中医辨证参考"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源 中医辨证参考",30],["主要诊断编码","M54.5",30]]},{"id":"templates-b686cd75afc127acf812","key":"v1-c9ccc21dfe2a3058|templates-b686cd75afc127acf812","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"腹主动脉瘤","category":"血管外科","raw":{"name":"腹主动脉瘤","category":"血管外科","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】多无明显症状、腹部搏动性包块、腰背部疼痛（破裂先兆）、低血压休克（破裂）。\n【待人工确认·本机素材无此段原文】","现病史":"腹主动脉局限性扩张（直径≥3cm），破裂风险随直径增大而升高\n常见表现：多无明显症状、腹部搏动性包块、腰背部疼痛（破裂先兆）、低血压休克（破裂）。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：血压、心率，破裂时休克表现\n腹部：脐周可及搏动性包块，可伴压痛\n双下肢：评估股动脉搏动及缺血表现","辅助检查":"1. 腹主动脉彩超：筛查及随访首选，测量瘤体直径\n2. 腹主动脉CTA：确诊、精确测量及术前评估（瘤颈/髂动脉）\n3. 血常规+凝血功能+肾功能：术前评估及破裂出血时监测\n4. 心电图+心脏超声：评估心功能及合并冠心病\n5. 血脂血糖：动脉粥样硬化危险因素评估","初步诊断":"1. 腹部彩超筛查\n2. 腹主动脉CTA确诊并测量\n3. 直径≥5.5cm（男）/5cm（女）考虑手术\n1. 腹主动脉瘤（ICD-10：I71.4）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！\n\n方案1（破裂急诊）：\n 用法：快速建立双通道；疑破裂者行限制性液体复苏（允许性低血压，收缩压维持80-90mmHg至主动脉阻断，血制品优先），紧急EVAR或开放手术，避免盲目大量扩容\n\n方案2（术前）：\n 用法：NS250ml+美托洛尔5mg iv（控制心率）\n\n📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！\n\n药物1：\n 用法：阿托伐他汀20mg qn（强化降脂）\n\n药物2：\n 用法：阿司匹林100mg qd（动脉粥样硬化合并者）\n\n📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。\n\n【治疗】\n直径<5.5cm定期超声随访（每6-12个月）\n直径≥5.5cm或快速增大行EVAR或开放手术\n控制血压心率、戒烟\n\n【处理要点】\n戒烟、控制血压血糖血脂\n避免剧烈运动和重体力劳动\n定期影像随访\n\n【护理】\n病情观察：监测血压心率，警惕突发剧烈腹痛、血压下降等破裂先兆\n术后护理（EVAR/开放）：观察切口渗血、肢端血运、尿量，监测内漏征象\n控制血压：遵医嘱降压，避免血压波动，保持大便通畅避免用力\n健康宣教：戒烟、低脂饮食、定期复查超声，教会识别破裂先兆\n\n【饮食】\n低盐低脂饮食：每日食盐<5g，忌油炸肥肉，控制血脂血压\n戒烟限酒：吸烟是动脉瘤进展重要危险因素\n高纤维饮食：多吃蔬果粗粮，保持大便通畅，避免用力排便诱发破裂\n适量优质蛋白：瘦肉、鱼、豆制品，术后促进切口愈合\n\n【注意事项】\n破裂三联征：突发腹痛+低血压+搏动性包块\n随访中直径年增长>1cm提示手术指征\n筛查：65岁以上吸烟男性超声筛查\n\n【急诊/急救】\n破裂：立即呼救、平卧、快速扩容，急诊手术\n剧烈腹痛/腰背痛伴血压下降警惕破裂","资料来源":"疾病库 diseases.json"},"icd10_diagnosis":"I71.4","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2656,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"5ddc81cc83426a8094fad345709565576c28ebd91d03efca0da0d8ea507f2906","pinyin":"fuzhudongmailiu","initials":"fzdml","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","I71.4",30]]},{"id":"templates-bd9c135a68702c88590b","key":"v1-c9ccc21dfe2a3058|templates-bd9c135a68702c88590b","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"腹壁切口疝","category":"疝与腹壁外科","raw":{"name":"腹壁切口疝","category":"疝与腹壁外科","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】站立、咳嗽或用力时切口处出现可复性包块，平卧可消失、局部坠胀不适或隐痛，包块增大时明显、疝内容物嵌顿时出现腹痛、呕吐、腹胀（肠梗阻表现）、巨大切口疝可致腹壁功能障碍、便秘、呼吸受限、部分患者有切口感染、裂开或多次手术史。\n【待人工确认·本机素材无此段原文】","现病史":"腹壁切口疝是腹部手术后因切口愈合不良、腹壁薄弱或腹内压增高，腹腔内容物经原切口或切口旁突出形成的疝，多见于腹部大手术后。表现为站立或用力时切口处隆起，需手术修补（多采用补片无张力修补）。\n常见表现：站立、咳嗽或用力时切口处出现可复性包块，平卧可消失、局部坠胀不适或隐痛，包块增大时明显、疝内容物嵌顿时出现腹痛、呕吐、腹胀（肠梗阻表现）、巨大切口疝可致腹壁功能障碍、便秘、呼吸受限、部分患者有切口感染、裂开或多次手术史。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：体温、脉搏、血压（评估嵌顿/感染）\n一般情况：BMI、营养状态、有无慢性咳嗽与便秘\n腹部视诊：原切口瘢痕、包块位置与大小、站立位与卧位对比、皮肤颜色（有无红肿）\n腹部触诊：疝环大小（可容指数）、内容物性质、有无压痛、能否回纳、腹壁肌肉力量\n腹部叩诊与听诊：肠鸣音（嵌顿者亢进或减弱）\n呼吸系统：呼吸音、有无慢性阻塞性肺疾病（影响手术与复发）\n其他：有无合并腹股沟疝、脐疝等多发疝","辅助检查":"1. 血常规+CRP：评估有无感染或嵌顿，术前基线值\n2. 血糖+糖化血红蛋白：糖尿病患者术前必须控制（影响切口愈合与感染）\n3. 白蛋白+前白蛋白+血红蛋白：评估营养状态（营养不良增加复发风险）\n4. 凝血功能+肝肾功能：术前常规评估\n5. 腹部增强CT（含Valsalva）：明确疝环大小、腹壁缺损范围、疝内容物及有无隐匿疝\n6. 肺功能+血气分析（巨大切口疝/吸烟者）：评估呼吸功能与手术耐受\n7. 心电图+心脏超声（老年患者）：术前心血管评估","初步诊断":"1. 体格检查：站立位与卧位对比，可扪及疝环大小与内容物性质\n2. 腹部增强CT（含Valsalva动作）：首选，明确疝环大小、疝囊内容物、腹壁肌肉状态及有无隐匿疝（对手术方案至关重要）\n3. 腹部超声：评估疝内容物与疝环\n4. 腹部立位平片：合并肠梗阻时\n5. 血常规+CRP：评估有无感染或嵌顿\n6. 术前评估：腹壁功能、呼吸功能（巨大切口疝影响呼吸）、营养状态、血糖\n1. 腹壁切口疝（ICD-10：K43.2）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【药物治疗·输液】\n⚠️ 术前术后按医嘱用药，切勿全部同时使用！\n\n方案1（术前预防性抗感染，修补术前30～60分钟）：\n 用法：头孢呋辛 1.5g 静滴（单次）或 头孢唑林 1g 静滴\n\n方案2（术后支持）：\n 用法：0.9%氯化钠/葡萄糖 静滴；必要时白蛋白、氨基酸营养支持\n\n方案3（嵌顿/绞窄术前）：\n 用法：补液+头孢呋辛 1.5g q8h + 甲硝唑 0.5g q8h；胃肠减压\n\n📌 切口疝修补术为清洁-污染手术，预防性抗生素主要针对革兰阳性球菌。\n\n【药物治疗·口服】\n⚠️ 术后与恢复期用药，按医嘱选择：\n\n药物1（镇痛）：\n 用法：塞来昔布 200mg bid 或 洛索洛芬钠 60mg tid（餐后）；必要时曲马多 50mg\n\n药物2（通便，防腹压增高）：\n 用法：乳果糖 15ml bid 或 聚乙二醇4000散 1袋 qd\n\n药物3（止咳，慢性咳嗽者）：\n 用法：氨溴索 30mg tid 或 复方甲氧那明 2粒 tid\n\n📌 术后避免用力排便与剧烈咳嗽，必要时用镇咳与通便药物（腹压增高是复发主因）。\n\n【治疗】\n手术治疗：主要治疗手段，行切口疝修补术——开放或腹腔镜（IPOM/肌后间隙修补），多用补片行无张力修补\n术前准备：控制血糖、戒烟、改善营养、治疗慢性咳嗽与便秘、减重（BMI>35需减重）\n巨大切口疝：术前渐进性气腹或肉毒素注射辅助关腹，必要时行组织结构分离技术（CST）\n嵌顿/绞窄：急诊手术，切除坏死肠管并修补\n术后腹带加压：减少切口张力与积液，指导正确使用\n康复指导：避免提重物（3个月内）、腹压增高动作，逐步恢复活动\n\n【处理要点】\n术前评估与优化：控制血糖（<8mmol/L）、戒烟≥4周、纠正营养不良、治疗便秘与慢性咳嗽\n术后观察：切口有无红肿、渗液、积液（血清肿）、补片感染征象\n引流管护理：记录引流量与性状，量少后择期拔除\n腹带固定：术后使用腹带3个月，避免剧烈咳嗽与用力排便\n早期活动：术后第1天床上活动，逐步下床，避免剧烈活动与提重物\n随访：术后1、3、6、12个月复查，评估有无复发与慢性疼痛\n\n【护理】\n术前护理：指导戒烟、练习深呼吸与有效咳嗽（双手按压切口），训练床上排便\n术后体位与活动：术后早期床上活动，麻醉清醒后取半卧位，术后1天开始下床活动\n切口观察：注意有无渗血、渗液、红肿及积液（血清肿），腹带妥善固定\n腹压管理：指导避免剧烈咳嗽、用力排便与提重物，必要时用镇咳通便药\n引流护理：保持引流管通畅，记录引流量与性状，警惕补片感染（持续渗液、发热）\n\n【饮食】\n术前：高蛋白、高维生素饮食，纠正营养不良，控制体重\n术后：肠功能恢复后从流质逐步过渡到高蛋白软食\n多饮水、多食粗纤维蔬菜水果，保持大便通畅（防便秘致腹压增高）\n少量多餐，避免暴饮暴食与产气食物（减轻腹胀）\n忌烟酒，糖尿病患者按糖尿病饮食严格控糖\n\n【注意事项】\n切口疝不会自愈，一旦确诊应择期手术，嵌顿风险随疝环增大而增加\n腹内压增高（肥胖、慢性咳嗽、便秘、前列腺增生）是复发主要原因，术前术后必须控制\n术前CT评估疝环大小与腹壁肌肉缺损范围是选择术式的关键\n补片感染是最严重的并发症之一，术中严格无菌、术后警惕切口红肿渗液\n\n【急诊/急救】\n疝块不能回纳伴腹痛、呕吐、停止排气排便（嵌顿）→ 急诊手术\n疝块处皮肤红肿、发热、剧烈疼痛（绞窄/感染）→ 立即急诊处理\n疝内容物破溃致腹壁缺损与肠管外露 → 急诊抢救手术","资料来源":"疾病库 diseases.json"},"icd10_diagnosis":"K43.2","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2657,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"9e670b58de28229986d1b075a112d09f7bf19111e0ba16536910bdfdcd6245b1","pinyin":"fubiqiekoushan","initials":"fbqks","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","K43.2",30]]},{"id":"templates-c309628467548b13b04f","key":"v1-c9ccc21dfe2a3058|templates-c309628467548b13b04f","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"腹水(鉴别与处理)","category":"内科-消化","raw":{"name":"腹水(鉴别与处理)","category":"内科-消化","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】腹胀、腹围增大、体重增加、食欲减退与早饱、呼吸困难（大量腹水致膈肌上抬）、端坐呼吸、下肢水肿、阴囊水肿（门静脉高压或低蛋白）、原发病表现：黄疸与蜘蛛痣（肝硬化）、消瘦与腹块（肿瘤）、发热与盗汗（结核）、颈静脉怒张（心衰）、并发症表现：发热与腹痛（自发性腹膜炎）、意识改变（肝性脑病）、少尿（肝肾综合征）。\n【待人工确认·本机素材无此段原文】","现病史":"腹水是腹腔内液体积聚，最常见于肝硬化门静脉高压（约75%），其他包括恶性肿瘤、心力衰竭、结核性腹膜炎、肾病综合征与胰源性腹水。诊断核心是腹腔穿刺（SAAG、细胞数、细胞学与培养），治疗包括限钠限水、利尿、放腹水与病因治疗。\n常见表现：腹胀、腹围增大、体重增加、食欲减退与早饱、呼吸困难（大量腹水致膈肌上抬）、端坐呼吸、下肢水肿、阴囊水肿（门静脉高压或低蛋白）、原发病表现：黄疸与蜘蛛痣（肝硬化）、消瘦与腹块（肿瘤）、发热与盗汗（结核）、颈静脉怒张（心衰）、并发症表现：发热与腹痛（自发性腹膜炎）、意识改变（肝性脑病）、少尿（肝肾综合征）。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：血压、心率、呼吸（大量腹水致呼吸困难）、体温（感染）\n腹部视诊：腹围（测量并记录）、腹壁静脉曲张、脐疝、皮肤张力与妊娠纹样改变\n腹部触诊：液波震颤、肝脾大小与质地、腹块（肿瘤）、压痛（腹膜炎）\n腹部叩诊：移动性浊音（腹水≥1000ml可检出）、肝浊音界\n心肺：颈静脉充盈（心衰/缩窄性心包炎）、肺部呼吸音减弱（胸腔积液）、心音与杂音\n下肢与阴囊：凹陷性水肿、阴囊水肿\n肝病体征：黄疸、蜘蛛痣、肝掌、男性乳房发育（肝硬化）","辅助检查":"1. 腹腔穿刺检查（必查）：外观、细胞数（中性粒细胞≥250/mm³提示SBP）、SAAG、白蛋白、LDH、葡萄糖、细胞学与培养\n2. 血清-腹水白蛋白梯度（SAAG）：门静脉高压性（≥11g/L）与非门静脉高压性（<11g/L）鉴别\n3. 肝功能+白蛋白+胆红素+凝血功能：肝储备与门静脉高压评估\n4. 肾功能+电解质（钠、钾）+尿钠：肝肾综合征、低钠血症与利尿治疗监测\n5. 腹水ADA+结核相关（T-SPOT、腹水培养）+腹水细胞学：结核性与恶性腹水鉴别\n6. 心脏超声+BNP：心源性腹水（右心衰、缩窄性心包炎）\n7. 腹部超声/CT+肿瘤标志物：肝脾形态、门静脉血栓、腹块与肿瘤评估","初步诊断":"1. 腹腔穿刺（关键，所有新发腹水均应穿刺）：外观、细胞数（中性粒细胞≥250/mm³诊断SBP）、白蛋白、SAAG（血清腹水白蛋白梯度）、LDH、葡萄糖、细胞学与细菌培养\n2. SAAG≥11g/L提示门静脉高压（肝硬化、心衰、Budd-Chiari）；<11g/L提示非门静脉高压（肿瘤、结核、胰源性、肾病）\n3. 腹部超声/CT：腹水量、肝脾形态、门静脉内径与血栓、腹块与淋巴结\n4. 肝功能+白蛋白+胆红素+凝血：肝储备与门静脉高压评估\n5. 肾功能+电解质+尿钠：肝肾综合征与低钠血症评估\n6. 肿瘤标志物+腹水细胞学：恶性腹水（卵巢癌、胃癌、肝癌）\n7. 腹水ADA+结核相关检查（T-SPOT、腹水培养）：结核性腹膜炎\n8. 心脏超声+BNP：心源性腹水（右心衰、缩窄性心包炎）\n1. 腹水(鉴别与处理)（ICD-10：R18）","鉴别诊断":"1. 所有新发腹水均应行腹腔穿刺检查（SAAG、细胞数、细胞学与培养）——这是鉴别诊断的关键步骤\n2. 诊断要点：腹腔穿刺（关键，所有新发腹水均应穿刺）：外观、细胞数（中性粒细胞≥250/mm³诊断SBP）、白蛋白、SAAG（血清腹水白蛋白梯度）、LDH、葡萄糖、细胞学与细菌培养\n3. 诊断要点：SAAG≥11g/L提示门静脉高压（肝硬化、心衰、Budd-Chiari）；<11g/L提示非门静脉高压（肿瘤、结核、胰源性、肾病）\n4. 诊断要点：腹部超声/CT：腹水量、肝脾形态、门静脉内径与血栓、腹块与淋巴结\n5. 诊断要点：肝功能+白蛋白+胆红素+凝血：肝储备与门静脉高压评估\n6. 诊断要点：肾功能+电解质+尿钠：肝肾综合征与低钠血症评估\n7. 诊断要点：肿瘤标志物+腹水细胞学：恶性腹水（卵巢癌、胃癌、肝癌）","处理方案":"【药物治疗·输液】\n⚠️ 按病因选择，肝硬化腹水以限钠+利尿为主，避免大量补液！\n\n方案1（肝硬化腹水，白蛋白与利尿）：\n 用法：白蛋白 10～20g 静滴（低蛋白或大量放腹水后，每放1L腹水补6～8g白蛋白）；呋塞米 20～40mg 静推（与口服利尿剂配合，按医嘱）\n\n方案2（大量放腹水治疗，顽固性腹水）：\n 用法：一次性放腹水4～6L（每次<5L较安全）+ 白蛋白 40g 静滴（每升腹水6～8g）——术后腹围与体重下降、利尿剂继续使用\n\n方案3（自发性腹膜炎，SBP）：\n 用法：头孢曲松 2g 静滴 qd 或 头孢噻肟 2g 静滴 q8h（疗程5～7天）；白蛋白 1.5g/kg（第1天）+ 1g/kg（第3天）静滴（预防肝肾综合征）\n\n方案4（恶性腹水与结核性腹膜炎）：\n 用法：恶性腹水——利尿+放腹水+腹腔化疗（顺铂/紫杉醇，按瘤种，肿瘤科指导）；结核性——异烟肼+利福平+吡嗪酰胺+乙胺丁醇（抗结核方案，结核科指导）+ 必要时激素\n\n📌 肝硬化腹水禁用大量生理盐水（加重腹水）；放腹水后必须补充白蛋白（防循环功能障碍）；SBP诊断后及早抗感染（不必等培养）。\n\n【药物治疗·口服】\n⚠️ 肝硬化腹水的口服治疗是基础（限钠+利尿）：\n\n药物1（利尿剂，联合方案）：\n 用法：螺内酯 40～80mg qd + 呋塞米 20～40mg qd（起始比例100:40，按尿量与体重调整；每日体重下降不超过0.5kg（无水肿）～1kg（有下肢水肿））\n\n药物2（低钠血症处理）：\n 用法：限水（血钠<125mmol/L时每日<1000ml）；避免快速纠正（防渗透性脱髓鞘）；必要时托伐普坦 15mg qd（遵医嘱）\n\n药物3（预防SBP复发与肝性脑病）：\n 用法：诺氟沙星 0.4g qd 或 利福昔明 400mg q8h；乳果糖 15～30ml bid（软便为目标）\n\n药物4（营养与辅助）：\n 用法：复合维生素B 2片 tid；支链氨基酸口服（营养不良者）；锌剂（辅助）\n\n📌 避免NSAIDs（肾损与出血）与氨基糖苷类；利尿剂过量致肝性脑病、肾损与电解质紊乱（需监测）。\n\n【治疗】\n限钠限水：钠盐摄入<2g/日（严格限钠），血钠<125mmol/L时限水800～1000ml/日\n利尿剂治疗：螺内酯（首选）+呋塞米联合，按尿量、体重与电解质调整；监测体重（每日0.5～1kg下降为宜）\n放腹水治疗：大量放腹水（4～6L/次）+白蛋白补充（每升6～8g），用于利尿无效或张力性腹水\n顽固性腹水：反复放腹水+白蛋白、TIPS（评估指征与禁忌）、肝移植评估\n病因治疗：肝硬化（抗病毒、戒酒、护肝）、恶性肿瘤（化疗/靶向）、结核（抗结核）、心衰（强心利尿扩血管）、肾病综合征（激素与免疫抑制）\n并发症防治：SBP（抗感染+白蛋白）、肝肾综合征（特利加压素+白蛋白）、肝性脑病（乳果糖）、低钠血症（限水±托伐普坦）\n营养支持：热量25～35kcal/kg、蛋白1.2～1.5g/kg（不主张长期限制蛋白），夜间加餐\n随访：监测体重、腹围、尿量、电解质与肾功能；定期超声与腹水检查（SBP筛查）\n\n【处理要点】\n体重与腹围监测：每日固定时间测体重与腹围，记录24小时出入量与尿量（评估利尿与放腹水效果）\n限钠限水执行：饮食宣教（每日钠<2g）、记录液体入量（低钠者限水），观察口渴与脱水征\n利尿剂观察：监测电解质（钾、钠、肌酐）每2～3天，观察过度利尿征象（乏力、意识改变、肌痉挛）\n放腹水护理：术前排空膀胱、术中监测生命体征、术后腹带加压与记录引流量/放液量，观察穿刺点渗液与出血\n并发症观察：发热与腹痛（SBP）、意识改变（肝性脑病）、少尿与肌酐升高（肝肾综合征）、呼吸困难（大量腹水）\n皮肤与体位护理：半卧位（减轻呼吸困难）、皮肤保湿与减压（腹水致皮肤张力高易破损）、翻身防止压疮\n宣教：严格限盐、遵医嘱服利尿剂与复查电解质、体重突增或发热腹痛及时就诊、戒酒与抗病毒治疗依从性\n\n【护理】\n体重腹围与出入量监测：每日固定条件测体重与腹围，记录24小时出入量与尿量，异常立即报告\n利尿剂与电解质监测：按时给药并观察尿量变化，配合复查电解质（每2～3天），观察过度利尿征象\n放腹水护理：术前排空膀胱与生命体征评估、术中监测、术后腹带加压、记录放液量与穿刺点情况\n并发症观察：发热腹痛（SBP）、意识改变（肝性脑病）、少尿与肌酐升高（肝肾综合征）、呼吸困难加重\n体位与皮肤护理：半卧位减轻呼吸困难、皮肤保湿与减压（腹水致腹壁张力高）、每2小时翻身防压疮\n宣教：严格限盐（<2g/日）与限水（低钠者）、遵医嘱服药不可自行加量、按时复查、发热腹痛或意识改变立即就诊\n\n【饮食】\n严格限钠：每日钠盐<2g（避免腌制品、加工食品、含钠调料与饮料）\n限水：血钠<125mmol/L时每日液体<800～1000ml（含汤水、水果与输液）\n蛋白质：1.2～1.5g/kg/日（植物蛋白与乳制品优先），不主张长期严格限制\n高热量、易消化、少量多餐（每日4～6餐）+夜间加餐；补充维生素与微量元素\n绝对禁酒；避免粗糙坚硬食物（防静脉破裂出血）；低钠血症者避免大量饮水与低钠饮料\n\n【注意事项】\n所有新发腹水均应行腹腔穿刺检查（SAAG、细胞数、细胞学与培养）——这是鉴别诊断的关键步骤\nSAAG≥11g/L提示门静脉高压性腹水（肝硬化、心衰）；<11g/L提示肿瘤、结核、胰源性或肾病性\n腹水中性粒细胞≥250/mm³即可诊断自发性腹膜炎（不必等培养），须立即抗感染\n大量放腹水必须补充白蛋白（每升6～8g）以预防循环功能障碍（PPCD）\n肝硬化腹水患者不主张长期严格限制蛋白（加重肌少症）；每日体重下降过快（>1kg）提示过度利尿\n\n【急诊/急救】\n腹水患者发热伴腹痛或意识改变（自发性腹膜炎）→ 立即诊断性穿刺+经验性抗生素+白蛋白\n大量放腹水后出现低血压、心动过速与少尿（循环功能障碍）→ 立即补液与白蛋白输注\n腹胀剧痛伴呼吸困难（张力性腹水/膈疝）→ 紧急放腹水减压并评估手术\n少尿、无尿与肌酐升高（肝肾综合征）→ 停利尿剂与肾毒性药物，白蛋白+特利加压素，评估透析\n意识改变伴扑翼样震颤（肝性脑病）→ 乳果糖+门冬氨酸鸟氨酸，去除诱因","资料来源":"疾病库 diseases.json；鉴别诊断库 ddx_local.json（条目「腹水（鉴别与处理）」原文）"},"icd10_diagnosis":"R18","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2658,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"853ecac37265356d9ef5fabc6f21af9152130811314c4d95672ef1b944788e56","pinyin":"fushui(jianbieyuchuli)","initials":"fs(jbycl)","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","R18",30]]},{"id":"templates-9d78600be1ad3f785f99","key":"v1-c9ccc21dfe2a3058|templates-9d78600be1ad3f785f99","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"腹痛(中医辨证)","category":"中医","raw":{"name":"腹痛(中医辨证)","category":"中医","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】寒邪内阻：腹痛拘急，遇寒痛甚，得温痛减，口淡不渴，形寒肢冷，小便清长，舌淡苔白腻，脉沉紧、饮食停滞：脘腹胀痛，拒按，嗳腐吞酸，恶食，痛而欲泻，泻后痛减，苔厚腻，脉滑实、肝郁气滞：脘腹疼痛，痛无定处，攻窜两胁，时聚时散，每因情志诱发，嗳气则舒，舌淡红苔薄白，脉弦、瘀血内停：腹痛如刺，痛处固定，拒按，经久不愈，舌质紫暗或有瘀斑，脉涩、中虚脏寒：腹痛绵绵，时作时止，喜温喜按，劳累后加重，神疲乏力，气短怯寒，舌淡苔白，脉沉细。\n【待人工确认·本机素材无此段原文】","现病史":"腹痛是以胃脘以下、耻骨毛际以上部位发生疼痛为主症的疾病。分外感寒邪、饮食停滞、肝郁气滞、瘀血内阻、中虚脏寒等证型。可见于急慢性胃肠炎、肠易激综合征、肠梗阻等。\n常见表现：寒邪内阻：腹痛拘急，遇寒痛甚，得温痛减，口淡不渴，形寒肢冷，小便清长，舌淡苔白腻，脉沉紧、饮食停滞：脘腹胀痛，拒按，嗳腐吞酸，恶食，痛而欲泻，泻后痛减，苔厚腻，脉滑实、肝郁气滞：脘腹疼痛，痛无定处，攻窜两胁，时聚时散，每因情志诱发，嗳气则舒，舌淡红苔薄白，脉弦、瘀血内停：腹痛如刺，痛处固定，拒按，经久不愈，舌质紫暗或有瘀斑，脉涩、中虚脏寒：腹痛绵绵，时作时止，喜温喜按，劳累后加重，神疲乏力，气短怯寒，舌淡苔白，脉沉细。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：体温、脉搏、呼吸、血压\n望诊：神、色（青/赤/黄/白/黑）、形态、头面、五官、躯体、舌诊（舌质/舌苔/舌底络脉）、排泄物\n闻诊：声音（语声/呼吸/咳嗽/呃逆/嗳气/肠鸣）、气味\n问诊：一般情况、主诉、现病史、既往史、个人史、家族史、十问歌\n切诊：脉诊（浮沉迟数虚实滑涩洪细濡弱弦紧结代促）、按诊（肌肤/手足/胸腹/腧穴）\n辨证：八纲辨证、脏腑辨证、气血津液辨证、经络辨证","辅助检查":"检查计划：患者以胃脘以下、耻骨毛际以上部位疼痛为主症就诊，症见腹痛拘急、遇寒痛甚、得温痛减，或脘腹胀痛、嗳腐吞酸、痛而欲泻，或痛无定处、攻窜两胁、每因情志诱发，或腹痛如刺、痛处固定、经久不愈，舌淡苔白腻、脉沉紧，结合中医辨证属寒邪内阻、饮食停滞、肝郁气滞、瘀血内停、中虚脏寒之候，可见于急慢性胃肠炎、肠易激综合征、肠梗阻等病，入院即刻完善血常规检查了解有无感染及贫血；完善尿常规检查排除泌尿系结石、感染等所致腹痛；完善大便常规+隐血检查了解有无消化道出血；完善血淀粉酶、脂肪酶检查排除急性胰腺炎；查腹部B超了解肝胆胰脾及腹腔有无结石、积液、占位等病变；完善肝肾功能、电解质检查排除肝肾疾病及电解质紊乱所致腹痛，并为用药安全提供依据；完善血糖检查排除糖尿病酮症所致腹痛；查心电图检查排除急性心肌缺血等心源性腹痛；如腹胀明显、肛门停止排气排便，急诊完善腹部立位平片检查排除肠梗阻、消化道穿孔；女性患者完善妇科B超检查排除妇科疾病所致腹痛；必要时完善胃镜检查明确胃十二指肠病变以进一步明确诊断。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 腹痛为主症，可伴腹胀、恶心、腹泻等\n2. 腹部B超、血常规、淀粉酶等明确病因\n3. 急腹症（穿孔、梗阻、出血）需急诊处理\n1. 腹痛(中医辨证)（ICD-10：R10.4）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！\n\n方案1：\n 用法：一般不需输液，以口服中药为主\n\n方案2（症状较重/脱水明显）：\n 用法：NS500ml+维生素C2.0g+维生素B6 0.2g ivgtt qd\n\n方案3（合并细菌感染）：\n 用法：NS250ml+头孢呋辛3.0g ivgtt bid（皮试后）\n\n📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！\n\n📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。\n\n药物1（寒邪内阻）：良附丸6g tid，或附子理中丸1丸 tid\n药物2（饮食停滞）：保和丸6-9g tid，或枳实导滞丸6g tid\n药物3（肝郁气滞）：元胡止痛片4片 tid，或气滞胃痛颗粒5g tid\n药物4（瘀血内停）：少腹逐瘀丸1丸 tid，或血府逐瘀胶囊4粒 tid\n药物5（中虚脏寒）：理中丸1丸 tid，或香砂六君丸6g tid\n\n【治疗】\n寒邪内阻：散寒温里，理气止痛，良附丸合正气天香散加减\n饮食停滞：消食导滞，理气止痛，枳实导滞丸加减\n肝郁气滞：疏肝解郁，理气止痛，柴胡疏肝散加减\n瘀血内停：活血化瘀，理气止痛，少腹逐瘀汤加减\n中虚脏寒：温中补虚，缓急止痛，小建中汤加减\n\n【处理要点】\n腹痛缓解前暂禁食或进流食，忌生冷\n注意腹部保暖\n保持大便通畅，避免用力\n\n【护理】\n病情观察：密切观察腹痛的部位、性质、程度、持续时间及诱发因素，注意有无呕吐、腹泻、发热、便血等伴随症状；若出现持续性剧烈腹痛、腹肌紧张、板状腹、压痛反跳痛等急腹症征象，立即报告医师，暂禁食禁水并做好术前准备。\n辨证施护：寒邪内阻者注意腹部保暖，可用热水袋热敷或艾灸神阙、中脘、天枢穴，忌冷水擦浴、避免受凉；湿热壅滞者观察大便性状、颜色及气味，保持二便通畅，便后温水清洗肛周；饮食停滞者暂进流质或半流质，观察呕吐物及大便是否含未消化食物；气滞血瘀者加强情志护理，耐心疏导，避免恼怒忧思，鼓励其倾诉。\n起居调护：病室宜安静整洁、温湿度适宜，寒证者居室宜温暖避风，热证者宜凉爽通风；嘱患者注意休息，避免劳累和剧烈活动，起身及活动时动作轻缓，防止诱发或加重腹痛。\n煎药服药护理：腹痛汤剂宜温服，寒凝腹痛宜热服，饭前温服以助药力；活血化瘀类方药宜饭后温服以护胃；服药后观察腹痛是否缓解及有无药后呕吐，若呕吐可将药汁少量多次频服。\n外治护理：遵医嘱行艾灸、中药热奄包、穴位贴敷（神阙、中脘、天枢、足三里）等外治，操作前评估局部皮肤状况，操作中观察有无红肿、烫伤，治疗后注意保暖，勿立即吹风受凉。\n\n【饮食】\n辨证忌口：寒邪内阻者忌食生冷瓜果、冰镇饮料及寒凉之品；湿热壅滞者忌肥甘厚味、辛辣油炸及甜腻食物；饮食停滞者忌暴饮暴食及黏腻难化之品；气滞血瘀者忌产气碍胃之品（如豆类、薯类、糯米）；中虚脏寒者忌生冷、苦寒之品以免伤脾败胃。\n适宜食物：寒凝腹痛宜温热易消化之品，如生姜、胡椒、羊肉、粳米粥；湿热腹痛宜清淡利湿之品，如冬瓜、薏苡仁、赤小豆、芹菜；食滞腹痛宜消食导滞之品，如山楂、萝卜、麦芽、鸡内金；气滞腹痛宜理气之品，如陈皮、佛手、萝卜；虚寒腹痛宜温补之品，如山药、红枣、莲子、桂圆。\n饮食宜少食多餐、细嚼慢咽，忌过饥过饱；急性发作期腹痛剧烈者暂禁食或仅进少量流质，缓解后由半流质逐步过渡至软食。\n药膳食疗：寒凝腹痛可服生姜红糖水、胡椒猪肚汤；食滞腹痛可用山楂麦芽粥、萝卜陈皮汤；气滞腹痛可用陈皮佛手茶；虚寒腹痛可用山药红枣粥、桂圆莲子羹。\n饮食调养：餐后不宜立即卧床或剧烈活动，可适当缓步行走以助运化；戒烟酒，忌浓茶、咖啡等刺激性饮品。\n\n【注意事项】\n腹痛剧烈、腹肌紧张、拒按者立即转急诊\n伴发热黄疸、血便者警惕急腹症\n慢性反复腹痛需结肠镜等排查\n\n【急诊/急救】\n一般不需急救\n症状加重伴休克/昏迷：立即急救处理\n反复发作/黑便/消瘦：转上级医院进一步检查","资料来源":"疾病库 diseases.json","中医辨证参考":"首次病程记录\n\n拟诊讨论：\n\n【中医辨证参考】腹痛\n（本页列出该病常见证型，请根据患者实际四诊资料选择相应证型，切勿直接套用）\n\n一、寒邪内阻\n    症状舌脉：腹痛拘急，遇寒痛甚，得温痛减，口淡不渴，形寒肢冷，小便清长，大便清稀或秘结，舌质淡、苔白腻，脉沉紧\n    治法：散寒温里、理气止痛\n    方剂：良附丸合正气天香散\n\n二、湿热壅滞\n    症状舌脉：腹痛拒按，烦渴引饮，大便秘结，或溏滞不爽，潮热汗出，小便短黄，舌质红、苔黄燥或黄腻，脉滑数\n    治法：泄热通腑、行气导滞\n    方剂：大承气汤\n\n三、饮食积滞\n    症状舌脉：脘腹胀满，疼痛拒按，嗳腐吞酸，恶食呕恶，痛而欲泻，泻后痛减，或大便秘结，舌苔厚腻，脉滑\n    治法：消食导滞、理气止痛\n    方剂：枳实导滞丸\n\n四、肝郁气滞\n    症状舌脉：腹痛胀闷，痛无定处，痛引少腹，或兼痛窜两胁，时作时止，得嗳气、矢气则舒，遇忧思恼怒则剧，舌质红、苔薄白，脉弦\n    治法：疏肝解郁、理气止痛\n    方剂：柴胡疏肝散\n\n五、瘀血内停\n    症状舌脉：腹痛较剧，痛如针刺，痛处固定，经久不愈，舌质紫暗、脉细涩\n    治法：活血化瘀、和络止痛\n    方剂：少腹逐瘀汤\n\n六、中虚脏寒\n    症状舌脉：腹痛绵绵，时作时止，喜温喜按，形寒肢冷，神疲乏力，气短懒言，胃纳不佳，面色无华，大便溏薄，舌质淡、苔薄白，脉沉细\n    治法：温中补虚、缓急止痛\n    方剂：小建中汤。来源：《中医内科学》（中国中医药出版社“十四五”规划教材）·脾胃系病证·腹痛。提示：急性腹痛须先排除外科急腹症（阑尾炎、穿孔、肠梗阻、宫外孕等），不可盲目止痛\n\n【方剂参考】\n  良附丸：组成 高良姜9g、香附9g；功效 行气疏肝，祛寒止痛\n      用法：水煎温服，日一剂，分二次服；原方为丸剂，每服6g，日二次，米饮汤送下。\n      注意：胃热疼痛、阴虚火旺者忌用；高良姜辛热，久服易伤阴；胃痛持续或伴消瘦、黑便者须先做胃镜检查。来源：《方剂学》（中国中医药出版社“十四五”规划教材）·理气剂（行气）；原方出自《良方集腋·卷上》\n  大承气汤：组成 大黄12g、芒硝9g、厚朴24g、枳实12g；功效 峻下热结\n      用法：枳实、厚朴先煎，后入大黄，芒硝烊化（冲服）；分温再服，得下（泻下）即止，不必尽剂。\n      注意：表证未解、年老体弱、孕妇、久病津亏及无实热积滞者忌用；得泻即停，过服伤正，忌与油腻同服。\n  枳实导滞丸：组成 大黄30g、枳实15g、神曲15g、茯苓9g、黄芩9g、黄连9g、白术9g、泽泻6g；功效 消导化积，清热利湿\n      用法：上药为末，蒸饼为丸如梧桐子大，每次6-9g，空腹温开水送服，日二次；亦可作汤剂，大黄后下。\n      注意：脾胃虚弱者、孕妇及无食积湿热者忌用；得泻即止，不宜久服。\n  柴胡疏肝散：组成 陈皮（醋炒）6g、柴胡6g、川芎4.5g、香附4.5g、枳壳（麸炒）4.5g、白芍4.5g、炙甘草1.5g；功效 疏肝解郁，行气止痛\n      用法：水煎温服，日一剂，分两次服；亦可研末为散，每服6~9g，开水送下。\n      注意：阴虚火旺、气郁化火及孕妇慎用；本方辛散，久服易耗气伤阴。来源：《方剂学》（中国中医药出版社“十四五”规划教材）·理气剂（行气）；原方出自《景岳全书·古方八阵》\n  少腹逐瘀汤：组成 小茴香1.5g（炒）、干姜3g（炒）、延胡索3g、没药6g（研）、当归9g、川芎6g、肉桂3g、赤芍6g、蒲黄9g（生）、五灵脂6g（炒）；功效 活血祛瘀，温经止痛\n      用法：水煎温服，日一剂，分二次服；亦可研末为散，每次6g，温酒送服。\n      注意：孕妇忌用（本方原书用于安胎，须身体壮实、确有瘀血可据者，且应遵医嘱）；月经过多、有出血倾向者慎用；体虚无瘀者不宜。来源：《方剂学》（中国中医药出版社“十四五”规划教材）·理血剂（活血祛瘀）；原方出自《医林改错·卷下》\n  小建中汤：组成 桂枝9g、白芍18g、炙甘草6g、生姜9g、大枣6枚、饴糖30g；功效 温中补虚，和里缓急\n      用法：水煎去滓，纳入饴糖，文火加热溶化，分两次温服。\n      注意：呕吐或中满者不宜；阴虚火旺、湿热内蕴者忌用；本方饴糖用量宜足，不可省略。来源：《方剂学》（中国中医药出版社“十四五”规划教材）·温里剂（温中祛寒）；原方出自《伤寒论·辨太阳病脉证并治中》\n\n【西医诊断】\n  功能性腹痛 / 慢性胃炎\n  （西医诊断依据与鉴别诊断请结合患者病史、体征、辅助检查补充）\n\n医师签名：＿＿＿＿"},"icd10_diagnosis":"R10.4","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2659,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"2af97348d9eb87eb1de687653768869fa3259e875f56819cff47d65413c7f5c8","pinyin":"futong(zhongyibianzheng)","initials":"ft(zybz)","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源","中医辨证参考"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源 中医辨证参考",30],["主要诊断编码","R10.4",30]]},{"id":"templates-b89b8a5dd9951a057d69","key":"v1-c9ccc21dfe2a3058|templates-b89b8a5dd9951a057d69","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"腹股沟疝(成人)","category":"疝与腹壁外科","raw":{"name":"腹股沟疝(成人)","category":"疝与腹壁外科","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】腹股沟区可复性包块：站立、行走、咳嗽或用力时出现，平卧或手推可回纳、局部坠胀感或隐痛，久站、劳累后加重、斜疝包块呈梨形，可降入阴囊（男性）；直疝呈半球形，一般不进入阴囊、难复性疝：包块不能完全回纳（内容物与疝囊粘连），无明显疼痛、嵌顿/绞窄：包块突然增大、变硬、不能回纳，剧痛伴恶心呕吐（肠梗阻）、发热、腹膜刺激征。\n【待人工确认·本机素材无此段原文】","现病史":"腹股沟疝是腹腔内脏器经腹股沟区薄弱处突出形成的疝，分为斜疝（经腹股沟管深环，最多见，可进入阴囊）、直疝（经直疝三角，少见于老年人）和股疝（经股环，女性多见、最易嵌顿）。成人腹股沟疝不能自愈，原则上应手术治疗，首选无张力修补（补片）。\n常见表现：腹股沟区可复性包块：站立、行走、咳嗽或用力时出现，平卧或手推可回纳、局部坠胀感或隐痛，久站、劳累后加重、斜疝包块呈梨形，可降入阴囊（男性）；直疝呈半球形，一般不进入阴囊、难复性疝：包块不能完全回纳（内容物与疝囊粘连），无明显疼痛、嵌顿/绞窄：包块突然增大、变硬、不能回纳，剧痛伴恶心呕吐（肠梗阻）、发热、腹膜刺激征。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：体温、脉搏、血压（嵌顿时评估感染与休克）\n一般情况：年龄、有无慢性咳嗽、便秘、前列腺增生、重体力劳动史\n站立位视诊：包块位置、形状（梨形/半球形）、是否降入阴囊、体位变化时变化\n卧位触诊：能否回纳、疝环大小（可容指尖/指/两指）、咳嗽冲击感\n鉴别检查：透光试验（鞘膜积液阳性）、睾丸与附睾触诊、精索情况\n嵌顿评估：包块张力、压痛、皮肤颜色与温度、有无腹膜刺激征\n对侧与股部检查：有无双侧疝、股疝（卵圆窝处包块）","辅助检查":"1. 血常规+CRP：术前基线，嵌顿时白细胞升高提示感染/绞窄\n2. 乳酸+血气分析：嵌顿/绞窄时乳酸升高提示肠缺血坏死（重要指标）\n3. 凝血功能+肝肾功能+心电图+胸片：术前常规评估（老年患者需心肺评估）\n4. 腹股沟区超声：明确疝内容物与疝环，鉴别鞘膜积液、淋巴结、精索静脉曲张\n5. 腹部CT（含Valsalva）：隐匿疝、复发疝、双侧疝或拟腹腔镜手术者的术前评估\n6. 腹部立位平片：嵌顿疝合并肠梗阻时（气液平面）\n7. 血糖+糖化血红蛋白：糖尿病患者术前控糖（影响补片感染风险）","初步诊断":"1. 体格检查：站立位与卧位对比、咳嗽冲击感（指尖冲击试验）、能否回纳、疝环大小（最关键）\n2. 腹股沟区超声：明确疝内容物与疝环，鉴别淋巴结肿大、鞘膜积液、精索静脉曲张、脂肪瘤\n3. 腹部CT（含Valsalva）：肥胖、隐匿疝、复发疝或拟腹腔镜手术者，明确分型与解剖\n4. 腹部立位平片：嵌顿疝合并肠梗阻时可见气液平面\n5. 血常规+CRP+乳酸：嵌顿/绞窄时白细胞升高、乳酸升高（提示肠缺血）\n6. 鉴别诊断：鞘膜积液（透光试验阳性）、精索静脉曲张、睾丸肿瘤、隐睾、股疝（女性）\n1. 腹股沟疝(成人)（ICD-10：K40.9）","鉴别诊断":"1. 腹股沟区超声：明确疝内容物与疝环，鉴别淋巴结肿大、鞘膜积液、精索静脉曲张、脂肪瘤\n2. 鉴别诊断：鞘膜积液（透光试验阳性）、精索静脉曲张、睾丸肿瘤、隐睾、股疝（女性）\n3. 诊断要点：体格检查：站立位与卧位对比、咳嗽冲击感（指尖冲击试验）、能否回纳、疝环大小（最关键）\n4. 诊断要点：腹股沟区超声：明确疝内容物与疝环，鉴别淋巴结肿大、鞘膜积液、精索静脉曲张、脂肪瘤\n5. 诊断要点：腹部CT（含Valsalva）：肥胖、隐匿疝、复发疝或拟腹腔镜手术者，明确分型与解剖\n6. 诊断要点：腹部立位平片：嵌顿疝合并肠梗阻时可见气液平面\n7. 诊断要点：血常规+CRP+乳酸：嵌顿/绞窄时白细胞升高、乳酸升高（提示肠缺血）\n8. 成人腹股沟疝不会自愈，'疝气带'仅能临时缓解症状，不能治愈，且可能增加嵌顿风险","处理方案":"【药物治疗·输液】\n⚠️ 按围手术期需要选择方案，切勿全部同时使用！\n\n方案1（术前预防性抗感染，切皮前0.5～1小时，置入补片者必用）：\n 用法：头孢呋辛 1.5g 静滴（单次）或 头孢唑林 1g 静滴；青霉素过敏者克林霉素 0.6g 静滴\n\n方案2（嵌顿/绞窄术前，合并肠梗阻）：\n 用法：头孢呋辛 1.5g 静滴 q8h + 甲硝唑 0.5g 静滴 q8h；平衡盐溶液 500～1000ml 静滴补液\n\n方案3（术后支持）：\n 用法：0.9%氯化钠/葡萄糖 静滴；老年患者注意补液速度\n\n📌 无张力修补（补片）术为清洁手术，预防性抗生素以覆盖金黄色葡萄球菌为主。\n\n【药物治疗·口服】\n⚠️ 术后用药，按医嘱选择，同类只选一种：\n\n药物1（镇痛）：\n 用法：塞来昔布 200mg qd～bid 或 洛索洛芬钠 60mg tid（餐后）；必要时曲马多 50mg\n\n药物2（通便，防腹压增高）：\n 用法：乳果糖 15ml bid 或 聚乙二醇4000散 1袋 qd\n\n药物3（镇咳，慢性咳嗽者）：\n 用法：复方甲氧那明 2粒 tid 或 氨溴索 30mg tid；吸烟者术前戒烟≥2周\n\n药物4（前列腺增生者，防排尿困难）：\n 用法：坦索罗辛 0.2mg qn（遵医嘱）\n\n📌 术后避免用力排便、剧烈咳嗽与提重物（腹压增高是复发主因）。\n\n【治疗】\n成人腹股沟疝原则上均应手术：疝不能自愈，且嵌顿风险随病程增加（股疝嵌顿率最高）\n无张力修补术：Lichtenstein术（开放，平片补片）为经典术式；腹腔镜TAPP/TEP适用于双侧疝、复发疝、需快速恢复者\n组织修补（Bassini/Shouldice）：仅用于补片禁忌（感染风险高、补片过敏）者，复发率高\n嵌顿疝：手法复位（嵌顿<4～6小时、无绞窄征象）成功后择期手术；复位失败或疑绞窄者急诊手术\n绞窄疝：急诊手术，切除坏死肠管+疝修补（感染情况下不做补片修补）\n术前优化：控制慢性咳嗽、便秘、前列腺增生，戒烟，减重，控制血糖\n术后并发症处理：血清肿（多自行吸收，避免反复穿刺）、慢性疼痛（神经阻滞/药物）、切口感染（换药引流，必要时取出补片）\n\n【处理要点】\n术前准备：完善检查（血常规、凝血、心电图、胸片）、控制咳嗽与便秘、备皮、术前排空膀胱\n术后体位与活动：麻醉清醒后取平卧位（可垫高阴囊），术后6小时可下床轻度活动\n切口观察：观察有无渗血、渗液、红肿；阴囊水肿/血清肿常见（可自行吸收，避免挤压）\n疼痛管理：评估疼痛评分，遵医嘱镇痛；术后慢性疼痛（>3个月）需专科评估\n腹压管理：避免剧烈咳嗽、用力排便、提重物（术后1～3个月内），必要时用药控制\n出院指导：术后1周、1个月门诊复查；腹腔镜术后2周内避免剧烈运动；复发及时就诊\n\n【护理】\n术前护理：戒烟、训练床上排便与有效咳嗽（按压切口）、术前排空膀胱、备皮\n术后体位：平卧、可垫高阴囊（减轻水肿），麻醉清醒后6小时可下床轻度活动\n切口与阴囊观察：注意渗血、阴囊水肿与血肿（必要时冷敷、托起阴囊）\n腹压管理：指导避免剧烈咳嗽、用力排便与提重物，必要时使用镇咳通便药\n疼痛护理：评估疼痛并遵医嘱镇痛，指导咳嗽时用手按压切口减轻张力\n出院宣教：保持切口清洁干燥、术后1～3个月避免重体力劳动、按时复查\n\n【饮食】\n术前禁食禁水6～8小时\n术后6小时可进流质，逐步过渡到半流质、软食、普食\n高蛋白、高维生素饮食促进切口与补片愈合\n多饮水、多食蔬菜水果与粗纤维，保持大便通畅（防便秘致腹压增高）\n忌辛辣刺激、产气食物与烟酒；慢性咳嗽者积极治疗呼吸道疾病\n\n【注意事项】\n成人腹股沟疝不会自愈，'疝气带'仅能临时缓解症状，不能治愈，且可能增加嵌顿风险\n股疝（女性多见）最易嵌顿绞窄，一经确诊应尽早手术\n嵌顿疝手法复位成功后仍需择期手术（复发嵌顿率高）\n腹腔镜修补（TAPP/TEP）术后恢复快、慢性疼痛少，但对术者技术要求高\n腹压增高因素（慢性咳嗽、便秘、前列腺增生、重体力劳动）需同步治疗，否则易复发\n\n【急诊/急救】\n包块突然增大变硬、不能回纳伴剧痛、呕吐（嵌顿）→ 急诊手术\n发热、心率增快、腹膜刺激征、乳酸升高（绞窄坏死）→ 立即急诊手术\n手法复位后腹痛加重、出现腹膜炎（假性复位）→ 立即手术探查","资料来源":"疾病库 diseases.json；鉴别诊断库 ddx_local.json（条目「腹股沟疝（成人）」原文）"},"icd10_diagnosis":"K40.9","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2660,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"9974f9dc571a3a192dae0c28216c596f79390a77d76caa45c1cf0ca40cdd39b7","pinyin":"fugugoushan(chengren)","initials":"fggs(cr)","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","K40.9",30]]},{"id":"templates-13270281a2c328fbe9c7","key":"v1-c9ccc21dfe2a3058|templates-13270281a2c328fbe9c7","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"腹腔间隔室综合征","category":"胃肠外科","raw":{"name":"腹腔间隔室综合征","category":"胃肠外科","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】腹部高度膨隆、腹壁紧张发亮、按压僵硬（'板状腹'样但为张力性）、呼吸困难、气道压升高、低氧血症与高碳酸血症（膈肌上抬）、少尿或无尿（肾灌注下降，早期即可出现）、心率增快、血压下降、中心静脉压升高（心输出量下降）、肠道缺血表现：腹胀、肠鸣音消失、消化道出血、乳酸升高。\n【待人工确认·本机素材无此段原文】","现病史":"腹腔间隔室综合征（ACS）是腹腔内压（IAP）持续升高（>20mmHg）并伴新发器官功能障碍的危重状态，多见于重症胰腺炎、腹部创伤、大面积烧伤、腹腔感染与大量液体复苏后。IAP升高致膈肌上抬（呼吸衰竭）、肾血流下降（少尿/无尿）、心输出量下降与肠道缺血，病死率高，需紧急减压。\n常见表现：腹部高度膨隆、腹壁紧张发亮、按压僵硬（'板状腹'样但为张力性）、呼吸困难、气道压升高、低氧血症与高碳酸血症（膈肌上抬）、少尿或无尿（肾灌注下降，早期即可出现）、心率增快、血压下降、中心静脉压升高（心输出量下降）、肠道缺血表现：腹胀、肠鸣音消失、消化道出血、乳酸升高。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：血压、心率、呼吸频率与形态、血氧（呼吸衰竭与休克）\n腹部视诊：高度膨隆、腹壁紧张发亮、皮肤张力性水疱、静脉扩张\n腹部触诊：全腹张力增高（僵硬但非炎性板状腹）、压痛、有无包块\n腹部叩诊：鼓音（肠管扩张）、移动性浊音（腹腔积液）\n腹部听诊：肠鸣音减弱或消失（肠麻痹/肠缺血）\n呼吸系统：呼吸动度减弱（膈肌上抬）、呼吸音减弱、气道压升高\n肾功能相关：尿量（尿袋/尿管记录）、下肢与颜面水肿（液体负荷）","辅助检查":"1. 腹内压（膀胱压）测定：每4～6小时，分级评估（Ⅰ级12～15、Ⅱ级16～20、Ⅲ级21～25、Ⅳ级>25mmHg）\n2. 血气分析+乳酸：呼吸衰竭（高碳酸血症）与组织灌注（乳酸升高）评估，每4～6小时\n3. 肾功能+电解质+尿量：急性肾损伤评估（每小时尿量记录）\n4. 血常规+CRP+PCT+血培养：感染与脓毒症评估\n5. 肝功能+白蛋白+凝血功能：多器官功能障碍评估\n6. 腹部CT/床旁超声：腹腔积液、肠管扩张、下腔静脉受压与下腔静脉变异度\n7. 心肌酶+BNP：心脏受累与容量状态评估（必要时）","初步诊断":"1. 腹内压测量（膀胱压法）：最常用，IAP>12mmHg为腹内高压（IAH），>20mmHg伴器官功能障碍为ACS（分级Ⅰ～Ⅳ）\n2. 器官功能评估：尿量（<0.5ml/kg/h）、气道峰压、氧合指数、心输出量与乳酸\n3. 腹部CT：腹腔积液、肠管扩张、腹壁紧张、下腔静脉受压（'圆腹征'）\n4. 床旁超声：腹腔积液与肠管扩张、下腔静脉变异度\n5. 血气分析+乳酸：呼吸衰竭与组织灌注评估\n6. 肾功能+电解质：少尿与急性肾损伤评估\n7. 腹部X线：肠管扩张、膈肌上抬\n1. 腹腔间隔室综合征（ICD-10：K65.9）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【药物治疗·输液】\n⚠️ 抢救用药，患者ICU监护下进行！\n\n方案1（液体管理，限制性复苏）：\n 用法：限制晶体液（避免加重水肿），平衡盐溶液按需；高渗盐水（3%氯化钠 100～150ml 静滴）或白蛋白/利尿剂（呋塞米 20～40mg 静推）促进液体排出\n\n方案2（镇痛镇静与肌松）：\n 用法：芬太尼 0.05mg 静推后泵入；咪达唑仑 2～5mg 静推后泵入；必要时维库溴铵 0.1mg/kg 静推（降低腹壁张力，短期）\n\n方案3（器官支持）：\n 用法：去甲肾上腺素 0.05～0.5μg/kg/min 泵入（维持MAP≥65mmHg）；必要时CRRT（肾替代与液体清除）\n\n方案4（抗感染，腹腔感染/脓毒症）：\n 用法：哌拉西林他唑巴坦 4.5g 静滴 q8h 或 美罗培南 1g 静滴 q8h + 甲硝唑 0.5g 静滴 q8h\n\n📌 避免过量液体复苏（加重腹内高压）；及时胃肠减压、引流腹腔积液与经皮穿刺减压可降低IAP。\n\n【药物治疗·口服】\n⚠️ 危重期不宜口服给药；恢复期遵医嘱：\n\n药物1（肠道功能恢复）：\n 用法：莫沙必利 5mg tid 或 甲氧氯普胺 10mg tid（腹胀、肠麻痹）\n\n药物2（通便）：\n 用法：乳果糖 15ml bid；必要时甘油灌肠剂\n\n药物3（营养补充）：\n 用法：口服营养补充剂 1～2份/日（恢复期）；胰酶制剂（胰腺炎后）\n\n📌 恢复期需长期随访肾功能与营养状态；避免暴饮暴食与大量补液。\n\n【治疗】\n非手术减压：胃肠减压（鼻胃管/肛管）、腹腔积液引流（超声引导穿刺）、限制液体、利尿、镇痛镇静与肌松\n体位与护理：床头抬高≤30°（过高增加IAP），避免腹部加压包扎\n经皮穿刺引流：腹腔大量积液时超声引导下置管引流（可显著降低IAP）\n手术减压（开腹减压术）：IAP>25mmHg伴器官功能障碍、非手术减压无效时，行剖腹探查减压+临时关腹（Bogota袋、负压封闭引流）\n器官功能支持：机械通气（高气道压者调整参数）、CRRT（少尿/无尿）、循环支持\n病因治疗：重症胰腺炎（抑酶、肠内营养）、腹腔感染（引流+抗感染）、出血（止血）\n临时关腹与二期缝合：待腹内高压缓解、器官功能改善后（一般3～7天）行二期关腹\n并发症防治：肠缺血坏死、切口疝（二期关腹后）、感染与脓毒症\n\n【处理要点】\n腹内压监测：每4～6小时（危重者每1～2小时）测膀胱压并记录，评估分级与趋势\n器官功能监测：每小时尿量（目标≥0.5ml/kg/h）、气道压、氧合、乳酸与血流动力学\n减压护理：保持胃肠减压与腹腔引流管通畅，记录引流量与性状；避免腹部加压（松解腹带）\n液体管理：严格记录出入量，限制晶体液，遵医嘱利尿或CRRT，监测电解质\n体位与镇静：床头抬高≤30°，按医嘱镇痛镇静与肌松，评估镇静深度（RASS）\n术前/术后护理（开腹减压）：观察减压后尿量与呼吸改善、临时关腹敷料渗液与感染征象\n营养支持：早期肠外营养，肠功能恢复后尽早肠内营养（监测腹内压变化）\n\n【护理】\n腹内压监测：按时测量膀胱压并记录（危重者每1～2小时），发现升高立即报告\n减压护理：保持胃管、肛管与腹腔引流管通畅，记录引流量与性状；松解腹带等加压物\n液体管理：严格记录24小时出入量，遵医嘱限制晶体液、利尿或CRRT，监测电解质\n器官功能观察：每小时尿量、呼吸频率与血氧、气道压、意识与乳酸变化\n体位护理：床头抬高≤30°，避免压迫腹部与增加腹压的操作，协助翻身（避免屈曲腹部）\n心理与家属沟通：病情危重，及时沟通病情与治疗方案，配合完成知情同意\n\n【饮食】\n急性期严格禁食禁水（胃肠减压），全肠外营养支持\n腹内压下降、肠功能恢复后尽早肠内营养（鼻空肠管，缓慢滴注并监测腹内压）\n限制液体与钠盐摄入（配合液体管理），避免加重水肿\n恢复期高蛋白、高热量、易消化饮食，少量多餐\n避免产气食物与暴饮暴食；胰腺炎患者长期低脂饮食、禁酒\n\n【注意事项】\nACS的诊断依据『腹内压>20mmHg + 新发器官功能障碍』，单纯腹内高压（IAH）不等于ACS\n膀胱压测量是最简便可靠的IAP监测方法，危重患者应常规监测\n过量液体复苏是IAP升高的重要医源性因素，应遵循限制性液体策略并尽早清除多余液体\n非手术减压无效且出现器官功能恶化时应果断开腹减压，延迟手术病死率显著升高\n临时关腹后需计划性二期关腹，避免强行缝合导致IAP再次升高\n\n【急诊/急救】\n腹内压>20mmHg伴少尿、气道压升高与低氧（器官功能障碍）→ 立即非手术减压，无效则急诊开腹减压\n腹内压>25mmHg伴休克或乳酸明显升高（肠缺血）→ 急诊开腹减压\n腹胀迅速加重伴呼吸困难与气道压骤升 → 立即减压并评估机械通气调整\n腹腔引流管引出大量血液或肠内容物（出血/肠瘘）→ 急诊处理","资料来源":"疾病库 diseases.json"},"icd10_diagnosis":"K65.9","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2661,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"c01bc85c3a462bb414041d8523a950341cc33afe14bdb143fe7b85c594bcab1f","pinyin":"fuqiangjiangeshizonghezheng","initials":"fqjgszhz","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","K65.9",30]]},{"id":"templates-7e9db763a164a3929015","key":"v1-c9ccc21dfe2a3058|templates-7e9db763a164a3929015","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"腹膜透析后腹膜炎","category":"肾脏病临床路径（2019年版）","raw":{"name":"腹膜透析后腹膜炎","category":"肾脏病临床路径（2019年版）","case":{"case_name":"门诊病历","templates":{"主诉":"【待人工确认·本机素材无此段原文】","现病史":"【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"【临床路径·住院期间检查项目】\n必需的检查项目：\r（1）血常规、尿常规（如仍有残余肾功能）、大便常规。\r（2）肝肾功能、血脂、电解质、血气分析、血糖、CRP、ESR、 PCT、血淀粉酶、腹水淀粉酶、BNP、乙肝、丙肝、梅毒、HIV相关检查及iPTH 。\r（3）透出液常规、病原微生物革兰染色及细菌、真菌涂片、培养及药敏试验。\r（4）心电图。\r2. 根据患者病情必要时的检查项目：\r（1）血培养、腹水CA125、腹水微量白蛋白、凝血功能及纤溶指标、造血原料指标、血真菌葡聚糖。\r（2）鼻腔分泌物、手、出口处分泌物培养及药敏试验；透出液抗酸杆菌培养。\r（3）营养评估相关指标：如前白蛋白、转铁蛋白。\r（4）腹部超声、X线胸片、腹部X线平片、超声心动图、腹部CT等。\r（七）治疗方案与药物选择\r1.纠正原发病因和可逆因素，预防再次感染。\r2.根据病情，积极纠正水电解质及酸碱平衡紊乱，加强营养支持等对症治疗。\r3.必要时拔除腹透管行血液透析治疗。\r（八）","初步诊断":"【临床路径·诊断依据】\n诊断依据\r根据《血液净化标准操作规程》（陈香美主编，人民军医出版社，2010年）、《腹膜透析标准操作规程》（陈香美主编，人民军医出版社，2010年）、《ISPD Peritonitis Recommendations: 2016 Update on Prevention and Treatment》[Li P K, et al. Perit Dial Int, 2016, 36(5):481-508]。\r1.透出液浑浊伴或不伴腹痛。\r2.透出液常规WBC＞100/\nl或＞0.1\n109/L; 多形核细胞＞50%（透出液在腹腔内停留至少2小时）。\r3.透出液病原微生物培养阳性。\r上述3条中符合2条可确诊。\r（三）\n1. 腹膜透析后腹膜炎（ICD-10：T85.711）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【临床路径·治疗方案的选择】\n治疗方案的选择\r根据《血液净化标准操作规程》（陈香美主编，人民军医出版社，2010年）、《腹膜透析标准操作规程》（陈香美主编，人民军医出版社，2010年）、《ISPD Peritonitis Recommendations: 2016 Update on Prevention and Treatment》[Li P K, et al. Perit Dial Int, 2016, 36(5):481-508]。\r1.早期诊断一旦出现腹透液混浊，无论有无腹痛，应怀疑腹膜炎。及时留取第一袋浑浊透出液送检，包括细胞计数和分类、革兰染色、真菌涂片和病原学培养+药敏试验。\r2.一旦考虑为腹膜透析后腹膜炎，留取标本后即应开始经验性抗感染治疗。\r3.初始治疗可经验用药，应联合使用抗菌药物，推荐腹腔给药。经验性抗感染治疗选用覆盖革兰阳性菌和革兰阴性菌的抗菌药物，如万古霉素或第一代头孢菌素覆盖革兰阳性菌，第三代头孢或氨基糖苷类药物覆盖革兰阴性菌抗菌药物。根据透出液培养及药敏试验结果及时调整抗菌药物。尽量选用对残余肾功能影响小的药物。推荐腹腔使用抗菌药物，间歇给药的抗菌药物留腹时间不小于6小时，使用抗菌药物治疗时可使用口服抗真菌药物预防真菌性腹膜炎。凝固酶阴性的葡萄球菌、链球菌抗菌药物疗程为2周；金黄色葡萄球菌、假单胞菌属、除假单胞菌属外的革兰阴性菌、肠球菌、棒状杆菌、多种肠道致病菌、多种革兰阳性菌感染抗菌药物疗程为3 周。\r4.发生腹膜透析后腹膜炎时，为避免纤维蛋白凝块形成，可在腹透液中加入适量肝素。\r5.发生腹膜透析相关性腹膜炎时，常出现超滤功能下降，此时可调整腹膜透析处方，如更改腹透液葡萄糖浓度，缩短存腹时间，夜间干腹等措施保证超滤量，避免容量超负荷。\r6.使用合适的抗菌药物规范治疗5天后透出液仍未变清亮定义为难治性腹膜炎，应尽早拔除腹透管。\r7.一旦诊断为真菌性腹膜炎，则应拔除腹透管，并使用敏感抗真菌药物至导管拔除后2周。\r8.结核性腹膜炎一般采取四联疗法，局部和全身用药相结合，无效者拔除导管并继续抗结核治疗。\r（四）","临床路径·进入路径标准":"进入路径标准\r1.第一诊断必须符合ICD\n10：T85.711腹膜透析后腹膜炎疾病编码。\r2.当患者同时具有其他疾病诊断时，但住院期间不需要特殊处理，也不影响第一诊断的临床路径流程实施时，可以进入路径。\r（六）住院后2～7天（指工作日）\r1.","临床路径·标准住院日":"标准住院日为15～24天\r（五）","临床路径·出院标准":"出院标准\r1.腹膜炎症状缓解，腹透液常规白细胞＜100/\nl，多核细胞＜50%。\r2.没有需要住院处理的并发症和（或）合并症。\r（九）","临床路径·变异及原因分析":"变异及原因分析\r1.新出现其他系统合并症，需要其他专科治疗。\r2.确诊难治性腹膜炎、真菌性腹膜炎、结核性腹膜炎、培养第3天仍为阴性的腹膜炎，退出本临床路径。。\r\r\f二、腹膜透析后腹膜炎（凝固酶阴性的葡萄球菌、链球菌感染腹膜炎）","资料来源":"国家卫健委《224个病种临床路径（2019年版）》（国卫办医函〔2019〕933号）· 肾脏病临床路径（2019年版） · 腹膜透析后腹膜炎临床路径（2019年版）.doc"},"icd10_diagnosis":"T85.711","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2662,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"a3ebc8a254f6568325d6dd8ef62b8d6f5e9fda80552a871c362fb4d784967ddc","pinyin":"fumotouxihoufumoyan","initials":"fmtxhfmy","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","临床路径·进入路径标准","临床路径·标准住院日","临床路径·出院标准","临床路径·变异及原因分析","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 临床路径·进入路径标准 临床路径·标准住院日 临床路径·出院标准 临床路径·变异及原因分析 资料来源",30],["主要诊断编码","T85.711",30]]},{"id":"templates-67d803c8ba1b1f22b173","key":"v1-c9ccc21dfe2a3058|templates-67d803c8ba1b1f22b173","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"腹膜透析相关腹膜炎","category":"内科-泌尿","raw":{"name":"腹膜透析相关腹膜炎","category":"内科-泌尿","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】透出液浑浊（最早且最可靠的表现）、絮状物或纤维蛋白凝块、腹痛（弥漫性，程度不等，可伴压痛与反跳痛）、腹胀、发热（可低热或高热）、寒战、恶心呕吐、导管出口或隧道感染征象：红肿、压痛、脓性分泌物、严重者出现脓毒症表现（低血压、意识改变）。\n【待人工确认·本机素材无此段原文】","现病史":"腹膜透析相关腹膜炎是腹膜透析（PD）最常见的严重并发症，多因操作污染（接触污染、导管出口感染）致细菌（革兰阳性球菌为主，金黄色葡萄球菌与凝固酶阴性葡萄球菌）进入腹腔，也可为革兰阴性菌与真菌。表现为透出液浑浊、腹痛与发热，需立即留取透出液培养并经验性腹腔内抗生素治疗。\n常见表现：透出液浑浊（最早且最可靠的表现）、絮状物或纤维蛋白凝块、腹痛（弥漫性，程度不等，可伴压痛与反跳痛）、腹胀、发热（可低热或高热）、寒战、恶心呕吐、导管出口或隧道感染征象：红肿、压痛、脓性分泌物、严重者出现脓毒症表现（低血压、意识改变）。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：体温、血压（脓毒症）、心率、呼吸\n腹部：弥漫压痛与反跳痛、腹胀、肠鸣音（减弱）\n透析导管：出口与隧道（红肿、渗液、压痛、脓性分泌物）、导管位置与固定\n透出液：浑浊程度、颜色、絮状物与纤维蛋白凝块（每袋观察）\n一般情况：脱水或水肿、营养状态、体重与干体重对比\n皮肤与穿刺部位：出口周围皮肤情况、有无感染灶\n其他：肺部（感染灶）、泌尿系（感染源）","辅助检查":"1. 透出液细胞计数（白细胞>100/μl、中性粒细胞>50%）+革兰染色：诊断核心（治疗前留取）\n2. 透出液细菌培养（需氧+厌氧+真菌，注入血培养瓶提高阳性率）：病原学诊断与药敏\n3. 血常规+CRP+PCT+血培养（疑脓毒症）：全身感染评估\n4. 透出液生化+淀粉酶（必要时）：排除胰源性与其他原因\n5. 腹部超声/CT（疑继发性腹膜炎或脓肿）：排除外科急腹症与腹腔脓肿\n6. 白蛋白+前白蛋白+电解质：营养与电解质状态（腹膜炎丢失蛋白增加）\n7. 导管出口分泌物培养：出口/隧道感染病原学","初步诊断":"1. 透出液检查（关键）：细胞计数（白细胞>100/μl，中性粒细胞>50%诊断腹膜炎）、革兰染色、细菌培养（留取在抗生素前）\n2. 透出液培养：需氧+厌氧+真菌培养（阳性率>80%）；同时做血培养（疑脓毒症）\n3. 透出液生化+革兰染色+细胞学：排除其他原因（嗜酸性粒细胞增多性腹膜炎、肿瘤、结核）\n4. 导管出口与隧道检查：分泌物培养与体检\n5. 血常规+CRP+PCT：炎症程度评估\n6. 腹部超声/CT：排除腹腔内脓肿、脏器病变与其他急腹症（疑继发性腹膜炎）\n7. 鉴别诊断：继发性腹膜炎（外科急腹症）、化学性腹膜炎（透析液刺激）、嗜酸粒细胞性腹膜炎、结核性腹膜炎\n1. 腹膜透析相关腹膜炎（ICD-10：T85.7）","鉴别诊断":"1. 透出液生化+革兰染色+细胞学：排除其他原因（嗜酸性粒细胞增多性腹膜炎、肿瘤、结核）\n2. 腹部超声/CT：排除腹腔内脓肿、脏器病变与其他急腹症（疑继发性腹膜炎）\n3. 鉴别诊断：继发性腹膜炎（外科急腹症）、化学性腹膜炎（透析液刺激）、嗜酸粒细胞性腹膜炎、结核性腹膜炎","处理方案":"【药物治疗·输液】\n⚠️ 腹腔内给药是首选途径，须立即留取培养后开始经验性治疗！\n\n方案1（经验性腹腔内抗生素，覆盖革兰阳性与阴性菌）：\n 用法：头孢唑林 1g（或万古霉素 1g）加入透析液 2L 中腹腔内留腹 6小时（负荷剂量），之后维持剂量（头孢唑林 250mg/2L 每袋）——革兰阳性覆盖；联合 头孢他啶 1g（负荷，腹腔内）+ 维持 250mg/2L 或 庆大霉素 40mg（负荷）——革兰阴性覆盖\n\n方案2（静脉给药，重症/脓毒症）：\n 用法：万古霉素 1g 静滴 q12h（监测血药浓度）+ 头孢他啶 2g 静滴 q8h（或 哌拉西林他唑巴坦 4.5g q8h）；脓毒症休克者按脓毒症处理\n\n方案3（真菌性腹膜炎）：\n 用法：氟康唑 200mg 腹腔内/静滴 qd 或 卡泊芬净 50～70mg 静滴 qd——通常需拔除导管\n\n方案4（支持治疗）：\n 用法：0.9%氯化钠 静滴（补液）；白蛋白 10g 静滴（低蛋白者）；必要时镇痛（对乙酰氨基酚）\n\n📌 治疗前必须留取透出液培养；革兰阳性菌用头孢唑林/万古霉素，革兰阴性菌用头孢他啶/氨基糖苷类；反复或难治性腹膜炎（抗生素5天无效）需拔除PD导管（改血液透析）。\n\n【药物治疗·口服】\n⚠️ 腹腔内用药为主，口服为辅：\n\n药物1（口服抗生素，按药敏序贯）：\n 用法：头孢氨苄 0.5g qid 或 阿莫西林克拉维酸 0.625g tid（敏感菌，疗程14～21天）；利福平 0.45g qd（金黄色葡萄球菌辅助，遵医嘱）\n\n药物2（对症与支持）：\n 用法：对乙酰氨基酚 0.5g 必要时（腹痛）；乳果糖 15ml bid（便秘，防导管移位）\n\n药物3（预防与出口护理）：\n 用法：莫匹罗星软膏 导管出口处 每日1次（金黄色葡萄球菌预防，遵医嘱）；聚维酮碘或氯己定出口护理（按中心规范）\n\n药物4（营养支持）：\n 用法：口服营养补充剂 1～2份/日；复合维生素B 2片 tid\n\n📌 抗生素疗程14～21天（金黄色葡萄球菌与难治性者更长）；治疗期间每日评估透出液变清情况；出口感染需加强护理。\n\n【治疗】\n立即留取透出液培养（细胞计数+革兰染色+需氧厌氧真菌培养），随后开始经验性腹腔内抗生素（覆盖革兰阳性与阴性菌）\n腹腔内给药方案：负荷剂量留腹6小时，随后每袋透析液维持剂量（疗程14～21天）；培养结果出来按药敏调整（尽量窄谱）\n严重感染或脓毒症：静脉抗生素+腹腔内给药，必要时转ICU\n拔管指征：难治性腹膜炎（抗生素治疗5天透出液不转清）、真菌性腹膜炎、反复发作（同一菌株复发）、难治性导管出口/隧道感染、脓毒症——拔管后改血液透析（4～6周后可再置管）\n导管相关处理：出口感染加强局部护理与抗生素；隧道感染常需拔管\n透出液冲洗：部分中心采用快速冲洗（1～2次交换不含抗生素）减少炎症介质\n支持治疗：补液、营养支持（蛋白丢失增加）、镇痛与电解质监测\n随访与预防：评估疗效（透出液细胞计数与培养复查），培训患者操作规范（洗手、戴口罩、无菌操作），定期评估出口与隧道\n\n【处理要点】\n透出液观察：每次换液观察透出液是否浑浊（记录浑浊、絮状物与颜色），异常立即留取标本并报告\n标本留取：按规范留取透出液（>50ml，注入血培养瓶提高阳性率）并在使用抗生素前完成\n腹腔内给药护理：按医嘱将抗生素加入透析液、留腹时间准确（负荷6小时）、记录给药时间与剂量\n症状与体征监测：腹痛、发热、寒战与腹部压痛，监测生命体征与透出液性状变化（每袋记录）\n导管出口护理：每日观察出口与隧道（红肿、渗液、压痛）、按规范清洁消毒、避免牵拉与污染\n营养与液体管理：高蛋白饮食（腹透丢失蛋白3～5g/日）、记录出入量与体重（干体重评估）\n宣教：严格无菌操作（洗手、口罩、戴手套）、连接与断开规范、出现透出液浑浊立即联系医疗团队（不可等待）、按时随访\n\n【护理】\n透出液观察与记录：每袋换液观察透出液性状（浑浊、絮状物）并记录，发现浑浊立即留取标本并报告\n标本留取护理：按规范留取透出液（>50ml注入血培养瓶），确保在抗生素使用前完成\n腹腔内给药护理：按医嘱将抗生素加入透析液、准确记录留腹时间（负荷6小时）与剂量，观察疗效（透出液变清）\n出口与导管护理：每日观察出口与隧道、按规范清洁消毒、固定导管避免牵拉、观察有无渗液与红肿\n症状与生命体征监测：腹痛、发热、寒战与腹部压痛，每4小时测体温，异常立即报告\n宣教：无菌操作规范（洗手、戴口罩、戴手套、连接消毒）、发现透出液浑浊立即联系团队、营养与液体管理、按时随访\n\n【饮食】\n高蛋白饮食（1.2～1.5g/kg/日，腹透每日丢失蛋白3～5g）、高热量（30～35kcal/kg/日）\n限制钠（<3～5g/日）与液体（按超滤量与尿量调整，体重增长<干体重3%～5%）\n限制钾与磷（按化验调整，腹透患者高钾风险低于血透）\n腹膜炎期间：易消化、少量多餐，必要时口服营养补充剂（感染消耗增加）\n避免生冷与不洁食物（腹透患者腹膜炎风险与肠道细菌移位相关）；充足维生素补充\n\n【注意事项】\n透出液浑浊是腹膜透析相关腹膜炎最早、最可靠的表现——出现浑浊应立即留取标本并开始治疗（不必等结果）\n诊断标准：透出液白细胞>100/μl且中性粒细胞>50%（或涂片/培养阳性）+ 临床表现\n经验性抗生素必须同时覆盖革兰阳性与阴性菌（头孢唑林/万古霉素+头孢他啶/庆大霉素）\n抗生素治疗5天透出液不转清为难治性腹膜炎，需拔除PD导管（避免导致包裹性硬化性腹膜炎）\n真菌性腹膜炎一经诊断应拔管并抗真菌治疗（预后差）\n\n【急诊/急救】\n透出液浑浊伴剧烈腹痛与高热（重症腹膜炎）→ 立即留取标本+腹腔内/静脉抗生素，评估脓毒症\n腹膜炎伴血压下降与意识改变（脓毒症休克）→ 立即复苏+静脉广谱抗生素+ICU，评估拔管\n腹痛伴腹膜刺激征与影像提示腹腔内脓肿（继发性腹膜炎）→ 外科急会诊与手术评估\n抗生素治疗5天透出液不转清（难治性腹膜炎）→ 拔除PD导管并改血液透析\n真菌性腹膜炎伴透出液絮状物与发热 → 立即拔管+抗真菌治疗","资料来源":"疾病库 diseases.json；鉴别诊断库 ddx_local.json（条目「腹膜透析相关腹膜炎」原文）"},"icd10_diagnosis":"T85.7","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2663,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"5785dfab374721fdff027fdaedcc9d24e53f8f2c4e1f288e1fb2910d57e21f71","pinyin":"fumotouxixiangguanfumoyan","initials":"fmtxxgfmy","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","T85.7",30]]},{"id":"templates-f917461033af723a36eb","key":"v1-c9ccc21dfe2a3058|templates-f917461033af723a36eb","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"膀胱肿瘤经尿道等离子电切术","category":"泌尿外科临床路径（2019年版）","raw":{"name":"膀胱肿瘤经尿道等离子电切术","category":"泌尿外科临床路径（2019年版）","case":{"case_name":"门诊病历","templates":{"主诉":"【待人工确认·本机素材无此段原文】","现病史":"【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"【临床路径·住院期间检查项目】\n必需的检查项目\n1.血常规、尿常规；\n2.电解质、肝肾功能、血型、凝血功能；\n3.感染性疾病筛查（乙型肝炎、丙型肝炎、艾滋病、梅毒等）；\n4.X线胸片，心电图。\n（七）预防性抗菌药物选择与使用时机\n按照《抗菌药物临床患者指导原则》（国卫办医发〔2015〕43号）执行，并结合患者的病情决定抗菌药物的选择与使用时间。\n（八）手术日为入院后\n4天\n1.麻醉方式：脊椎麻醉或硬膜外麻醉或全身麻醉。\n2.手术方式：经尿道膀胱肿瘤等离子电切术（PKRBT）。\n3.术中用药：麻醉用药，必要时用抗菌药物。\n4.输血：必要时。\n（九）术后住院恢复\n3天\n1.必须复查的检查项目：血常规、尿常规；根据患者病情变化可选择相应的检查项目。\n2.术后抗菌药物患者：按照《抗菌药物临床患者指导原则》（国卫办医发〔2015〕43号）执行。\n（十）","初步诊断":"【临床路径·诊断依据】\n诊断依据\n根据《中国泌尿外科疾病诊断治疗指南》（中华医学会泌尿外科学分会编著，人民卫生出版社，2014年）。\n1.病史。\n2.体格检查。\n3.实验室检查、影像学检查和（或）内镜检查。\n（三）\n1. 膀胱肿瘤经尿道等离子电切术（ICD-10：C67）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【临床路径·治疗方案的选择】\n选择治疗方案的依据\n根据《中国泌尿外科疾病诊断治疗指南》（中华医学会泌尿外科学分会编著，人民卫生出版社，2014年）。\n1.适合经尿道膀胱肿瘤电切术（PKRBT）：PKRBT既是非肌层浸润性膀胱癌的重要诊断方法，也是主要的治疗手段。PKRBT应将肿瘤完全切除直至露出正常的膀胱壁肌层。肿瘤切除后，建议进行基底部组织活检，便于病理分期和下一步治疗方案的确定。\n符合下列情况者建议行二次PKRBT术：\n（1）首次PKRBT不充分；\n（2）首次PKRBT标本中没有肌层组织，TaG1（低级别）肿瘤和单纯原位癌除外；\n（3）T1期肿瘤；\n（4）G3（高级别）肿瘤，单纯原位癌除外。\n2.能够耐受手术。\n（四）","临床路径·进入路径标准":"进入路径标准\n1.门诊完成膀胱镜检、CT泌尿系平扫（或CTU检查），证实膀胱占位性病变。完成手术适应证及禁忌证评估。\n2.第一诊断必须符合ICD-10：C67,C79.1,D09.0，D30.3,D41.4膀胱肿瘤疾病编码。\n3.当患者合并其他疾病诊断，但住院期间无需特殊处理也不影响第一诊断临床路径实施时，可以进入路径。\n（六）术前准备（术前评估）\n3天","临床路径·标准住院日":"标准住院日为\n7天\n（五）","临床路径·出院标准":"出院标准\n1.一般情况良好。 \n2.拔除尿管。\n（十一）","临床路径·变异及原因分析":"变异及原因分析\n1.术中、术后出现并发症，需要进一步诊治，导致住院时间延长、费用增加。\n2.等离子电切手术效果不满意，需进一步治疗（如膀胱全切、动脉化疗等）。\n3.术后原伴随疾病控制不佳，需请相关科室会诊，进一步诊治。\n4.住院后出现其他内、外科疾病需进一步明确诊断，可进入其他路径。","资料来源":"国家卫健委《224个病种临床路径（2019年版）》（国卫办医函〔2019〕933号）· 泌尿外科临床路径（2019年版） · 膀胱肿瘤经尿道等离子电切术临床路径（2019年版）.docx"},"icd10_diagnosis":"C67","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2664,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"7a3944c2963372d2d2bfdcf935fc53fe605bc67567be21ec692853d54bfc541a","pinyin":"pangguangzhongliujingniaodaodenglizidianqieshu","initials":"pgzljnddlzdqs","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","临床路径·进入路径标准","临床路径·标准住院日","临床路径·出院标准","临床路径·变异及原因分析","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 临床路径·进入路径标准 临床路径·标准住院日 临床路径·出院标准 临床路径·变异及原因分析 资料来源",30],["主要诊断编码","C67",30]]},{"id":"templates-6c71557bd6bc7f3764d8","key":"v1-c9ccc21dfe2a3058|templates-6c71557bd6bc7f3764d8","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"膝关节骨关节炎(全膝关节置换)","category":"骨科","raw":{"name":"膝关节骨关节炎(全膝关节置换)","category":"骨科","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】膝关节疼痛（负重与上下楼梯时加重，休息后减轻），可有夜间痛、关节僵硬（晨起或久坐后起步困难，活动后缓解，一般<30分钟）、关节活动受限（屈伸范围减小），下蹲困难、关节肿胀、摩擦感（骨摩擦音）、畸形（膝内翻或外翻）、病程晚期：关节不稳、行走困难、肌肉萎缩与生活质量显著下降。\n【待人工确认·本机素材无此段原文】","现病史":"膝关节骨关节炎是中老年最常见的退行性关节病，表现为膝关节疼痛、僵硬与活动受限。治疗遵循阶梯原则：基础治疗（减重、运动、物理治疗）→ 药物治疗（NSAIDs、关节腔注射）→ 手术治疗（关节镜、截骨、全膝关节置换TKA）。TKA适用于终末期病变、疼痛严重影响生活且保守治疗无效者。\n常见表现：膝关节疼痛（负重与上下楼梯时加重，休息后减轻），可有夜间痛、关节僵硬（晨起或久坐后起步困难，活动后缓解，一般<30分钟）、关节活动受限（屈伸范围减小），下蹲困难、关节肿胀、摩擦感（骨摩擦音）、畸形（膝内翻或外翻）、病程晚期：关节不稳、行走困难、肌肉萎缩与生活质量显著下降。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：血压、心率、体温、BMI（肥胖评估）\n步态与姿势：跛行、步幅、下肢力线（膝内翻/外翻畸形）\n膝关节视诊：肿胀、积液、畸形、肌肉萎缩（股四头肌）、手术瘢痕\n膝关节触诊：关节线压痛、髌骨研磨试验、皮温（感染筛查）、浮髌试验（积液）\n关节活动度：屈曲与伸展范围（记录角度），有无屈曲挛缩\n稳定性：前后抽屉试验（交叉韧带）、侧方应力试验（侧副韧带）、有无关节不稳\n神经血管：足背动脉搏动、末梢感觉与运动；腰椎检查（排除腰源性膝痛）","辅助检查":"1. 膝关节负重X线（正位+侧位+髌骨轴位）+双下肢全长片：分级、畸形与力线评估（术前规划）\n2. 血常规+CRP+血沉+类风湿因子+抗CCP抗体：排除感染性与类风湿性关节炎\n3. 关节液检查（必要时）：细胞数、结晶、细菌培养（排除痛风与感染）\n4. 凝血功能+肝肾功能+心电图+心脏超声+肺功能：老年患者术前风险评估\n5. 骨密度（DEXA）+血钙磷+维生素D：骨质疏松评估与治疗依据\n6. 血糖+糖化血红蛋白：糖尿病患者术前控糖（感染与愈合风险）\n7. 下肢静脉超声（术前，高危患者）：评估DVT（既往VTE史者）","初步诊断":"1. 膝关节X线（负重正位+侧位+髌骨轴位）：关节间隙变窄、骨赘形成、软骨下骨硬化与囊性变（Kellgren-Lawrence分级）\n2. 膝关节MRI（必要时）：评估软骨、半月板与韧带（X线不典型或疑合并损伤）\n3. 膝关节功能评分（HSS、WOMAC、KSS）：术前评估与疗效评价\n4. 血常规+CRP+血沉+类风湿因子+抗CCP抗体：排除感染性关节炎与类风湿关节炎\n5. 关节液检查（必要时）：细胞数、结晶（排除痛风与感染）\n6. 双下肢全长X线：评估下肢力线（畸形程度，术前规划）\n7. 骨密度+心肺功能评估（老年患者）：术前风险评估\n1. 膝关节骨关节炎(全膝关节置换)（ICD-10：M17.9）","鉴别诊断":"1. 血常规+CRP+血沉+类风湿因子+抗CCP抗体：排除感染性关节炎与类风湿关节炎\n2. 关节液检查（必要时）：细胞数、结晶（排除痛风与感染）\n3. 诊断要点：膝关节X线（负重正位+侧位+髌骨轴位）：关节间隙变窄、骨赘形成、软骨下骨硬化与囊性变（Kellgren-Lawrence分级）\n4. 诊断要点：膝关节MRI（必要时）：评估软骨、半月板与韧带（X线不典型或疑合并损伤）\n5. 诊断要点：膝关节功能评分（HSS、WOMAC、KSS）：术前评估与疗效评价\n6. 诊断要点：血常规+CRP+血沉+类风湿因子+抗CCP抗体：排除感染性关节炎与类风湿关节炎\n7. 诊断要点：关节液检查（必要时）：细胞数、结晶（排除痛风与感染）\n8. 诊断要点：双下肢全长X线：评估下肢力线（畸形程度，术前规划）","处理方案":"【药物治疗·输液】\n⚠️ 围手术期按医嘱选择方案，切勿全部同时使用！\n\n方案1（术前预防性抗感染，切皮前0.5～1小时）：\n 用法：头孢呋辛 1.5g 静滴（单次）或 头孢唑林 1g 静滴；过敏者克林霉素 0.6g 或万古霉素 1g\n\n方案2（氨甲环酸减少出血，术前/术中）：\n 用法：氨甲环酸 1g 静滴（切皮前15～30分钟）或 1～2g 关节腔内注射（关闭切口前）；必要时术后3小时追加1g\n\n方案3（术后镇痛）：\n 用法：氟比洛芬酯 50mg 静滴 q12h；曲马多 100mg 静滴 必要时；必要时静脉镇痛泵（多模式镇痛）\n\n方案4（抗凝预防VTE）：\n 用法：低分子肝素 0.4ml 皮下注射 qd（术后12～24小时开始，疗程10～14天，可延长至35天）；或利伐沙班 10mg qd\n\n📌 氨甲环酸可显著减少TKA出血与输血需求；所有患者均需VTE预防（药物+物理）。\n\n【药物治疗·口服】\n⚠️ 术后与长期用药，按医嘱选择：\n\n药物1（镇痛）：\n 用法：塞来昔布 200mg qd～bid 或 洛索洛芬钠 60mg tid（餐后）；必要时曲马多 50mg；注意与抗凝药合用的出血风险\n\n药物2（抗凝序贯）：\n 用法：利伐沙班 10mg qd（术后35天，按医嘱）或 阿司匹林 100mg qd（替代方案）\n\n药物3（钙与维生素D）：\n 用法：碳酸钙D3 600mg qd + 维生素D 800IU/日\n\n药物4（通便）：\n 用法：乳果糖 15ml bid（术后卧床与阿片类致便秘）\n\n📌 术后避免NSAIDs与抗凝药大剂量合用（出血风险）；糖尿病与高血压患者围手术期需控制基础病。\n\n【治疗】\n阶梯治疗：基础治疗（减重、股四头肌与臀中肌力量训练、有氧运动、物理治疗、支具）→ 药物治疗（外用/口服NSAIDs、关节腔注射玻璃酸钠或糖皮质激素）→ 手术\n全膝关节置换（TKA）指征：中重度疼痛影响睡眠与日常活动、保守治疗无效、X线示关节间隙明显消失（K-L 3～4级）、畸形（内/外翻>10°）或关节不稳\n手术方式：后稳定型（PS）或后交叉韧带保留型（CR）假体；骨水泥固定为标准；双侧病变可分期或同期置换（评估风险）\n围手术期管理（ERAS）：术前宣教与功能训练、氨甲环酸减少出血、多模式镇痛、早期下床（术后6～24小时）、早期功能锻炼\n术后康复：术后第1天开始踝泵、股四头肌等长收缩与被动屈伸；逐步过渡到主动活动与步行（助行器→手杖→独立行走），争取6周内屈膝≥90°、伸直0°\n并发症处理：深静脉血栓（抗凝+物理预防）、感染（假体周围感染需清创或二期翻修）、僵硬（麻醉下手法松解或关节镜）、神经血管损伤、假体周围骨折\n长期随访：术后6周、3个月、6个月、1年复查（X线与功能评分），之后每年或每2年；假体寿命一般15～20年\n\n【处理要点】\n术前准备：宣教（手术流程、康复计划）、功能训练（踝泵、股四头肌训练）、控制基础病（血糖、血压）、戒烟、皮肤准备（防感染）\n术后体位与制动：患肢抬高（垫软枕，膝下勿垫高枕以防屈曲挛缩）、必要时用CPM机辅助屈伸\n切口与引流观察：观察渗血、渗液与引流量，保持敷料清洁干燥；警惕假体周围感染（持续渗液、发热）\n疼痛管理：多模式镇痛（神经阻滞+静脉+口服），评估疼痛评分（疼痛控制好是早期活动的前提）\n早期活动：术后6～24小时坐起与床边站立，术后第1～2天助行器下地行走；每日康复训练（屈伸、直腿抬高、步态训练）\nVTE预防执行：药物抗凝+间歇充气加压装置+踝泵运动，观察下肢肿胀与疼痛（DVT/PE）\n出院指导：继续康复训练（每日3～4次）、避免深蹲与跪姿、控制体重、按时复查；警惕感染征象（红肿热痛、发热）\n\n【护理】\n术前护理：功能训练宣教（踝泵、股四头肌等长收缩、直腿抬高）、皮肤准备、戒烟、控制基础病\n术后体位：患肢抬高（垫软枕，膝下勿垫高枕防屈曲挛缩），保持膝关节中立位\n切口与引流护理：观察渗血渗液与引流量，保持敷料清洁干燥，记录引流量与性状\n疼痛管理：多模式镇痛并按评分给药，疼痛控制满意后协助早期活动\n早期活动与康复：术后6～24小时坐起站立，第1～2天助行器行走，指导踝泵（每小时10～20次）与屈伸训练\n并发症观察与宣教：下肢肿胀疼痛（DVT）、呼吸困难（PE）、切口红肿渗液与发热（感染）、膝关节活动度进展；出院后继续康复训练与按时复查\n\n【饮食】\n术前：高蛋白、高钙、高维生素饮食，控制体重（减重可减轻关节负荷）\n术后：高蛋白饮食促进切口愈合与康复（鱼、瘦肉、蛋、奶、豆制品）\n多饮水（每日1500～2000ml），预防脱水与血栓\n多食蔬菜水果与粗纤维，保持大便通畅（防便秘致腹压增高与VTE风险）\n控制血糖与体重；戒烟限酒；补充钙与维生素D\n\n【注意事项】\n膝关节骨关节炎治疗应遵循阶梯原则，TKA仅用于终末期病变且保守治疗无效者\n围手术期VTE预防是必需的（药物+物理），髋膝关节置换术后DVT风险高\n早期功能锻炼（术后24小时内开始）是获得良好关节活动度的关键，延迟康复易致关节僵硬\n假体周围感染是最严重的并发症（发生率1%～2%），需注意口腔与皮肤感染灶的处理（术前牙科治疗）\n肥胖患者应先减重（BMI>40者术后并发症与假体磨损风险显著升高）\n\n【急诊/急救】\n术后突发呼吸困难、胸痛、血氧下降（肺栓塞）→ 立即抢救、抗凝或溶栓，转ICU\n切口大量渗液伴发热与关节红肿热痛（急性假体周围感染）→ 急诊关节穿刺培养+抗感染，评估清创\n术后患肢肿胀迅速加重伴剧痛、足背动脉搏动减弱（血管损伤/骨筋膜室综合征）→ 急诊评估处理\n膝关节屈伸时突发剧痛伴畸形（假体周围骨折/脱位）→ 急诊影像与处理","资料来源":"疾病库 diseases.json；鉴别诊断库 ddx_local.json（条目「膝关节骨关节炎（全膝关节置换）」原文）"},"icd10_diagnosis":"M17.9","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2665,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"895a1a61d23f4ea6d9e99c08d9d07bd269447209672193760c7ec8063f2a3f34","pinyin":"xiguanjieguguanjieyan(quanxiguanjiezhihuan)","initials":"xgjggjy(qxgjzh)","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","M17.9",30]]},{"id":"templates-7ccdbd161a3a95dcd17e","key":"v1-c9ccc21dfe2a3058|templates-7ccdbd161a3a95dcd17e","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"膝内翻","category":"骨科临床路径（2019年版）","raw":{"name":"膝内翻","category":"骨科临床路径（2019年版）","case":{"case_name":"门诊病历","templates":{"主诉":"【待人工确认·本机素材无此段原文】","现病史":"【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"【临床路径·住院期间检查项目】\n必需的检查项目：\r（1）血常规、血型（ABO 血型+Rh因子）、尿常规；\r（2）肝功能、肾功能、凝血功能检查、感染性疾病筛查（乙型肝炎、丙型肝炎、梅毒、艾滋病）；\r（3）胸部X线平片、心电图；\r（4）手术部位X线检查：患侧膝关节正侧位片及双下肢站立位全长片。\r2.根据患者病情可选择的检查项目：如手术部位CT检查、血气分析、肺功能检查、超声心动图、双下肢血管彩色超声等。\r（七）预防性抗菌药物选择与使用时机\r1.按照《抗菌药物临床患者指导原则》（卫医发〔2015〕43号）执行，并根据患者的病情决定抗菌药物的选择与使用时间。建议使用第一、二代头孢菌素，如头孢唑林、头孢呋辛，对于感染高危患者或者其他药物过敏患者，也可以使用万古霉素进行预防。\r2.术前30分钟预防性用抗菌药物；手术超过3小时加用1次抗菌药物。\r（八）手术日为入院第4～6天\r1.麻醉方式：椎管内麻醉或全身麻醉。\r2.手术方式：胫骨上端楔形截骨内固定或外固定术。\r3.手术内植物：T形钢板或角钢板、U形钢板内固定，或外固定支架固定、螺钉、异体骨、人工骨。\r4.术中用药：麻醉用药、抗菌药、术中止血药物等。\r（1）抗菌药物使用：按照《抗菌药物临床患者指导原则》（卫医发〔2015〕43号）执行，并根据患者的病情决定抗菌药物的选择与使用时间。建议使用第一、二代头孢菌素，如头孢唑林、头孢呋辛，对于感染高危患者或者其他药物过敏患者，也可以使用万古霉素进行预防。\r（2）氨甲环酸可以减少术中术后出血，可以静脉使用也可以局部使用。\r5.输血：视术中具体情况而定。\r（九）术后住院恢复6～10天\r1.必须复查的项目：血常规、手术部位X线检查。\r2.必要时复查的项目：肝肾功能、D-二聚体、下肢深静脉B超等。\r3.术后用药：\r（1）抗菌药物使用：按照《抗菌药物临床患者指导原则》（卫医发〔2015〕43号）执行，并根据患者的病情决定抗菌药物的选择与使用时间。建议使用第一、二代头孢菌素，如头孢唑林、头孢呋辛，过敏者可使用克林霉素；\r（2）术后镇痛：参照《骨科常见疼痛的处理专家建议》（《中华骨科杂志》.2008年1月.28卷.1期）；\r（3）其他药物：消肿、促骨折愈合等。\r4.功能锻炼。\r（十）","初步诊断":"【临床路径·诊断依据】\n诊断依据\r根据《临床诊疗指南\n骨科分册》（中华医学会编著，人民卫生出版社，2009年），《外科学（下册）》（8年制和7年制临床医学专用教材，赵玉沛、陈孝平主编，人民卫生出版社，2015年）。\r1.病史：膝内翻畸形，伴或不伴有关节痛。\r2.体格检查：膝关节活动正常，关节稳定，内翻畸形。\r3.辅助检查：X线检查发现膝内翻畸形，内侧关节间隙无明显狭窄,X线正位片测量胫骨MPTA\n85\n。\r（三）\n1. 膝内翻（ICD-10：M21.104）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【临床路径·治疗方案的选择】\n选择治疗方案的依据\r根据《临床诊疗指南\n骨科分册》（中华医学会编著，人民卫生出版社，2009年），《外科学（下册）》（8年制和7年制临床医学专用教材，赵玉沛、陈孝平主编，人民卫生出版社，2015年）。\r1.膝关节内翻畸形。\r2.膝关节内侧单间室轻度病变。 \r3.膝关节屈曲活动＞90\n。\r4.膝关节屈曲挛缩＜5\n。\r5.年龄一般在60岁以下。\r6.可以选择钢板内固定，也可根据具体情况选择外固定或者其他内固定形式。\r（四）","临床路径·进入路径标准":"进入路径标准\r1.第一诊断必须符合ICD-10：M21.103/Q74.104/E64.302膝内翻畸形疾病编码。\r2.膝内翻畸形、膝关节单间室受累。\r3.除外膝关节及周围感染、严重的膝关节不稳、髌股关节骨关节炎、膝关节严重屈曲畸形。\r4.当患者合并其他疾病，但住院期间不需要特殊处理也不影响第一诊断的临床路径流程实施时，可以进入路径。\r5.X线正位片测量胫骨MPTA\n85\n。\r（六）术前准备（术前评估）3～5天\r1.","临床路径·标准住院日":"标准住院日为\n16天\r（五）","临床路径·出院标准":"出院标准\r1.体温正常，血常规无明显异常。\r2.伤口无感染征象、外固定针道无渗液（或可在门诊处理的伤口情况）。\r3.术后X线片显示截骨矫形角度及固定满意。\r4.无需要住院处理的并发症和（或）合并症。\r（十一）","临床路径·变异及原因分析":"变异及原因分析\r1.并发症：伴有其他部位损伤,如腓总神经损伤、血肿引起体温增高或感染等，导致术前检查和准备时间延长。\r2.合并症：如术前存在一些合并症如骨质疏松、糖尿病、心脑血管疾病等，截骨后合并症可能加重，需同时治疗，导致住院时间延长和住院费用增加。\r3.内植物选择：根据畸形严重程度、截骨类型可选择适当的内植物或外固定器械，可能导致治疗费用的差别。\r\f二、膝内翻胫骨高位截骨","资料来源":"国家卫健委《224个病种临床路径（2019年版）》（国卫办医函〔2019〕933号）· 骨科临床路径（2019年版） · 膝内翻临床路径（2019年版）.doc"},"icd10_diagnosis":"M21.104","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2666,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"42ec779f96a60e5dcb3d86387240b5196d9a0d40313f686964ad1ed54d5ed6a4","pinyin":"xineifan","initials":"xnf","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","临床路径·进入路径标准","临床路径·标准住院日","临床路径·出院标准","临床路径·变异及原因分析","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 临床路径·进入路径标准 临床路径·标准住院日 临床路径·出院标准 临床路径·变异及原因分析 资料来源",30],["主要诊断编码","M21.104",30]]},{"id":"templates-3f0b4f7e542206f92ed4","key":"v1-c9ccc21dfe2a3058|templates-3f0b4f7e542206f92ed4","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"自发性气胸(外科处理与胸腔闭式引流)","category":"胸外科","raw":{"name":"自发性气胸(外科处理与胸腔闭式引流)","category":"胸外科","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】突发患侧胸痛（针刺样或刀割样），随后出现呼吸困难、呼吸困难程度与气胸量及基础肺功能相关，重者不能平卧、发绀、刺激性干咳，少量咯血、患侧胸廓饱满、呼吸动度减弱、叩诊鼓音、呼吸音减弱或消失、张力性气胸：极度呼吸困难、发绀、烦躁、血压下降、气管健侧移位、颈静脉怒张。\n【待人工确认·本机素材无此段原文】","现病史":"自发性气胸是肺组织及脏层胸膜自发破裂，气体进入胸膜腔致肺萎陷。原发性多见于瘦高体型青年男性（肺大疱破裂），继发性多见于慢阻肺、肺结核、肺癌等。张力性气胸可迅速危及生命，需紧急减压。\n常见表现：突发患侧胸痛（针刺样或刀割样），随后出现呼吸困难、呼吸困难程度与气胸量及基础肺功能相关，重者不能平卧、发绀、刺激性干咳，少量咯血、患侧胸廓饱满、呼吸动度减弱、叩诊鼓音、呼吸音减弱或消失、张力性气胸：极度呼吸困难、发绀、烦躁、血压下降、气管健侧移位、颈静脉怒张。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：呼吸频率与形态、血氧、心率、血压（张力性气胸可致休克）\n一般情况：神志、发绀程度、是否可平卧、有无烦躁\n颈部：气管位置（有无向健侧移位）、颈静脉充盈情况（张力性气胸可怒张）\n胸部视诊：患侧胸廓饱满、呼吸动度减弱、肋间隙增宽\n胸部触诊：语颤减弱或消失、皮下气肿（握雪感）\n胸部叩诊与听诊：患侧鼓音、呼吸音减弱或消失\n心脏：心音遥远（大量气胸）、心率增快","辅助检查":"1. 血气分析：评估低氧血症与二氧化碳潴留（继发性气胸常异常）\n2. 血常规+CRP：评估感染与有无血胸\n3. 胸部X线（立位正侧位）：诊断与随访肺复张情况\n4. 胸部CT：明确肺大疱、胸腔积液、纵隔气肿及基础肺病，为手术提供依据\n5. 凝血功能+血型+交叉配血：拟手术者术前准备\n6. 心电图：胸痛鉴别（排除心肌梗死）、张力性气胸致心律失常评估\n7. 肺功能（病情稳定后）：评估基础肺功能与手术耐受","初步诊断":"1. 胸部X线（立位）：首选，可见气胸线、肺压缩、纵隔移位；少量气胸需呼气相摄片\n2. 胸部CT：明确气胸量、肺大疱位置、有无胸腔积液与纵隔气肿（拟手术者必查）\n3. 血气分析：评估缺氧与二氧化碳潴留\n4. 床旁超声：快速判断气胸（肺滑动征消失）、可引导穿刺\n5. 诊断性胸腔穿刺：抽出气体确诊（张力性气胸在紧急减压时进行）\n6. 心电图：排除急性心肌梗死（胸痛鉴别）\n1. 自发性气胸(外科处理与胸腔闭式引流)（ICD-10：J93.0）","鉴别诊断":"1. 心电图：排除急性心肌梗死（胸痛鉴别）\n2. 诊断要点：胸部X线（立位）：首选，可见气胸线、肺压缩、纵隔移位；少量气胸需呼气相摄片\n3. 诊断要点：胸部CT：明确气胸量、肺大疱位置、有无胸腔积液与纵隔气肿（拟手术者必查）\n4. 诊断要点：血气分析：评估缺氧与二氧化碳潴留\n5. 诊断要点：床旁超声：快速判断气胸（肺滑动征消失）、可引导穿刺\n6. 诊断性胸腔穿刺：抽出气体确诊（张力性气胸在紧急减压时进行）\n7. 诊断要点：心电图：排除急性心肌梗死（胸痛鉴别）","处理方案":"【药物治疗·输液】\n⚠️ 按病情选择方案，切勿全部同时使用！\n\n方案1（抗感染，胸膜腔穿刺/引流后）：\n 用法：头孢呋辛 1.5g 静滴 q8h 或 头孢呋辛酯口服序贯\n\n方案2（镇痛）：\n 用法：对乙酰氨基酚 0.5g 静滴/口服 必要时 或 曲马多 100mg 静滴 必要时\n\n方案3（补液支持）：\n 用法：0.9%氯化钠/葡萄糖 静滴；气胸禁剧烈咳嗽者必要时镇咳\n\n📌 张力性气胸急救以穿刺减压为第一要务，用药为辅助。\n\n【药物治疗·口服】\n⚠️ 按病情选择药物，同类只选一种：\n\n药物1（镇咳）：\n 用法：复方甲氧那明 2粒 tid 或 可待因 15mg 必要时（剧烈干咳影响肺复张时）\n\n药物2（通便，防用力）：\n 用法：乳果糖 15ml bid（避免用力排便致复发）\n\n药物3（镇痛）：\n 用法：布洛芬 0.3g bid 或 塞来昔布 200mg qd\n\n📌 避免使用抑制呼吸的强效镇静药；继发性气胸需同时治疗基础肺病。\n\n【治疗】\n少量气胸（肺压缩<20%）且无症状：卧床休息、吸氧、观察，复查胸片\n胸腔穿刺抽气：肺压缩20%～50%者，锁骨中线第2肋间穿刺抽气\n胸腔闭式引流：肺压缩>50%、张力性气胸、呼吸困难明显或抽气后复发者（锁骨中线第2肋间或腋中线第4～5肋间置管）\n张力性气胸急救：立即于患侧锁骨中线第2肋间粗针穿刺减压，随后置管引流\n手术治疗：反复发作（≥2次）、持续漏气>3～5天、双侧气胸、血气胸、肺大疱明显者行胸腔镜下肺大疱切除+胸膜固定\n基础病治疗：慢阻肺、肺结核、肺癌等的规范治疗；戒烟\n\n【处理要点】\n卧床休息，取半卧位，给予吸氧（2～4L/min）\n监测呼吸、血氧、心率与血压，观察呼吸困难与发绀变化\n胸腔闭式引流护理：观察水封瓶气泡（漏气）、引流量与性状，防止管路脱出与逆流\n避免剧烈咳嗽、用力排便、屏气与剧烈活动（防止复发）\n复查胸片：置管后及拔管前确认肺复张，拔管后24小时复查\n复发预防宣教：戒烟、避免剧烈运动与乘坐飞机（未愈合前）、及时治疗呼吸道感染\n\n【护理】\n急性期护理：绝对卧床、半卧位，吸氧，密切监测呼吸与血氧，发现呼吸困难加重立即报告\n闭式引流护理：水封瓶低于胸壁引流口60～100cm，保持密闭与通畅，观察气泡与引流量，搬动时夹闭管路\n疼痛护理：评估疼痛程度，遵医嘱镇痛，指导深呼吸与有效咳嗽（促进肺复张）\n活动指导：避免剧烈咳嗽、屏气、用力排便及剧烈运动，戒烟\n复发观察：出院后如再次突发胸痛、呼吸困难，立即就诊\n\n【饮食】\n高蛋白、高维生素、易消化饮食，促进胸膜愈合\n多饮水，多食蔬菜水果，保持大便通畅（避免用力排便）\n避免产气食物（豆类、碳酸饮料）以免腹胀影响呼吸\n戒烟酒，避免辛辣刺激食物\n继发性气胸者按基础病饮食管理（如限盐、控糖）\n\n【注意事项】\n张力性气胸是急症，必须立即穿刺减压，不能等待影像学检查\n瘦高体型青年男性反复气胸应警惕肺大疱，建议胸腔镜手术根治\n继发性气胸（慢阻肺、肺结核等）病情更重，病死率高，需积极处理基础病\n拔管后仍有气胸复发可能，需随访胸片\n\n【急诊/急救】\n极度呼吸困难、发绀、烦躁、血压下降、气管移位（张力性气胸）→ 立即穿刺减压+闭式引流\n胸痛伴咯血、血红蛋白下降（血气胸）→ 急诊评估，必要时手术\n双侧气胸或呼吸衰竭 → 立即转ICU并双侧减压","资料来源":"疾病库 diseases.json；鉴别诊断库 ddx_local.json（条目「自发性气胸（外科处理与胸腔闭式引流）」原文）"},"icd10_diagnosis":"J93.0","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2667,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"dd3aecde28c9d2add03007a642dae2e448bb3b72954b7449ec7239bb98308538","pinyin":"zifaxingqixiong(waikechuliyuxiongqiangbishiyinliu)","initials":"zfxqx(wkclyxqbsyl)","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","J93.0",30]]},{"id":"templates-491f6fb61d1729abc36b","key":"v1-c9ccc21dfe2a3058|templates-491f6fb61d1729abc36b","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"自然临产阴道分娩","category":"妇产科临床路径（2019年版）","raw":{"name":"自然临产阴道分娩","category":"妇产科临床路径（2019年版）","case":{"case_name":"门诊病历","templates":{"主诉":"【待人工确认·本机素材无此段原文】","现病史":"【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"检查计划：患者为孕龄37周以上孕妇，已出现规律性子宫收缩、宫颈扩张伴胎头下降，临床检查除外臀位和横位，诊断为自然临产阴道分娩，拟经阴道分娩，入院即刻完善血常规检查了解有无贫血、感染及血小板水平，评估产程中出血风险；完善尿常规检查排除泌尿系感染及妊娠期高血压疾病所致蛋白尿；完善凝血功能检查排除凝血功能障碍，评估产后出血及椎管内分娩镇痛的出血风险；完善血型鉴定（含Rh血型）检查为产时产后输血及新生儿溶血病防治做好准备；孕期未做者完善感染性疾病筛查（乙型肝炎、丙型肝炎、艾滋病、梅毒等）检查明确有无母婴传播风险，指导阻断方案；根据产妇病情选择完善肝肾功能、电解质检查排除肝肾功能不全及电解质紊乱，为宫缩诱导药物及分娩镇痛用药安全提供依据；完善心电图检查了解心脏情况，评估分娩耐受能力；必要时完善超声检查明确胎位、胎儿大小、羊水及胎盘情况；产后住院恢复1～3天期间定期复查血常规、尿常规检查了解有无产后出血、贫血及产褥感染。\n\n（检查清单）\n【临床路径·住院期间检查项目】\n必需的检查项目：\r（1）血常规、尿常规、凝血功能。\r（2）血型、感染性疾病筛查（乙型肝炎、丙型肝炎、艾滋病、梅毒等）（孕期未做者）。 \r2.根据患者病情可选择项目：肝肾功能、电解质，心电图、超声等。\r（七）产程干预及药物选择\r1.人工破膜、宫缩诱导药物：用于宫缩乏力时造成的产程延长。\r2.镇静药：根据产妇状态酌情。\r3.分娩镇痛：酌情。\r（八）产后住院恢复1～3天\r1.复查的检查项目：血常规、尿常规。\r2.产后用药：酌情使用促进子宫复旧药物。\r（九）","初步诊断":"【临床路径·诊断依据】\n诊断依据\r根据《妇产科学（第9版）》（谢幸、孔北华、段涛主编，人民卫生出版社，2018年）\r1.孕龄\n37周。\r2.规律性子宫收缩、宫颈扩张伴胎头下降。\r3.临床检查除外臀位和横位。\r（三）分娩方式的选择\r阴道分娩（包括阴道手术助产）。\r（四）\n1. 自然临产阴道分娩（ICD-10：O80.0）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【待人工确认·本机素材无此段原文】","临床路径·进入路径标准":"进入路径标准\r1.第一诊断必须符合ICD-10：O80.0伴Z37孕足月头位自然临产编码。\r2.无阴道分娩禁忌证。\r3.当患者同时具有其他疾病诊断，但在住院期间不需特殊处理也不影响第一诊断的临床路径流程实施时，可以进入路径。\r（六）入院后第1天\r1.","临床路径·标准住院日":"标准住院日2～4天\r（五）","临床路径·出院标准":"出院标准\r1.产后恢复良好。\r2.会阴伤口愈合良好。\r（十）","临床路径·变异及原因分析":"变异及原因分析\r1.产程中若出现剖宫产指征（如胎儿窘迫、头位难产等），转入剖宫产临床路径，退出本路径。\r2.阴道手术助产者，可适当延长住院时间。\r3.产后出现感染、出血等并发症，导致住院时间延长。\f 二、自然临产阴道分娩","资料来源":"国家卫健委《224个病种临床路径（2019年版）》（国卫办医函〔2019〕933号）· 妇产科临床路径（2019年版） · 自然临产阴道分娩临床路径（2019年版）.doc"},"icd10_diagnosis":"O80.0","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2668,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"997acfb7741e79927f1e2878ede76d412280460333c6a0d1821d4889571a91e2","pinyin":"ziranlinchanyindaofenmian","initials":"zrlcydfm","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","临床路径·进入路径标准","临床路径·标准住院日","临床路径·出院标准","临床路径·变异及原因分析","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 临床路径·进入路径标准 临床路径·标准住院日 临床路径·出院标准 临床路径·变异及原因分析 资料来源",30],["主要诊断编码","O80.0",30]]},{"id":"templates-dd67b5ee13e0b07c56b3","key":"v1-c9ccc21dfe2a3058|templates-dd67b5ee13e0b07c56b3","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"舌癌","category":"肿瘤科","raw":{"name":"舌癌","category":"肿瘤科","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文·卫健委临床路径原文】舌部溃疡经久不愈（>2周）、舌部肿块、疼痛、舌运动受限、言语不清、吞咽困难、涎液增多、口臭、颈部淋巴结肿大。\n【待人工确认·本机素材无此段原文】","现病史":"舌部恶性肿瘤，以鳞状细胞癌最常见，好发于舌中1/3侧缘，与吸烟、饮酒、口腔卫生不良及不良刺激有关\n常见表现：舌部溃疡经久不愈（>2周）、舌部肿块、疼痛、舌运动受限、言语不清、吞咽困难、涎液增多、口臭、颈部淋巴结肿大。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"口腔检查：舌部肿物位置、大小、质地、边界、有无溃疡出血\n舌运动：伸舌有无偏斜、受限\n颈部：颈淋巴结检查（分区、大小、质地、活动度）\n口腔卫生：有无龋齿、残根、不良修复体等刺激因素","辅助检查":"1. 口腔视诊+触诊：初诊必做\n2. 病理活检：确诊金标准\n3. 颈部增强CT/MRI：评估原发灶深度及淋巴结转移\n4. 胸部CT：排除肺转移\n5. 血常规、肝肾功能、心电图：术前/化疗前评估","初步诊断":"1. 舌部溃疡或肿物，边缘隆起、质硬、触之易出血\n2. 病理活检确诊\n3. 颈部增强CT/MRI评估原发灶范围及淋巴结转移\n4. 胸部CT排除肺转移\n【临床路径·诊断依据】\n诊断依据\r根据《临床诊疗指南\n口腔医学分册（2016修订版）》（中华口腔医学会编著，人民卫生出版社，2016）。\r1.病史：局部常有慢性刺激因素（如锐利牙尖或残根）；也可有白斑等癌前病损；或无明显诱发因素，病变发展较快。\r2.体征：舌体局部溃疡或浸润块，也可外突呈菜花状，常有明显自发痛或触痛。\r3.实验室检查：活组织检查病理明确为癌瘤。\r（三）\n1. 舌癌（ICD-10：C02.9）","鉴别诊断":"1. 胸部CT排除肺转移\n2.与舌部良性溃疡、白斑、乳头状瘤、舌下腺肿瘤鉴别\n3. 诊断要点：舌部溃疡或肿物，边缘隆起、质硬、触之易出血\n4. 诊断要点：病理活检确诊\n5. 诊断要点：颈部增强CT/MRI评估原发灶范围及淋巴结转移\n6. 诊断要点：胸部CT排除肺转移\n7. 舌部溃疡超过2周不愈、质硬无痛应尽早活检\n8. 舌癌（尤其前2/3）易早期转移至颈部淋巴结，须行颈部评估","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：以下为化疗参考方案，请根据患者分期、体质及MDT意见选择，切勿全部同时使用！\n\n方案1（TPF诱导化疗，参考）：\n 用法：NS250ml+多西他赛75mg/m² ivgtt d1（预处理后）\n 用法：NS500ml+顺铂75mg/m² ivgtt d1（充分水化利尿）\n 用法：5-FU 750mg/m²/d 持续泵入 d1-5（120h），q3w\n\n方案2（同步放化疗单药，参考）：\n 用法：NS500ml+顺铂100mg/m² ivgtt d1，q3w（与放疗同步）\n\n📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史；化疗前查血常规、肝肾功能及心电图。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！\n\n药物1：\n 用法：康复新液10ml tid（促进创面修复）\n\n药物2：\n 用法：复方氯己定含漱液10ml 含漱 tid（保持口腔清洁）\n\n药物3：\n 用法：布洛芬缓释胶囊0.3g bid（疼痛时）\n\n📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。\n\n【治疗】\n早期：手术扩大切除+颈清扫（首选）\n术后放疗（存在高危因素者）\n局部晚期：诱导化疗+手术+放化疗综合治疗\n晚期：化疗、靶向（西妥昔单抗）、免疫治疗\n多学科（MDT）制定个体化方案\n\n【处理要点】\n戒烟戒酒，保持口腔卫生\n术后规律随访复查\n语言及吞咽康复训练\n营养支持，防体重下降\n\n【护理】\n口腔护理：每日含漱液漱口2-3次，保持口腔清洁，预防感染\n术后护理：观察皮瓣颜色、温度、血运，负压引流管护理，观察渗血\n营养护理：鼻饲或胃造瘘营养支持，监测体重及营养状况\n语言康复：术后循序渐进发声训练，鼓励交流\n心理护理：关注形象及语言改变的心理负担，加强疏导\n\n【饮食】\n高蛋白高热量流质：牛奶、蛋羹、鱼汤、匀浆膳\n半流质过渡：粥、烂面条、肉泥\n忌辛辣、过烫、过硬及粗糙食物，避免刺激创面\n少量多餐，进食宜慢防呛咳\n多饮水，保持口腔湿润\n\n【注意事项】\n舌部溃疡超过2周不愈、质硬无痛应尽早活检与舌部良性溃疡、白斑、乳头状瘤、舌下腺肿瘤鉴别\n舌癌（尤其前2/3）易早期转移至颈部淋巴结，须行颈部评估\n\n【急诊/急救】\n肿瘤侵蚀血管致大出血：局部压迫止血，急诊处理\n术后创面出血或皮瓣血运障碍：立即通知医生\n呼吸困难（肿物压迫）：保持气道通畅，急诊就医\n\n【临床路径·治疗方案的选择】\n治疗方案的选择\r根据《临床技术操作规范\n口腔医学分册（2017修订版）》（中华口腔医学会编著，人民卫生出版社,2017）。\r选择舌癌扩大切除术或舌癌扩大切除术+颈淋巴清扫术，其适应证为：\r1.在肿瘤边界外1.5～2cm正常组织内扩大切除肿瘤。\r2.根据不同情况，颈部淋巴结可予以观察，或行选择性或治疗性颈淋巴结清扫术。\r3.病理明确颈部淋巴结转移的患者，建议行术后放疗。\r（四）","临床路径·进入路径标准":"进入路径标准\r1.第一诊断符合ICD-10：C02M8070/3舌癌疾病编码。\r2.患者同时具有其他疾病诊断，如在住院期间不需要特殊处理也不影响第一诊断的临床路径流程实施时，可以进入路径。\r3.TNM分类：原发灶T1或T2，淋巴结N0或N1，远处转移M0。\r（六）术前准备（术前评估）1～3天\r1.术前必须检查的项目\r（1）血常规、尿常规、大便常规、血型。\r（2）凝血功能。\r（3）血生化。\r（4）感染性疾病筛查（乙型肝炎、丙型肝炎、艾滋病、梅毒等）。 \r（5）X线胸片、心电图。\r2.根据病情可选择\r（1）超声心动图和肺功能检查（老年人或既往有相关病史者）。\r（2）必要时行曲面断层、CT、MRI检查。\r（七）预防性抗菌药物选择与使用时机\r1.按照《抗菌药物临床患者指导原则》（卫医发〔2015〕43号）执行。\r2.青霉素类或其他类抗菌药物，预防性用药时间为术前0.5～1小时静脉输注。\r（八）手术日为入院第3～4天\r1.麻醉方式：全身麻醉或局部麻醉。\r2.术中用药：麻醉常规用药、术后镇痛泵的患者。\r3.输血：视术中情况而定。\r4.术后标本冰冻加石蜡切片送病理。\r（九）术后住院恢复7～10天\r1.术后根据当时患者情况复查相关检查项目。\r2.术后使用青霉素类或其他类抗菌药物，用药时间3～5天。\r（十）","临床路径·标准住院日":"标准住院日\n14天\r（五）","临床路径·出院标准":"出院标准\r1.患者一般情况良好，伤口愈合好，引流管拔除，伤口无感染，无皮下积液（或门诊可处理的少量积液），无组织坏死。\r2.无需要住院处理的并发症和（或）合并症。\r（十一）","临床路径·变异及原因分析":"变异及原因分析\r1.有影响手术的全身疾病或合并症，需要进行相关的诊断和治疗。\r2.必要时需要进行CT、MRI等检查以明确肿瘤范围。\r3.越过中线的舌癌，根据情况可以行双侧颈淋巴结清扫术。\r4.侵及口底接近下颌骨的舌癌，扩大切除肿瘤时可能需要切除部分下颌骨。\r5.舌体局部切除后需要皮瓣修复者不进入该路径。\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\f二、舌癌","资料来源":"疾病库 diseases.json；鉴别诊断库 ddx_local.json（条目「舌癌」原文）；国家卫健委《224个病种临床路径（2019年版）》（国卫办医函〔2019〕933号）· 口腔医学临床路径（2019年版） · 舌癌临床路径（2019年版）.doc"},"icd10_diagnosis":"C02.9","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2669,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"5ec771eadc082d71424b27a7305012980a3d71c371e306b257219c5beed41032","pinyin":"sheai","initials":"sa","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","临床路径·进入路径标准","临床路径·标准住院日","临床路径·出院标准","临床路径·变异及原因分析","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 临床路径·进入路径标准 临床路径·标准住院日 临床路径·出院标准 临床路径·变异及原因分析 资料来源",30],["主要诊断编码","C02.9",30]]},{"id":"templates-72b5884c72250339121d","key":"v1-c9ccc21dfe2a3058|templates-72b5884c72250339121d","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"舒乐安定中毒(艾司唑仑)","category":"中毒/理化","raw":{"name":"舒乐安定中毒(艾司唑仑)","category":"中毒/理化","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】轻度：嗜睡、头晕、乏力、言语含糊、共济失调、反应迟钝、中度：昏睡、意识模糊、眼球震颤、血压正常或轻度下降、重度：昏迷、瞳孔缩小、呼吸浅慢、血压下降、脉搏细速、严重者：呼吸抑制、发绀、休克、深昏迷、反射消失、口服早期可有恶心、呕吐、合并酒精/巴比妥类/阿片类时呼吸抑制加重、长期服用者突然停药可出现戒断症状（焦虑、震颤、抽搐、失眠）、舒乐安定作用比安定强，比阿普唑仑弱。\n【待人工确认·本机素材无此段原文】","现病史":"艾司唑仑（商品名舒乐安定）是苯二氮卓类镇静催眠抗焦虑药，作用强度介于安定和阿普唑仑之间。过量表现为嗜睡、共济失调、昏迷、呼吸抑制。氟马西尼是特效解毒剂。\n常见表现：轻度：嗜睡、头晕、乏力、言语含糊、共济失调、反应迟钝、中度：昏睡、意识模糊、眼球震颤、血压正常或轻度下降、重度：昏迷、瞳孔缩小、呼吸浅慢、血压下降、脉搏细速、严重者：呼吸抑制、发绀、休克、深昏迷、反射消失、口服早期可有恶心、呕吐、合并酒精/巴比妥类/阿片类时呼吸抑制加重、长期服用者突然停药可出现戒断症状（焦虑、震颤、抽搐、失眠）、舒乐安定作用比安定强，比阿普唑仑弱。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：体温（高热/低体温）、脉搏（过速/过缓/心律失常）、呼吸（频率/节律/气味）、血压（升高/降低/休克）、血氧饱和度\n一般情况：神志（清醒/嗜睡/昏睡/昏迷/谵妄/抽搐）、精神状态、面容、体位\n皮肤黏膜：颜色（潮红-阿托品/酒精/一氧化碳樱桃红/发绀-亚硝酸盐/肠源性青紫/苍白-休克/出血）、湿度（多汗-有机磷/吗啡/干燥-阿托品/抗组胺）、皮疹/水疱/灼伤（腐蚀性毒物）、黄疸（毒蕈/对乙酰氨基酚/鱼胆）、发绀、出血点\n呼出气/呕吐物气味：蒜臭味（有机磷）、苦杏仁味（氰化物）、酒味（酒精）、酚味（苯酚）、臭鸡蛋味（硫化氢）、梨味（水合氯醛）\n头颈部：瞳孔（缩小-有机磷/吗啡/针尖样-阿片类/扩大-阿托品/抗组胺/氰化物、对光反射）、眼球震颤、口腔黏膜灼伤/溃疡、流涎（有机磷）、口干（阿托品）\n胸部：呼吸节律（抑制-镇静催眠药/吗啡/兴奋-咖啡因/回苏灵）、肺水肿（有机磷/刺激性气体）、双肺啰音/哮鸣音、心率心律/心音/杂音\n腹部：压痛/反跳痛、肝脾肿大、肠鸣音（亢进-有机磷/减弱-阿托品/抗胆碱）、呕吐物性状\n神经系统：意识状态、抽搐（有机磷/毒鼠强/氰化物/异烟肼）、肌力肌张力、病理征、脑膜刺激征、震颤（有机磷/酒精戒断）\n四肢：肌束颤动（有机磷）、瘫痪（肉毒/河豚/蛇毒）、水肿\n其他：呕吐物/洗胃液/尿液性状、现场毒物残留","辅助检查":"1. 毒物检测：血、尿苯二氮䓬类定性/定量筛查（艾司唑仑及其代谢物），明确诊断并评估中毒程度\n2. 动脉血气分析：评估呼吸抑制、低氧血症及呼吸性酸中毒（昏迷患者入院立即查，动态复查）\n3. 快速血糖测定：鉴别低血糖性意识障碍，昏迷患者即刻床边测定\n4. 心电图：排除混合服药（尤其三环类抗抑郁药、其他镇静药）所致心律失常，观察心率、QT间期及传导\n5. 血电解质、肝肾功能：评估内环境紊乱及药物代谢功能，指导补液与病情评估\n6. 头颅CT：深昏迷或予氟马西尼后意识无改善者，排除颅内出血、卒中等其他意识障碍病因","初步诊断":"1. 舒乐安定（艾司唑仑）服用史\n2. 中枢神经系统抑制表现，呼吸抑制\n3. 瞳孔缩小\n4. 血/尿中可检出艾司唑仑\n5. 氟马西尼试验阳性\n6. 排除其他原因昏迷\n7. 血糖、电解质、肝肾功能、血气分析\n1. 舒乐安定中毒(艾司唑仑)（ICD-10：T42.4）","鉴别诊断":"1. 排除其他原因昏迷\n2. 诊断要点：舒乐安定（艾司唑仑）服用史\n3. 诊断要点：中枢神经系统抑制表现，呼吸抑制\n4. 诊断要点：血/尿中可检出艾司唑仑\n5. 诊断要点：氟马西尼试验阳性\n6. 诊断要点：排除其他原因昏迷\n7. 诊断要点：血糖、电解质、肝肾功能、血气分析","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！\n\n方案1：\n 用法：氟马西尼 首剂0.2mg静注，如未清醒可每分钟0.1mg重复，总量不超过2mg（特效）\n\n方案2（氟马西尼维持）：\n 用法：0.1-0.4mg/h静脉泵入（防止反跳）\n\n方案3：\n 用法：纳洛酮 0.4-0.8mg静注，必要时重复（促醒）\n\n方案4：\n 用法：5%葡萄糖+维生素C 静滴（促进代谢）\n\n方案5：\n 用法：呋塞米 20-40mg静注（促进排泄）\n\n方案6：\n 用法：20%甘露醇 125ml静滴（脑水肿时）\n\n方案7：\n 用法：呼吸兴奋剂（呼吸抑制时）\n\n方案8：\n 用法：升压药（低血压时）\n\n方案9：\n 用法：碳酸氢钠（酸中毒时）\n\n📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！\n\n药物1：\n 用法：维生素C片（恢复期）\n\n📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。\n\n【治疗】\n口服者立即催吐、洗胃（清水/1:5000高锰酸钾），洗胃后活性炭吸附，导泻\n保持呼吸道通畅，吸氧，必要时气管插管机械通气\n氟马西尼特效解毒（严重中枢抑制和呼吸抑制者）\n纳洛酮促醒（辅助）\n静脉补液、利尿，促进药物排泄\n对症支持：维持血压、纠正酸中毒、保护肝肾功能\n严重中毒可行血液灌流\n长期服用者注意戒断症状，逐渐减量\n密切监测生命体征、意识状态、血氧饱和度\n\n【处理要点】\n口服者立即催吐，尽快送医洗胃\n平卧，头偏向一侧，防止误吸\n保持呼吸道通畅，及时清除口鼻分泌物\n嗜睡者可刺激人中、合谷促醒\n不要给患者灌水/喂食（防止误吸）\n记录服药剂量、时间、品种\n监测呼吸、血压、心率、意识状态\n呼吸抑制者立即人工呼吸，尽快送医\n长期服用者不要突然停药\n\n【护理】\n气道管理：意识障碍者取侧卧位、头偏向一侧，及时清除口咽分泌物，保持SpO₂≥95%，呼吸衰竭者配合气管插管及机械通气\n解毒剂观察：遵医嘱静注氟马西尼（首剂0.2-0.3mg，必要时重复），观察意识转清情况；氟马西尼半衰期短，警惕再镇静及呼吸抑制复发，同时观察有无烦躁、抽搐等矛盾反应\n洗胃配合：口服中毒6小时内遵医嘱洗胃，洗胃前先建立气道保护（昏迷者先行气管插管），洗胃中防误吸、防体位性低血压，洗胃后禁食4-6小时\n生命体征监测：持续心电监护，每30-60分钟评估意识（GCS评分）、呼吸频率与节律、血压、SpO₂，每2-4小时观察瞳孔大小及对光反射\n并发症预防：每2小时翻身拍背预防坠积性肺炎及压疮，注意观察腹胀、尿潴留，留置导尿者做好会阴护理\n\n【饮食】\n洗胃后禁食4-6小时，禁食期间经静脉补液维持水电解质平衡\n禁食解除后从温凉流质（米汤、藕粉、稀粥）开始，少量多餐，无恶心呕吐后渐过渡至半流质、软食\n忌饮酒及含酒精饮品（酒精与艾司唑仑有协同中枢抑制作用，可加重呼吸抑制），忌咖啡、浓茶等刺激性饮料\n恢复期进食高维生素、易消化食物，适量补充优质蛋白（蛋羹、鱼泥、瘦肉汤）促进康复\n治疗期间避免同服其他镇静催眠药及含镇静成分的感冒药、止咳药，饮食用药调整遵医嘱执行\n\n【注意事项】\n舒乐安定（艾司唑仑）作用强度是安定的2-4倍\n氟马西尼是特效解毒剂，半衰期短，需重复给药或维持\n氟马西尼禁用于长期服用苯二氮卓类者、合并三环类抗抑郁药过量者、颅内高压者\n合并酒精、巴比妥类、阿片类时风险显著增加\n活性炭吸附效果好，应尽早使用\n严重中毒者可行血液灌流\n长期服用可成瘾，突然停药可出现严重戒断症状\n恢复期注意心理疏导，防止再次服药\n\n【急诊/急救】\n口服者立即催吐，尽快清水洗胃\n保持呼吸道通畅，吸氧\n氟马西尼0.2mg静注，必要时重复（总量不超过2mg）\n纳洛酮0.4-0.8mg静注\n呼吸抑制者人工呼吸，必要时气管插管\n静脉补液利尿促进排泄","资料来源":"疾病库 diseases.json；鉴别诊断库 ddx_local.json（条目「舒乐安定中毒(艾司唑仑)」原文）"},"icd10_diagnosis":"T42.4","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2670,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"2e35bf50faf3da1d11d1744f807d44538f159e3680d7a759aed70b93f3ef89e0","pinyin":"shuleandingzhongdu(aisizuolun)","initials":"sladzd(aszl)","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","T42.4",30]]},{"id":"templates-367c38c326ed9e0e8167","key":"v1-c9ccc21dfe2a3058|templates-367c38c326ed9e0e8167","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"良性前列腺增生经尿道前列腺电切术","category":"泌尿外科临床路径（2019年版）","raw":{"name":"良性前列腺增生经尿道前列腺电切术","category":"泌尿外科临床路径（2019年版）","case":{"case_name":"门诊病历","templates":{"主诉":"【待人工确认·本机素材无此段原文】","现病史":"【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"【临床路径·住院期间检查项目】\n必需的检查项目：\n1.血常规、尿常规；\n2.电解质、肝肾功能、血型、凝血功能；\n3.感染性疾病筛查（乙型肝炎、丙型肝炎、艾滋病、梅毒等）；\n4.X线胸片、心电图。\n（七）预防性抗菌药物选择与使用时机\n按照《抗菌药物临床患者指导原则》（国卫办医发〔2015〕43号）执行，并结合患者的病情决定抗菌药物的选择与使用时间。\n（八）手术日为入院第\n3天\n1.麻醉方式：脊椎麻醉、硬膜外麻醉或全身麻醉。\n2.手术方式：经尿道前列腺电切术（TURP）。\n3.术中用药：麻醉用药，必要时用抗菌药物。\n4.输血：必要时。\n（九）术后住院恢复\n7天\n1.必须复查的检查项目：血常规、尿常规；根据患者病情变化可选择相应的检查项目。\n2.术后抗菌药物患者：按照《抗菌药物临床患者指导原则》（国卫办医发〔2015〕43号）执行。\n（十）","初步诊断":"【临床路径·诊断依据】\n诊断依据\n根据《中国泌尿外科疾病诊断治疗指南》（中华医学会泌尿外科学分会编著，人民卫生出版社，2014年）。\n1.病史：IPSS、QOL评分。\n2.体格检查。\n3.实验室检查及影像学检查。\n（三）\n1. 良性前列腺增生经尿道前列腺电切术（ICD-10：N40）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【临床路径·治疗方案的选择】\n选择治疗方案的依据\n根据《中国泌尿外科疾病诊断治疗指南》（中华医学会泌尿外科学分会编著，人民卫生出版社，2014年）。\n1.适合经尿道前列腺电切术（TURP）。\n2.能够耐受手术。\n（四）","临床路径·进入路径标准":"进入路径标准\n1.第一诊断必须符合ICD-10：N40良性前列腺增生疾病编码。\n2.当患者同时具有其他疾病诊断，但在住院期间不需要特殊处理也不影响第一诊断的临床路径流程实施时，可以进入路径。\n（六）术前准备（术前评估）\n3天","临床路径·标准住院日":"标准住院日为\n10天\n（五）","临床路径·出院标准":"出院标准\n1.一般情况良好。\n2.拔除尿管后，排尿通畅。\n3.耻骨上造瘘口无漏尿（如适用）。\n（十一）","临床路径·变异及原因分析":"变异及原因分析\n1.术中、术后出现并发症，需要进一步诊治，导致住院时间延长、费用增加。\n2.术后出现排尿功能异常，需要进一步诊治，导致住院时间延长、费用增加。\n3.术后原伴随疾病控制不佳，需请相关科室会诊，进一步诊治。\n4.住院后出现其他内、外科疾病需进一步明确诊断，可进入其他路径。","资料来源":"国家卫健委《224个病种临床路径（2019年版）》（国卫办医函〔2019〕933号）· 泌尿外科临床路径（2019年版） · 良性前列腺增生经尿道前列腺电切术临床路径（2019年版）.docx"},"icd10_diagnosis":"N40","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2671,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"dfff2fc8c556d96d08d2235c9add719d11281c3d21c68d0e355c9a240c7b39ca","pinyin":"liangxingqianliexianzengshengjingniaodaoqianliexiandianqieshu","initials":"lxqlxzsjndqlxdqs","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","临床路径·进入路径标准","临床路径·标准住院日","临床路径·出院标准","临床路径·变异及原因分析","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 临床路径·进入路径标准 临床路径·标准住院日 临床路径·出院标准 临床路径·变异及原因分析 资料来源",30],["主要诊断编码","N40",30]]},{"id":"templates-c2900f2489367750f6a9","key":"v1-c9ccc21dfe2a3058|templates-c2900f2489367750f6a9","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"良性前列腺增生经尿道前列腺等离子电切术","category":"泌尿外科临床路径（2019年版）","raw":{"name":"良性前列腺增生经尿道前列腺等离子电切术","category":"泌尿外科临床路径（2019年版）","case":{"case_name":"门诊病历","templates":{"主诉":"【待人工确认·本机素材无此段原文】","现病史":"【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"【临床路径·住院期间检查项目】\n必需的检查项目：\n1.血常规、尿常规；\n2.电解质、肝肾功能、血型、凝血功能；\n3.感染性疾病筛查（乙型肝炎、丙型肝炎、艾滋病、梅毒等）；\n4.X线胸片、心电图。\n（七）预防性抗菌药物选择与使用时机\n按照《抗菌药物临床患者指导原则》（国卫办医发〔2015〕43号）执行，并结合患者的病情决定抗菌药物的选择与使用时间。\n（八）手术日为入院第\n3天\n1.麻醉方式：脊椎麻醉、硬膜外麻醉或全身麻醉。\n2.手术方式：经尿道前列腺等离子电切术（TUPKP）。\n3.术中用药：麻醉用药，必要时用抗菌药物。\n4.输血：必要时。\n（九）术后住院恢复\n5天\n1.必须复查的检查项目：血常规、尿常规；根据患者病情变化可选择相应的检查项目。\n2.术后抗菌药物患者：按照《抗菌药物临床患者指导原则》（国卫办医发〔2015〕43号）执行。\n（十）","初步诊断":"【临床路径·诊断依据】\n诊断依据\n根据《中国泌尿外科疾病诊断治疗指南》（中华医学会泌尿外科学分会编著，人民卫生出版社，2014年）。\n1.病史：IPSS、QOL评分。\n2.体格检查。\n3.实验室检查及影像学检查。\n（三）\n1. 良性前列腺增生经尿道前列腺等离子电切术（ICD-10：N40）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【临床路径·治疗方案的选择】\n选择治疗方案的依据\n根据《中国泌尿外科疾病诊断治疗指南》（中华医学会泌尿外科学分会编著，人民卫生出版社，2014年）。\n1.适合经尿道前列腺等离子电切术（TUPKP）。\n（1）具有中-重度下尿路症状（LUTS）并已明显影响生活质量的BPH患者可选择TUPKP，尤其是药物治疗效果不佳或拒绝接受药物治疗的患者。\n（2）出现下列并发症的BPH患者：\n反复尿潴留（至少在一次拔尿管后不能排尿或两次尿潴留）；\n反复血尿，药物治疗无效；\n反复泌尿系感染；\n膀胱结石；\n继发性上尿路积水（伴或不伴肾功能损害）。\n（3）BPH患者合并腹股沟疝、严重的痔疮或脱肛，临床判断不解除下尿路梗阻难以达到治疗效果者。伴有反复性尿路感染或渐进的膀胱功能障碍的膀胱憩室患者。\n（4）残余尿明显增多以致充溢性尿失禁的BPH患者应当考虑手术或微创治疗。\n2.能够耐受手术。\n（四）","临床路径·进入路径标准":"进入路径标准\n1.门诊完成前列腺超声，膀胱残余尿，尿流率，尿流动力学检查（如适用），IPSS分，QOL评分及前列腺特异性抗原（PSA）检查。完成术前适应证和禁忌证评估。\n2.第一诊断必须符合ICD-10：N40良性前列腺增生疾病编码。\n3.当患者同时具有其他疾病诊断，但在住院期间不需要特殊处理也不影响第一诊断的临床路径流程实施时，可以进入路径。\n（六）术前准备（术前评估）\n2天","临床路径·标准住院日":"标准住院日为\n8天\n（五）","临床路径·出院标准":"出院标准\n1.一般情况良好。\n2.拔除尿管后，排尿通畅。\n3.耻骨上造瘘口无漏尿（如适用）。\n（十一）","临床路径·变异及原因分析":"变异及原因分析\n1.术中、术后出现并发症，需要进一步诊治，导致住院时间延长、费用增加。\n2.术后出现排尿功能异常，需要进一步诊治，导致住院时间延长、费用增加。\n3.术后原伴随疾病控制不佳，需请相关科室会诊，进一步诊治。\n4.住院后出现其他内、外科疾病需进一步明确诊断，可进入其他路径。","资料来源":"国家卫健委《224个病种临床路径（2019年版）》（国卫办医函〔2019〕933号）· 泌尿外科临床路径（2019年版） · 良性前列腺增生经尿道前列腺等离子电切术临床路径（2019年版）.docx"},"icd10_diagnosis":"N40","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2672,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"0425d929fdb0a9a0e7f5757cf72984cceee8e8f580545faf1aa003f7d2c12160","pinyin":"liangxingqianliexianzengshengjingniaodaoqianliexiandenglizidianqieshu","initials":"lxqlxzsjndqlxdlzdqs","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","临床路径·进入路径标准","临床路径·标准住院日","临床路径·出院标准","临床路径·变异及原因分析","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 临床路径·进入路径标准 临床路径·标准住院日 临床路径·出院标准 临床路径·变异及原因分析 资料来源",30],["主要诊断编码","N40",30]]},{"id":"templates-751f5509498f703da414","key":"v1-c9ccc21dfe2a3058|templates-751f5509498f703da414","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"虚劳(中医辨证)","category":"中医","raw":{"name":"虚劳(中医辨证)","category":"中医","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】气虚（肺脾气虚）：短气自汗，声音低怯，时寒时热，平素易于感冒，面白，食少便溏，倦怠乏力，舌淡苔白，脉弱、血虚（心血虚/肝血虚）：心悸怔忡，健忘，失眠多梦，面色不华，头晕目眩，肢体麻木，月经量少色淡，舌淡苔白，脉细、阴虚（肺胃/肝肾阴虚）：口干咽燥，干咳少痰，潮热盗汗，五心烦热，头晕耳鸣，腰膝酸软，舌红少津，脉细数、阳虚（心/脾/肾阳虚）：畏寒肢冷，面色晄白，神疲乏力，心悸自汗，腰膝酸软，小便清长，夜尿多，舌淡胖有齿痕，脉沉迟。\n【待人工确认·本机素材无此段原文】","现病史":"虚劳又称虚损，是由多种原因所致的，以脏腑亏损、气血阴阳虚衰为主要病机，以五脏虚证为主要临床表现的多种慢性虚弱证候的总称。分气虚、血虚、阴虚、阳虚及五脏虚证。可见于慢性消耗性疾病、贫血、营养不良、肿瘤后期等。\n常见表现：气虚（肺脾气虚）：短气自汗，声音低怯，时寒时热，平素易于感冒，面白，食少便溏，倦怠乏力，舌淡苔白，脉弱、血虚（心血虚/肝血虚）：心悸怔忡，健忘，失眠多梦，面色不华，头晕目眩，肢体麻木，月经量少色淡，舌淡苔白，脉细、阴虚（肺胃/肝肾阴虚）：口干咽燥，干咳少痰，潮热盗汗，五心烦热，头晕耳鸣，腰膝酸软，舌红少津，脉细数、阳虚（心/脾/肾阳虚）：畏寒肢冷，面色晄白，神疲乏力，心悸自汗，腰膝酸软，小便清长，夜尿多，舌淡胖有齿痕，脉沉迟。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：体温、脉搏、呼吸、血压\n望诊：神、色（青/赤/黄/白/黑）、形态、头面、五官、躯体、舌诊（舌质/舌苔/舌底络脉）、排泄物\n闻诊：声音（语声/呼吸/咳嗽/呃逆/嗳气/肠鸣）、气味\n问诊：一般情况、主诉、现病史、既往史、个人史、家族史、十问歌\n切诊：脉诊（浮沉迟数虚实滑涩洪细濡弱弦紧结代促）、按诊（肌肤/手足/胸腹/腧穴）\n辨证：八纲辨证、脏腑辨证、气血津液辨证、经络辨证","辅助检查":"检查计划：患者以短气自汗、声音低怯、易于感冒，或心悸怔忡、健忘失眠、面色不华、头晕目眩，或口干咽燥、潮热盗汗、五心烦热、腰膝酸软，或畏寒肢冷、神疲乏力、夜尿增多为主症，病程长、病势缓，结合中医辨证属气虚、血虚、阴虚、阳虚之虚劳，可见于慢性消耗性疾病、贫血、营养不良、肿瘤后期等，入院即刻完善血常规检查了解有无贫血、感染及血细胞减少；完善肝肾功能检查排除肝肾疾病所致虚损，并为用药安全提供依据；完善血糖检查排除糖尿病等代谢性疾病；完善电解质检查排除低钾、低钠等电解质紊乱所致乏力；查肿瘤标志物检查排除肿瘤所致慢性消耗；完善甲状腺功能检查排除甲状腺功能亢进或减退所致虚劳；完善胸部CT检查排除肺结核、肺部占位等病变；查腹部超声了解肝、胆、胰、脾、肾等脏器情况；女性患者完善妇科超声检查排除子宫及附件病变；必要时完善骨髓穿刺检查明确有无血液系统疾病；定期复查血常规、肝肾功能了解病情变化及治疗效果。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 多种慢性虚弱证候，病程长，病势缓\n2. 血常规、肝肾功能、血糖、肿瘤标志物等排查基础病\n3. 明确原发疾病是关键\n1. 虚劳(中医辨证)（ICD-10：R53）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！\n\n方案1：\n 用法：一般不需输液，以口服中药为主\n\n方案2（症状较重/脱水明显）：\n 用法：NS500ml+维生素C2.0g+维生素B6 0.2g ivgtt qd\n\n方案3（合并细菌感染）：\n 用法：NS250ml+头孢呋辛3.0g ivgtt bid（皮试后）\n\n📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！\n\n📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。\n\n药物1（肺脾气虚）：补中益气丸6g tid，或参苓白术散6g tid\n药物2（心血虚）：归脾丸6g tid，或柏子养心丸6g tid\n药物3（肝血虚）：四物合剂10ml tid\n药物4（阴虚）：六味地黄丸6g bid，或知柏地黄丸6g bid\n药物5（阳虚）：金匮肾气丸6g bid，或右归丸1丸 bid\n药物6（配合）：纠正贫血、补充营养，治疗原发病\n\n【治疗】\n肺脾气虚：健脾益气，补肺固卫，补肺汤合四君子汤加减\n心血虚：养血安神，归脾汤加减\n肝血虚：补血养肝，四物汤加减\n阴虚：滋养阴液，六味地黄丸、沙参麦冬汤等加减\n阳虚：温补阳气，金匮肾气丸、右归丸等加减\n\n【处理要点】\n加强营养，优质蛋白饮食\n规律作息，避免过劳\n适度锻炼，增强体质\n\n【护理】\n情志护理：虚劳病程缠绵，患者易忧思焦虑，应多予开导安抚，避免忧思过度暗耗气血；阴虚者尤忌劳神动怒，五志化火更灼阴津，可引导听轻音乐、静坐养神以宁心敛神。\n起居调护：虚劳忌过劳，气血虚者宜劳逸结合，避免剧烈活动耗气，可练八段锦、散步等缓动；阳虚者避风寒、注意保暖，居处宜向阳；阴虚者居室宜安静凉爽，嘱子时前就寝，切忌熬夜暗耗阴液。\n病情观察：观察神疲乏力、体重、食欲及脉象舌象变化；注意有无午后低热、盗汗、五心烦热（阴虚内热），有无畏寒肢冷、便溏（阳虚），发现病情加重及时报告。\n煎药服药护理：补益之剂宜文火久煎，饭前温服以利吸收；阴虚证药液宜偏凉或微温服，阳虚证宜热服；服补药期间忌浓茶、萝卜（耗气破气）同服，并观察服药后有无腹胀、虚不受补之象。\n外治护理：气虚、阳虚者可艾灸足三里、气海、关元以温补元气，施灸时注意防烫伤、灸后避风；阴虚内热者慎用灸法，改以按揉三阴交、涌泉等穴，睡前温水泡足引火归元。\n\n【饮食】\n辨证忌口：阴虚者忌辛辣温燥之品（辣椒、羊肉、狗肉、酒类），以免助火伤阴；阳虚者忌生冷寒凉（冰饮、生瓜果），以免损脾伤阳；脾胃虚弱者忌肥甘厚腻，以防碍胃生湿、虚不受补。\n适宜食物：气虚者宜山药、小米、大枣、鸡肉、鲫鱼；血虚者宜桂圆、黑芝麻、猪肝、红枣；阴虚者宜百合、银耳、鸭肉、枸杞、桑葚；阳虚者宜羊肉、核桃、韭菜、桂圆肉。\n药膳食疗：气虚者可用黄芪炖鸡、山药大枣粥补益中气；阳虚者可用当归生姜羊肉汤温阳散寒；阴虚者宜百合银耳莲子羹、枸杞菊花茶滋阴清热。\n进食调护：宜少食多餐、细嚼慢咽，食物温热软烂易消化，不可暴饮暴食或过饥过饱；虚劳恢复期可逐渐增加蛋、奶、瘦肉等优质蛋白以充养气血，但须以食后胃脘舒适为度。\n\n【注意事项】\n虚劳需明确并积极治疗原发病\n恶性肿瘤所致虚劳按专科方案治疗\n补益药物需辨证选用，防虚不受补\n\n【急诊/急救】\n一般不需急救\n症状加重伴休克/昏迷：立即急救处理\n反复发作/黑便/消瘦：转上级医院进一步检查","资料来源":"疾病库 diseases.json","中医辨证参考":"首次病程记录\n\n拟诊讨论：\n\n【中医辨证参考】虚劳\n（本页列出该病常见证型，请根据患者实际四诊资料选择相应证型，切勿直接套用）\n\n一、气血两虚\n    症状舌脉：面色苍白或萎黄，唇甲色淡，头晕目眩，心悸气短，神疲乏力，失眠健忘，月经量少色淡，舌淡苔薄白，脉细弱\n    治法：补气养血、健脾益心\n    方剂：八珍汤\n\n二、脾胃虚弱\n    症状舌脉：面色萎黄，神疲乏力，食少纳呆，脘腹胀满，大便溏薄，头晕心悸，舌淡苔白，脉缓弱\n    治法：健脾益气、养血补心\n    方剂：归脾汤\n\n三、肝肾阴虚\n    症状舌脉：面色无华，头晕目眩，耳鸣，腰膝酸软，五心烦热，潮热盗汗，口干咽燥，舌红少苔，脉弦细数\n    治法：滋养肝肾、益精养血\n    方剂：左归丸\n\n四、脾肾阳虚\n    症状舌脉：面色㿠白，神疲嗜卧，畏寒肢冷，腰膝酸冷，纳呆便溏，面浮肢肿，夜尿频多，舌淡胖苔白，脉沉细\n    治法：温补脾肾、益气生血\n    方剂：右归丸\n\n【方剂参考】\n  八珍汤：组成 人参9g、白术9g、茯苓9g、当归9g、川芎6g、白芍9g、熟地黄12g、炙甘草6g、生姜3片、大枣2枚；功效 益气补血\n      用法：水煎温服，日一剂，分两次服；加生姜、大枣同煎。\n      注意：湿热内蕴、食积停滞及外感表证未解者不宜用；脾胃虚弱运化无力者，宜先健脾或酌减滋阴之品。来源：《方剂学》（中国中医药出版社“十四五”规划教材）·补益剂（气血双补）；原方出自《正体类要·卷下》\n  归脾汤：组成 白术9g、当归9g、白茯苓9g、黄芪12g、龙眼肉12g、远志6g、酸枣仁12g、人参9g、木香6g、炙甘草3g、生姜3片、大枣3枚；功效 益气补血，健脾养心\n      用法：加生姜3片、大枣3枚，水煎温服，日二次；亦可服归脾丸，每次6-9g，日二次。\n      注意：痰湿内盛、肝火扰心之失眠及外感发热者不宜；本方偏温补，有实火者忌用。\n  左归丸：组成 熟地黄24g、山药12g、枸杞子12g、山茱萸12g、川牛膝9g、菟丝子12g、鹿角胶12g、龟甲胶12g；功效 滋阴补肾，填精益髓\n      用法：上药为末，炼蜜为丸如梧桐子大，每次9g，空腹淡盐汤送服，日二次；亦可作汤剂，阿胶、鹿角胶烊化兑服。\n      注意：脾虚便溏、痰湿内盛者忌用（纯补无泻，滋腻滞脾）；感冒发热期间停服。\n  右归丸：组成 熟地黄24g、山药12g、山茱萸9g、枸杞子12g、鹿角胶12g、菟丝子12g、杜仲12g、肉桂6g、当归9g、附子6g；功效 温补肾阳，填精补血\n      用法：上药为末，炼蜜为丸如弹子大，每次1丸（约9g），空腹淡盐汤或温开水送服，日二次；亦可作汤剂，鹿角胶烊化。\n      注意：阴虚火旺、湿热内盛及感冒发热者忌用；脾虚便溏者慎用（滋腻）；孕妇慎用附子、肉桂。（本方肉桂6g超《中国药典》2020年版一部肉桂用量1-5g，系教材原方折算，临床宜酌减）\n\n【西医诊断】\n  贫血\n  （西医诊断依据与鉴别诊断请结合患者病史、体征、辅助检查补充）\n\n医师签名：＿＿＿＿"},"icd10_diagnosis":"R53","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2673,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"7951cae50a8974a818b403ae2dcf067731133ecfc969d7665feef40f1f706905","pinyin":"xulao(zhongyibianzheng)","initials":"xl(zybz)","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源","中医辨证参考"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源 中医辨证参考",30],["主要诊断编码","R53",30]]},{"id":"templates-cf4fd5347bd7008a1a02","key":"v1-c9ccc21dfe2a3058|templates-cf4fd5347bd7008a1a02","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"虱病","category":"皮肤科","raw":{"name":"虱病","category":"皮肤科","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文·皮肤病库原文】头虱：头皮瘙痒，可见虱及虱卵，多位于耳后、枕部、体虱：躯干、腰部、臀部瘙痒，可见线状抓痕、血痂、阴虱：阴毛部位剧烈瘙痒，可见阴毛上黏附灰白色虱卵、可伴抓痕、血痂、继发感染、内裤上可见点状血迹（阴虱）。\n【待人工确认·本机素材无此段原文】","现病史":"虱病是由虱寄生于人体叮咬皮肤所引起的一种瘙痒性皮肤病，根据寄生部位可分为头虱、体虱和阴虱。\n常见表现：头虱：头皮瘙痒，可见虱及虱卵，多位于耳后、枕部、体虱：躯干、腰部、臀部瘙痒，可见线状抓痕、血痂、阴虱：阴毛部位剧烈瘙痒，可见阴毛上黏附灰白色虱卵、可伴抓痕、血痂、继发感染、内裤上可见点状血迹（阴虱）。\n自觉症状：剧烈瘙痒，夜间或贴身衣物摩擦后加重。。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"皮损形态：头虱、体虱或阴虱叮咬引起瘙痒性丘疹、抓痕、血痂，阴虱可见青灰色斑，毛发上可见虱卵（虮）。\n好发部位：头虱多见于头部，体虱多见于躯干衣缝处，阴虱多见于阴毛及肛周。","辅助检查":"检查计划：患者头皮、躯干或阴毛部位出现剧烈瘙痒，夜间及贴身衣物摩擦后加重，查体可见虱及虱卵，多位于耳后、枕部或阴毛上黏附灰白色虱卵，伴线状抓痕、血痂，内裤上可见点状血迹，结合接触史及卫生条件差或性接触传播史，诊断虱病，入院即刻完善皮肤镜检查查找虱虫及虱卵以明确诊断；完善血常规检查了解有无继发感染及嗜酸性粒细胞增高；如为阴虱，完善梅毒血清学、艾滋病抗体等性传播疾病筛查检查明确有无合并感染，指导治疗；皮损不典型时完善皮肤镜检查鉴别疥疮、湿疹等其他瘙痒性皮肤病；抓痕继发感染、有脓性分泌物者完善分泌物涂片及培养检查明确感染病原；瘙痒剧烈影响睡眠、病情反复者定期复查皮肤镜观察治疗效果；如伴发热、淋巴结肿大，完善血常规、CRP检查排除全身感染，必要时完善皮肤病理活检以进一步明确诊断。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 相应部位剧烈瘙痒\n2. 可找到虱或虱卵\n3. 好发于卫生条件差者或性接触传播（阴虱）\n4. 可伴抓痕、血痂\n诊断要点：依据接触史、剧烈瘙痒及在毛发或衣缝中找到虱或虱卵即可确诊；需与疥疮、湿疹等鉴别。\n1. 虱病（ICD-10：B85）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【药物治疗·输液】\n一般无需静脉用药\n\n【药物治疗·口服】\n瘙痒明显者：氯雷他定 10mg 口服 qd\n或西替利嗪 10mg 口服 qd\n继发感染时：抗生素治疗\n\n【治疗】\n头虱：10%百部酊外搽，或用密齿梳篦除虱卵\n体虱：煮沸消毒衣物被褥，皮肤外用硫磺软膏\n阴虱：剃除阴毛，外用50%百部酊或10%硫磺软膏\n性伴侣同时治疗\n衣物、被褥煮沸消毒\n\n【处理要点】\n注意个人卫生，勤洗澡、勤换衣\n避免与患者共用梳子、帽子、衣物\n阴虱患者治疗期间避免性生活\n性伴侣同时检查治疗\n衣物、被褥煮沸消毒或暴晒\n\n【注意事项】\n本病通过直接接触或间接接触传播\n治疗后需检查是否有活虱或活虱卵，必要时重复治疗\n注意环境卫生，避免再次感染\n\n【急诊/急救】\n继发严重感染时需抗感染治疗\n\n【治疗】\n外用杀虫剂（如扑灭司林、硫磺软膏），剔除或剪短毛发，煮沸消毒衣物、床品。\n\n【注意事项】\n家庭成员及密切接触者需同时治疗，防止相互再感染。","资料来源":"疾病库 diseases.json；皮肤病库 derm.json（条目「虱病」原文）"},"icd10_diagnosis":"B85","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2674,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"9103da204c399705979ad33bcd89e66b2509a479512659c40ad01db512b4ad18","pinyin":"shibing","initials":"sb","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","B85",30]]},{"id":"templates-690490a37545632d4a8f","key":"v1-c9ccc21dfe2a3058|templates-690490a37545632d4a8f","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"蛇串疮(中医辨证)","category":"中医","raw":{"name":"蛇串疮(中医辨证)","category":"中医","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】肝经郁热：皮损鲜红，疱壁紧张，灼热刺痛，口苦咽干，烦躁易怒，大便干结，小便黄赤，舌红苔薄黄或黄厚，脉弦滑数、脾虚湿蕴：皮损颜色较淡，疱壁松弛，疼痛略轻，口不渴，食少腹胀，大便时溏，舌淡胖苔白腻，脉沉缓或滑、气滞血瘀：皮疹消退后局部疼痛不止，放射到附近部位，痛不可忍，坐卧不安，重者可持续数月或更长时间，舌暗苔白，脉弦细。\n【待人工确认·本机素材无此段原文】","现病史":"蛇串疮是一种皮肤上出现成簇水疱、沿身体一侧周围神经呈带状分布、伴明显神经痛的急性疱疹性皮肤病，又称缠腰火丹。分肝经郁热、脾虚湿蕴、气滞血瘀（后遗神经痛）等证型。可见于带状疱疹。\n常见表现：肝经郁热：皮损鲜红，疱壁紧张，灼热刺痛，口苦咽干，烦躁易怒，大便干结，小便黄赤，舌红苔薄黄或黄厚，脉弦滑数、脾虚湿蕴：皮损颜色较淡，疱壁松弛，疼痛略轻，口不渴，食少腹胀，大便时溏，舌淡胖苔白腻，脉沉缓或滑、气滞血瘀：皮疹消退后局部疼痛不止，放射到附近部位，痛不可忍，坐卧不安，重者可持续数月或更长时间，舌暗苔白，脉弦细。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：体温、脉搏、呼吸、血压\n望诊：局部皮损（红肿/化脓/成脓/破溃/肉芽）、舌诊（舌质/舌苔）\n闻诊：脓液气味、口气\n问诊：发病诱因、局部疼痛性质、伴随全身症状、既往史（糖尿病/免疫低下）\n切诊：局部触诊（皮温/波动感/压痛/边界）、脉诊、淋巴结检查\n辨证：疮疡辨证（善恶顺逆）、八纲辨证、气血津液辨证","辅助检查":"检查计划：患者沿单侧周围神经分布区域出现成簇水疱，皮损鲜红、疱壁紧张、灼热刺痛，伴明显神经痛，或皮损色淡、疱壁松弛、疼痛略轻、食少腹胀、大便时溏，或皮疹消退后局部疼痛不止、痛不可忍、坐卧不安，结合中医辨证属肝经郁热、脾虚湿蕴、气滞血瘀之蛇串疮（带状疱疹），入院即刻完善血常规检查了解有无感染及血细胞异常；完善CRP、血沉检查评估炎症反应程度；完善肝肾功能、电解质检查排除肝肾疾病及电解质紊乱，并为抗病毒、止痛药物用药安全提供依据；完善血糖检查排除糖尿病等免疫功能低下相关因素；皮损位于胸背部者完善胸部CT检查排除肺部及胸膜病变所致神经痛；皮损位于头面部、伴耳痛或眼痛者完善头颅MRI检查排除颅内病变，并完善眼科裂隙灯检查排除眼部受累；年龄大于50岁、免疫功能低下者完善免疫球蛋白、淋巴细胞亚群检查评估免疫状态及后遗神经痛风险；疼痛持续不缓解、皮疹不典型者完善单纯疱疹病毒抗体及病毒核酸检测检查明确病原；定期复查血常规、肝肾功能了解病情变化及用药安全性。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 沿单侧周围神经分布的成簇水疱，伴明显神经痛\n2. 多发生于肋间神经、三叉神经等区域\n3. 年龄>50岁、免疫功能低下者后遗神经痛风险高\n1. 蛇串疮(中医辨证)（ICD-10：B02.9）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！\n\n方案1：\n 用法：一般不需输液，口服中药+外治为主\n\n方案2（感染较重/发热）：\n 用法：NS250ml+头孢呋辛3.0g ivgtt bid（皮试后）；甲硝唑0.5g ivgtt bid\n\n方案3（糖尿病合并感染）：\n 用法：NS250ml+头孢哌酮舒巴坦2.0g ivgtt bid（皮试后），控制血糖\n\n📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！\n\n📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。\n\n药物1（肝经郁热）：龙胆泻肝丸6g bid，或加味逍遥丸6g bid\n药物2（脾虚湿蕴）：参苓白术散6g tid，或除湿丸6g tid\n药物3（气滞血瘀后遗痛）：血府逐瘀胶囊4粒 tid，或元胡止痛片4片 tid\n药物4（配合）：阿昔洛韦0.4g tid（发病72h内，遵医嘱），加巴喷丁0.3g tid（神经痛，遵医嘱），甲钴胺0.5mg tid\n\n【治疗】\n肝经郁热：清泄肝火，解毒止痛，龙胆泻肝汤加减\n脾虚湿蕴：健脾利湿，解毒消肿，除湿胃苓汤加减\n气滞血瘀：理气活血，通络止痛，柴胡疏肝散合桃红四物汤加减\n\n【处理要点】\n保持皮损清洁干燥，避免搔抓\n穿宽松棉质衣物，减少摩擦\n忌辛辣、发物，注意休息\n\n【护理】\n情志护理：本病疼痛剧烈，肝经郁热证患者多烦躁易怒，怒则肝火更盛，应耐心疏导，嘱戒怒、保持心境平和，可用音乐、交谈等转移注意力；气滞血瘀证疼痛缠绵难愈，易焦虑抑郁，需多加安抚鼓励，树立治疗信心。\n起居调护：保持皮损区清洁干燥，穿宽松柔软的棉质衣裤，减少摩擦压迫；切忌搔抓或挤破水疱，疱破糜烂者注意无菌换药，防止继发感染；保证充足睡眠，疼痛明显或属脾虚者注意卧床休息、避免劳累耗气。\n病情观察：观察皮损颜色、水疱大小疏密及有无破溃、糜烂、渗液、继发感染；重点评估疼痛性质与程度，警惕疱疹消退后遗留神经痛；发于眼周者密切观察眼部症状，及时就医，防止损伤角膜。\n外治护理：肝经郁热证皮损红赤灼痛者用青黛散或金黄散调敷；脾虚湿蕴证破溃渗液处以三黄洗剂湿敷、糜烂处涂金黄膏；疼痛甚者可行刺络拔罐或火针治疗，操作后保持创面清洁干燥，观察有无出血及感染。\n煎药服药护理：中药宜温服、按医嘱定时服；服清热泻火方（如龙胆泻肝汤）期间忌辛辣、酒类；服活血化瘀方（如桃红四物汤加减）时观察有无出血倾向，妇女经期停服，服药期间忌生冷。\n\n【饮食】\n肝经郁热证：忌辛辣刺激、油炸肥腻及烟酒，忌羊肉、狗肉等温燥发物；宜食苦瓜、芹菜、冬瓜、绿豆等清肝泻火之品，常饮菊花茶、金银花茶。\n脾虚湿蕴证：忌生冷瓜果、肥甘厚味及海鲜等助湿生痰之发物；宜食薏苡仁、赤小豆、山药、白扁豆、茯苓粥等健脾利湿之品，饮食宜温热、易消化。\n气滞血瘀证：宜食山楂、玫瑰花、陈皮、桃仁、黑木耳等理气活血之品；忌生冷凝滞碍气之食；疼痛日久耗伤气血者适当增加瘦肉、蛋类等高蛋白营养，扶助正气。\n药膳食疗：肝经郁热者以金银花、菊花、蒲公英煎水代茶饮；脾虚湿蕴者用薏苡仁赤小豆粥或山药扁豆粥；瘀痛明显者用桃仁粥，或少量三七粉温水冲服，均以清淡为原则。\n疱疹急性期饮食宜清淡、易消化，忌食海鲜、牛羊肉、辛辣、酒等发物，多饮水，多食富含维生素B族及维生素C的新鲜蔬果，促进皮损愈合、减轻神经痛。\n\n【注意事项】\n眼周、耳周带状疱疹需眼科/耳鼻喉科会诊\n>50岁患者积极抗病毒预防后遗神经痛\n免疫低下者（肿瘤、HIV）需系统治疗\n\n【急诊/急救】\n一般不需急救\n脓毒血症/高热寒战/神志改变：立即急诊\n疔疮走黄（火毒内陷）为危候，立即转院","资料来源":"疾病库 diseases.json","中医辨证参考":"首次病程记录\n\n拟诊讨论：\n\n【中医辨证参考】蛇串疮\n⚠️ 本条为通用辨证参考，尚未逐条核对教材原文，请务必结合患者实际四诊资料，\n   并核对相应教材（中医外科学/中医儿科学/中医内科学）后再使用；\n   方剂仅列组成药味，具体剂量请依药典、患者体质及本院药房规格确定。\n\n一、肝经郁热\n    症状舌脉：皮损鲜红，疱壁紧张，灼热刺痛，伴口苦咽干、烦躁易怒、大便干、小便黄；舌红苔黄，脉弦滑数\n    治法：清肝泻火、解毒止痛\n    方剂：龙胆泻肝汤加减（龙胆草、黄芩、栀子、泽泻、木通、车前子、当归、生地黄、柴胡、甘草）\n\n二、脾虚湿蕴\n    症状舌脉：皮损色淡，疱壁松弛，疼痛较轻，伴食少腹胀、大便时溏；舌淡胖、苔白腻，脉沉缓\n    治法：健脾利湿、解毒止痛\n    方剂：除湿胃苓汤加减（苍术、厚朴、陈皮、猪苓、泽泻、茯苓、白术、滑石、防风、栀子、木通、肉桂、甘草）\n\n三、气滞血瘀\n    症状舌脉：皮疹消退后局部疼痛不止（后遗神经痛），痛处固定，拒按；舌暗紫、苔白，脉弦细\n    治法：理气活血、通络止痛\n    方剂：柴胡疏肝散合桃红四物汤加减（柴胡、枳壳、白芍、川芎、香附、桃仁、红花、当归、生地黄）\n\n【西医诊断】\n  带状疱疹\n  （西医诊断依据与鉴别诊断请结合患者病史、体征、辅助检查补充）\n\n⚠️ 皮疹位于眼周（眼带状疱疹）须立即眼科会诊；发病72小时内抗病毒治疗效果最佳\n\n医师签名：＿＿＿＿"},"icd10_diagnosis":"B02.9","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2675,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"a155925d3708e97cca30a459b2132952bf9b52acb0f32a31da47abd65321ec6e","pinyin":"shechuanchuang(zhongyibianzheng)","initials":"scc(zybz)","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源","中医辨证参考"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源 中医辨证参考",30],["主要诊断编码","B02.9",30]]},{"id":"templates-bd8347e923636db01aa0","key":"v1-c9ccc21dfe2a3058|templates-bd8347e923636db01aa0","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"蜂蜇伤过敏","category":"院前急救","raw":{"name":"蜂蜇伤过敏","category":"院前急救","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】蜇伤处红肿、剧痛、荨麻疹、全身瘙痒、面部/口唇/眼睑肿胀、喉头紧、声音嘶哑、呼吸困难、胸闷、喘息、头晕、心慌、血压下降、恶心呕吐、腹痛、意识丧失。\n【待人工确认·本机素材无此段原文】","现病史":"蜂毒过敏可致局部红肿、荨麻疹，严重者发生过敏性休克、喉头水肿、支气管痉挛，可在数分钟内致死。\n常见表现：蜇伤处红肿、剧痛、荨麻疹、全身瘙痒、面部/口唇/眼睑肿胀、喉头紧、声音嘶哑、呼吸困难、胸闷、喘息、头晕、心慌、血压下降、恶心呕吐、腹痛、意识丧失。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征（快速评估ABC）：意识（清醒/呼之能应/无反应）、气道（通畅/梗阻）、呼吸（存在/停止/频率/节律）、脉搏（桡动脉/颈动脉/股动脉，存在/停止）、血压（可测/不可测）、血氧\n一般情况：神志、面色（苍白/发绀/潮红）、体位、有无大汗\n皮肤黏膜：温度/湿度/颜色、出血点/瘀斑、伤口/出血（部位/量/活动性）、烧伤（面积/深度）、发绀\n头颈部：瞳孔（大小/对光反射）、耳鼻出血/脑脊液漏、颈椎损伤（固定）、颈静脉怒张\n胸部：胸廓对称/畸形（连枷胸）、呼吸动度、心尖搏动、心率心律、心音、双肺呼吸音（单侧消失提示气胸/血胸）、皮下气肿\n腹部：膨隆/凹陷、压痛（观察反应）、肌紧张、移动性浊音、外出血\n骨盆：挤压分离试验（骨盆骨折）\n四肢：畸形/肿胀/压痛/反常活动（骨折）、脉搏（桡/足背）、毛细血管充盈、感觉运动（脊髓损伤评估）\n脊柱：轴线对位、压痛（脊髓损伤风险）\n其他：GCS评分、创伤评分、现场环境安全","辅助检查":"1. 血常规+CRP：评估有无感染、嗜酸性粒细胞升高及炎症反应，入急诊即查\n2. 血气分析：评估缺氧、酸碱失衡及过敏休克时的组织灌注，呼吸困难或休克者即刻查\n3. 血清电解质+肝肾功能：评估过敏反应及液体复苏后内环境紊乱，休克患者每4-6小时复查\n4. 心电图+心肌损伤标志物（肌钙蛋白、CK-MB）：排除过敏致心肌缺血/损伤，持续胸闷者动态复查\n5. 凝血功能+D-二聚体：评估严重过敏并发弥散性血管内凝血风险，持续低血压者必查\n6. 蜂毒特异性IgE检测：病情稳定后送检，用于明确致敏原及后续脱敏治疗","初步诊断":"1. 蜂蜇史\n2. 局部反应+全身过敏表现\n3. 过敏性休克：血压下降+意识改变+皮肤表现\n4. 喉头水肿：声嘶、喘鸣、呼吸困难\n1. 蜂蜇伤过敏（ICD-10：T63.4）","鉴别诊断":"1. 诊断要点：局部反应+全身过敏表现\n2. 诊断要点：过敏性休克：血压下降+意识改变+皮肤表现\n3. 诊断要点：喉头水肿：声嘶、喘鸣、呼吸困难\n4. 肾上腺素是过敏性休克的首选和救命药，不要因犹豫而延误\n5. 肌注部位选大腿前外侧（比上臂吸收快）\n6. 蜜蜂毒刺不要用镊子夹（挤压毒囊）\n7. 胡蜂/马蜂蜇伤比蜜蜂更危险（可反复蜇刺）\n8. 过敏反应可双相发生，需观察24h\n9. 群蜂蜇伤（>30处）可致横纹肌溶解、肾衰，即使无过敏也需就医","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！\n\n方案1：\n 用法：0.9%氯化钠 500-1000ml 快速静滴（休克时）\n\n方案2（肾上腺素 0.3-0.5mg（1）：\n 用法：1000）大腿前外侧肌注（过敏性休克首选，5-15min可重复）\n\n方案3：\n 用法：地塞米松 10-20mg 静推\n\n方案4：\n 用法：10%葡萄糖酸钙 10ml + 5%GS 20ml 缓慢静推\n\n方案5：\n 用法：甲泼尼龙 40-80mg 静推\n\n📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！\n\n药物1：\n 用法：氯雷他定 10mg 口服\n\n药物2：\n 用法：西替利嗪 10mg 口服\n\n药物3：\n 用法：局部肥皂水/3%氨水冲洗（蜜蜂毒液酸性）\n\n📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。\n\n【治疗】\n立即拔除毒刺（蜜蜂蜇伤，不要挤压毒囊）\n过敏性休克：肾上腺素肌注（首选！）\n保持气道通畅，喉头水肿需气管插管/环甲膜穿刺\n吸氧、补液抗休克\n抗组胺药\n糖皮质激素\n支气管痉挛：沙丁胺醇雾化\n观察至少24h（双相反应）\n\n【处理要点】\n立即离开蜂群环境\n蜜蜂蜇伤：用卡片刮除毒刺（不要用镊子夹，会挤压毒囊注入更多毒液）；胡蜂/马蜂不留毒刺\n肥皂水冲洗（蜜蜂）或食醋冲洗（胡蜂毒液碱性）\n局部冷敷\n轻度过敏：口服抗组胺药+局部激素软膏\n严重过敏/休克：立即肾上腺素0.3-0.5mg大腿前外侧肌注（最重要！）\n建立静脉通路，快速补液\n地塞米松/甲泼尼龙静推\n高流量吸氧\n喉头水肿、喘鸣：紧急气管插管，插管困难则环甲膜穿刺\n支气管痉挛：沙丁胺醇雾化\n监测生命体征至少24h（可发生双相过敏反应，症状缓解后6-12h再次加重）\n有蜂毒过敏史者建议携带肾上腺素自动注射笔（EpiPen）\n\n【护理】\n持续心电监护+SpO2监测，每5-15分钟测量血压、脉搏直至生命体征稳定，警惕迟发型休克\n保持气道通畅，取平卧或休克体位（抬高下肢）；喉头水肿呼吸困难时立即配合环甲膜穿刺或气管插管，备好急救用物\n迅速建立两条静脉通道，遵医嘱快速给予肾上腺素、抗组胺药及糖皮质激素，密切观察用药后血压、心率及皮疹变化\n重点观察皮疹范围、面部及咽喉部水肿进展、呼吸困难程度，记录每小时尿量，预防休克及过敏复发\n蜂刺未取出时协助拔出毒刺并局部冰敷，嘱患者勿搔抓，防止毒液吸收及继发感染\n\n【饮食】\n急性期（意识不清、休克未纠正或气管插管者）禁食禁水，防止误吸\n生命体征稳定后，先试少量温凉流质（米汤、稀粥），无不适再逐步过渡到半流质、普食\n忌辛辣、海鲜、酒精及既往致敏食物，避免诱发再次过敏反应\n多饮温水或口服补液盐，补充过敏反应及呕吐导致的液体丢失，观察尿量\n恢复期清淡均衡饮食，进食后注意观察有无皮疹、腹痛等迟发过敏表现，出现异常及时报告\n\n【注意事项】\n肾上腺素是过敏性休克的首选和救命药，不要因犹豫而延误\n肌注部位选大腿前外侧（比上臂吸收快）\n蜜蜂毒刺不要用镊子夹（挤压毒囊）\n胡蜂/马蜂蜇伤比蜜蜂更危险（可反复蜇刺）\n过敏反应可双相发生，需观察24h\n群蜂蜇伤（>30处）可致横纹肌溶解、肾衰，即使无过敏也需就医\n\n【急诊/急救】\n立即离开蜂群，蜜蜂蜇伤用卡片刮除毒刺（勿挤压毒囊）\n蜜蜂蜇伤用肥皂水冲洗，胡蜂蜇伤用食醋冲洗，局部冷敷\n轻度：氯雷他定10mg口服+局部激素软膏\n过敏性休克（血压下降、呼吸困难、意识改变）：立即肾上腺素0.3-0.5mg（1:1000）大腿前外侧肌注，5-15min可重复\n建立静脉通路快速补液，高流量吸氧\n地塞米松10-20mg静推+10%葡萄糖酸钙10ml缓慢静推\n喉头水肿喘鸣→紧急气管插管，失败则环甲膜穿刺\n支气管痉挛→沙丁胺醇雾化\n监护至少24h（双相过敏反应）","资料来源":"疾病库 diseases.json；鉴别诊断库 ddx_local.json（条目「蜂蜇伤过敏」原文）"},"icd10_diagnosis":"T63.4","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2676,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"ceabc29af2bbac2ae6fdcd7d3c360385605bba3818bf5e059d992626afa3e9d9","pinyin":"fengzheshangguomin","initials":"fzsgm","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","T63.4",30]]},{"id":"templates-cbc83ebd27c4016dc2fb","key":"v1-c9ccc21dfe2a3058|templates-cbc83ebd27c4016dc2fb","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"螨虫皮炎","category":"皮肤科","raw":{"name":"螨虫皮炎","category":"皮肤科","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】被叮咬部位出现红色丘疹、风团、水疱、剧烈瘙痒，夜间尤甚、好发于颈部、躯干、四肢等暴露部位、可伴抓痕、血痂、继发感染、部分患者可伴发热、头痛、乏力等全身症状。\n【待人工确认·本机素材无此段原文】","现病史":"螨虫皮炎是由螨虫叮咬或接触其分泌物引起的急性皮炎，好发于夏秋温暖潮湿季节，多见于接触农作物、谷物者。\n常见表现：被叮咬部位出现红色丘疹、风团、水疱、剧烈瘙痒，夜间尤甚、好发于颈部、躯干、四肢等暴露部位、可伴抓痕、血痂、继发感染、部分患者可伴发热、头痛、乏力等全身症状。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"检查计划：患者于夏秋温暖潮湿季节接触农作物、谷物或不洁环境后，颈部、躯干、四肢等暴露部位出现红色丘疹、风团、水疱，剧烈瘙痒、夜间尤甚，伴抓痕、血痂，部分患者有发热、头痛、乏力等全身症状，结合脱离环境后症状可逐渐缓解，考虑螨虫皮炎，入院即刻完善皮肤镜检查查找螨虫及虫卵以明确诊断；完善血常规检查了解有无继发感染及嗜酸性粒细胞增高；完善CRP、血沉检查评估炎症反应程度；皮疹泛发、瘙痒剧烈者完善血清总IgE及过敏原检测检查了解过敏状态，指导抗过敏治疗；伴发热、头痛、乏力等全身症状者完善肝肾功能、电解质检查排除全身感染及内环境紊乱；皮疹不典型、需与荨麻疹、湿疹、疥疮等鉴别时完善皮肤病理活检检查以进一步明确诊断；抓痕继发感染者完善分泌物涂片及培养检查明确病原；脱离致病环境后定期复查血常规、CRP了解炎症指标变化及治疗效果。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 夏秋季节，有接触农作物、谷物或不洁环境史\n2. 暴露部位红色丘疹、风团，剧烈瘙痒\n3. 可找到螨虫\n4. 脱离环境后症状可逐渐缓解\n1. 螨虫皮炎（ICD-10：B88.0）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【药物治疗·输液】\n严重者：葡萄糖酸钙 20ml + 5%GS 250ml 静滴 qd\n维生素C 3g + 5%GS 250ml 静滴 qd\n\n【药物治疗·口服】\n氯雷他定 10mg 口服 qd\n或西替利嗪 10mg 口服 qd\n或扑尔敏 4mg 口服 tid\n继发感染时：抗生素治疗\n\n【治疗】\n外用炉甘石洗剂\n外用糖皮质激素软膏（如地奈德乳膏、糠酸莫米松乳膏）\n口服抗组胺药止痒\n继发感染时外用或口服抗生素\n\n【处理要点】\n脱离有螨虫的环境\n衣物、被褥煮沸消毒或暴晒\n保持室内通风干燥\n接触农作物时做好防护（穿长袖衣物、戴手套）\n避免搔抓，防止继发感染\n\n【注意事项】\n本病好发于夏秋温暖潮湿季节\n脱离环境后经治疗多在1周左右痊愈\n注意环境卫生，定期清洗晾晒被褥\n\n【急诊/急救】\n广泛皮损、严重过敏反应需住院治疗\n继发严重感染时需抗感染治疗","资料来源":"疾病库 diseases.json"},"icd10_diagnosis":"B88.0","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2677,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"16f83ccdcc65f4f24b4f8b599a95ca996eb317b5d9ee60a070acbe02beb637e7","pinyin":"manchongpiyan","initials":"mcpy","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","B88.0",30]]},{"id":"templates-9b2302fa6c5f22998c3a","key":"v1-c9ccc21dfe2a3058|templates-9b2302fa6c5f22998c3a","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"血尿(鉴别与处理)","category":"内科-泌尿","raw":{"name":"血尿(鉴别与处理)","category":"内科-泌尿","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】肉眼血尿（洗肉水样、浓茶色或鲜红色）或体检发现的镜下血尿、血块（提示非肾小球性出血，如膀胱与前列腺病变）与尿痛、伴随症状：腰痛（结石与肾盂肾炎）、尿频尿急尿痛（感染）、排尿困难（前列腺病变）、无痛性肉眼血尿（泌尿系肿瘤的典型警示，尤其老年吸烟者）、全身表现：水肿与高血压（肾炎）、发热（感染）、消瘦（肿瘤）与出血倾向（凝血障碍）。\n【待人工确认·本机素材无此段原文】","现病史":"血尿指尿中红细胞异常增多（镜下血尿：离心尿沉渣红细胞>3个/HP；肉眼血尿：尿呈洗肉水样或血色）。按来源分为肾小球性（肾炎、IgA肾病与狼疮性肾炎）与非肾小球性（结石、感染、肿瘤、外伤与药物）。核心是判断出血部位、有无血块与伴随症状，并警惕泌尿系肿瘤（无痛性肉眼血尿）。\n常见表现：肉眼血尿（洗肉水样、浓茶色或鲜红色）或体检发现的镜下血尿、血块（提示非肾小球性出血，如膀胱与前列腺病变）与尿痛、伴随症状：腰痛（结石与肾盂肾炎）、尿频尿急尿痛（感染）、排尿困难（前列腺病变）、无痛性肉眼血尿（泌尿系肿瘤的典型警示，尤其老年吸烟者）、全身表现：水肿与高血压（肾炎）、发热（感染）、消瘦（肿瘤）与出血倾向（凝血障碍）。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：血压（肾炎与肾损伤）、体温（感染）、心率与血红蛋白相关表现\n一般情况：面色（贫血与苍白）、水肿（眼睑与下肢，肾炎）\n肾区：肋脊角叩击痛（肾盂肾炎与结石）\n腹部：腹部包块（多囊肾、肿瘤与膀胱充盈）与压痛\n泌尿生殖系：外尿道口（炎症与损伤）、睾丸与附睾（肿瘤与炎症）\n直肠指检（男性）：前列腺大小、结节与压痛（前列腺癌与增生）\n皮肤黏膜：出血点与瘀斑（凝血障碍与血管炎）、皮疹（狼疮与过敏性紫癜）","辅助检查":"1. 尿常规+尿沉渣（红细胞计数）+尿红细胞形态：确诊血尿与肾小球性判断\n2. 尿三杯试验：出血部位定位（初/终末/全程血尿）\n3. 尿蛋白定量+尿红细胞管型：肾小球疾病评估\n4. 泌尿系超声+CT尿路成像（CTU）：结石、肿瘤与肾积水（老年血尿首选）\n5. 尿脱落细胞学+膀胱镜（>40岁无痛性血尿）：尿路肿瘤排查\n6. 肾功能+免疫学（ANA、补体、抗GBM抗体、ANCA）：肾炎与自身免疫病\n7. 凝血功能+血小板+血红蛋白（动态）：凝血障碍与出血程度","初步诊断":"1. 尿常规+尿沉渣（确诊）：红细胞计数与形态（畸形红细胞>70%提示肾小球性）\n2. 尿三杯试验：初血尿（尿道病变）、终末血尿（膀胱颈与后尿道）、全程血尿（肾与输尿管/膀胱）\n3. 尿红细胞形态+尿蛋白定量+尿红细胞管型（肾小球性血尿证据）\n4. 泌尿系超声（首选影像）：结石、肿瘤、肾积水与前列腺病变\n5. 泌尿系CT尿路成像（CTU，首选）：结石、肿瘤与上尿路病变（老年血尿必查）\n6. 尿脱落细胞学+膀胱镜（>40岁无痛性血尿必查）：膀胱与尿路肿瘤\n7. 肾功能+免疫学（ANA、补体、抗GBM抗体）：肾炎与自身免疫病；凝血功能：凝血障碍\n8. 药物与运动史：抗凝药、环磷酰胺、NSAIDs与剧烈运动后血尿（鉴别）\n1. 血尿(鉴别与处理)（ICD-10：R31.9）","鉴别诊断":"1. 药物与运动史：抗凝药、环磷酰胺、NSAIDs与剧烈运动后血尿（鉴别）\n2. 肉眼血尿需与血红蛋白尿、肌红蛋白尿与药物染色鉴别\n3. 剧烈运动后血尿（运动性血尿）多为良性，但需排除其他病因后诊断","处理方案":"【药物治疗·输液】\n⚠️ 按病因治疗，活动性出血需补液与监测！\n\n方案1（大量血尿伴血块与排尿困难）：\n 用法：0.9%氯化钠 静滴（补液与冲洗，必要时三腔尿管膀胱冲洗）；氨甲环酸 0.5～1g 静滴（遵医嘱，慎用于疑上尿路出血）；必要时输血（Hb<70g/L）\n\n方案2（急性肾小球肾炎相关血尿）：\n 用法：青霉素 160万U 肌注 bid（清除链球菌，10～14天）；呋塞米 20～40mg 静推（水肿与高血压）；降压（氨氯地平 5mg qd）\n\n方案3（尿路感染与肾盂肾炎）：\n 用法：左氧氟沙星 0.5g 静滴 qd 或 头孢曲松 1～2g 静滴 qd（按尿培养调整）；0.9%氯化钠 静滴（补液与冲刷）\n\n方案4（抗凝药相关血尿与凝血障碍）：\n 用法：评估停用或减量抗凝药（遵医嘱）；维生素K1 10mg 静滴（华法林）；必要时新鲜冰冻血浆与血小板\n\n📌 无痛性肉眼血尿（尤其>40岁）必须排查泌尿系肿瘤（CTU+膀胱镜）；肾小球性血尿需评估蛋白尿与肾功能（可能需肾活检）。\n\n【药物治疗·口服】\n⚠️ 按病因选择口服用药：\n\n药物1（尿路感染）：\n 用法：左氧氟沙星 0.5g qd（疗程7天）或 头孢克肟 0.1g bid（按尿培养）；碳酸氢钠 1g tid（碱化尿液减轻刺激）\n\n药物2（结石与排石）：\n 用法：坦索罗辛 0.2mg qn（输尿管下段结石辅助排石）；双氯芬酸钠栓 50mg（肾绞痛，短期）；枸橼酸氢钾钠颗粒 1袋 tid（尿酸结石溶石）\n\n药物3（肾炎与免疫相关，专科指导）：\n 用法：泼尼松 0.5～1mg/kg/日（IgA肾病与狼疮性肾炎活动期）；ACEI/ARB（缬沙坦 80mg qd，降蛋白尿）\n\n药物4（止血与支持）：\n 用法：云南白药 0.5g qid（辅助止血，遵医嘱）；琥珀酸亚铁 0.1g bid（持续血尿致缺铁性贫血）；维生素C 0.2g tid\n\n📌 抗凝与抗血小板药物相关血尿需评估用药指征（不可自行停药）；避免NSAIDs（肾损害与出血加重）。\n\n【治疗】\n明确出血部位与病因：尿三杯试验、尿红细胞形态、泌尿系超声与CTU；老年无痛性血尿行膀胱镜\n病因治疗：感染（抗生素）、结石（排石/碎石/取石）、肿瘤（手术与放化疗）、肾炎（激素/免疫抑制）、凝血障碍（纠正凝血）、药物（停药或调整）\n大量出血处理：留置三腔尿管膀胱冲洗（清除血块）、补液与输血；持续出血行膀胱镜电凝或介入栓塞\n肾小球性血尿处理：控制血压与蛋白尿（ACEI/ARB）、激素与免疫抑制（依病理）、必要时肾活检\n避免加重因素：停用或调整抗凝/抗血小板药（评估血栓风险）、避免NSAIDs与剧烈运动\n监测：尿色与尿量、血红蛋白（活动性出血每4～6小时）、肾功能与血压\n随访：明确病因后定期复查（尿常规、肾功能与影像）；肿瘤患者按肿瘤随访\n宣教：血尿不可忽视（无痛性血尿需排查肿瘤）、多饮水、遵医嘱复查与用药\n\n【处理要点】\n尿色与出血观察：记录尿色（洗肉水样/鲜红/浓茶色）、血块与尿量，活动性出血监测血红蛋白\n尿液与标本管理：留取尿常规与尿红细胞形态标本（新鲜）、必要时记录尿三杯结果\n疼痛与排尿护理：评估腰痛与排尿疼痛、遵医嘱镇痛与解痉、鼓励多饮水（无梗阻者）\n导管护理（留置尿管）：保持通畅与膀胱冲洗（血块堵塞时）、记录冲洗液与尿色变化\n用药观察：抗感染与止血药疗效、观察药物不良反应（NSAIDs与抗凝药相关出血）\n宣教与随访：强调无痛性血尿需排查肿瘤（膀胱镜与CTU）、多饮水与避免剧烈运动、按时复查尿常规与肾功能\n\n【护理】\n尿色与出血监测：记录尿色、血块与尿量（每班），活动性出血时监测生命体征与血红蛋白\n标本留取：及时留取新鲜尿常规与尿红细胞形态标本并送检、记录尿三杯结果\n饮水与排尿护理：无梗阻与心肾功能限制者鼓励多饮水（冲刷尿路）、观察排尿困难与血块\n导管与冲洗护理：留置尿管者保持通畅、膀胱冲洗（血块堵塞时）、记录冲洗液性状\n疼痛与用药护理：评估腰痛与排尿痛并遵医嘱镇痛、观察抗感染与止血药疗效与不良反应\n宣教：无痛性血尿必须排查肿瘤（膀胱镜与CTU）、按时复查尿常规与肾功能、避免剧烈运动与自行停用抗凝药\n\n【饮食】\n充足饮水（每日2000～3000ml，无梗阻与心肾功能限制者）冲刷尿路、减少血块形成\n清淡饮食、避免辛辣刺激与酒类（减少泌尿系刺激）\n结石患者：按结石成分调整饮食（尿酸结石限嘌呤；草酸钙结石限草酸与适量钙）\n肾炎患者：限盐（<3g/日）与适量优质蛋白（按肾功能分期）\n贫血者：富铁食物（红肉、动物肝脏与深绿蔬菜）+ 维生素C促吸收；避免浓茶与咖啡\n\n【注意事项】\n镜下血尿标准：离心尿沉渣红细胞>3个/HP；肉眼血尿需与血红蛋白尿、肌红蛋白尿与药物染色鉴别\n畸形红细胞>70%或红细胞管型提示肾小球性出血（肾炎），需评估蛋白尿与肾功能\n无痛性肉眼血尿是泌尿系肿瘤的典型警示——>40岁患者必须行CTU与膀胱镜（不可仅按'上火'处理）\n抗凝与抗血小板药物相关血尿需评估用药指征（权衡血栓与出血风险），不可自行停药\n剧烈运动后血尿（运动性血尿）多为良性，但需排除其他病因后诊断\n\n【急诊/急救】\n大量血尿伴血块致排尿困难与膀胱填塞 → 立即留置三腔尿管冲洗，必要时膀胱镜清除血块与电凝止血\n血尿伴血压下降与血红蛋白快速下降（活动性大出血）→ 补液输血+介入栓塞或手术探查\n血尿伴少尿与肌酐快速升高（急进性肾炎/急性肾损伤）→ 急诊肾内科评估与肾活检\n血尿伴高热寒战与腰痛（急性肾盂肾炎/脓毒症）→ 血培养+尿培养+静脉抗生素\n外伤后血尿伴腹痛与休克（肾损伤）→ 急诊CT与泌尿外科评估，必要时手术","资料来源":"疾病库 diseases.json；鉴别诊断库 ddx_local.json（条目「血尿（鉴别与处理）」原文）"},"icd10_diagnosis":"R31.9","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2678,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"62665a61cba97067b1dedee4edba3fbd33375bfaeb3873136906c5496a47568e","pinyin":"xueniao(jianbieyuchuli)","initials":"xn(jbycl)","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","R31.9",30]]},{"id":"templates-970ac7035a09df185f04","key":"v1-c9ccc21dfe2a3058|templates-970ac7035a09df185f04","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"血栓性外痔","category":"普通外科临床路径（2019年版）","raw":{"name":"血栓性外痔","category":"普通外科临床路径（2019年版）","case":{"case_name":"门诊病历","templates":{"主诉":"【卫健委临床路径原文】肛门不适、潮湿不洁；发生血栓时，肛门局部剧痛，起病突然。\r2.体格检查：肛门直肠指检，必要时行直肠、乙状结肠硬镜或纤维肠镜检查。\r（三）。\n【待人工确认·本机素材无此段原文】","现病史":"常见表现：肛门不适、潮湿不洁；发生血栓时，肛门局部剧痛，起病突然。\r2.体格检查：肛门直肠指检，必要时行直肠、乙状结肠硬镜或纤维肠镜检查。\r（三）。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"检查计划：患者肛门不适、潮湿不洁，突发肛门局部剧痛、起病急骤，肛门可见暗紫色圆形肿物、触痛明显，结合肛门直肠指检考虑血栓性外痔，拟行手术治疗，入院即刻完善血常规检查了解有无感染、贫血及血小板水平；完善凝血功能检查排除凝血功能障碍，评估手术及麻醉出血风险；完善肝肾功能、电解质检查排除肝肾功能不全及电解质紊乱，评估手术耐受性；完善血糖检查排除糖尿病，为围手术期血糖管理提供依据；完善心电图检查了解心脏情况，评估麻醉手术风险；完善胸部X线片检查排除肺部感染及其他手术禁忌；完善感染性疾病筛查（乙型肝炎、丙型肝炎、艾滋病、梅毒等）检查明确有无血源性传播疾病，做好职业防护及术前准备；完善肛门直肠指检明确血栓位置、范围及有无合并内痔；年龄大于50岁、有大便习惯改变或便血者完善直肠、乙状结肠硬镜或纤维肠镜检查排除结直肠肿瘤、息肉等病变以鉴别诊断；术后定期复查血常规了解有无出血及感染。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"【临床路径·诊断依据】\n诊断依据\r根据《临床诊疗指南\n外科学分册》（中华医学会编著，人民卫生出版社，2006年，第1版）。\r1.临床表现：肛门不适、潮湿不洁；发生血栓时，肛门局部剧痛，起病突然。\r2.体格检查：肛门直肠指检，必要时行直肠、乙状结肠硬镜或纤维肠镜检查。\r（三）\n1. 血栓性外痔（ICD-10：I84.3）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【临床路径·治疗方案的选择】\n治疗方案的选择\r根据《临床诊疗指南\n外科学分册》（中华医学会编著，人民卫生出版社，2006年，第1版）。\r1.一般治疗：包括增加水分摄入及膳食纤维，保持大便通畅，防治便秘和腹泻，温热坐浴，保持会阴清洁等。\r2.手术治疗：血栓性外痔通常伴有明显的疼痛，应急诊手术减压、去除血栓。\r（四）","临床路径·进入路径标准":"进入路径标准\r1.第一诊断必须符合ICD-10：I84.3血栓性外痔疾病编码。\r2.当患者同时具有其他疾病诊断，但在住院期间不需特殊处理也不影响第一诊断的临床路径流程实施时，可以进入路径。\r（六）术前准备（术前评估）1天\r1.所必须的检查项目：\r（1）血常规、尿常规；\r（2）肝肾功能、电解质、凝血功能、血型、感染性疾病筛查（乙型肝炎、丙型肝炎、梅毒、艾滋病等）；\r（3）心电图、X线胸片。\r2.必要时行直肠、乙状结肠硬镜或纤维肠镜检查。\r（七）预防性抗菌药物选择与使用时机\r预防性抗菌药物：按照《抗菌药物临床患者指导原则》（卫医发〔2015〕43号）执行，并结合患者的病情决定抗菌药物的选择。\r（八）手术日为入院当天\r1.麻醉方式：局部麻醉、蛛网膜下腔麻醉、连续硬膜外麻醉或硬膜外蛛网膜下腔联合阻滞麻醉。\r2.急诊手术行血栓性外痔切除术。\r3.术后标本送病理。\r（九）术后住院恢复2天\r1.局部麻醉患者术后即可进食，半小时后可下床活动、进食。\r2.连续硬膜外麻醉或腰硬联合麻醉者术后去枕平卧、禁食、禁水6小时，补液治疗；术后6小时可下床活动，可进流质饮食。\r3.每天切口换药1～2次，创面较深时，放置纱条引流并保持引流通畅。\r4.术后用药：局部用药（栓剂、膏剂、洗剂）、口服药、物理治疗等。\r5.术后异常反应处理：\r（1）疼痛处理：酌情选用镇静药、镇痛药、患者自控镇痛泵等。\r（2）术后尿潴留的预防及处理：理疗、针灸、局部封闭、导尿等。\r（3）伤口渗血处理：换药、出血点压迫，使用止血剂。\r（4）排便困难：软化大便药物口服，必要时诱导灌肠。\r（5）创面水肿：使用局部或全身消水肿药。\r（6）术后继发性大出血的处理。\r（7）其他情况处理：呕吐、发热、头痛等，对症处理。\r（十）","临床路径·标准住院日":"标准住院日为3天\r（五）","临床路径·出院标准":"出院标准\r1.患者一般情况良好，正常饮食，排便顺畅，无明显排便时肛门疼痛，各项实验室检查结果正常，体温正常。\r2.肛门部创面无异常分泌物，引流通畅，无明显水肿、出血。\r（十一）","临床路径·变异及原因分析":"变异及原因分析\r1.手术后出现继发切口感染或持续性大出血等并发症时，导致住院时间延长与费用增加。\r2.伴发其他\n汾\n〽\n伀\n倀\n愀\n漀\n癢\n伀\n倀\n愀\n漀\n虝\n伀\n倀\n愀\n漀\n襨灿\n脈\n襨灿\n伀\n倀\n儀\n愀\n漀\n戀\n伀\n倀\n漀\n硨攟\n脈\n伀\n倀\n儀\n尀脈\n瀁h\n癢\n脈\n伀\n倀\n儀\n尀脈\n瀁h\n襨灿\n癢\n脈\n伀\n倀\n儀\n尀脈\n瀁h\n襨灿\n脈\n伀\n倀\n儀\n尀脈\n瀁h\n虝\n脈\n,\n,\n萑\n搒\n葠\n摧拍v\n萑\n搒\n葠\n摧\n萑\n搒\n葠\n摧羉p\n肄\n桤\n圀\n怀肄朂襤灿洀\n搒\n摧\n搒\n朁襤灿洀\n躞\n黢黢波黢岮躞\n繾\n虝\n伀\n倀\n愀\n漀\n癢\n伀\n倀\n儀\n愀\n漀\n癢\n癢\n伀\n倀\n愀\n漀\n虝\n癢\n伀\n倀\n愀\n漀\n虝\n伀\n倀\n愀\n漀\n襨灿\n脈\n使\n瀁ｨ\n癢\n伀\n倀\n愀\n漀\n伀\n倀\n愀\n漀\n伀\n倀\n愀\n漀\n隳沁\n譨\n癢\n瀁h\n譨\n瀁h\n譨\n伀\n倀\n愀\n漀\n婈\n伀\n倀\n愀\n漀\n笠\n伀\n倀\n愀\n漀\n襨灿\n脈\n虝\n伀\n倀\n愀\n漀\n伀\n倀\n愀\n漀\n伀\n倀\n愀\n漀\n萑\n搒\n葠\n摧\n萑\n搒\n葠\n摧羉p\n骬趬肬聰\n骬\n趬趬\n渽\n伀\n倀\n儀\n愀\n漀\n虝\n輶\n伀\n倀\n愀\n漀\n輶\n伀\n倀\n愀\n漀\n婈\n伀\n倀\n愀\n漀\n襨灿\n脈\n虝\n伀\n倀\n愀\n漀\n伀\n倀\n愀\n漀\n譨\n伀\n倀\n愀\n漀\n譨\n瀁h\n癢\n瀁h\n鮛鮛鮛鮛鮛鮛鮛鮛鮛\n詨\n脈\n脈\n表\n伀\n倀\n愀\n漀\n唃\n襨灿\n脈\n婈\n伀\n倀\n愀\n漀\n伀\n倀\n愀\n漀\n虝\n伀\n倀\n愀\n漀\n萑\n葠\n摧拍v\n萑\n搒\n葠\n摧\n萑\n搒\n葠\n摧羉p\n基础疾病需要进一步明确诊断，导致住院时间延长与费用增加。\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r二、血栓性外痔","资料来源":"国家卫健委《224个病种临床路径（2019年版）》（国卫办医函〔2019〕933号）· 普通外科临床路径（2019年版） · 血栓性外痔临床路径（2019年版）.doc"},"icd10_diagnosis":"I84.3","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2679,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"8673f2b2905fcbd2cab59602d8471a5b835a8a53c2fe0c550886b7626ff2448a","pinyin":"xueshuanxingwaizhi","initials":"xsxwz","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","临床路径·进入路径标准","临床路径·标准住院日","临床路径·出院标准","临床路径·变异及原因分析","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 临床路径·进入路径标准 临床路径·标准住院日 临床路径·出院标准 临床路径·变异及原因分析 资料来源",30],["主要诊断编码","I84.3",30]]},{"id":"templates-71a75727db15fb4fe272","key":"v1-c9ccc21dfe2a3058|templates-71a75727db15fb4fe272","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"血证(中医辨证)","category":"中医","raw":{"name":"血证(中医辨证)","category":"中医","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】热盛迫血：出血量多，血色鲜红，面赤烦躁，口渴，口苦，小便黄，大便干，舌红苔黄，脉数或滑数、阴虚火旺：出血量少，血色鲜红，口干咽燥，五心烦热，潮热盗汗，舌红少苔，脉细数、气虚不摄：反复出血，血色淡红，神疲乏力，气短懒言，面色苍白或萎黄，食少便溏，舌淡苔薄白，脉细弱。\n【待人工确认·本机素材无此段原文】","现病史":"凡血液不循常道，或上溢于口鼻诸窍，或下泄于前后二阴，或渗出于肌肤所形成的疾患，统称血证。包括鼻衄、齿衄、咳血、吐血、便血、尿血、紫斑等。分热盛迫血、阴虚火旺、气虚不摄等证型。可见于血液病、消化道出血、泌尿系出血、过敏性疾病等。\n常见表现：热盛迫血：出血量多，血色鲜红，面赤烦躁，口渴，口苦，小便黄，大便干，舌红苔黄，脉数或滑数、阴虚火旺：出血量少，血色鲜红，口干咽燥，五心烦热，潮热盗汗，舌红少苔，脉细数、气虚不摄：反复出血，血色淡红，神疲乏力，气短懒言，面色苍白或萎黄，食少便溏，舌淡苔薄白，脉细弱。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：体温、脉搏、呼吸、血压\n望诊：神、色（青/赤/黄/白/黑）、形态、头面、五官、躯体、舌诊（舌质/舌苔/舌底络脉）、排泄物\n闻诊：声音（语声/呼吸/咳嗽/呃逆/嗳气/肠鸣）、气味\n问诊：一般情况、主诉、现病史、既往史、个人史、家族史、十问歌\n切诊：脉诊（浮沉迟数虚实滑涩洪细濡弱弦紧结代促）、按诊（肌肤/手足/胸腹/腧穴）\n辨证：八纲辨证、脏腑辨证、气血津液辨证、经络辨证","辅助检查":"检查计划：患者以鼻衄、齿衄、咳血、吐血、便血、尿血或肌肤紫斑等出血为主症，症见出血量多、血色鲜红、面赤烦躁、口渴口苦，或出血量少、口干咽燥、五心烦热、潮热盗汗，或反复出血、血色淡红、神疲乏力、气短懒言、面色苍白，结合中医辨证属热盛迫血、阴虚火旺、气虚不摄之血证，可见于血液病、消化道出血、泌尿系出血、过敏性疾病等，大出血伴休克者立即急诊抢救并完善检查，入院即刻完善血常规检查了解出血程度、有无贫血及血小板减少；完善凝血功能检查排除凝血功能障碍所致出血；完善肝肾功能检查排除肝病及尿毒症所致出血，并为用药安全提供依据；完善血型鉴定及交叉配血检查为紧急输血做好准备；根据出血部位选择检查，便血、吐血者完善大便隐血、胃镜检查明确有无消化性溃疡、食管胃底静脉曲张及消化道肿瘤；尿血者完善尿常规、泌尿系超声检查排除泌尿系结石、肿瘤及感染；咳血者完善胸部X线片或胸部CT检查排除肺结核、支气管扩张及肺部肿瘤；鼻衄者完善鼻内镜检查明确鼻腔局部病因；皮肤紫斑、血细胞异常者完善骨髓穿刺检查明确有无血液系统疾病；完善腹部B超检查了解肝脾有无肿大；定期复查血常规、凝血功能检查了解病情变化及治疗效果。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 以出血（衄血/咳血/吐血/便血/尿血/紫斑）为主症\n2. 血常规、凝血功能、肝肾功能、B超、胃镜等明确出血原因\n3. 大出血伴休克者立即急诊抢救\n1. 血证(中医辨证)（ICD-10：D69.9）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！\n\n方案1：\n 用法：一般不需输液，以口服中药为主\n\n方案2（症状较重/脱水明显）：\n 用法：NS500ml+维生素C2.0g+维生素B6 0.2g ivgtt qd\n\n方案3（合并细菌感染）：\n 用法：NS250ml+头孢呋辛3.0g ivgtt bid（皮试后）\n\n📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！\n\n📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。\n\n药物1（热盛迫血）：云南白药胶囊2粒 tid（出血期），或槐角丸6g tid（便血）\n药物2（阴虚火旺）：知柏地黄丸6g bid，或二至丸6g bid\n药物3（气虚不摄）：归脾丸6g tid，或补中益气丸6g tid\n药物4（配合）：酚磺乙胺0.5g tid（遵医嘱），维生素K1 10mg im qd（凝血障碍时）\n\n【治疗】\n热盛迫血：清热泻火，凉血止血，十灰散加减\n阴虚火旺：滋阴降火，凉血止血，茜根散加减\n气虚不摄：益气摄血，归脾汤加减\n\n【处理要点】\n出血期卧床休息，监测生命体征\n饮食清淡，忌辛辣刺激及过热食物\n保持大便通畅，避免用力\n\n【护理】\n病情观察：密切观察出血部位、颜色、量及伴随症状；吐血、便血者每日观察大便颜色（黑便提示上消化道出血），咳血者取头偏向一侧、保持气道通畅防血块窒息；若出血量多伴头晕心悸、面色苍白、四肢厥冷、脉细数，为气随血脱之兆，须立即报告并取平卧位、防搬动。\n起居调护：出血活动期绝对卧床静养，减少活动与搬动；血热妄行者居室宜凉爽通风，忌高温燥热环境；气虚不摄者注意保暖避风寒，防感冒诱发再出血；阴虚火旺者忌熬夜、劳神、剧烈运动，保证充足睡眠以养阴制火。\n情志护理：血证患者多因出血而恐惧焦虑，情志过激（尤其暴怒）易动火迫血妄行而加重出血；应主动安抚疏导，讲明病情与预后，嘱其静心休养、避免情绪波动与言语过多。\n煎药服药护理：止血药一般不宜久煎，凉血止血之剂宜温凉服、徐徐咽下；鼻衄、齿衄者服药后忌立即用力擤鼻或刷牙；吐血者汤药宜少量频服，服药后半小时内卧床静养并观察有无呕血。\n外治护理：鼻衄发作时取坐位、头略前倾，以冷毛巾或冰袋敷额部及鼻根部，用云南白药或血余炭棉球填塞止血；齿衄可用白茅根、仙鹤草煎水含漱；紫斑（肌衄）局部冷敷，忌热敷、搔抓及磕碰。\n\n【饮食】\n辨证忌口：血热妄行者忌辛辣燥烈及温补动血之品（辣椒、酒、羊肉、狗肉、桂圆、人参、煎炸烧烤）；阴虚火旺者忌辛辣温燥助火之品（生姜、花椒、韭菜、烟酒）；气虚不摄者忌生冷寒凉伤脾之品；瘀血内阻者忌滋腻碍胃之品。\n血热妄行宜清凉止血：可食鲜藕汁、荸荠、梨、甘蔗、马齿苋、芹菜、黑木耳；药膳用鲜藕节、白茅根、侧柏叶煎汤代茶饮。\n阴虚火旺宜滋阴凉血：可食银耳、百合、甲鱼、枸杞、桑葚；药膳如二鲜饮（鲜藕、鲜白茅根捣汁频饮）、百合银耳羹、生地黄粥。\n气虚不摄宜健脾益气摄血：可食山药、莲子、大枣、红衣花生（花生衣）、牛肉；药膳如花生衣红枣汤、山药莲子粥，出血停止后可用黄芪炖母鸡补气摄血。\n便血者宜半流质少渣饮食，忌粗硬、辛辣刺激之品；尿血者忌酒及辛辣，多饮水；服汤药期间忌浓茶及萝卜等解药之品。\n\n【注意事项】\n大出血（呕血、便血量大、咯血）立即转急诊\n反复出血需血液科/消化科进一步检查\n服抗凝药者调整用药\n\n【急诊/急救】\n一般不需急救\n症状加重伴休克/昏迷：立即急救处理\n反复发作/黑便/消瘦：转上级医院进一步检查","资料来源":"疾病库 diseases.json","中医辨证参考":"首次病程记录\n\n拟诊讨论：\n\n【中医辨证参考】血证\n⚠️ 本条为通用辨证参考，尚未逐条核对教材原文，请务必结合患者实际四诊资料，\n   并核对相应教材（中医外科学/中医儿科学/中医内科学）后再使用；\n   方剂仅列组成药味，具体剂量请依药典、患者体质及本院药房规格确定。\n\n一、热盛迫血\n    症状舌脉：出血势急、量多色鲜红，伴发热口渴、烦躁、便秘尿黄；舌红苔黄，脉弦数\n    治法：清热泻火、凉血止血\n    方剂：泻心汤合十灰散加减（大黄、黄连、黄芩、大蓟、小蓟、荷叶、侧柏叶、白茅根、茜草根、棕榈皮、牡丹皮、栀子）\n\n二、阴虚火旺\n    症状舌脉：出血反复发作，量少色红，伴午后潮热、盗汗、五心烦热、腰膝酸软；舌红少苔，脉细数\n    治法：滋阴降火、宁络止血\n    方剂：茜根散加减（茜草根、黄芩、阿胶、侧柏叶、生地黄、甘草）\n\n三、气虚不摄\n    症状舌脉：出血反复不止，色淡质稀，伴面色㿠白、神疲乏力、气短懒言、头晕心悸；舌淡苔薄白，脉细弱\n    治法：益气摄血\n    方剂：归脾汤加减（人参、黄芪、白术、当归、茯神、远志、酸枣仁、龙眼肉、木香、甘草、生姜、大枣）\n\n四、瘀血阻络\n    症状舌脉：出血紫暗有块，伴刺痛固定、肌肤瘀斑；舌质紫暗或有瘀点，脉涩\n    治法：活血化瘀、止血\n    方剂：血府逐瘀汤加减（桃仁、红花、当归、川芎、赤芍、牛膝、柴胡、桔梗、枳壳、生地黄、甘草）\n\n【西医诊断】\n  出血性疾病（按出血部位分类）\n  （西医诊断依据与鉴别诊断请结合患者病史、体征、辅助检查补充）\n\n⚠️ **出血量大或伴血流动力学不稳定须立即急诊**（输血、内镜/介入止血）；本条仅供辨证参考\n\n医师签名：＿＿＿＿"},"icd10_diagnosis":"D69.9","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2680,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"f2cb2084e34503ec9f34557700ac9c91d7c3b80633a45414703dd8dd13aca9d0","pinyin":"xuezheng(zhongyibianzheng)","initials":"xz(zybz)","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源","中医辨证参考"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源 中医辨证参考",30],["主要诊断编码","D69.9",30]]},{"id":"templates-31aad2daeb1adf556ffc","key":"v1-c9ccc21dfe2a3058|templates-31aad2daeb1adf556ffc","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"表皮囊肿","category":"烧伤整形科","raw":{"name":"表皮囊肿","category":"烧伤整形科","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】圆形或卵圆形结节，质地中等硬、表面皮肤正常，可与皮肤粘连、好发于头面部、颈部、躯干、生长缓慢，一般无自觉症状、继发感染时可出现红肿、疼痛。\n【待人工确认·本机素材无此段原文】","现病史":"表皮囊肿是一种良性皮肤附属器肿瘤，又名角质囊肿，系毛囊漏斗部的囊肿，囊壁由表皮构成，囊内为角质物。\n常见表现：圆形或卵圆形结节，质地中等硬、表面皮肤正常，可与皮肤粘连、好发于头面部、颈部、躯干、生长缓慢，一般无自觉症状、继发感染时可出现红肿、疼痛。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"检查计划：患者头面部、颈部、躯干出现圆形或卵圆形结节，质地中等硬、表面皮肤正常、生长缓慢且一般无自觉症状，为明确肿块性质、大小、边界、深度及其与皮肤的粘连关系，查体表肿物彩色多普勒超声了解结节是否位于皮下、有无囊性成分及血流信号，必要时与脂肪瘤、神经纤维瘤等体表肿物鉴别；患者结节可与皮肤粘连，若近期出现红肿、疼痛提示继发感染，入院即查血常规、CRP 排除继发细菌感染，必要时行囊内容物或脓液细菌培养加药敏试验，指导抗菌药物选择；本病确诊依赖组织病理，其囊壁由复层鳞状上皮构成、囊内为角质物，故术后将切除标本送组织病理检查明确诊断，并排除钙化上皮瘤、皮样囊肿等其他皮肤附属器肿瘤；患者拟行手术切除，术前完善凝血功能检查排除凝血功能障碍所致术中术后出血风险，查肝肾功能、血糖了解代谢与脏器功能状态，评估手术与麻醉耐受性；查乙肝五项、丙肝抗体、人类免疫缺陷病毒抗体、梅毒螺旋体抗体等感染筛查，既是择期手术前的常规要求，也为术中职业防护提供依据；查心电图、胸部 X 线检查评估心肺功能，排除手术麻醉禁忌；术后定期复查切口愈合情况，若出现红肿渗液及时复查血常规、CRP，了解有无切口感染。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 圆形或卵圆形结节，质地中等硬\n2. 表面皮肤正常，可与皮肤粘连\n3. 好发于头面部、颈部、躯干\n4. 组织病理：囊壁由复层鳞状上皮构成，囊内为角质物\n1. 表皮囊肿（ICD-10：L72.0）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【药物治疗·输液】\n继发感染时：抗生素治疗\n\n【药物治疗·口服】\n继发感染时：头孢类或青霉素类抗生素\n\n【治疗】\n一般无需治疗\n手术切除（完整切除囊壁，避免复发）\n继发感染时先抗感染治疗，炎症消退后再手术切除\n不要自行挤压，以免感染或形成瘢痕\n\n【处理要点】\n避免搔抓、挤压\n保持局部清洁\n出现红肿、疼痛时及时就医\n手术切除后注意伤口护理，防止感染\n\n【注意事项】\n本病为良性肿瘤，手术切除后预后良好\n手术时需完整切除囊壁，否则易复发\n避免自行挤压，以免感染或形成瘢痕\n\n【急诊/急救】\n囊肿继发感染、脓肿形成时需切开引流","资料来源":"疾病库 diseases.json"},"icd10_diagnosis":"L72.0","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2681,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"4dcbf5d814c573d9455021b6345184c73b21c4eaf57bd7c22c4d91c1d4236283","pinyin":"biaopinangzhong","initials":"bpnz","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","L72.0",30]]},{"id":"templates-c10411a1b04c59763989","key":"v1-c9ccc21dfe2a3058|templates-c10411a1b04c59763989","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"角膜裂伤","category":"眼科临床路径（2019年版）","raw":{"name":"角膜裂伤","category":"眼科临床路径（2019年版）","case":{"case_name":"门诊病历","templates":{"主诉":"【待人工确认·本机素材无此段原文】","现病史":"【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"检查计划：患者有明确眼部外伤史并出现眼部刺激症状，入院即刻查视力、眼压及裂隙灯显微镜检查，明确角膜裂伤为板层还是全层、裂伤口大小与位置、有无前房形成不良及虹膜嵌顿；因眼球外伤常合并眼后段损伤，屈光介质混浊时查眼部 B 超了解玻璃体、视网膜情况，排除玻璃体积血、视网膜脱离及眼内异物；怀疑眼内异物或眶壁骨折时急诊行眼眶及头颅 CT 检查，明确异物性质、位置与有无眶骨骨折、颅内损伤，考虑金属异物时禁行磁共振检查，以免异物移位造成二次损伤；查眼前节光学相干断层扫描（AS-OCT）及角膜地形图评估裂伤深度与角膜形态，为手术缝合方式提供依据；查超声生物显微镜（UBM）了解房角、睫状体有无损伤及隐匿性异物；患者拟急诊行角膜裂伤缝合术，术前完善血常规、凝血功能排除感染与凝血异常，查肝肾功能、血糖评估手术与麻醉耐受性；查乙肝五项、丙肝抗体、人类免疫缺陷病毒抗体、梅毒螺旋体抗体等感染筛查，查心电图、胸部 X 线检查评估心肺功能；术后定期复查裂隙灯、眼压及视力，了解伤口愈合情况，排除外伤性白内障、继发性青光眼及交感性眼炎等并发症。\n\n（检查清单）\n【临床路径·住院期间检查项目】\n住院期间检查项目\n1.","初步诊断":"【临床路径·诊断依据】\n诊断依据\n根据《临床诊疗指南\n眼科学分册》（中华医学会编著，人民卫生出版社，2006年版，第1版）。\n1.眼部外伤史。\n2.症状：眼部刺激症状。\n3.体征：角膜板层或者全层裂伤伴或不伴前房形成不良。\n（三）\n1. 角膜裂伤（ICD-10：S05.302）","鉴别诊断":"1. （1）排除其他危及患者生命的疾病\n2. 1.手术前准备：肌注破伤风抗毒素，排除角膜全层裂伤后可以清洁结膜囊，角膜全层裂伤患者硬质眼罩保护眼部，并注意勿采用任何可能对眼球加压的操作","处理方案":"【临床路径·治疗方案的选择】\n治疗方案的选择\n根据《临床诊疗指南\n眼科学分册》（中华医学会编著，人民卫生出版社，2006年版，第1版）。\n行角膜裂伤缝合术（ICD-9-CM-3：11.51）。\n（四）","临床路径·进入路径标准":"进入路径标准\n1.第一诊断符合ICD-10：H05.302角膜全层裂伤疾病编码。\n2.当患者同时具有其他疾病诊断，但在住院期间不需要特殊处理，也不影响第一诊断的临床路径流程实施时，可以进入路径。\n（六）","临床路径·标准住院日":"标准住院日为5～6天\n（五）","临床路径·出院标准":"出院标准\n1. 无感染迹象、角膜伤口闭合，前房形成。\n2.没有需要住院处理的并发症和（或）合并症。\n（十一）","临床路径·变异及原因分析":"变异及原因分析\n1.角膜伤口对合欠佳，需要二次缝线调整的；角膜部分缺损需要再行修补手术，或者角膜、羊膜移植的。\n2.治疗中角膜伤口愈合延期，或因炎症反应加重或前房出血等合并症，进行相关的诊断和治疗，并适当延长住院时间。\n3.若眼部CT显示有明确球内异物，合并眼内容物脱出、晶体损伤或术后炎症反应进行性加重，有眼内炎趋势，或者需要特殊处理的眼后段损伤或虹膜睫状体损伤，退出此路径，进入相关途径。\n4.依据患者情况及伤情需要决定是否需要进行全身麻醉。\n5. 伴前房形成不良的术中会做前房成形术，则会出路径。","资料来源":"鉴别诊断库 ddx_local.json（条目「角膜裂伤」原文）；国家卫健委《224个病种临床路径（2019年版）》（国卫办医函〔2019〕933号）· 眼科临床路径（2019年版） · 角膜裂伤临床路径（2019年版）.docx"},"icd10_diagnosis":"S05.302","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2682,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"57a03073016d625a42a433b7a78e5f0a4e3fa7c4f3aa2abe3a8a49dfa6c101ad","pinyin":"jiaomolieshang","initials":"jmls","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","临床路径·进入路径标准","临床路径·标准住院日","临床路径·出院标准","临床路径·变异及原因分析","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 临床路径·进入路径标准 临床路径·标准住院日 临床路径·出院标准 临床路径·变异及原因分析 资料来源",30],["主要诊断编码","S05.302",30]]},{"id":"templates-ee3e384175c8b063372a","key":"v1-c9ccc21dfe2a3058|templates-ee3e384175c8b063372a","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"计划性剖宫产","category":"妇产科临床路径（2019年版）","raw":{"name":"计划性剖宫产","category":"妇产科临床路径（2019年版）","case":{"case_name":"门诊病历","templates":{"主诉":"【待人工确认·本机素材无此段原文】","现病史":"【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"检查计划：患者为计划性剖宫产、择期手术，术前需全面评估母体状况与胎儿宫内情况。查血常规了解有无贫血、血小板减少及感染征象，为手术与备血提供依据；查尿常规排除泌尿系统感染及妊娠期高血压疾病所致蛋白尿；查凝血功能（凝血酶原时间、活化部分凝血活酶时间、纤维蛋白原、D-二聚体）排除凝血功能障碍，为术中止血与麻醉方式选择提供依据；查肝肾功能排除妊娠期肝内胆汁淤积症及肝肾疾病，评估麻醉与手术耐受性；查空腹血糖及口服葡萄糖耐量试验排除妊娠期糖尿病，了解血糖控制水平；查甲状腺功能排除甲状腺功能异常对母体与胎儿的影响；查血型及不规则抗体筛查并备血，为术中出血做准备；查乙肝五项、丙肝抗体、人类免疫缺陷病毒抗体、梅毒螺旋体抗体等感染筛查，明确有无母婴传播风险并指导新生儿处理；查心电图评估心脏情况，必要时查心脏彩超；产科彩色多普勒超声明确胎位、胎盘位置、羊水量、胎儿大小及有无前置胎盘、胎盘植入，脐动脉血流了解胎儿宫内储备；定期行胎心监护（无应激试验）评估胎儿宫内状况，必要时查胎儿生物物理评分；查双下肢血管彩超排除妊娠期高凝状态所致下肢深静脉血栓。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"【临床路径·诊断依据】\n诊断依据\r根据《剖宫产手术的专家共识》[中华医学会妇产科学分会产科学组，中华妇产科杂志，2014，49（10）：721-724]。\r（三）\n1. 计划性剖宫产","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【临床路径·治疗方案的选择】\n选择治疗方案的依据\r根据《剖宫产手术的专家共识》[中华医学会妇产科学分会产科学组，中华妇产科杂志，2014，49（10）：721-724]。\r1.慢性胎儿窘迫。\r2.头盆不称。\r3.胎位异常。\r4.孕妇存在严重合并症和并发症。\r5.骨盆及产道异常，无法经阴道分娩。\r6.瘢痕子宫。\r7.前置胎盘及前置血管。\r8.双胎或多胎妊娠。\r9.孕妇要求的剖宫产。\r10.妊娠巨大儿者。\r11.外阴疾病。\r12.生殖道严重的感染性疾病。\r13.妊娠合并肿瘤。\r（四）\n\n【临床路径·选择用药】\n选择用药\r1.按《抗菌药物临床患者指导原则》（卫医发〔2015〕43号）执行，剖宫产（\n类切口）的抗菌药物为预防性用药。 \r2.抗菌药物选择第一代或第二代头孢类。\r3.预防性用药时间为手术前30～120分钟，也可在断脐后使用。\r（八）手术日为入院第 2天\r1.麻醉方式：硬膜外或腰硬联合麻醉。\r2.手术方式：子宫下段剖宫产术。\r3.术中用药：缩宫素10～20U，抗菌药物。\r4.输血：必要时输血。\r5.新生儿处理：断脐、保暖、清理呼吸道等常规处理。\r（九）术后住院恢复\n7 天\r1.必须复查的检查项目：血常规。\r2.术后用药：抗菌药物，缩宫药物。\r3.预防性抗菌药物：第一代或第二代头孢类，术后72小时内停止使用。\r（十）","临床路径·进入路径标准":"进入路径标准\r1.第一诊断为首选治疗方案符合ICD-9-CM-3：74.1子宫下段剖宫产术手术编码者。\r2.孕妇患有其他疾病时，但在住院期间不需特殊处理，也不影响第一诊断的临床路径流程，可以进入路径。\r（六）术前准备（术前评估）0～2天\r所必须的检查项目：\r1.血常规、尿常规。 \r2.凝血功能、肝肾功能、交叉配血\r3.感染性疾病筛查（孕期未筛查的乙型肝炎、丙型肝炎、艾滋病、梅毒等）。\r4.心电图、胎心监护\r5.其他根据病情需要而定。\r（七）","临床路径·标准住院日":"标准住院日为9 天\r（五）","临床路径·出院标准":"出院标准\r1.一般状况良好，体温正常。\r2.血常规基本正常。\r3.切口愈合良好。\r4.子宫复旧良好，恶露正常。\r（十一）有无","临床路径·变异及原因分析":"变异及原因分析\r1.孕妇原因延期手术。\r2.子宫复旧不良，并发阴道流血过多。\r3.并发产褥感染。\r4.切口延期愈合。\r5.其他并发症。\r\f二、计划性剖宫产","资料来源":"国家卫健委《224个病种临床路径（2019年版）》（国卫办医函〔2019〕933号）· 妇产科临床路径（2019年版） · 计划性剖宫产临床路径（2019年版）.doc"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2683,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"2db86cbb132d93164544d6e411981db0f3756f4dc705735c3e039a79cf30cb01","pinyin":"jihuaxingpougongchan","initials":"jhxpgc","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","临床路径·进入路径标准","临床路径·标准住院日","临床路径·出院标准","临床路径·变异及原因分析","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 临床路径·进入路径标准 临床路径·标准住院日 临床路径·出院标准 临床路径·变异及原因分析 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-ed4428af671234e32562","key":"v1-c9ccc21dfe2a3058|templates-ed4428af671234e32562","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"贫血的鉴别诊断与处理思路","category":"内科-血液","raw":{"name":"贫血的鉴别诊断与处理思路","category":"内科-血液","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】乏力、头晕、活动后心悸气短、注意力不集中与睡眠障碍、面色与结膜苍白、指甲苍白脆薄、口角炎与舌炎（缺铁、营养性）、溶血表现：黄疸、脾大、酱油色尿（血红蛋白尿）、胆石症、出血表现：皮肤瘀点瘀斑、牙龈与鼻腔出血、黑便（合并血小板或凝血异常）、原发病表现：消瘦（肿瘤）、发热（感染/血液病）、骨痛（骨髓瘤）、水肿（肾病）、神经症状（维生素B12缺乏）。\n【待人工确认·本机素材无此段原文】","现病史":"贫血是外周血血红蛋白低于正常下限（成年男性<120g/L、女性<110g/L、孕妇<100g/L）的临床综合征。鉴别诊断按红细胞形态（MCV）分为小细胞性（缺铁、地中海贫血、慢性病贫血）、正细胞性（急性失血、溶血、肾性贫血、骨髓病性）与大细胞性（巨幼细胞贫血、MDS、肝病、甲减），据病因治疗。\n常见表现：乏力、头晕、活动后心悸气短、注意力不集中与睡眠障碍、面色与结膜苍白、指甲苍白脆薄、口角炎与舌炎（缺铁、营养性）、溶血表现：黄疸、脾大、酱油色尿（血红蛋白尿）、胆石症、出血表现：皮肤瘀点瘀斑、牙龈与鼻腔出血、黑便（合并血小板或凝血异常）、原发病表现：消瘦（肿瘤）、发热（感染/血液病）、骨痛（骨髓瘤）、水肿（肾病）、神经症状（维生素B12缺乏）。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：心率（贫血代偿增快）、血压、呼吸（气促）、体温（感染/淋巴瘤）\n一般情况：面色与结膜苍白程度、营养状态、消瘦（肿瘤）、发育（儿童）\n皮肤黏膜：口角炎与舌炎（缺铁）、牛肉舌与舌面光滑（B12缺乏）、黄疸（溶血）、瘀点瘀斑（血小板减少）、反甲\n心脏：心界扩大、心率增快、贫血性收缩期杂音、心衰体征\n腹部：肝脾大小（溶血、MDS、淋巴瘤）、腹块（肿瘤）\n神经系统：深感觉减退、Romberg征、振动觉与位置觉（B12缺乏致亚急性联合变性）、病理反射\n淋巴结与骨：淋巴结肿大（淋巴瘤）、骨压痛（骨髓瘤/白血病）","辅助检查":"1. 血常规+红细胞形态（MCV、MCH、MCHC）+网织红细胞：贫血分类第一步\n2. 铁代谢（血清铁、铁蛋白、总铁结合力、TSAT）：缺铁性贫血与慢性病贫血鉴别\n3. 维生素B12+叶酸+同型半胱氨酸+甲基丙二酸（必要时）：巨幼细胞贫血诊断\n4. 溶血全套：间接胆红素、LDH、结合珠蛋白、网织红细胞、Coombs试验、红细胞脆性试验、G6PD活性、血红蛋白电泳\n5. 粪便隐血+消化道内镜（必要时）+妇科检查：失血来源（消化道肿瘤、月经过多）\n6. 骨髓穿刺+活检+铁染色+细胞遗传学：骨髓病性贫血、MDS、白血病与再障\n7. 肾功能+促红素水平+甲状腺功能+肝功能：肾性贫血、内分泌疾病与肝病性贫血","初步诊断":"1. 血常规+红细胞形态（MCV、MCH、MCHC）+网织红细胞计数：贫血分类与骨髓代偿能力评估（第一步）\n2. MCV分类：小细胞（MCV<80fl）、正细胞（80～100fl）、大细胞（>100fl）\n3. 铁代谢（血清铁、铁蛋白、总铁结合力、转铁蛋白饱和度）：缺铁性贫血（铁蛋白<15ng/ml）与其他小细胞贫血鉴别\n4. 维生素B12+叶酸+同型半胱氨酸：巨幼细胞贫血\n5. 溶血相关：网织红细胞升高、间接胆红素升高、LDH升高、结合珠蛋白降低、Coombs试验、红细胞脆性试验、G6PD活性\n6. 骨髓穿刺+活检+铁染色：骨髓病性贫血、MDS、白血病与再生障碍性贫血（必要时）\n7. 器官功能与病因筛查：肾功能（肾性贫血）、肝功能、甲状腺功能、粪便隐血+消化道内镜（失血）、妇科检查（月经过多）\n8. 促红细胞生成素（EPO）水平：肾性贫血与再障鉴别（必要时）\n1. 贫血的鉴别诊断与处理思路（ICD-10：D64.9）","鉴别诊断":"1. 铁代谢（血清铁、铁蛋白、总铁结合力、转铁蛋白饱和度）：缺铁性贫血（铁蛋白<15ng/ml）与其他小细胞贫血鉴别\n2. 促红细胞生成素（EPO）水平：肾性贫血与再障鉴别（必要时）\n3. 贫血鉴别第一步是红细胞形态（MCV）与网织红细胞计数，其次按分类选择铁代谢、B12/叶酸、溶血与骨髓检查\n4. 鉴别诊断按红细胞形态（MCV）分为小细胞性（缺铁、地中海贫血、慢性病贫血）、正细胞性（急性失血、溶血、肾性贫血、骨髓病性）与大细胞性（巨幼细胞贫血、MDS、肝病、甲减），据病因治疗","处理方案":"【药物治疗·输液】\n⚠️ 按病因治疗，输血指征需严格掌握！\n\n方案1（重度贫血输血，Hb<60g/L或有症状）：\n 用法：红细胞悬液 1～2U 静滴（目标Hb 70～90g/L，冠心病者80～100g/L）；缓慢输注并监测生命体征（防容量负荷）\n\n方案2（缺铁性贫血，静脉铁剂，口服不耐受或吸收障碍者）：\n 用法：蔗糖铁 100～200mg + 0.9%氯化钠 100ml 静滴（>30分钟，每周1～3次）；按铁缺乏量计算总剂量（常用1000mg）\n\n方案3（巨幼细胞贫血，重度或吸收障碍）：\n 用法：维生素B12 1000μg 肌注 qd×1周 → 每周1次；叶酸 5mg 口服/静滴（注意先补B12再补叶酸，避免加重神经症状）\n\n方案4（病因治疗与支持）：\n 用法：0.9%氯化钠 静滴（维持通路与补液）；肾性贫血用促红素（见肾性贫血条目）；溶血性贫血用激素（甲泼尼龙 40～80mg 静滴，免疫性溶血）；慢性病贫血治疗原发病\n\n📌 贫血治疗必须先明确病因（不可盲目补铁与输血）；输血目标是缓解症状而非纠正数值；免疫性溶血禁用输血（除危急情况）。\n\n【药物治疗·口服】\n⚠️ 按病因选择（同类只选一种）：\n\n药物1（缺铁性贫血）：\n 用法：琥珀酸亚铁 0.1g bid～tid（餐间服）+ 维生素C 0.2g tid（促进吸收）；或多糖铁复合物 150mg qd\n\n药物2（巨幼细胞贫血）：\n 用法：维生素B12 500μg 肌注 每月1次（终身，吸收障碍者）；叶酸 5mg qd\n\n药物3（肾性贫血/慢性病贫血）：\n 用法：罗沙司他 100mg tiw（按体重）；促红素（皮下注射）；铁剂按铁代谢补充\n\n药物4（辅助与饮食）：\n 用法：复合维生素B 2片 tid；维生素C 0.2g tid；避免与钙剂、浓茶、抗酸剂同服（影响铁吸收）\n\n📌 缺铁性贫血补铁需持续至铁蛋白恢复正常（一般血红蛋白正常后继续3～6个月以补足储存铁）；巨幼贫需先查B12缺乏原因（萎缩性胃炎、素食、回肠切除）。\n\n【治疗】\n病因治疗（核心）：缺铁（补铁+寻找失血原因：消化道、月经过多）、巨幼（补B12/叶酸+病因）、溶血（激素/免疫抑制/停用致病药物）、肾性贫血（EPO/铁剂/HIF-PHI）、慢性病贫血（治疗原发病）、骨髓病性（治疗原发病）\n输血治疗：严格指征（Hb<60g/L或心血管症状），目标Hb 70～90g/L，避免不必要输血\n营养支持：高蛋白、富含铁/叶酸/B12饮食；纠正营养不良\n并发症防治：贫血性心脏病（严重贫血致心衰）、感染（白细胞减少）、出血（血小板减少）\n监测疗效：补铁后2～4周网织红细胞升高、4周血红蛋白上升约10g/L（反应不佳需重新评估诊断与依从性）\n多学科协作：血液科、消化科（失血）、妇科（月经过多）、肾内科（肾性贫血）\n随访：血红蛋白与铁代谢每1～3个月复查至正常，之后定期随访\n宣教：遵医嘱服药（铁剂需长期）、避免浓茶与钙剂同服铁剂、识别贫血加重症状（气促、心悸）、按时复查\n\n【处理要点】\n贫血评估与分类：记录血红蛋白、MCV与网织红细胞，初步分类并安排针对性检查（勿盲目补铁）\n症状与功能评估：评估乏力、气促、活动耐量与心率，记录并监测（贫血性心脏病风险）\n输血护理：严格核对与监测（输血反应），控制输注速度（尤其老年与心功能不全者，防容量负荷）\n用药护理：铁剂餐间服用并与维生素C同服、观察胃肠道反应与黑便（正常现象）；静脉铁剂观察过敏反应\n饮食指导：富铁（瘦肉、动物肝脏、深绿蔬菜）、富叶酸与B12（绿叶蔬菜、蛋奶、动物内脏）饮食\n病因随访提醒：消化道失血者安排内镜、月经过多者妇科评估、老年贫血者警惕肿瘤\n宣教：铁剂需长期（血红蛋白正常后继续3～6个月）、避免浓茶咖啡与钙剂同服、出现黑便与气促及时就诊\n\n【护理】\n病情观察：评估乏力、气促、心悸与活动耐量，监测心率与血压（贫血性心脏病风险），异常立即报告\n输血护理：严格核对与监测（输血反应）、控制输注速度（老年与心功能不全者缓慢，防容量负荷）\n用药护理：铁剂餐间服用并与维生素C同服、观察胃肠道反应（黑便为正常现象）；静脉铁剂缓慢输注并观察过敏反应\n饮食指导：鼓励富铁、叶酸与B12饮食；避免浓茶、咖啡、钙剂与铁剂同服（间隔2小时）\n安全护理：重度贫血者卧床休息、防跌倒（头晕）、活动时协助、必要时吸氧\n宣教：铁剂需长期服用（血红蛋白正常后继续3～6个月）、按时复查血常规与铁代谢、出现气促/黑便/乏力加重及时就诊\n\n【饮食】\n富铁食物：瘦肉、动物肝脏与血制品、深绿色蔬菜、豆类、黑木耳（植物铁吸收差，需配合维生素C）\n富叶酸食物：绿叶蔬菜、动物肝脏、豆类、全谷物（避免过度烹调破坏叶酸）\n富维生素B12食物：动物肝脏、鱼虾、蛋奶（素食者需补充剂）\n促进铁吸收：餐后或餐间服铁剂并同服维生素C；避免浓茶、咖啡、钙剂与抗酸剂同服\n高蛋白饮食纠正营养不良；避免长期素食（B12缺乏）与过度节食\n\n【注意事项】\n贫血鉴别第一步是红细胞形态（MCV）与网织红细胞计数，其次按分类选择铁代谢、B12/叶酸、溶血与骨髓检查\n缺铁性贫血必须寻找失血原因（成人尤其男性与绝经后女性需排查消化道肿瘤）\n巨幼细胞贫血：维生素B12缺乏可致神经系统损害（亚急性联合变性），补叶酸前必须先补B12（否则加重神经症状）\n慢性病贫血（炎症性贫血）表现为铁利用障碍（铁蛋白正常或升高、TSAT降低），以治疗原发病为主\n输血指征严格掌握（Hb<60g/L或有症状），不必要输血增加感染与免疫风险\n\n【急诊/急救】\n重度贫血伴呼吸困难、胸痛或意识改变（Hb<60g/L）→ 立即输注红细胞并吸氧、监护\n急性溶血危象（寒战高热、酱油色尿、腰背痛、血红蛋白快速下降）→ 立即停用可疑药物、补液碱化尿液、激素，必要时输血与血液净化\n溶血危象伴少尿与急性肾损伤 → 补液、碱化尿液、必要时CRRT\n贫血伴急性左心衰（端坐呼吸、肺水肿）→ 吸氧、利尿、缓慢少量输血（必要时透析超滤）\n贫血伴出血不止（血小板减少/凝血障碍）→ 输注血小板/凝血因子并病因处理","资料来源":"疾病库 diseases.json；鉴别诊断库 ddx_local.json（条目「贫血的鉴别诊断与处理思路」原文）"},"icd10_diagnosis":"D64.9","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2684,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"17981a5fa0f02a02fe76c1f620ec211b565dacfdf4a93abc2fa68dea9864a22c","pinyin":"pinxuedejianbiezhenduanyuchulisilu","initials":"pxdjbzdyclsl","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","D64.9",30]]},{"id":"templates-efa8f255d4c8ec5fcebe","key":"v1-c9ccc21dfe2a3058|templates-efa8f255d4c8ec5fcebe","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"贲门失弛症内镜下气囊扩张术","category":"消化病临床路径（2019年版）","raw":{"name":"贲门失弛症内镜下气囊扩张术","category":"消化病临床路径（2019年版）","case":{"case_name":"门诊病历","templates":{"主诉":"【待人工确认·本机素材无此段原文】","现病史":"【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"检查计划：患者病程长、吞咽困难反复发作并伴反食、胸痛、夜间呛咳及体质量减轻，入院后查胃镜明确食管下段及贲门部狭窄情况，排除食管癌、贲门癌等食管下段与贲门部其他病变，必要时取活检送病理；查上消化道造影（食管造影）了解食管扩张程度、有无鸟嘴样改变及钡剂排空情况，评估病变严重程度；查食管高分辨率压力测定明确食管下段括约肌压力增高、松弛障碍及食管体部蠕动缺失，为贲门失弛症的诊断与分型提供客观依据；因患者夜间呛咳，查胸部 CT 排除吸入性肺炎、纵隔病变及食管壁增厚，并了解有无肺部并发症；患者长期进食困难、体质量减轻，查血常规、血清白蛋白及前白蛋白评估营养状况，指导围手术期营养支持；长期反食呕吐易致电解质丢失，查电解质排除低钾、低钠等电解质紊乱；查肝肾功能、凝血功能、血糖评估麻醉与内镜下气囊扩张术的耐受性；查心电图、胸部 X 线检查评估心肺功能；查乙肝五项、丙肝抗体、人类免疫缺陷病毒抗体、梅毒螺旋体抗体等感染筛查；必要时查 24 小时食管 pH 及阻抗监测排除胃食管反流病；术后定期复查食管造影及胃镜，了解扩张效果并排除穿孔、出血等并发症。\n\n（检查清单）\n【临床路径·住院期间检查项目】\n住院期间检查项目\n1.","初步诊断":"【临床路径·诊断依据】\n诊断依据\n根据《临床诊疗指南\n消化系统疾病分册》（中华医学会编著，人民卫生出版社，2007年，第2版）。\n1.症状：吞咽困难，可伴有反食、胸痛、夜间呛咳、体质量减轻。病程长，病情反复，时轻时重。\n2.体征：可无特殊体征或有营养不良的体征。\n3.辅助检查：食管造影或上消化道造影、食管压力测定等符合贲门失弛症，胃镜检查除外食管下段、贲门部其他病变。\n（三）\n1. 贲门失弛症内镜下气囊扩张术（ICD-10：K22.0）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【临床路径·治疗方案的选择】\n治疗方案的选择\n根据《临床诊疗指南\n消化系统疾病分册》（中华医学会编著，人民卫生出版社，2007年，第2版）。\n1.一般治疗：改变进食方式，包括流质饮食或半流质饮食、缓慢进食等。\n2.药物治疗：钙离子拮抗剂、硝酸盐制剂、营养治疗药物等。\n3.内镜下扩张或肉毒杆菌毒素局部注射。\n4.病情影响生活质量或以上治疗无效者，可考虑经口内镜下肌切开术（peroral endoscopic myotomy, POEM）或外科手术治疗。\n（四）","临床路径·进入路径标准":"进入路径标准\n1.第一诊断必须符合ICD-10：K22.0贲门失弛症疾病编码。\n2.如患者同时具有其他疾病诊断，但住院期间不需要特殊处理，也不影响第一诊断临床路径流程的实施时，可以进入路径。\n（六）","临床路径·标准住院日":"标准住院日为6～7天\n（五）","临床路径·出院标准":"出院标准\n1.诊断已明确。\n2.治疗后症状减轻，营养摄入状况改善或营养状态稳定。\n3.无操作相关严重并发症。\n（九）","临床路径·变异及原因分析":"变异及原因分析\n1.食管造影或上消化道造影、胃镜检查提示其他病变，如肿瘤等，不进入本路径。\n2.","资料来源":"国家卫健委《224个病种临床路径（2019年版）》（国卫办医函〔2019〕933号）· 消化病临床路径（2019年版） · 贲门失弛症内镜下气囊扩张术临床路径（2019年版）.docx"},"icd10_diagnosis":"K22.0","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2685,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"6cf1741e71370e0732b06df68cc3f9909f60f0c73e03a876f9c937babfcc6e48","pinyin":"benmenshichizhengneijingxiaqinangkuozhangshu","initials":"bmscznjxqnkzs","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","临床路径·进入路径标准","临床路径·标准住院日","临床路径·出院标准","临床路径·变异及原因分析","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 临床路径·进入路径标准 临床路径·标准住院日 临床路径·出院标准 临床路径·变异及原因分析 资料来源",30],["主要诊断编码","K22.0",30]]},{"id":"templates-965cef14a8ef0eea2b74","key":"v1-c9ccc21dfe2a3058|templates-965cef14a8ef0eea2b74","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"轮状病毒肠炎","category":"小儿内科临床路径（2019年版）","raw":{"name":"轮状病毒肠炎","category":"小儿内科临床路径（2019年版）","case":{"case_name":"门诊病历","templates":{"主诉":"【卫健委临床路径原文】腹泻，大便为黄稀便、水样或蛋花汤样，每天可达10余次，往往伴有呕吐，呕吐先于腹泻出现，伴或不伴发热。严重者可出现水、电解质紊乱。\r3.体征：有或无脱水征，肠鸣音活跃。\r4.实验室检查：大便常规镜检正常，或见少许白细胞。血常规白细胞正常或轻度升高；大便轮状病毒检测阳性。\r（三）。\n【待人工确认·本机素材无此段原文】","现病史":"常见表现：腹泻，大便为黄稀便、水样或蛋花汤样，每天可达10余次，往往伴有呕吐，呕吐先于腹泻出现，伴或不伴发热。严重者可出现水、电解质紊乱。\r3.体征：有或无脱水征，肠鸣音活跃。\r4.实验室检查：大便常规镜检正常，或见少许白细胞。血常规白细胞正常或轻度升高；大便轮状病毒检测阳性。\r（三）。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"检查计划：患儿为 6～24 月龄婴幼儿，秋冬季节起病，腹泻呈黄稀便、水样或蛋花汤样，每天可达 10 余次，伴呕吐且呕吐先于腹泻，入院后查大便常规加潜血了解有无白细胞、红细胞，与细菌性肠炎鉴别；查大便轮状病毒抗原检测明确病原，符合本病诊断依据；若出现黏液脓血便或高热不退，完善大便细菌培养加药敏试验，排除细菌性痢疾、致病性大肠埃希菌肠炎等；查血常规、CRP 及降钙素原评估感染程度及有无细菌感染；患儿呕吐、腹泻明显，查电解质、血气分析及血糖评估脱水性质与程度，排除低钠血症、低钾血症、代谢性酸中毒及低血糖；查肾功能、尿常规了解肾脏灌注情况，排除肾前性氮质血症；轮状病毒感染可累及心肌，查心肌酶谱（肌酸激酶同工酶、肌钙蛋白）并查心电图排除病毒性心肌损害；患儿哭闹、呕吐明显时查腹部彩色多普勒超声排除肠套叠等急腹症；必要时查肝功能了解有无肝损害；治疗期间定期复查电解质、血气分析及血糖，指导补液方案调整。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"【临床路径·诊断依据】\n诊断依据\r1.根据《临床诊疗指南\n小儿内科分册》（中华医学会编著，人民卫生出版社，2005）、《诸福棠实用儿科学》（江载芳、申昆玲、沈颖主编，第8版，人民卫生出版社，2015）、病史：6～24月龄小儿多见，多发于秋冬季节，全年可有散发病例。\r2.临床表现：腹泻，大便为黄稀便、水样或蛋花汤样，每天可达10余次，往往伴有呕吐，呕吐先于腹泻出现，伴或不伴发热。严重者可出现水、电解质紊乱。\r3.体征：有或无脱水征，肠鸣音活跃。\r4.实验室检查：大便常规镜检正常，或见少许白细胞。血常规白细胞正常或轻度升高；大便轮状病毒检测阳性。\r（三）\n1. 轮状病毒肠炎（ICD-10：A08.001）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【临床路径·治疗方案的选择】\n治疗方案的选择\r根据《临床诊疗指南\n小儿内科分册》（中华医学会编著，人民卫生出版社，2005）、《诸福棠实用儿科学》（江载芳、申昆玲、沈颖主编，第8版，人民卫生出版社，2015）、中华医学会儿科学分会消化学组 中华医学会肠外肠内营养学分会儿科学组.婴儿急性腹泻的临床营养干预路径.中华儿科杂志，2012，50（9）：682-683.中华医学会儿科学分会消化学组,中华医学会儿科学分会感染学组,《中华儿科杂志》编辑委员会.儿童腹泻病诊断治疗原则的专家共识.中华儿科杂志,2009，47（8）：634-636.中华医学会儿科学分会消化学组,《中华儿科杂志》编辑委员会.中国儿童急性感染性腹泻病临床实践指南.中华儿科杂志,2016,54（7）：483-488.进行治疗方案的制定。\r1.消化道隔离至腹泻缓解。\r2.根据临床表现和实验室检查纠正脱水和电解质酸碱紊乱。\r（四）","临床路径·进入路径标准":"进入路径标准\r1.第一诊断必须符合ICD-10：A08.001轮状病毒肠炎疾病编码。\r2.当患者同时具有其他疾病诊断，只要住院期间不需要特殊处理也不影响第一诊断的临床路径流程实施时，可以进入路径。\r（六）入院后第1-2天\r1.必须检查的项目：\r（1）血常规、尿常规、大便常规；\r（3）肝肾功能、血电解质；\r（4）大便轮状病毒检测。\r2.根据患儿病情可选择：血气分析、乳糖检测、大便细菌培养、难辨梭状芽孢杆菌抗原及毒素检测、C反应蛋白、诺如病毒检测、心电图、心肌酶等。\r（七）药物选择\r1.口服补液盐或静脉补液。\r2.益生菌制剂及锌制剂。\r3.胃肠道黏膜保护剂。 \r（八）必要时复查的检查项目\r1.血常规、尿常规、大便常规。\r2.血电解质。\r（九）","临床路径·标准住院日":"标准住院日为4-7天\r（五）","临床路径·出院标准":"出院标准\r1.体温正常，呕吐、腹泻好转。\r2.脱水纠正。\r3.大便常规、血电解质正常。\r（十）","临床路径·变异及原因分析":"变异及原因分析\r1.存在使腹泻进一步加重的其他疾病，需要处理干预。\r2.患儿入院时已发生严重水、电解质紊乱，需进行积极对症处理，完善相关检查，向家属解释并告知病情，导致住院时间延长，增加住院费用等。\r\r\f二、轮状病毒肠炎","资料来源":"国家卫健委《224个病种临床路径（2019年版）》（国卫办医函〔2019〕933号）· 小儿内科临床路径（2019年版） · 轮状病毒肠炎临床路径（2019年版） .doc"},"icd10_diagnosis":"A08.001","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2686,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"849ab3ce6158b59e4e1dd61f57ac621cd6dfa58fba22906d7c3004d49af58bd3","pinyin":"lunzhuangbingduchangyan","initials":"lzbdcy","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","临床路径·进入路径标准","临床路径·标准住院日","临床路径·出院标准","临床路径·变异及原因分析","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 临床路径·进入路径标准 临床路径·标准住院日 临床路径·出院标准 临床路径·变异及原因分析 资料来源",30],["主要诊断编码","A08.001",30]]},{"id":"templates-9e99227e9b9b8eb95794","key":"v1-c9ccc21dfe2a3058|templates-9e99227e9b9b8eb95794","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"轻症急性胰腺炎","category":"消化病临床路径（2019年版）","raw":{"name":"轻症急性胰腺炎","category":"消化病临床路径（2019年版）","case":{"case_name":"门诊病历","templates":{"主诉":"【卫健委临床路径原文】急性、持续性腹痛（偶无腹痛）。\r2.实验室检查：血清淀粉酶和/或脂肪酶活性增高。\n【待人工确认·本机素材无此段原文】","现病史":"常见表现：急性、持续性腹痛（偶无腹痛）。\r2.实验室检查：血清淀粉酶和/或脂肪酶活性增高。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"检查计划：患者以急性、持续性腹痛起病，入院即刻查血清淀粉酶、脂肪酶明确胰腺损伤，并动态观察其升降与病情演变的关系；查腹部彩色多普勒超声（肝胆胰脾）明确有无胆结石、胆总管扩张，筛查胆源性病因；发病 72 小时后或腹痛、腹胀加重时查上腹部增强 CT 评估胰腺形态、有无胰腺坏死及局部并发症，计算 CT 严重指数；超声提示胆管扩张或怀疑胆总管结石时查磁共振胰胆管成像（MRCP）明确胆道病因；查血常规、CRP 评估炎症反应程度，判断病情轻重及有无继发感染；查肝肾功能、电解质（尤其血钙）了解有无肝肾功能损害及低钙血症（血钙降低常提示病情较重）；查血糖、血脂（甘油三酯）排除高脂血症性胰腺炎并指导降脂治疗；查尿淀粉酶辅助诊断；查腹部立位 X 线平片排除消化道穿孔、肠梗阻等急腹症，查心电图、胸部 X 线检查排除心肌梗死、肺炎等所致腹痛并了解有无胸腔积液；病因不明时查血钙、甲状旁腺激素及免疫球蛋白 G4 等，排除甲状旁腺功能亢进、自身免疫性胰腺炎；治疗期间定期复查血常规、CRP、肝肾功能、电解质及腹部超声或 CT，了解有无假性囊肿、包裹性坏死等局部并发症。\n\n（检查清单）\n【临床路径·住院期间检查项目】\n住院期间检查项目\r1.","初步诊断":"【临床路径·诊断依据】\n诊断依据\r根据《临床诊疗指南\n消化系统疾病分册》（中华医学会编著，人民卫生出版社，2007年，第2版），《实用内科学》（复旦大学医学院编著，人民卫生出版社，2017年，第15版），《临床消化病学》（姚希贤主编，天津科学技术出版社，1999年，第1版）。\r1.临床表现：急性、持续性腹痛（偶无腹痛）。\r2.实验室检查：血清淀粉酶和/或脂肪酶活性增高\n正常值上限3倍。\r3.辅助检查：影像学提示胰腺有或无形态学改变。 \r（三）\n1. 轻症急性胰腺炎（ICD-10：K85.001）","鉴别诊断":"1. 2.排除急性重症胰腺炎及有严重合并症的患者（合并心、肺、肾等脏器功能损害，合并恶性肿瘤、胰腺占位病变、胰腺脓肿、胰腺假性囊肿等）\n2. 3.排除其他急腹症：急性肠梗阻、消化性溃疡穿孔、胆石症和急性胆囊炎、肠系膜血管栓塞、心绞痛或心肌梗死者\n3.与其他急腹症鉴别","处理方案":"【临床路径·治疗方案的选择】\n治疗方案的选择\r根据《临床诊疗指南-消化系统疾病分册》（中华医学会编著，人民卫生出版社），《实用内科学（第12版）》（复旦大学医学院编著，人民卫生出版社），《临床消化病学》（天津科学技术出版社）\r1.内科治疗：\r（1）监护、禁食、胃肠减压（必要时）。\r（2）维持水电解质平衡。\r（3）药物治疗:抑酸治疗、抑制胰腺分泌药物、胰酶抑制剂、营养治疗药物；无感染征象的患者不建议使用抗菌药物；必要时谨慎使用镇静和镇痛药物。\r2.内镜治疗：对于胆源性胰腺炎，有条件的医疗机构可采用内镜治疗。\r（四）\n\n【临床路径·选择用药】\n选择用药\r1.抑酸药（质子泵抑制剂、H2受体拮抗剂）。\r2.生长抑素及其类似物。\r3.抗菌药物：按照《抗菌药物临床患者指导原则》（卫医发〔2015〕43号）执行，并结合患者的病情决定抗菌药物的选择与使用时间。\r4. 营养治疗药物：有营养风险或营养不良的患者，入院24～48小时内尽早启动肠内营养。肠内营养不能达到目标量60%时，可选全合一的方式实施肠外营养。\r（八）","临床路径·进入路径标准":"进入路径标准\r1.第一诊断必须符合ICD-10：K85.001/K85.101/K85.201\r/K85.301/K85.801/K85.802/K85.901轻症急性胰腺炎疾病编码。\r2.排除急性重症胰腺炎及有严重合并症的患者（合并心、肺、肾等脏器功能损害，合并合并恶性肿瘤、胰腺占位病变、胰腺脓肿、胰腺假性囊肿等）。\r3.排除其他急腹症：急性肠梗阻、消化性溃疡穿孔、胆石症和急性胆囊炎、肠系膜血管栓塞、心绞痛或心肌梗死者。\r4.当患者同时具有其他疾病诊断，但在住院期间不需要特殊处理也不影响第一诊断的临床路径流程实施时，可以进入路径。\r（六）","临床路径·标准住院日":"标准住院日为7～10天\r（五）","临床路径·出院标准":"出院标准\r1.腹痛、腹胀缓解，营养摄入状况改善或营养状态稳定。\r2.血淀粉酶稳定下降，或进食后无明显升高。\r（九）","临床路径·变异及原因分析":"变异及原因分析\r1.患者由轻症急性胰腺炎转为中度重症或重症急性胰腺炎，退出本路径。\r2.内镜治疗：对于急性胆源性胰腺炎，有内镜治疗指征者，可行胆管引流术或内镜下括约肌切开术，，转入相应路径。\r3.血淀粉酶持续高水平，或进食后明显升高，CRP持续高水平，导致住院时间延长。\r\f二、轻症急性胰腺炎","资料来源":"鉴别诊断库 ddx_local.json（条目「轻症急性胰腺炎」原文）；国家卫健委《224个病种临床路径（2019年版）》（国卫办医函〔2019〕933号）· 消化病临床路径（2019年版） · 轻症急性胰腺炎临床路径（2019年版）.doc"},"icd10_diagnosis":"K85.001","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2687,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"8390cb475992812c47039b16e11957169ea66613e114dec802d180bd222f38b2","pinyin":"qingzhengjixingyixianyan","initials":"qzjxyxy","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","临床路径·进入路径标准","临床路径·标准住院日","临床路径·出院标准","临床路径·变异及原因分析","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 临床路径·进入路径标准 临床路径·标准住院日 临床路径·出院标准 临床路径·变异及原因分析 资料来源",30],["主要诊断编码","K85.001",30]]},{"id":"templates-2645c24a4084531050bf","key":"v1-c9ccc21dfe2a3058|templates-2645c24a4084531050bf","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"输尿管癌(腹腔镜机器人辅助腹腔镜切除术)","category":"泌尿外科临床路径（2019年版）","raw":{"name":"输尿管癌(腹腔镜机器人辅助腹腔镜切除术)","category":"泌尿外科临床路径（2019年版）","case":{"case_name":"门诊病历","templates":{"主诉":"【待人工确认·本机素材无此段原文】","现病史":"【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"检查计划：患者拟行腹腔镜（机器人辅助腹腔镜）下输尿管癌切除术，术前需明确肿瘤部位、范围、病理性质及分肾功能。查尿常规及尿细胞学检查（连续 3 次）明确有无尿路上皮肿瘤细胞，为本病诊断提供依据；查 CT 尿路造影（CTU）明确肿瘤部位、大小、浸润范围及有无肾盂、膀胱多发肿瘤；对碘造影剂过敏或肾功能不全者改行磁共振尿路成像（MRU）；查双肾 ECT（肾动态显像加肾小球滤过率测定）评估分肾功能，为手术方式与切除范围提供依据；查膀胱镜明确有无膀胱内肿瘤或原位癌；必要时行输尿管镜检查加组织活检，明确病理类型与分级；查胸部 CT、腹部超声或 CT 排除肺、肝等远处转移；出现骨痛、血碱性磷酸酶升高或血钙升高时查全身骨显像排除骨转移，必要时行正电子发射断层显像；术前查血常规、凝血功能、肝肾功能、电解质、血糖及感染筛查（乙肝五项、丙肝抗体、人类免疫缺陷病毒抗体、梅毒螺旋体抗体），查心电图、胸部 X 线检查及肺功能评估手术与麻醉耐受性；术后定期复查膀胱镜、尿细胞学及 CTU，了解有无肿瘤复发。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"【临床路径·诊断依据】\n诊断依据\n根据《吴阶平泌尿外科学》(吴阶平主编，山东科学技术出版社，2017年)和《临床诊疗指南\n泌尿外科分册》（中华医学会编著，人民卫生出版社，2006年）。\n1.病史。\n2.体格检查。\n3.常规实验室检查及影像学检查。\n4.尿细胞学检查。\n5.CTU和（或）MRU。\n6.双肾ECT。\n7.膀胱镜。\n8.必要时行输尿管镜检查+组织活检。\n（三）\n1. 输尿管癌(腹腔镜机器人辅助腹腔镜切除术)（ICD-10：C66）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【临床路径·治疗方案的选择】\n选择治疗方案的依据\n根据《吴阶平泌尿外科学》(吴阶平主编，山东科学技术出版社，2017年)和《临床诊疗指南\n泌尿外科分册》（中华医学会编著，人民卫生出版社，2006年）。\n1.适合行腹腔镜肾、输尿管全长及膀胱部分切除术。\n2.能够耐受手术。\n（四）","临床路径·进入路径标准":"进入路径标准\n1.第一诊断必须符合ICD-10：C66输尿管癌疾病编码。\n2.当患者合并其他疾病，但住院期间不需要特殊处理也不影响第一诊断的临床路径流程实施时，可以进入路径。\n（六）术前准备2天\n1.术前必须检查的项目：\n（1）血常规、尿常规、便常规+隐血试验；\n（2）电解质、肝功能测定、肾功能测定、血型、凝血功能；\n（3）感染性疾病筛查（乙型肝炎、丙型肝炎、艾滋病、梅毒等）；\n（4）X线胸片、心电图。\n（5）相关影像学检查，尿细胞学检查，膀胱镜检查。\n2.根据患者病情可选择检查的项目：超声心动图、心功能测定[如B型钠尿肽(BNP)测定、B型钠尿肽前体(PRO-BNP)测定等]、葡萄糖测定、肺功能、血气分析、放射性核素肾功能检查、放射性核素骨扫描等。\n（七）预防性抗菌药物选择与使用时机\n按照《抗菌药物临床患者指导原则》（卫医发〔2015〕43号）执行，并结合患者的病情决定抗菌药物的选择与使用时间。建议使用第一、二代头孢菌素，或氟喹诺酮类。如可疑感染，需做相应的微生物学检查，必要时做药敏试验。\n（八）手术日为入院\n3天\n1.麻醉方式：全身麻醉。\n2.手术方式：腹腔镜肾、输尿管全长及膀胱部分切除术。\n3.术中用药：麻醉用药，必要时用抗菌药物。\n4.输血：必要时。输血前需行血型鉴定、抗体筛选和交叉合血。\n（九）术后住院恢复\n7天\n1.必须复查的检查项目：血常规、尿常规、肾功能测定。\n2.根据患者病情变化可选择相应的检查项目。\n3.术后抗菌药物：按照《抗菌药物临床患者指导原则》（卫医发〔2015〕43号）执行，建议使用第一、二代头孢菌素，或氟喹诺酮类。如可疑感染，需做相应的微生物学检查，必要时做药敏试验。\n（十）","临床路径·标准住院日":"标准住院日为\n10天\n（五）","临床路径·出院标准":"出院标准\n1.一般情况良好。\n2.伤口无异常。\n（十一）","临床路径·变异及原因分析":"变异及原因分析\n1.术中、术后出现并发症，需要进一步诊治，导致住院时间延长、费用增加。\n2.术后原伴随疾病控制不佳，需请相关科室会诊和治疗，进一步诊治。\n3.住院后出现其他内、外科疾病需进一步明确诊断，可进入其他路径。\n4.合并膀胱肿瘤患者不进入本路径。","资料来源":"国家卫健委《224个病种临床路径（2019年版）》（国卫办医函〔2019〕933号）· 泌尿外科临床路径（2019年版） · 输尿管癌（腹腔镜机器人辅助腹腔镜切除术）临床路径（2019年版）.docx"},"icd10_diagnosis":"C66","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2688,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"581b24c2a8c0e78c84a380a1eebd57414b1c215b1de0e6adfa94ae01ba413297","pinyin":"shuniaoguanai(fuqiangjingjiqirenfuzhufuqiangjingqiechushu)","initials":"snga(fqjjqrfzfqjqcs)","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","临床路径·进入路径标准","临床路径·标准住院日","临床路径·出院标准","临床路径·变异及原因分析","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 临床路径·进入路径标准 临床路径·标准住院日 临床路径·出院标准 临床路径·变异及原因分析 资料来源",30],["主要诊断编码","C66",30]]},{"id":"templates-3b500707183fd5948e39","key":"v1-c9ccc21dfe2a3058|templates-3b500707183fd5948e39","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"输尿管结石(肾绞痛)","category":"泌尿外科","raw":{"name":"输尿管结石(肾绞痛)","category":"泌尿外科","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】突发一侧腰腹部绞痛，阵发性加剧，向同侧下腹、会阴部及大腿内侧放射、恶心、呕吐、腹胀（反射性），面色苍白、大汗、辗转不安、肉眼或镜下血尿、尿频、尿急、尿痛（结石位于输尿管下段时）、合并感染时寒战高热、腰痛加重；双侧梗阻或孤立肾梗阻可致无尿。\n【待人工确认·本机素材无此段原文】","现病史":"输尿管结石多由肾结石下移所致，典型表现为突发腰腹部绞痛（肾绞痛）、向会阴部放射、伴血尿。结石直径<0.6cm多可自行排出，较大或伴梗阻、感染、肾功能损害者需体外冲击波碎石或输尿管镜取石。\n常见表现：突发一侧腰腹部绞痛，阵发性加剧，向同侧下腹、会阴部及大腿内侧放射、恶心、呕吐、腹胀（反射性），面色苍白、大汗、辗转不安、肉眼或镜下血尿、尿频、尿急、尿痛（结石位于输尿管下段时）、合并感染时寒战高热、腰痛加重；双侧梗阻或孤立肾梗阻可致无尿。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：体温、脉搏、血压（评估感染与疼痛应激）\n一般情况：痛苦面容、大汗、辗转不安、脱水征\n腹部视诊：有无膨隆、手术瘢痕\n腹部触诊：患侧肾区压痛、输尿管走行区压痛、有无腹膜刺激征（鉴别急腹症）\n肾区叩击痛：患侧明显（肾绞痛特征性体征）\n下腹部与膀胱区：有无压痛、膀胱充盈（尿潴留）\n其他：睾丸/阴唇有无牵涉痛、有无皮疹（带状疱疹鉴别）","辅助检查":"1. 尿常规+尿沉渣：镜下或肉眼血尿，白细胞提示感染\n2. 泌尿系超声+腹部CT平扫：明确结石部位、大小、肾积水（CT为金标准）\n3. 血常规+CRP+PCT：评估感染；发热者加血培养\n4. 肾功能（肌酐、尿素氮）+电解质：评估梗阻性肾功能损害\n5. 尿培养+药敏：合并感染时指导抗生素\n6. 血钙、血磷、尿酸、甲状旁腺激素（复发者）：代谢性病因筛查\n7. 结石成分分析：排石或取石后送检，指导预防","初步诊断":"1. 尿常规：镜下血尿（红细胞增多），合并感染时白细胞增多\n2. 泌尿系超声：首选筛查，可见结石强回声、肾积水、输尿管扩张\n3. 腹部CT平扫（泌尿系CTU/CT）：金标准，明确结石部位、大小、数目及有无梗阻\n4. 腹部平片（KUB）：可见阳性结石影（尿酸结石不显影）\n5. 血常规+CRP+PCT：评估感染；合并发热者查血培养\n6. 肾功能+电解质：评估梗阻所致肾功能损害\n7. 静脉肾盂造影（IVP）：必要时评估肾功能与解剖（现多被CT替代）\n1. 输尿管结石(肾绞痛)（ICD-10：N20.1）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【药物治疗·输液】\n⚠️ 按病情选择方案，切勿全部同时使用！\n\n方案1（解痉镇痛）：\n 用法：间苯三酚 40～80mg + 0.9%氯化钠 100ml 静滴（或静推）；或山莨菪碱 10mg 肌注；剧痛用哌替啶 50mg 肌注 + 间苯三酚\n\n方案2（补液促排）：\n 用法：0.9%氯化钠/葡萄糖 500～1000ml 静滴（无梗阻、无肾功能不全者）\n\n方案3（抗感染，合并感染时）：\n 用法：头孢曲松 2g 静滴 qd 或 左氧氟沙星 0.5g 静滴 qd（按药敏调整）\n\n📌 合并感染梗阻者属急症，须尽早解除梗阻（引流/置管），单纯抗感染无效。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：同类药物选一种，切勿重复用药！\n\n药物1（排石/利尿）：\n 用法：坦索罗辛 0.2mg qn（输尿管下段结石助排）或 硝苯地平 10mg tid\n\n药物2（解痉镇痛）：\n 用法：双氯芬酸钠栓 50mg 纳肛 必要时 或 塞来昔布 200mg bid\n\n药物3（通淋排石，中成药）：\n 用法：排石颗粒 1袋 tid 或 尿石通丸 1袋 tid（辅助排石）\n\n药物4（抗感染序贯）：\n 用法：头孢克肟 0.1g bid 或 左氧氟沙星 0.5g qd\n\n📌 多饮水、适度运动有助于排石；尿酸结石者可碱化尿液（枸橼酸氢钾钠）。\n\n【治疗】\n保守排石：结石<0.6cm、无梗阻感染、疼痛可控者——大量饮水（每日2500～3000ml）、适度运动（跳绳、跳跃）、解痉镇痛、α受体阻滞剂助排，2～4周复查\n体外冲击波碎石（ESWL）：结石0.6～2cm、肾及输尿管上段结石，无梗阻感染者\n输尿管镜碎石取石（URS+钬激光）：中下段结石、ESWL失败、结石嵌顿或合并梗阻者\n经皮肾镜取石（PCNL）：肾结石>2cm、鹿角形结石或URS失败者\n急诊引流：合并感染梗阻、脓毒症、无尿或孤立肾梗阻者行输尿管支架或经皮肾造瘘引流\n代谢评估与预防：结石成分分析，针对性预防（多饮水、限钠、限草酸、碱化尿液）\n\n【处理要点】\n疼痛评估与处理：评估疼痛部位、性质、评分，遵医嘱解痉镇痛并观察效果\n观察排石：排尿时用滤网收集结石（送成分分析），观察有无结石排出\n饮水管理：无梗阻/心肾功能允许者每日饮水2500～3000ml，夜间加饮\n尿量与尿色观察：记录尿量，观察有无血尿加重与脓尿\n感染监测：体温、寒战、腰痛加重、白细胞与PCT（警惕梗阻性化脓性感染）\n复查随访：2～4周复查超声/CT评估结石位置与有无肾积水\n\n【护理】\n疼痛护理：评估疼痛评分（肾绞痛常达7～10分），遵医嘱及时解痉镇痛，观察缓解情况\n排石护理：指导大量饮水与适度跳跃运动，排尿用滤网收集结石\n病情观察：体温、尿量、尿色、腰痛变化，警惕感染与无尿\n饮水指导：无梗阻者每日饮水2500～3000ml，分次饮用，夜间加饮一次\n术后护理（碎石/取石后）：观察血尿程度、支架管位置、排尿情况，指导避免剧烈运动\n\n【饮食】\n大量饮水（每日2500～3000ml），保持尿量2000ml以上\n草酸钙结石：限制高草酸食物（菠菜、甜菜、坚果、巧克力）、限钠\n尿酸结石：限制高嘌呤食物（动物内脏、海鲜、浓肉汤），碱化尿液\n适量钙摄入（不必过度限制，过度限钙反而增加结石风险），避免过量维生素C\n少饮浓茶咖啡与碳酸饮料，避免高动物蛋白饮食\n\n【注意事项】\n结石合并感染并梗阻属泌尿外科急症，需尽快解除梗阻引流，否则可致脓毒症\n肾绞痛发作时禁用过量补液（加重梗阻侧压力），以解痉镇痛为主\n直径>0.6cm结石自行排出可能性小，应积极介入治疗，避免长期梗阻损害肾功能\n结石复发率高（5年约50%），需长期生活方式干预与随访\n\n【急诊/急救】\n寒战高热伴腰痛、白细胞升高（梗阻性化脓性肾盂肾炎）→ 紧急解除梗阻引流（支架/肾造瘘）\n无尿或孤立肾梗阻、肾功能急剧恶化 → 急诊引流\n剧烈绞痛不能缓解伴呕吐、脱水 → 急诊镇痛补液并评估梗阻","资料来源":"疾病库 diseases.json"},"icd10_diagnosis":"N20.1","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2689,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"c56c060fec6da1bd87ec8ae2ba95cb7e29d10339ed4e95014f34282c5411a03b","pinyin":"shuniaoguanjieshi(shenjiaotong)","initials":"sngjs(sjt)","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","N20.1",30]]},{"id":"templates-afc3dcefe621b6066d28","key":"v1-c9ccc21dfe2a3058|templates-afc3dcefe621b6066d28","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"过敏性肺炎(外源性)","category":"内科-呼吸","raw":{"name":"过敏性肺炎(外源性)","category":"内科-呼吸","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】急性：接触抗原后4～12小时出现发热、寒战、干咳、胸闷与气促，脱离接触后数天缓解（反复发作）、亚急性：隐匿起病的咳嗽、气促、乏力、食欲减退与体重下降（数周至数月）、慢性：进行性呼吸困难、干咳、杵状指与呼吸衰竭（不可逆纤维化）、体征：双肺底爆裂音（velcro啰音）、紫绀、活动后气促加重、抗原接触史：鸟类（鸽、鹦鹉）饲养、发霉干草/谷物、加湿器与空调、蘑菇种植、木材加工。\n【待人工确认·本机素材无此段原文】","现病史":"过敏性肺炎（外源性变应性肺泡炎，HP）是反复吸入有机粉尘抗原（发霉干草、鸟类蛋白、加湿器与空调污染、蘑菇与木材粉尘）引起的免疫介导性肺间质炎症。分为急性（接触后4～12小时发热、咳嗽、气促）、亚急性与慢性（进行性纤维化）。治疗核心是脱离抗原接触±糖皮质激素。\n常见表现：急性：接触抗原后4～12小时出现发热、寒战、干咳、胸闷与气促，脱离接触后数天缓解（反复发作）、亚急性：隐匿起病的咳嗽、气促、乏力、食欲减退与体重下降（数周至数月）、慢性：进行性呼吸困难、干咳、杵状指与呼吸衰竭（不可逆纤维化）、体征：双肺底爆裂音（velcro啰音）、紫绀、活动后气促加重、抗原接触史：鸟类（鸽、鹦鹉）饲养、发霉干草/谷物、加湿器与空调、蘑菇种植、木材加工。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：体温（急性发作可发热）、呼吸频率、血氧、心率\n肺部：双肺底爆裂音（velcro啰音，特征性）、哮鸣音、呼吸音减弱\n一般情况：气促程度（活动后加重）、紫绀、杵状指（慢性纤维化）\n心脏：心率增快、肺动脉瓣区第二心音亢进（肺心病）\n暴露相关：居住环境询问（霉变、鸟类、加湿器）、职业暴露（农业、蘑菇、木材加工）\n体重与营养：消瘦（慢性病程）\n其他：皮肤与关节（结缔组织病鉴别）、淋巴结（结节病鉴别）","辅助检查":"1. 胸部高分辨CT（HRCT）：磨玻璃影、小结节影、马赛克灌注与纤维化（上肺为主）\n2. 肺功能+弥散功能：限制性通气障碍与DLCO下降（随访核心）\n3. 支气管肺泡灌洗（BAL）：淋巴细胞增多（>40%）伴CD4/CD8降低（诊断价值高）\n4. 血清特异性IgG抗体（鸟蛋白、嗜热放线菌等）：支持诊断\n5. 血气分析：低氧血症与肺泡-动脉氧分压差增大\n6. 血常规+CRP+PCT：炎症与感染鉴别\n7. 肺活检（必要时）：肉芽肿性炎与机化性肺炎（诊断不明确或需与IPF鉴别）","初步诊断":"1. 胸部高分辨CT（HRCT）：急性为磨玻璃影与小结节影；慢性为纤维化、网格影与蜂窝（以上肺为主，与IPF不同）\n2. 肺功能：限制性通气障碍与弥散功能下降（DLCO降低）\n3. 支气管肺泡灌洗（BAL）：淋巴细胞增多（>40%～50%）伴CD4/CD8比值降低（诊断价值高）\n4. 血清特异性IgG抗体：针对鸟蛋白、嗜热放线菌等抗原（支持诊断，需结合临床）\n5. 抗原暴露史与激发试验（必要时）：详细询问职业与环境暴露（关键）\n6. 肺活检（必要时）：肉芽肿性炎症（诊断不明确或需与IPF鉴别）\n7. 血常规+CRP+血气分析：炎症与低氧血症评估；排除感染\n1. 过敏性肺炎(外源性)（ICD-10：J67.9）","鉴别诊断":"1. 肺活检（必要时）：肉芽肿性炎症（诊断不明确或需与IPF鉴别）\n2. HRCT上肺为主的纤维化与蜂窝影有助于与特发性肺纤维化（IPF，下肺为主）鉴别","处理方案":"【药物治疗·输液】\n⚠️ 以脱离抗原与激素治疗为主，静脉用药用于重症！\n\n方案1（重症急性发作，糖皮质激素）：\n 用法：甲泼尼龙 40～80mg 静滴 qd（或 q12h，按病情），症状缓解后逐渐减量并过渡口服\n\n方案2（低氧血症支持）：\n 用法：0.9%氯化钠 静滴；鼻导管吸氧（维持SpO₂≥90%），必要时无创/有创机械通气\n\n方案3（合并感染/鉴别感染）：\n 用法：头孢呋辛 1.5g 静滴 q8h 或 莫西沙星 0.4g 静滴 qd（在明确病原前短期经验性治疗）\n\n方案4（慢性纤维化支持）：\n 用法：0.9%氯化钠 静滴；必要时抗纤维化治疗（吡非尼酮/尼达尼布，专科评估）；氧疗\n\n📌 治疗核心是彻底脱离抗原接触（脱离后常迅速缓解）；激素用于中重度或进展性病例，需逐渐减量（避免复发）。\n\n【药物治疗·口服】\n⚠️ 口服激素与对症为主：\n\n药物1（糖皮质激素，中重度）：\n 用法：泼尼松 0.5～1mg/kg/日（晨起顿服，疗程4～8周后逐渐减量，总疗程3～6个月）；密切监测激素不良反应\n\n药物2（抗纤维化，慢性进展型，专科评估）：\n 用法：吡非尼酮 200mg tid 起（逐渐加量）或 尼达尼布 150mg bid；监测肝功能与胃肠道反应\n\n药物3（对症）：\n 用法：孟鲁司特 10mg qn（辅助）；氨溴索 30mg tid（化痰）；必要时支气管扩张剂（吸入）\n\n药物4（氧疗与其他）：\n 用法：碳酸钙D3 600mg qd（长期激素者）；必要时疫苗（流感、肺炎球菌）\n\n📌 避免再次接触抗原是关键（否则激素减量时易复发）；吸烟者戒烟（加重肺损伤）。\n\n【治疗】\n脱离抗原暴露（最重要）：停止接触鸟类、发霉干草、污染加湿器与空调等；职业性者调离环境并改善通风与防护\n糖皮质激素：中重度或进展性病例使用泼尼松 0.5～1mg/kg/日（口服）或甲泼尼龙静滴，逐渐减量（总疗程3～6个月）\n氧疗与呼吸支持：低氧血症者吸氧，呼吸衰竭者无创/有创机械通气\n抗纤维化治疗：慢性进展性纤维化者（吡非尼酮/尼达尼布）由呼吸专科评估\n并发症处理：呼吸衰竭、肺心病、感染（激素治疗期间警惕）\n鉴别诊断处理：与IPF、结节病、感染、嗜酸粒细胞性肺炎鉴别（BAL与活检）\n随访与监测：肺功能与HRCT随访（每3～6个月），评估纤维化进展与治疗反应\n宣教：避免抗原再暴露（家庭环境与职业防护）、识别急性发作症状（接触后发热气促）及时就诊、戒烟、接种疫苗\n\n【处理要点】\n暴露史采集（关键）：详细询问职业、居住环境、宠物（鸟类）、加湿器与空调使用史，记录抗原接触与症状时间关系\n环境干预指导：清除霉变物质、更换/清洁加湿器与空调、避免饲养鸟类、改善通风、职业防护（口罩/呼吸器）\n用药护理：激素按医嘱逐渐减量（不可骤停）、监测血糖、血压与感染征象；抗纤维化药监测肝功能与胃肠道反应\n氧疗护理：按医嘱吸氧（维持SpO₂≥90%），观察氧疗效果与二氧化碳潴留（慢性者低流量吸氧）\n肺功能与影像随访：按时复查肺功能、HRCT与血气，记录结果变化\n宣教：抗原接触是病因（必须避免）、激素不可自行停药、出现发热与气促加重及时就诊、戒烟与疫苗接种\n\n【护理】\n暴露史与环境干预：详细采集暴露史，指导清除霉变物、清洁加湿器与空调、避免鸟类、改善通风与职业防护\n氧疗护理：按医嘱吸氧并维持SpO₂≥90%，观察氧疗效果与呼吸状态变化\n用药护理：激素按医嘱逐渐减量（不可骤停）、监测血糖、血压、体重与感染征象；抗纤维化药监测肝功能与胃肠道反应\n呼吸功能观察：记录呼吸频率、血氧与活动耐量变化，异常立即报告\n随访提醒：按时复查肺功能、HRCT与血气，记录并对比结果\n宣教：避免抗原再暴露是关键、激素不可自行停药、出现发热与气促加重及时就诊、戒烟与疫苗接种\n\n【饮食】\n高蛋白、高热量饮食（慢性消耗与呼吸功增加）；少量多餐（避免饱胀影响呼吸）\n长期激素治疗：低盐低糖饮食、补充钙与维生素D（防骨质疏松）\n避免已知过敏食物；均衡蔬果摄入（抗氧化）\n戒烟、避免饮酒；保持足够水分（稀释痰液，心功能允许下）\n慢性低氧与呼吸衰竭者：营养支持（必要时肠内营养），避免过度碳水（减少二氧化碳产生）\n\n【注意事项】\n过敏性肺炎的诊断依赖抗原暴露史+BAL淋巴细胞增多+HRCT表现，脱离抗原是最好的'治疗'\n急性发作多在抗原接触后4～12小时出现（发热、咳嗽、气促），脱离接触后迅速缓解——反复发作提示持续暴露\nHRCT上肺为主的纤维化与蜂窝影有助于与特发性肺纤维化（IPF，下肺为主）鉴别\n长期激素治疗需缓慢减量（突然停药易复发），并监测感染、血糖、血压与骨质疏松\n预防胜于治疗：改善居住与工作环境、避免鸟类与霉变物质、加湿器与空调定期清洁是根本措施\n\n【急诊/急救】\n接触抗原后突发严重呼吸困难与低氧（急性重症发作）→ 立即吸氧+静脉激素，必要时机械通气\n呼吸衰竭（SpO₂<90%、呼吸窘迫）→ 无创/有创机械通气支持并转ICU\n激素治疗期间高热与肺部新发浸润（继发感染）→ 抗感染+病原学检查，必要时减停激素\n慢性患者突发气胸（胸痛+呼吸困难）→ 急诊胸部影像与闭式引流\n咯血伴呼吸困难加重 → 急诊评估（感染、气胸或疾病进展）","资料来源":"疾病库 diseases.json；鉴别诊断库 ddx_local.json（条目「过敏性肺炎（外源性）」原文）"},"icd10_diagnosis":"J67.9","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2690,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"599d5ba6a0c3068d81ad303e09d1640479213d5f2835b22e6435162847f2dcaf","pinyin":"guominxingfeiyan(waiyuanxing)","initials":"gmxfy(wyx)","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","J67.9",30]]},{"id":"templates-ff442b65a5a6872cfbd9","key":"v1-c9ccc21dfe2a3058|templates-ff442b65a5a6872cfbd9","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"过期妊娠","category":"妇产科临床路径（2019年版）","raw":{"name":"过期妊娠","category":"妇产科临床路径（2019年版）","case":{"case_name":"门诊病历","templates":{"主诉":"【待人工确认·本机素材无此段原文】","现病史":"【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"【临床路径·住院期间检查项目】\n必需的检查项目：\r（1）血常规、尿常规。\r（2）肝肾功能、凝血功能、血型和交叉配血。\r（3）感染性疾病筛查（乙型肝炎、丙型肝炎、艾滋病、梅毒等，孕期未查者）。\r（4）心电图。\r（5）超声和电子胎心监护。\r2.根据患者病情可选择项目：白带常规、宫颈分泌物培养+药敏、阴道微生态检查、GBS筛查、胎儿脐动脉血流等。\r（七）促宫颈成熟及引产方式选择\r1.促宫颈成熟：用于Bishop评分6分以下患者。\r（1）缩宫素静脉点滴。\r（2）前列腺素制剂：无前列腺素禁忌者。\r（3）其他方法：如宫颈扩张球囊、Foleys管、昆布条、海藻棒等。\r2.引产：用于Bishop评分\n6分患者，行人工破膜术和/或缩宫素静脉点滴引产术。\r（八）产后住院恢复3～5天\r1.必须复查的检查项目：血常规。\r2.产后用药：酌情使用预防性抗菌药物，按照《抗菌药物临床患者指导原则》（卫医发〔2015〕43号）执行。\r（九）","初步诊断":"【临床路径·诊断依据】\n诊断依据\r根据《临床诊疗指南\n妇产科学分册》（中华医学会编著，人民卫生出版社，2007年）和《妇产科学（第9版）》（谢幸、苟文丽主编，人民卫生出版社，2018年）。\r1.以末次月经计算：月经规律者，停经达到或超过42周（294天）尚未分娩者。\r2.根据排卵日计算：根据基础体温提示的排卵期推算若排卵后280天仍未分娩者。还可通过性交日期或辅助生殖技术的日期推算孕周。\r3.超声检查确定孕周：妊娠5～13+6周内以胎儿顶臀径推算预产期，妊娠14～20周内以胎儿双顶径、股骨长度推算预产期。\r4.其他：妊娠最初血、尿HCG增高的时间、早孕反应出现时间、胎动开始时间以及早孕期妇科检查发现的子宫大小均有助于推算预产期。\r（三）\n1. 过期妊娠（ICD-10：O48）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【临床路径·治疗方案的选择】\n选择治疗方案的依据\r根据《临床诊疗指南\n妇产科学分册》（中华医学会编著，人民卫生出版社，2007年）和《妇产科学（第9版）》（谢幸、苟文丽主编，人民卫生出版社，2018年）。\r1.应当尽可能避免发生过期妊娠，争取妊娠足月时分娩。确诊过期妊娠的患者，应当根据胎盘功能、胎儿大小、宫颈成熟度等综合分析，选择恰当的分娩方式。\r2.引产：确诊过期妊娠而无胎儿窘迫、无明显头盆不称。\r（1）引产前促宫颈成熟：引产前应当常规进行宫颈评分，宫颈Bishop评分＜6分，引产前应当给予促宫颈成熟治疗。\r（2）引产：对宫颈成熟，Bishop评分\n6分且胎头已衔接者，采用缩宫素静脉滴注引产。引产过程中严密监护胎心、宫缩及产程进展。\r（四）","临床路径·进入路径标准":"进入路径标准\r1.第一诊断必须符合ICD-10：O48过期妊娠疾病编码。\r2.当患者合并其他疾病，但住院期间不需要特殊处理也不影响第一诊断的临床路径流程实施时，可以进入路径。\r（六）入院后当日\r1.","临床路径·标准住院日":"标准住院日4～8天\r（五）","临床路径·出院标准":"出院标准\r1.一般状况良好。 \r2.无感染征象。\r（十）","临床路径·变异及原因分析":"变异及原因分析\r1.引产成功后顺利阴道分娩进入自然临产阴道分娩临床路径，产钳助产者进入阴道产钳助产临床路径，引产失败或引产过程中出现剖宫产指征（如胎儿窘迫、头位难产等）转入剖宫产临床路径，退出本路径。\r2.子宫复旧不良，出现阴道流血过多、产褥感染、切口延期愈合等并发症，导致住院时间延长。\r\r\f二、过期妊娠","资料来源":"国家卫健委《224个病种临床路径（2019年版）》（国卫办医函〔2019〕933号）· 妇产科临床路径（2019年版） · 过期妊娠临床路径（2019年版）.doc"},"icd10_diagnosis":"O48","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2691,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"da20da0a0e8e70bc09aabb1f088198018660cc18af6aa9de95508445f605ca40","pinyin":"guoqirenshen","initials":"gqrs","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","临床路径·进入路径标准","临床路径·标准住院日","临床路径·出院标准","临床路径·变异及原因分析","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 临床路径·进入路径标准 临床路径·标准住院日 临床路径·出院标准 临床路径·变异及原因分析 资料来源",30],["主要诊断编码","O48",30]]},{"id":"templates-b90167d4ce11f12d9bc5","key":"v1-c9ccc21dfe2a3058|templates-b90167d4ce11f12d9bc5","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"连枷胸(多根多处肋骨骨折)","category":"胸外科","raw":{"name":"连枷胸(多根多处肋骨骨折)","category":"胸外科","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】胸痛剧烈，深呼吸、咳嗽时加重，局部压痛与骨擦感、反常呼吸运动（吸气时患处胸壁塌陷、呼气时膨出）、呼吸困难、发绀、呼吸急促，血氧下降、可伴皮下气肿、气胸、血胸、咯血、重者出现呼吸衰竭、休克、意识改变。\n【待人工确认·本机素材无此段原文】","现病史":"连枷胸指相邻多根（≥3根）多处肋骨骨折，胸壁失去肋骨支撑形成浮动胸壁，出现反常呼吸运动（吸气时塌陷、呼气时膨出），导致通气障碍、缺氧，常合并肺挫伤，是胸部创伤的危重情况。\n常见表现：胸痛剧烈，深呼吸、咳嗽时加重，局部压痛与骨擦感、反常呼吸运动（吸气时患处胸壁塌陷、呼气时膨出）、呼吸困难、发绀、呼吸急促，血氧下降、可伴皮下气肿、气胸、血胸、咯血、重者出现呼吸衰竭、休克、意识改变。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：呼吸频率与形态、血氧、心率、血压（评估呼吸衰竭与休克）\n一般情况：意识、发绀、是否可平卧、烦躁程度\n胸部视诊：胸壁畸形、反常呼吸运动、呼吸动度、肋间隙\n胸部触诊：肋骨压痛与骨擦感、皮下气肿（握雪感）、语颤减弱\n胸部叩诊与听诊：浊音或鼓音（血胸/气胸）、呼吸音减弱、湿啰音（肺挫伤）\n颈部与气管：气管移位（张力性气胸）、颈静脉怒张（心脏压塞）\n合并伤评估：腹部压痛（肝脾破裂）、颅脑与脊柱损伤","辅助检查":"1. 血气分析（含氧合指数）：评估低氧血症与呼吸衰竭，动态复查（每6～12小时）\n2. 血常规+血型+交叉配血：评估失血与备血\n3. 凝血功能+D-二聚体：创伤性凝血病风险\n4. 心肌酶（CK-MB、肌钙蛋白）+心电图：评估心脏挫伤\n5. 胸部CT（含三维重建）：明确骨折与肺挫伤范围，为首选检查\n6. 床旁超声+肝脾胰超声：排除胸腹联合伤\n7. 乳酸+肝肾功能：评估组织灌注与器官功能","初步诊断":"1. 体格检查：反常呼吸运动、肋骨压痛与骨擦感、皮下气肿（关键体征）\n2. 胸部CT（含三维重建）：明确骨折数目、部位、移位及肺挫伤程度（首选）\n3. 胸部X线：可见肋骨骨折线、气胸、血胸、肺挫伤影（早期肺挫伤可阴性）\n4. 血气分析：评估低氧血症与通气障碍（PaO2下降、PaCO2可正常或升高）\n5. 床旁超声：评估胸腔积液与气胸，可引导穿刺\n6. 血常规+凝血功能+血型：评估出血与备血；心肌酶排除心脏挫伤\n1. 连枷胸(多根多处肋骨骨折)（ICD-10：S22.5）","鉴别诊断":"1. 心肌酶排除心脏挫伤\n2. 诊断要点：体格检查：反常呼吸运动、肋骨压痛与骨擦感、皮下气肿（关键体征）\n3. 诊断要点：胸部CT（含三维重建）：明确骨折数目、部位、移位及肺挫伤程度（首选）\n4. 诊断要点：胸部X线：可见肋骨骨折线、气胸、血胸、肺挫伤影（早期肺挫伤可阴性）\n5. 诊断要点：血气分析：评估低氧血症与通气障碍（PaO2下降、PaCO2可正常或升高）\n6. 诊断要点：床旁超声：评估胸腔积液与气胸，可引导穿刺\n7. 诊断要点：血常规+凝血功能+血型：评估出血与备血；心肌酶排除心脏挫伤","处理方案":"【药物治疗·输液】\n⚠️ 抢救用药，按病情选择！\n\n方案1（镇痛，重点）：\n 用法：曲马多 100mg 静滴 q8h（必要时）；或氟比洛芬酯 50mg 静滴 q12h；剧痛者行硬膜外/椎旁阻滞镇痛（需麻醉科协作）\n\n方案2（液体管理）：\n 用法：限制晶体液（避免加重肺挫伤肺水肿），平衡盐溶液按需；必要时白蛋白\n\n方案3（抗感染）：\n 用法：头孢呋辛 1.5g 静滴 q8h 或 头孢曲松 2g 静滴 qd（合并肺挫伤/开放伤）\n\n方案4（化痰/支持）：\n 用法：氨溴索 30mg 静滴 bid；必要时雾化吸入（布地奈德+特布他林）\n\n📌 充分镇痛是治疗核心（利于咳嗽排痰、减少呼吸机依赖），避免过量补液加重肺水肿。\n\n【药物治疗·口服】\n⚠️ 稳定后遵医嘱，同类只选一种：\n\n药物1（镇痛）：\n 用法：塞来昔布 200mg bid 或 洛索洛芬钠 60mg tid（餐后）；必要时曲马多 50mg\n\n药物2（化痰）：\n 用法：氨溴索 30mg tid 或 乙酰半胱氨酸 0.6g tid\n\n药物3（通便镇咳）：\n 用法：乳果糖 15ml bid；复方甲氧那明 2粒 tid（干咳明显者）\n\n📌 镇痛需持续足量，疼痛控制不佳会导致排痰困难与肺部感染。\n\n【治疗】\n镇痛：硬膜外/椎旁神经阻滞或静脉镇痛（多模式镇痛），是治疗关键\n胸壁固定：胸带包扎、肋骨固定板或手术内固定（多发移位明显、呼吸功能差者）\n呼吸支持：吸氧，必要时无创或有创机械通气（内固定作用）；肺挫伤重者按ARDS处理（小潮气量）\n胸腔闭式引流：合并气胸/血胸者\n液体管理：限制晶体液，避免肺水肿加重\n抗感染、化痰、鼓励咳嗽排痰，预防肺部感染与肺不张\n合并伤处理：腹部脏器损伤、心脏挫伤、颅脑损伤等\n\n【处理要点】\n监测呼吸功能：呼吸频率、血氧、血气分析，动态评估氧合指数\n镇痛评估：每4小时评估疼痛评分（目标<3分），保证深呼吸与有效咳嗽\n呼吸道管理：翻身拍背、雾化吸入、鼓励咳痰，必要时吸痰（注意避免诱发气胸）\n出入量与液体管理：限制晶体液，记录24小时出入量，警惕肺水肿\n复查影像：伤后24～48小时复查CT评估肺挫伤进展\n康复：疼痛控制后鼓励早期床上活动与下床活动，预防深静脉血栓（必要时抗凝）\n\n【护理】\n呼吸护理：半卧位、持续吸氧，监测血氧与呼吸形态，发现反常呼吸加重或发绀立即报告\n镇痛护理：按医嘱定时给予镇痛，评估疼痛评分与呼吸改善情况（疼痛控制是排痰前提）\n排痰护理：每2小时翻身拍背，雾化吸入后鼓励咳痰，无力咳痰者协助吸痰\n固定护理：胸带包扎松紧适宜，观察皮肤受压与呼吸受限情况\n并发症观察：体温、痰液性状（肺部感染）、尿量、下肢肿胀（深静脉血栓）\n\n【饮食】\n急性期禁食或流质（视病情与是否手术），必要时静脉营养\n高蛋白、高热量、高维生素饮食促进骨折愈合与创伤修复\n适量饮水（限液者按医嘱），保持痰液稀释\n多食蔬菜水果防便秘（避免用力排便），必要时用缓泻剂\n戒烟酒，避免产气与辛辣刺激食物\n\n【注意事项】\n连枷胸的主要危险是合并肺挫伤与呼吸衰竭，治疗核心是镇痛+呼吸管理\n反常呼吸运动早期可不明显，需仔细查体并结合影像判断\n肺挫伤常在伤后24～48小时进展，需动态复查与评估\n避免过量补液，限制性液体策略可减少肺水肿与呼吸衰竭\n\n【急诊/急救】\n呼吸窘迫、血氧持续下降、PaO2<60mmHg（呼吸衰竭）→ 立即机械通气并转ICU\n反常呼吸明显伴循环不稳定 → 急诊胸壁固定并评估手术内固定\n合并张力性气胸或大量血胸 → 立即减压/引流","资料来源":"疾病库 diseases.json；鉴别诊断库 ddx_local.json（条目「连枷胸（多根多处肋骨骨折）」原文）"},"icd10_diagnosis":"S22.5","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2692,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"6ea3daf044e65eef5da2a0c73baf4eda4ac83d84ecfec33de1ef1847620f7b96","pinyin":"lianjiaxiong(duogenduochuleiguguzhe)","initials":"ljx(dgdclggz)","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","S22.5",30]]},{"id":"templates-23fe33e92b309aae11f3","key":"v1-c9ccc21dfe2a3058|templates-23fe33e92b309aae11f3","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"连续性肾脏替代治疗(CRRT)","category":"重症医学","raw":{"name":"连续性肾脏替代治疗(CRRT)","category":"重症医学","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】适应证表现：少尿/无尿（AKI 3期）、高钾血症（>6.5mmol/L）、严重酸中毒（pH<7.2）、容量超负荷（肺水肿）与尿毒症症状（脑病与心包炎）、脓毒症相关：高热、低血压与乳酸升高（炎症介质清除指征）、治疗相关：导管相关（穿刺点出血、感染与血栓）、抗凝相关（出血）与电解质紊乱（低磷、低钾与低钙）、低温（体外循环致热量丢失）、低血压（超滤过快）与管路凝血（跨膜压升高）、药物清除：抗生素与药物剂量需调整（经CRRT清除）。\n【待人工确认·本机素材无此段原文】","现病史":"连续性肾脏替代治疗（CRRT）是危重症患者（血流动力学不稳定）的缓慢持续血液净化技术，用于急性肾损伤伴容量超负荷、电解质与酸碱紊乱、脓毒症（清除炎症介质）与中毒。常用模式：CVVH（连续性静脉-静脉血液滤过）、CVVHD（透析）与CVVHDF（透析滤过）。管理核心是抗凝、容量平衡与管路维护。\n常见表现：适应证表现：少尿/无尿（AKI 3期）、高钾血症（>6.5mmol/L）、严重酸中毒（pH<7.2）、容量超负荷（肺水肿）与尿毒症症状（脑病与心包炎）、脓毒症相关：高热、低血压与乳酸升高（炎症介质清除指征）、治疗相关：导管相关（穿刺点出血、感染与血栓）、抗凝相关（出血）与电解质紊乱（低磷、低钾与低钙）、低温（体外循环致热量丢失）、低血压（超滤过快）与管路凝血（跨膜压升高）、药物清除：抗生素与药物剂量需调整（经CRRT清除）。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：血压（超滤与容量）、心率与心律（电解质紊乱）、体温（低温与感染）、血氧\n容量状态：颈静脉充盈、肺部湿啰音（肺水肿）、下肢与骶部水肿、体重变化\n导管部位：颈内静脉/股静脉穿刺点出血、红肿与渗液、导管固定与通畅\n管路与滤器：外观（凝血与颜色）、跨膜压与压力参数（每2～4小时）\n神经系统：意识与抽搐（电解质紊乱与尿毒症脑病）、口周麻木（低钙）\n皮肤与黏膜：出血点与瘀斑（抗凝）、皮肤弹性（脱水）\n电解质紊乱体征：心律失常（高钾/低钾）、腱反射（低镁与低钙）","辅助检查":"1. 电解质（钾、钠、钙、磷、镁）每6～12小时：置换液调整与并发症监测（低磷与低钾常见）\n2. 血气分析（每6～12小时）：酸碱状态与乳酸；避免乳酸酸中毒（用碳酸氢盐置换液）\n3. 肾功能（肌酐、尿素氮）+尿量：治疗剂量与脱机评估\n4. 凝血功能+血小板+APTT（抗凝监测）：肝素抗凝监测APTT（1.5～2倍）\n5. 滤器后离子钙+外周离子钙（枸橼酸抗凝）：目标 0.25～0.35与 1.0～1.2mmol/L；总钙/离子钙比值>2.5提示枸橼酸蓄积\n6. 血常规+肝功能+白蛋白：贫血与肝功能（枸橼酸代谢）评估\n7. 药物血药浓度（抗生素与镇静药）：CRRT期间剂量调整依据","初步诊断":"1. 肾功能与电解质（每6～12小时）：肌酐、尿素氮、钾、钠、钙、磷、镁（CRRT期间动态监测）\n2. 血气分析（每6～12小时）：酸碱状态与乳酸（治疗剂量调整）\n3. 容量状态评估：出入量平衡、体重、中心静脉压、超声（下腔静脉变异度与肺水肿）与生物阻抗\n4. 凝血功能+血小板+APTT（抗凝监测）：依抗凝方式选择（肝素监测APTT、枸橼酸监测离子钙）\n5. 管路参数监测：跨膜压（TMP）、滤器前压与滤器凝血情况（每2～4小时）\n6. 导管评估：位置（超声确认）、穿刺点出血与感染征象、导管功能（血流量不足提示位置不良或血栓）\n7. 药物剂量评估：按CRRT清除率调整抗生素与其他药物剂量\n1. 连续性肾脏替代治疗(CRRT)（ICD-10：Z49.1）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【药物治疗·输液】\n⚠️ CRRT为持续治疗，抗凝与置换液管理是核心！\n\n方案1（抗凝，无出血风险者）：\n 用法：枸橼酸抗凝（局部抗凝首选）——4%枸橼酸钠 前稀释泵入（血流速的1.2～1.5倍），监测滤器后离子钙 0.25～0.35mmol/L与外周离子钙 1.0～1.2mmol/L，必要时补钙（10%葡萄糖酸钙 泵入）；或 普通肝素 首剂 2000～5000U 后 5～15U/kg/h 泵入（监测APTT 1.5～2倍）；或 低分子肝素（按医嘱）\n\n方案2（有出血风险/无抗凝）：\n 用法：无抗凝策略（生理盐水定时冲洗管路、前稀释、高血流速）——适用于活动性出血与严重凝血障碍者；密切监测管路凝血\n\n方案3（置换液与容量管理）：\n 用法：碳酸氢盐置换液（含钠、钾、钙、镁与葡萄糖）前/后稀释方式输注（治疗剂量20～35ml/kg/h，脓毒症可加大）；按目标平衡（负平衡0～-100ml/h或按医嘱调整）设置超滤率\n\n方案4（并发症处理）：\n 用法：低血压——减慢超滤、补液或调整升压药（去甲肾上腺素 0.05～0.5μg/kg/min）；低磷/低钾——补充磷酸盐与氯化钾；低钙——补充葡萄糖酸钙；低温——加温置换液与加温装置\n\n📌 枸橼酸局部抗凝是首选（出血风险低）；CRRT期间药物剂量需按清除率调整（抗生素、镇静药与电解质）；每2～4小时监测管路与跨膜压。\n\n【药物治疗·口服】\n⚠️ CRRT患者多不能口服，长期管理用药：\n\n药物1（经CRRT清除需调整剂量的药物）：\n 用法：抗生素（如哌拉西林他唑巴坦 3.375g q8h、万古霉素按血药浓度调整）、镇静药（咪达唑仑与芬太尼清除增加）、抗癫痫药（左乙拉西坦需调整）\n\n药物2（电解质与代谢补充）：\n 用法：氯化钾缓释片（按血钾，兼顾口服者）；碳酸钙D3 600mg qd（钙磷代谢）；骨化三醇 0.25μg qd（活性维生素D）；磷酸盐补充剂（低磷者）\n\n药物3（抗凝相关）：\n 用法：维生素K1 10mg（华法林或肝素过量出血）；鱼精蛋白（肝素）；枸橼酸蓄积（肝功能不全者）——监测离子钙与总钙比值（>2.5提示蓄积）\n\n药物4（基础病与并发症）：\n 用法：降压药（按血压调整）；促红素 10000IU 皮下（肾性贫血）；磷结合剂（随餐，肠内营养者）\n\n📌 CRRT期间几乎所有药物剂量需重新评估（清除率差异大）；枸橼酸蓄积在肝功能不全者风险高（监测总钙/离子钙比值）。\n\n【治疗】\n启动指征：AKI 3期伴以下之一——高钾血症（>6.5mmol/L或心电图改变）、严重酸中毒（pH<7.2）、容量超负荷（肺水肿且利尿无效）、尿毒症并发症（脑病、心包炎与出血）；脓毒症与中毒（按病情）\n模式选择：CVVH（对流为主，清除中分子）、CVVHD（弥散为主，清除小分子）、CVVHDF（联合）；血流速150～250ml/min，治疗剂量20～35ml/kg/h\n抗凝管理：枸橼酸局部抗凝（首选）或肝素全身抗凝；活动性出血者无抗凝并加强管路冲洗\n容量与液体管理：按目标平衡设置超滤率（精确记录出入量）、评估容量状态（超声与CVP）并动态调整\n置换液与电解质：碳酸氢盐置换液（避免枸橼酸蓄积与乳酸酸中毒）；按血气与电解质调整钾、钙与镁浓度\n药物剂量调整：按CRRT清除率调整抗生素、镇静药与抗癫痫药剂量（监测血药浓度）\n管路与滤器管理：每2～4小时监测跨膜压与滤器外观（凝血）、及时更换滤器与管路；导管护理（无菌操作）\n脱机评估：肾功能恢复（尿量增加与肌酐下降）、电解质与酸碱稳定、容量达标后逐步减少并停止CRRT\n\n【处理要点】\n管路与滤器监测：每2～4小时记录跨膜压、滤器前压与滤器外观，凝血时评估抗凝剂量与更换\n抗凝与出血观察：枸橼酸抗凝者监测滤器后离子钙与外周离子钙、观察穿刺点与消化道出血（肝素抗凝者监测APTT）\n容量与出入量：精确记录CRRT超滤量与出入量、每小时记录、评估容量状态（体重、CVP与超声），防止容量不足或超负荷\n电解质与血气监测：每6～12小时复查钾、钙、磷、镁与血气，及时补充或调整置换液成分\n导管护理：保持通畅（避免打折与压迫）、观察穿刺点出血与红肿、严格无菌操作（换药与接头消毒）\n体温与舒适护理：监测体温（体外循环致低温）、加温置换液与患者保暖；镇静评估与镇痛\n药物管理：按CRRT调整剂量并监测血药浓度（抗生素与镇静药）；记录给药时间与滤器更换时间\n宣教与家属沟通：解释CRRT的目的与持续时间（可能数天至数周）、费用与护理要点；脱机评估与后续透析计划沟通\n\n【护理】\n管路与滤器护理：每2～4小时记录跨膜压与滤器外观、及时更换凝血滤器、保持管路通畅（避免打折与牵拉）\n抗凝护理：按医嘱调整抗凝泵速、按时监测离子钙与APTT、观察出血征象（穿刺点、消化道与皮肤）\n容量与出入量管理：每小时精确记录超滤量与出入量、评估容量状态（体重、CVP与肺部听诊），防止容量失衡\n电解质与血气监测配合：按时抽血复查并报告异常，配合调整置换液成分与补充电解质\n导管护理：严格无菌操作（换药与接头消毒）、观察穿刺点出血与感染、避免导管用于其他输液（专用）\n体温与舒适护理：监测体温并加温置换液、保暖；评估镇静与镇痛，预防压疮与深静脉血栓\n宣教与家属沟通：解释CRRT的持续时间与目的、费用与护理配合；脱机与后续治疗计划沟通\n\n【饮食】\nCRRT患者常需禁食或肠内营养（视病情）：肠内营养优先（鼻胃管/鼻肠管），必要时肠外营养\n蛋白需求高（CRRT丢失氨基酸与蛋白，1.5～2.0g/kg/日）；热量25～30kcal/kg/日\n限制钾与磷（按化验），但CRRT清除钾磷较多（部分患者反需补充）——按电解质结果个体化\n限制液体（按容量目标），配合CRRT超滤；钠盐按血压与容量管理\n补充水溶性维生素（CRRT损失增加）：维生素C、B族与叶酸（按医嘱补充）\n\n【注意事项】\nCRRT适用于血流动力学不稳定的危重患者（比间歇性血液透析更温和，避免低血压与颅压波动）\n枸橼酸局部抗凝是首选（出血风险低、滤器寿命长），但肝功能不全者需警惕枸橼酸蓄积（监测总钙/离子钙比值）\nCRRT期间药物剂量需重新评估（清除率差异大，尤其抗生素与镇静药）\n容量管理是CRRT的核心之一（精确记录出入量与目标平衡，避免容量不足与超负荷）\n治疗剂量建议20～35ml/kg/h（脓毒症与高分解代谢者可加大）\n\n【急诊/急救】\n管路大量出血或患者活动性出血（抗凝相关）→ 立即停抗凝、压迫止血、监测血红蛋白与凝血，必要时拮抗剂\n严重低血压（超滤过快/容量不足）→ 减慢或暂停超滤、补液与调整升压药\n滤器频繁凝血（跨膜压骤升）→ 评估抗凝剂量与管路位置，必要时更换滤器与调整抗凝\n严重低钙（口周麻木、手足搐搦与QT延长）→ 立即静脉补钙并复查离子钙（枸橼酸蓄积）\n导管相关血流感染（寒战高热）→ 双份血培养+经验性抗生素，评估拔管与更换导管","资料来源":"疾病库 diseases.json"},"icd10_diagnosis":"Z49.1","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2693,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"65830bd898e73348c6824adf984b189769f280b5e2608fdd880aef2bfd7a9400","pinyin":"lianxuxingshenzangtidaizhiliao(CRRT)","initials":"lxxsztdzl(","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","Z49.1",30]]},{"id":"templates-f2933f89aae05c52e23d","key":"v1-c9ccc21dfe2a3058|templates-f2933f89aae05c52e23d","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"郁证(中医辨证)","category":"中医","raw":{"name":"郁证(中医辨证)","category":"中医","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】肝气郁结：精神抑郁，情绪不宁，胸部满闷，胁肋胀痛，痛无定处，脘闷嗳气、气郁化火：性情急躁易怒，胸闷胁胀，嘈杂吞酸，口干而苦，大便秘结、痰气郁结：精神抑郁，胸部闷塞，胁肋胀满，咽中如有物梗塞，吞之不下，咯之不出（梅核气）、心神失养：精神恍惚，心神不宁，多疑易惊，悲忧善哭，喜怒无常（脏躁）、心脾两虚：多思善疑，头晕神疲，心悸胆怯，失眠健忘，纳差、心肾阴虚：情绪不宁，心悸健忘，失眠多梦，五心烦热，盗汗。\n【待人工确认·本机素材无此段原文】","现病史":"以心情抑郁、情绪不宁、胸部满闷、胁肋胀痛，或易怒易哭，或咽中如有异物梗塞等为主要表现，即抑郁焦虑状态。分肝气郁结、气郁化火、痰气郁结、心神失养、心脾两虚、心肾阴虚等证型。\n常见表现：肝气郁结：精神抑郁，情绪不宁，胸部满闷，胁肋胀痛，痛无定处，脘闷嗳气、气郁化火：性情急躁易怒，胸闷胁胀，嘈杂吞酸，口干而苦，大便秘结、痰气郁结：精神抑郁，胸部闷塞，胁肋胀满，咽中如有物梗塞，吞之不下，咯之不出（梅核气）、心神失养：精神恍惚，心神不宁，多疑易惊，悲忧善哭，喜怒无常（脏躁）、心脾两虚：多思善疑，头晕神疲，心悸胆怯，失眠健忘，纳差、心肾阴虚：情绪不宁，心悸健忘，失眠多梦，五心烦热，盗汗。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：体温、脉搏、呼吸、血压\n望诊：神（得神/少神/失神/假神/神乱）、色（常色/病色：青/赤/黄/白/黑，光泽/晦暗）、形态（形体胖瘦/动静姿态/异常动作）、头面（头颅/囟门/头发/面肿/口眼歪斜）、五官（目/耳/鼻/口/齿/龈/咽喉）、躯体（颈项/胸胁/腹部/腰背/四肢/皮肤）、舌诊（舌质：颜色/形质/动态；舌苔：苔色/苔质/润燥/厚薄/腻腐/剥落；舌底络脉）、排泄物（痰涎/呕吐物/大便/小便/经血/带下）\n闻诊：声音（语声/呼吸/咳嗽/喘哮/呃逆/嗳气/太息/肠鸣）、气味（口气/汗气/痰涕气味/二便气味/经带气味/病室气味）\n问诊：一般情况（姓名/性别/年龄/职业/籍贯）、主诉、现病史（起病情况/主症特点/病因诱因/病情发展/诊治经过/伴随症状）、既往史、个人史、家族史、十问歌（一问寒热二问汗，三问头身四问便，五问饮食六胸腹，七聋八渴俱当辨，九问旧病十问因，再兼服药参机变，妇女尤必问经期，迟速闭崩皆可见，再添片语告儿科，天花麻疹全占验）\n切诊：脉诊（部位：寸关尺；脉象：浮沉迟数虚实滑涩洪细濡弱弦紧结代促等，注意平脉/病脉/真脏脉）、按诊（按肌肤/按手足/按胸腹/按腧穴/按腹部，温度/湿度/压痛/包块/波动感）\n辨证：八纲辨证（表里/寒热/虚实/阴阳）、脏腑辨证、气血津液辨证、六经辨证、卫气营血辨证、三焦辨证、经络辨证","辅助检查":"检查计划：患者以心情抑郁、情绪不宁、胸部满闷、胁肋胀痛，或易怒易哭、咽中如有异物梗塞（梅核气）为主要表现，诊断需排除器质性疾病，故查汉密尔顿抑郁量表（HAMD）、汉密尔顿焦虑量表（HAMA）及抑郁、焦虑自评量表明确情绪障碍程度与证型，为中医辨证分型及疗效评价提供依据；查甲状腺功能（TSH、FT3、FT4）排除甲状腺功能减退或亢进所致情绪与精神症状；查血常规、血糖、电解质、肝肾功能排除贫血、低血糖、电解质紊乱所致头晕、神疲、心悸；患者胸部满闷、心悸，查心电图排除心律失常与心肌缺血，必要时查心脏彩超及 24 小时动态心电图；查胸部 X 线或胸部 CT、肺功能排除慢性肺部疾病所致胸闷；患者脘闷嗳气、嘈杂吞酸，查胃镜排除反流性食管炎、慢性胃炎及消化性溃疡；咽中如有物梗塞者查咽喉镜，必要时查食管测压排除咽喉及食管器质性病变；头晕明显或伴神经系统体征时查头颅 CT 或磁共振成像排除颅内器质性病变；必要时查性激素、皮质醇排除内分泌因素所致情绪障碍；若使用抗抑郁药物治疗，定期复查肝肾功能、血常规，监测药物不良反应。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 以忧郁不畅，情绪不宁为主要表现\n2. 排除器质性疾病\n3. 心理评估量表辅助\n1. 郁证(中医辨证)（ICD-10：F32.9）","鉴别诊断":"1. 排除器质性疾病","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！\n\n方案1：\n 用法：一般不需输液\n\n方案2（严重失眠）：\n 用法：NS250ml+丹参注射液20ml ivgtt qd\n\n📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！\n\n药物1（肝气郁结）：\n 用法：柴胡疏肝散1袋 tid，或逍遥丸1丸 tid\n\n药物2（气郁化火）：\n 用法：丹栀逍遥丸1丸 tid，或越鞠丸1袋 tid\n\n药物3（痰气郁结）：\n 用法：半夏厚朴汤1袋 tid，或舒肝颗粒1袋 tid\n\n药物4（心神失养）：\n 用法：甘麦大枣汤1袋 tid，或脑乐静口服液1支 tid\n\n药物5（心脾两虚）：\n 用法：归脾丸1丸 tid，或人参归脾丸1丸 tid\n\n药物6（心肾阴虚）：\n 用法：天王补心丹1丸 qn，或六味地黄丸1丸 tid\n\n📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。\n\n【治疗】\n肝气郁结：疏肝解郁，理气畅中，柴胡疏肝散\n气郁化火：疏肝解郁，清肝泻火，丹栀逍遥散\n痰气郁结：行气开郁，化痰散结，半夏厚朴汤\n心神失养：甘润缓急，养心安神，甘麦大枣汤\n心脾两虚：健脾养心，补益气血，归脾汤\n心肾阴虚：滋养心肾，天王补心丹合六味地黄丸\n\n【处理要点】\n心理疏导，保持心情舒畅\n规律作息，适当运动\n多与人交流\n避免过度劳累\n\n【护理】\n情志护理（重点）：多与患者沟通，以说理开导、移情易性、以情胜情之法疏导郁结之气；鼓励倾诉宣泄，对肝气郁结者勿斥责压抑，耐心倾听，引导其参加病友交流、听舒缓音乐、赏花弈棋等怡情活动；家属陪护多予关心，避免言语刺激。\n起居调护：病室宜安静整洁、光线柔和、通风良好；起居有常，鼓励晨起适当活动，如散步、八段锦、太极拳、瑜伽等以舒展气机；日间勿久卧久坐，睡前可用温水泡脚，不熬夜、不午睡过久，以防昼夜颠倒加重郁证。\n病情观察：密切观察情志变化、睡眠、食欲及二便情况，注意有无嗳气叹息、胸胁胀痛、咽中异物感（梅核气）等；对情绪低落、自语自笑、厌世者加强巡视，专人看护，妥善收藏刀具、绳索、药品等危险物品，严防自伤自杀意外。\n煎药服药护理：疏肝解郁之剂（如逍遥散、柴胡疏肝散）宜温服、饭前服用，服后嘱其稍事活动以助药力；养心安神之甘麦大枣汤宜睡前温服；服药期间忌恼怒，保持情志舒畅，勿与浓茶、咖啡同服。\n外治护理：每日按揉太冲、内关、膻中、百会等穴，每穴1～2分钟，以酸胀为度；耳穴压豆取肝、心、神门、交感，每日按压3～5次；可用合欢皮、郁金、夜交藤、香附煎水足浴，每晚1次以疏肝解郁安神。\n\n【饮食】\n辨证忌口：肝气郁结者忌辛辣燥热及刺激性饮食（辣椒、白酒、浓茶、咖啡），以免助火化燥；痰气郁结（梅核气）者忌肥甘厚腻、生冷黏滞之品（肥肉、油炸、甜食、冷饮），以防助湿生痰；阴虚火旺者忌羊肉、狗肉、桂圆等温热香燥之品，以免更伤阴液。\n适宜食物：宜食疏肝理气之品，如芹菜、萝卜、佛手、柑橘、金橘、香菜、茼蒿、玫瑰花、茉莉花等；心血不足、心神失养者宜食小麦、大枣、桂圆、百合、莲子、黑芝麻等养心安神之品；可常饮玫瑰花茶、茉莉花茶以畅达气机。\n药膳食疗：肝气郁结者可用玫瑰花、佛手、陈皮各适量沸水冲泡代茶饮，或煮陈皮佛手粥；心神失养者宜服甘麦大枣汤（甘草、浮小麦、大枣煎汤代饮）及百合莲子粥；阴虚者可用百合、枸杞、麦冬炖瘦肉汤或煮百合地黄粥。\n进餐宜定时定量、细嚼慢咽，勿过饱过饥，少食多餐；晚餐宜清淡少量，忌睡前进食及饮浓茶、咖啡，以免扰动心神加重失眠；进食时保持心情愉悦，避免边食边思虑忧烦之事。\n\n【注意事项】\n严重抑郁需精神科会诊\n有自杀倾向需24小时陪护\n中西医结合治疗效果更佳\n\n【急诊/急救】\n一般不需急救\n自杀倾向：精神科急诊，24小时陪护","资料来源":"疾病库 diseases.json；鉴别诊断库 ddx_local.json（条目「郁证（中医辨证）」原文）","中医辨证参考":"首次病程记录\n\n拟诊讨论：\n\n【中医辨证参考】郁证\n（本页列出该病常见证型，请根据患者实际四诊资料选择相应证型，切勿直接套用）\n\n一、肝气郁结\n    症状舌脉：精神抑郁，情绪不宁，胸部满闷，胁肋胀痛，痛无定处，脘闷嗳气，善太息，苔薄腻，脉弦\n    治法：疏肝解郁、理气畅中\n    方剂：柴胡疏肝散\n\n二、气郁化火\n    症状舌脉：情绪急躁易怒，胸胁胀满，口苦而干，头痛目赤，耳鸣，大便秘结，舌红苔黄，脉弦数\n    治法：疏肝解郁、清肝泻火\n    方剂：丹栀逍遥散\n\n三、痰气郁结\n    症状舌脉：精神抑郁，胸部闷塞，咽中如有物梗，吞之不下、咯之不出，苔白腻，脉弦滑\n    治法：行气开郁、化痰散结\n    方剂：半夏厚朴汤\n\n四、心脾两虚\n    症状舌脉：多思善疑，头晕神疲，心悸胆怯，失眠健忘，面色不华，纳差便溏，舌淡苔薄白，脉细弱\n    治法：健脾养心、益气补血\n    方剂：归脾汤\n\n五、心肾阴虚\n    症状舌脉：情绪不宁，心悸健忘，失眠多梦，五心烦热，盗汗，口干咽燥，腰膝酸软，舌红少苔，脉细数\n    治法：滋养心肾、安神定志\n    方剂：天王补心丹合六味地黄丸\n\n【方剂参考】\n  柴胡疏肝散：组成 陈皮（醋炒）6g、柴胡6g、川芎4.5g、香附4.5g、枳壳（麸炒）4.5g、白芍4.5g、炙甘草1.5g；功效 疏肝解郁，行气止痛\n      用法：水煎温服，日一剂，分两次服；亦可研末为散，每服6~9g，开水送下。\n      注意：阴虚火旺、气郁化火及孕妇慎用；本方辛散，久服易耗气伤阴。来源：《方剂学》（中国中医药出版社“十四五”规划教材）·理气剂（行气）；原方出自《景岳全书·古方八阵》\n  丹栀逍遥散：组成 牡丹皮6g、栀子6g、柴胡6g、当归9g、白芍9g、白术9g、茯苓9g、炙甘草3g、薄荷3g（后下）、煨生姜3g；功效 疏肝解郁，健脾养血，清肝泄热\n      用法：水煎温服，日一剂，分两次服；薄荷后下。\n      注意：脾胃虚寒、大便溏薄者不宜用；孕妇慎用；本方可作丸散常服，但不宜长期大量使用苦寒之栀子。来源：《方剂学》（中国中医药出版社“十四五”规划教材）·和解剂（调和肝脾）；原方出自《内科摘要·卷下》\n  半夏厚朴汤：组成 半夏12g、厚朴9g、茯苓12g、生姜9g、紫苏叶6g；功效 行气散结，降逆化痰\n      用法：水煎温服，日三次，分温三服；气郁甚者加香附、郁金，咽痛者加玄参、桔梗。\n      注意：咽喉有器质性病变（肿物、异物）者不属本方范围，须先检查排除；阴虚津少、舌红无苔者忌用；孕妇慎用半夏、厚朴。\n  归脾汤：组成 白术9g、当归9g、白茯苓9g、黄芪12g、龙眼肉12g、远志6g、酸枣仁12g、人参9g、木香6g、炙甘草3g、生姜3片、大枣3枚；功效 益气补血，健脾养心\n      用法：加生姜3片、大枣3枚，水煎温服，日二次；亦可服归脾丸，每次6-9g，日二次。\n      注意：痰湿内盛、肝火扰心之失眠及外感发热者不宜；本方偏温补，有实火者忌用。\n  六味地黄丸：组成 熟地黄24g、山茱萸12g、山药12g、泽泻9g、牡丹皮9g、茯苓9g；功效 滋补肝肾\n      用法：上药为末，炼蜜为丸，每次6-9g，空腹温开水或淡盐汤送服，日二至三次；亦可作汤剂（六味地黄汤）。\n      注意：脾虚便溏、痰湿内盛及感冒发热者忌用；本品滋腻，久服宜配健脾理气之品；肾阳虚（畏寒肢冷）者不宜。\n\n【西医诊断】\n  抑郁症\n  （西医诊断依据与鉴别诊断请结合患者病史、体征、辅助检查补充）\n\n医师签名：＿＿＿＿"},"icd10_diagnosis":"F32.9","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2694,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"14446d83424311b0b98e4d072da249ee31b222a1b886d87d29095a5bba40a07a","pinyin":"yuzheng(zhongyibianzheng)","initials":"yz(zybz)","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源","中医辨证参考"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源 中医辨证参考",30],["主要诊断编码","F32.9",30]]}]);